def _detect_windows_legacy_compat() -> bool:
    override = str(os.environ.get("XIAMI_WINDOWS_LEGACY_COMPAT") or "").strip().lower()
    if override:
        return override not in {"0", "false", "no", "off"}
    if "--legacy-windows-compat" in sys.argv:
        return True
    if sys.platform != "win32":
        return False
    try:
        version = sys.getwindowsversion()
        return (int(version.major), int(version.minor)) <= (6, 3)
    except Exception:
        return False


_WINDOWS_LEGACY_COMPAT = _detect_windows_legacy_compat()
if _WINDOWS_LEGACY_COMPAT:
    # Server 2012 R2 commonly runs through RDP or a basic display adapter.
    # Force Qt onto its bundled software renderer before PySide imports Qt DLLs.
    os.environ.setdefault("QT_OPENGL", "software")
    os.environ.setdefault("QT_QUICK_BACKEND", "software")
    os.environ.setdefault("QT_AUTO_SCREEN_SCALE_FACTOR", "0")
    os.environ.setdefault("QT_ENABLE_HIGHDPI_SCALING", "0")
    os.environ.setdefault("QT_SCALE_FACTOR_ROUNDING_POLICY", "Round")
    os.environ.setdefault("QTWEBENGINE_DISABLE_SANDBOX", "1")
    chromium_flags = str(os.environ.get("QTWEBENGINE_CHROMIUM_FLAGS") or "").strip()
    for flag in ("--disable-gpu", "--disable-gpu-compositing", "--no-sandbox"):
        if flag not in chromium_flags.split():
            chromium_flags = (chromium_flags + " " + flag).strip()
    os.environ["QTWEBENGINE_CHROMIUM_FLAGS"] = chromium_flags

