def _ensure_qt_plugin_paths() -> None:
    if not _QT_AVAILABLE:
        return
    if _QT_BINDING != "PySide2":
        return
    try:
        import PySide2 as _PySide2
    except Exception:
        return

    root = os.path.dirname(getattr(_PySide2, "__file__", "") or "")
    if not root:
        return
    plugins_dir = os.path.join(root, "plugins")
    platforms_dir = os.path.join(plugins_dir, "platforms")
    qwindows = os.path.join(platforms_dir, "qwindows.dll")
    if not os.path.exists(qwindows):
        return

    env_plugins = str(os.environ.get("QT_PLUGIN_PATH") or "")
    env_platforms = str(os.environ.get("QT_QPA_PLATFORM_PLUGIN_PATH") or "")

    def _is_current_pyside_dir(path: str, expected_name: str) -> bool:
        p = str(path or "").strip()
        if not p or not os.path.isdir(p):
            return False
        try:
            rp = os.path.normcase(os.path.abspath(p))
            expected = os.path.normcase(os.path.abspath(os.path.join(root, expected_name)))
            return rp == expected
        except Exception:
            return False

    if not _is_current_pyside_dir(env_plugins, "plugins"):
        os.environ["QT_PLUGIN_PATH"] = plugins_dir
    if not _is_current_pyside_dir(env_platforms, os.path.join("plugins", "platforms")):
        os.environ["QT_QPA_PLATFORM_PLUGIN_PATH"] = platforms_dir
    try:
        QtCore.QCoreApplication.setLibraryPaths([plugins_dir])
    except Exception:
        return


_ensure_qt_plugin_paths()


