    def _set_busy(self, busy: bool) -> None:
        self.email_edit.setEnabled(not busy)
        self.captcha_answer_edit.setEnabled(not busy)
        self.email_code_edit.setEnabled(not busy)
        self.password_edit.setEnabled(not busy)
        self.password2_edit.setEnabled(not busy)
        self.refresh_btn.setEnabled(not busy)
        self.submit_btn.setEnabled(not busy)
        if busy:
            self.send_btn.setEnabled(False)
        else:
            self._refresh_send_state()

    def _start_worker(self, worker: QtCore.QObject, done) -> None:
        if self._thread is not None:
            return
        thread = QtCore.QThread(self)
        worker.moveToThread(thread)
        thread.started.connect(getattr(worker, "run"))
        worker.finished.connect(lambda *args, _done=done: self._ui_invoke.invoke(lambda a=args: _done(*a)))
        worker.finished.connect(thread.quit)
        worker.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        thread.finished.connect(self._cleanup_thread)
        self._thread = thread
        self._worker = worker
        thread.start()

    def _cleanup_thread(self) -> None:
        self._thread = None
        self._worker = None

    def _refresh_send_state(self) -> None:
        if self._send_left > 0:
            return
        email = self.email_edit.text().strip()
        cap = self.captcha_answer_edit.text().strip()
        ok = bool(email) and bool(cap) and _is_valid_email(email) and bool(self._captcha_id)
        self.send_btn.setEnabled(ok and self._thread is None)

    def _fetch_captcha(self) -> None:
        if self._thread is not None:
            return
        self.info_label.setText("")
        self._captcha_id = None
        self.captcha_question.setText("验证码加载中...")
        self._refresh_send_state()

        class _CaptchaWorker(QtCore.QObject):
            finished = QtCore.Signal(object, str)

            def __init__(self, base: str) -> None:
                super().__init__()
                self._base = base

            @QtCore.Slot()
            def run(self) -> None:
                obj, err = _request_json(self._base + "/api/captcha", None, timeout=8)
                self.finished.emit(obj, err)

        self._set_busy(True)

        def done(obj, err: str) -> None:
            self._set_busy(False)
            if err or not isinstance(obj, dict) or not obj.get("ok"):
                self.info_label.setText(err or str(obj.get("error") or "加载失败"))
                self.captcha_question.setText("验证码加载失败")
                self._captcha_id = None
                self._refresh_send_state()
                return
            self._captcha_id = str(obj.get("captcha_id") or "").strip() or None
            q = str(obj.get("question") or "").strip()
            self.captcha_question.setText("算术验证码：" + q)
            self._refresh_send_state()

        self._start_worker(_CaptchaWorker(self._server_base), done)

    def _tick_send(self) -> None:
        if self._send_left <= 0:
            self._send_left = 0
            self._tick_timer.stop()
            self.send_btn.setText("发送注册码")
            self._refresh_send_state()
            return
        self.send_btn.setText(f"重新发送({self._send_left}s)")
        self._send_left -= 1

    def _send_code(self) -> None:
        if self._thread is not None:
            return
        if self._send_left > 0:
            self.info_label.setText(f"请等待{self._send_left}秒后再试")
            return
        email = self.email_edit.text().strip()
        cap = self.captcha_answer_edit.text().strip()
        if not _is_valid_email(email):
            self.info_label.setText("请输入正确邮箱")
            return
        if not cap:
            self.info_label.setText("请输入验证码")
            return
        if not self._captcha_id:
            self.info_label.setText("验证码未加载，请刷新")
            return

        class _SendWorker(QtCore.QObject):
            finished = QtCore.Signal(object, str)

            def __init__(self, base: str, payload: dict) -> None:
                super().__init__()
                self._base = base
                self._payload = payload

            @QtCore.Slot()
            def run(self) -> None:
                obj, err = _request_json(self._base + "/api/send_register_code", self._payload, timeout=10)
                self.finished.emit(obj, err)

        self._set_busy(True)
        self.send_btn.setText("发送中...")

        def done(obj, err: str) -> None:
            self._set_busy(False)
            if err or not isinstance(obj, dict) or not obj.get("ok"):
                self.info_label.setText(err or str(obj.get("error") or "发送失败"))
                self.send_btn.setText("发送注册码")
                self._refresh_send_state()
                QtCore.QTimer.singleShot(0, self._fetch_captcha)
                return
            self.info_label.setText("已发送，请查收邮箱")
            self._send_left = 60
            self.send_btn.setEnabled(False)
            self._tick_send()
            self._tick_timer.start()

        payload = {"email": email, "captcha_id": self._captcha_id, "captcha_answer": cap}
        self._start_worker(_SendWorker(self._server_base, payload), done)

    def _submit(self) -> None:
        if self._thread is not None:
            return
        email = self.email_edit.text().strip()
        code = self.email_code_edit.text().strip()
        pw1 = self.password_edit.text()
        pw2 = self.password2_edit.text()
        if not email or not code or not pw1:
            self.info_label.setText("请输入完整信息")
            return
        if not _is_valid_email(email):
            self.info_label.setText("请输入正确邮箱")
            return
        if pw1 != pw2:
            self.info_label.setText("两次密码不一致")
            return

        class _RegisterWorker(QtCore.QObject):
            finished = QtCore.Signal(object, str)

            def __init__(self, base: str, payload: dict) -> None:
                super().__init__()
                self._base = base
                self._payload = payload

            @QtCore.Slot()
            def run(self) -> None:
                obj, err = _request_json(self._base + "/api/register", self._payload, timeout=10)
                self.finished.emit(obj, err)

        self._set_busy(True)
        self.info_label.setText("")

        def done(obj, err: str) -> None:
            self._set_busy(False)
            if err or not isinstance(obj, dict) or not obj.get("ok"):
                self.info_label.setText(err or str(obj.get("error") or "注册失败"))
                return
            self.result = {"username": email, "password": pw1}
            self.accept()

        payload = {"email": email, "email_code": code, "password": pw1}
        self._start_worker(_RegisterWorker(self._server_base, payload), done)


