def _format_page_usage_html(page_name: str) -> str:
    guide = _PAGE_USAGE_GUIDES.get(str(page_name or "").strip()) or {}
    quick = html.escape(str(guide.get("quick") or "请先确认当前页面的目标，再按顺序完成配置。"))
    errors = html.escape(str(guide.get("errors") or "遇到异常时，优先检查目录、权限和输入内容。"))
    flow = html.escape(str(guide.get("flow") or "建议先小范围测试，再执行正式操作。"))
    return (
        "<div style='line-height:1.75'>"
        "<b>快速上手</b><br/>"
        f"{quick}<br/><br/>"
        "<b>常见错误</b><br/>"
        f"{errors}<br/><br/>"
        "<b>推荐流程</b><br/>"
        f"{flow}"
        "</div>"
    )


def _show_page_usage_dialog(parent: QtWidgets.QWidget | None, page_name: str) -> None:
    dlg = QtWidgets.QDialog(parent)
    dlg.setObjectName("pageUsageDialog")
    dlg.setWindowTitle(f"{page_name} - 使用说明")
    dlg.resize(UiMetrics.PAGE_USAGE_DIALOG_W, UiMetrics.PAGE_USAGE_DIALOG_H)
    layout = QtWidgets.QVBoxLayout(dlg)
    layout.setContentsMargins(
        UiMetrics.PAGE_USAGE_DIALOG_MARGIN_PX,
        UiMetrics.PAGE_USAGE_DIALOG_MARGIN_PX,
        UiMetrics.PAGE_USAGE_DIALOG_MARGIN_PX,
        UiMetrics.PAGE_USAGE_DIALOG_MARGIN_PX,
    )
    layout.setSpacing(UiMetrics.PAGE_USAGE_DIALOG_SPACING)

    title = QtWidgets.QLabel(f"{page_name} - 使用说明")
    title.setObjectName("pageTitle")
    layout.addWidget(title)

    browser = QtWidgets.QTextBrowser()
    browser.setObjectName("pageUsageBrowser")
    browser.setOpenExternalLinks(False)
    browser.setHtml(_format_page_usage_html(page_name))
    layout.addWidget(browser, 1)

    close_btn = _make_ui_action_button("关闭", "primary")
    close_btn.setObjectName("pageUsageCloseButton")
    close_btn.clicked.connect(dlg.accept)
    btn_row = QtWidgets.QHBoxLayout()
    btn_row.setSpacing(UiMetrics.PAGE_USAGE_DIALOG_BUTTON_ROW_SPACING)
    btn_row.addStretch(1)
    btn_row.addWidget(close_btn, 0)
    layout.addLayout(btn_row)
    dlg.exec_()


def _build_page_title_row(parent: QtWidgets.QWidget, page_name: str) -> QtWidgets.QWidget:
    row = QtWidgets.QWidget(parent)
    layout = QtWidgets.QHBoxLayout(row)
    layout.setContentsMargins(0, 0, 0, 0)
    layout.setSpacing(UiMetrics.PAGE_TITLE_ROW_SPACING)

    title = QtWidgets.QLabel(str(page_name or "").strip())
    title.setObjectName("pageTitle")
    layout.addWidget(title, 0)

    btn = _make_ui_action_button("使用说明", "help")
    btn.setObjectName("pageHelpButton")
    btn.setCursor(QtCore.Qt.PointingHandCursor)
    btn.setToolTip(f"查看“{str(page_name or '').strip()}”的详细使用说明")
    btn.clicked.connect(lambda _=False, p=parent, name=str(page_name or "").strip(): _show_page_usage_dialog(p, name))
    layout.addWidget(btn, 0)
    layout.addStretch(1)
    return row


class _LoginPage(QtWidgets.QWidget):
    session_changed = QtCore.Signal(object)

    def __init__(self, auto_refresh_register: bool = True) -> None:
        super().__init__()
        self._ui_invoke = _UiInvokeProxy(self)
        self._login_url = PRODUCTION_LOGIN_URL
        self._session: dict | None = None
        self._thread: QtCore.QThread | None = None
        self._worker: _LoginWorker | None = None
        self._allow_thread: QtCore.QThread | None = None
        self._allow_worker: _AllowRegisterWorker | None = None
        self._build()
        self._load_saved()
        if auto_refresh_register:
            QtCore.QTimer.singleShot(0, self._refresh_register_state)

    def session(self) -> dict | None:
        return self._session

    def _build(self) -> None:
        self.setObjectName("loginPage")
        self.setProperty("toolboxResponsiveStackWidth", True)
        layout = QtWidgets.QVBoxLayout(self)
