        form_layout.addWidget(self.server_edit, 0, 1)
        self.server_label.setVisible(False)
        self.server_edit.setVisible(False)

        self.user_edit = _make_ui_line_edit("normal", "邮箱")
        self.user_edit.setObjectName("loginFieldEdit")
        self.user_edit.setProperty("loginFieldRole", "email")
        self.user_edit.setAccessibleName("登录邮箱")
        self.user_edit.setFixedWidth(330)
        user_label = QtWidgets.QLabel("邮箱")
        user_label.setObjectName("loginFieldLabel")
        user_label.setProperty("formLabelRole", "field")
        user_label.setMinimumWidth(UiMetrics.FORM_LABEL_MIN_W)
        form_layout.addWidget(user_label, 1, 0)
        form_layout.addWidget(self.user_edit, 1, 1)

        self.pass_edit = _make_ui_line_edit("normal", "密码")
        self.pass_edit.setObjectName("loginFieldEdit")
        self.pass_edit.setProperty("loginFieldRole", "password")
        self.pass_edit.setAccessibleName("登录密码")
        self.pass_edit.setFixedWidth(330)
        self.pass_edit.setEchoMode(QtWidgets.QLineEdit.Password)
        self.pass_edit.returnPressed.connect(self._on_login_clicked)
        pass_label = QtWidgets.QLabel("密码")
        pass_label.setObjectName("loginFieldLabel")
