    def _refresh_basic_workspace_identity(self, _index: int = -1) -> None:
        tabs = getattr(self, "tabs", None)
        current = tabs.currentWidget() if isinstance(tabs, QtWidgets.QTabWidget) else None
        meta = {
            getattr(self, "basic_tab", None): ("基础设置", "根目录、服务端名称、本机地址与常用运行参数。"),
            getattr(self, "ports_tab", None): ("端口设置", "集中维护网关、数据库、角色网关和服务端端口。"),
            getattr(self, "currency_tab", None): ("货币兑换", "检查货币变量、兑换规则和脚本消费结果。"),
            getattr(self, "compare_tab", None): ("文件对比", "对比左右文件差异并快速定位变更。"),
        }
        title, note = meta.get(current, ("基础工作台", "根目录确认后可切换到搜索、端口、货币或文件对比。"))
        label = getattr(self, "basic_tabs_badge", None)
        if isinstance(label, QtWidgets.QLabel):
            label.setText(str(title or ""))
            label.setProperty("badgeRole", "info" if current is not getattr(self, "basic_tab", None) else "muted")
            _refresh_ui_dynamic_qss(label)
        note_label = getattr(self, "basic_tabs_note", None)
        if isinstance(note_label, QtWidgets.QLabel):
            note_label.setText(str(note or ""))

