    def _refresh_search_summary(self, *_args) -> None:
        if not hasattr(self, "search_path_summary"):
            return
        path_count = len(self._quick_path_actions())
        if self.search_all_cb.isChecked():
            scope_text = "全端"
        elif self.search_drop_cb.isChecked():
            scope_text = "爆率"
        else:
            scope_text = "常规"
        dedup_text = "开" if self.search_dedup_cb.isChecked() else "关"
        self.search_path_summary.setText(f"路径 {path_count}")
        self.search_scope_summary.setText(f"范围 {scope_text}")
        self.search_dedup_summary.setText(f"去重 {dedup_text}")

