    def _quick_path_category_lookup(self) -> dict[str, str]:
        groups = {
            "core": ("启动器", "服务端根目录", "Mir200目录", "Envir目录"),
            "scripts": ("登录脚本", "触发脚本", "QuestDiary", "NPC目录", "机器人脚本", "任务脚本"),
            "data": (
                "物品备注", "物品套装", "资源文件", "NPC列表", "刷怪配置", "爆率目录",
                "地图配置", "小地图配置", "出生点配置", "管理员列表", "公告信息",
            ),
            "config": ("Config.ini", "!Setup.txt", "GlobalVal.ini", "String.ini"),
        }
        return {label: key for key, labels in groups.items() for label in labels}

    def _set_quick_path_category(self, category: str) -> None:
        selected = str(category or "all").strip().lower()
        if selected not in ("all", "core", "scripts", "data", "config"):
            selected = "all"
        visible_count = 0
        for button, item_category in getattr(self, "_quick_path_buttons", []):
            visible = selected == "all" or selected == item_category
            button.setVisible(visible)
            if visible:
                visible_count += 1
        badge = getattr(self, "quick_path_badge", None)
        if isinstance(badge, QtWidgets.QLabel):
            badge.setText(f"{visible_count} / {len(self._quick_path_actions())}")
            badge.setToolTip(f"当前显示 {visible_count} 项，共 {len(self._quick_path_actions())} 项真实路径")

