    def _open_guide_path(self, rel_path: str) -> None:
        root = self._get_root_path()
        if not root:
            QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
            return

        rp = (rel_path or "").strip()
        if not rp:
            return

        candidates: list[str] = []
        if rp == "GameCenter.exe":
            for name in ("GameCenter.exe", "GameOfMir.exe", "GameOfMir引擎控制器.exe"):
                candidates.append(os.path.join(root, name))
            candidates.append(os.path.join(root, "GameOfMir引擎控制器.exe"))
        elif "|" in rp:
            for part in rp.split("|"):
                s = part.strip()
                if not s:
                    continue
                candidates.append(os.path.join(root, s))
        else:
            if rp == ".":
                candidates.append(root)
            else:
                candidates.append(os.path.join(root, rp))

        target = ""
        for c in candidates:
            if os.path.exists(c):
                target = c
                break

        if not target:
            QtWidgets.QMessageBox.warning(self, "提示", "未找到对应文件或目录")
            return

        try:
            os.startfile(target)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", f"无法打开: {e}")

    def _clear_search_results(self) -> None:
        if self._search_thread is not None:
            return
        try:
            self.search_table.setRowCount(0)
            self._search_outcome = "idle"
            self._search_error_message = ""
            self._set_search_task_state("idle")
            self._set_search_empty_state(
                "等待搜索",
                "输入关键字后搜索脚本、配置、物品、怪物或变量。",
                "idle",
            )
            self._set_search_status("扫描 TXT / INI，不区分大小写", "idle")
            self._set_search_count_badge("等待搜索", "muted")
            self._refresh_search_control_state()
        except Exception:
            return

    def _set_search_task_state(self, state: str) -> None:
        normalized = str(state or "idle").strip().lower()
        allowed = {
            "idle", "loading", "partial", "success", "empty", "error",
            "cancelling", "cancelled",
        }
        if normalized not in allowed:
            normalized = "idle"
        self._search_task_state = normalized
        for widget in (self, getattr(self, "search_results_stack", None), getattr(self, "search_top_actions", None)):
            if not isinstance(widget, QtWidgets.QWidget):
                continue
            try:
                widget.setProperty("searchTaskState", normalized)
                widget.style().unpolish(widget)
                widget.style().polish(widget)
                widget.update()
            except Exception:
                pass
        self._apply_real_basic_geometry()

    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        if bool(self.property("searchRouteMode")):
            self._apply_search_route_geometry()
        elif bool(getattr(self, "_real_basic_mode", False)):
            self._apply_real_basic_geometry()

    def _apply_search_route_geometry(self) -> None:
        compact = self.width() < 1100
        auxiliary_width = 244 if compact else 264
        filter_height = 48 if compact else 52
        toolbar_height = 38 if compact else 40
        result_title_height = 35 if compact else 37
        quick_header_height = 37 if compact else 39
        row_height = 30 if compact else 32
        stop_width = 64 if compact else 72
        clear_width = 48 if compact else 56
        try:
            ancestor = self.parentWidget()
            while ancestor is not None:
                if isinstance(ancestor, QtWidgets.QScrollArea) and ancestor.objectName() == "pageScrollWrapper":
                    ancestor.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
                    break
                ancestor = ancestor.parentWidget()
            splitter = self.basic_body_splitter
            splitter.setHandleWidth(12)
            self.quickPathPanel.setMinimumWidth(auxiliary_width)
            self.quickPathPanel.setMaximumWidth(auxiliary_width)
            splitter.setSizes([max(1, splitter.width() - auxiliary_width - 12), auxiliary_width])
            self.search_filter_band.setFixedHeight(filter_height)
            scope_width = 54 if compact else 60
            for button in self.search_scope_group.buttons():
                button.setFixedSize(scope_width, 32)
            self.search_toolbar.setFixedHeight(toolbar_height)
            self.search_toolbar.layout().setContentsMargins(0, 3 if compact else 4, 0, 3 if compact else 4)
            self.search_btn.setFixedSize(72, 32)
            self.search_stop_btn.setFixedSize(stop_width, 32)
            self.search_clear_btn.setFixedSize(clear_width, 32)
            self._filter_search_gap.changeSize(0, 6 if compact else 8, QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
            self._search_results_gap.changeSize(0, 8 if compact else 10, QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
            self.search_results_header.setFixedHeight(result_title_height)
            self.quick_path_header.setFixedHeight(quick_header_height)
            self.quick_path_categories.setFixedHeight(28)
            for category_button in self.quick_path_category_group.buttons():
                category_button.setFixedHeight(28)
            self._quick_path_bottom_gap.changeSize(0, 22 if compact else 24, QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
            for button, _category in self._quick_path_buttons:
                button.setFixedHeight(row_height)
            self.quick_path_scroll.configure_rows(row_height, 0, 0)
            splitter.updateGeometry()
            self.search_filter_band.parentWidget().layout().invalidate()
            self.quickPathPanel.layout().invalidate()
        except Exception:
            pass

    def _apply_real_basic_geometry(self) -> None:
        compact = self.width() < 1100
        auxiliary_width = 244 if compact else 264
        filter_height = 48 if compact else 52
        toolbar_height = 38 if compact else 40
        result_title_height = 35 if compact else 37
        quick_header_height = 37 if compact else 39
        row_height = 30 if compact else 32
        stop_width = 64 if compact else 72
        clear_width = 48 if compact else 56
        try:
            ancestor = self.parentWidget()
            while ancestor is not None:
                if isinstance(ancestor, QtWidgets.QScrollArea) and ancestor.objectName() == "pageScrollWrapper":
                    ancestor.setVerticalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
                    break
                ancestor = ancestor.parentWidget()
            splitter = self.basic_body_splitter
            splitter.setHandleWidth(12)
            self.quickPathPanel.setMinimumWidth(auxiliary_width)
            self.quickPathPanel.setMaximumWidth(auxiliary_width)
            splitter.setSizes([max(1, splitter.width() - auxiliary_width - 12), auxiliary_width])
            self.search_filter_band.setFixedHeight(filter_height)
            scope_width = 54 if compact else 60
            for button in self.search_scope_group.buttons():
                button.setFixedSize(scope_width, 32)
            self.search_toolbar.setFixedHeight(toolbar_height)
            self.search_toolbar.layout().setContentsMargins(0, 3 if compact else 4, 0, 3 if compact else 4)
            self.search_btn.setFixedSize(72, 32)
            self.search_stop_btn.setFixedSize(stop_width, 32)
            self.search_clear_btn.setFixedSize(clear_width, 32)
            self._filter_search_gap.changeSize(0, 6 if compact else 8, QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
            self._search_results_gap.changeSize(0, 8 if compact else 10, QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
            self.search_results_header.setFixedHeight(result_title_height)
            self.quick_path_header.setFixedHeight(quick_header_height)
            self.quick_path_categories.setFixedHeight(28)
            self._quick_path_bottom_gap.changeSize(0, 22 if compact else 24, QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
            for button, _category in self._quick_path_buttons:
                button.setFixedHeight(row_height)
            self.quick_path_scroll.configure_rows(row_height, 0, 0)
            self.basic_body_splitter.updateGeometry()
            self.search_filter_band.parentWidget().layout().invalidate()
            self.quickPathPanel.layout().invalidate()
        except Exception:
            pass

    def _refresh_search_control_state(self, *_args) -> None:
        running = self._search_thread is not None
        cancelling = running and self._search_outcome == "cancelling"
        query = ""
        try:
            query = str(self.search_combo.currentText() or "").strip()
        except Exception:
            pass
        root_valid = False
        try:
            root = self._get_root_path()
            root_valid = bool(root and os.path.exists(root))
        except Exception:
            pass
        try:
            self.search_btn.setEnabled((not running) and root_valid and bool(query))
            self.search_stop_btn.setEnabled(running and not cancelling)
            self.search_clear_btn.setEnabled(
                (not running)
                and (int(self.search_table.rowCount()) > 0 or self._search_outcome not in ("idle", "running"))
            )
            for control in (
                self.search_regular_cb,
                self.search_all_cb,
                self.search_drop_cb,
                self.search_dedup_cb,
                self.search_combo,
            ):
                control.setEnabled(not running)
            browse = getattr(self, "root_browse_btn", None)
            if isinstance(browse, QtWidgets.QWidget):
                browse.setEnabled(not running)
        except Exception:
            pass

    def _stop_search(self) -> None:
        worker = self._search_worker
        if self._search_thread is None or worker is None or self._search_outcome == "cancelling":
            return
        self._search_outcome = "cancelling"
        self._set_search_task_state("cancelling")
        self._set_search_status("正在停止，已找到的结果将保留...", "busy")
        self._set_search_count_badge("正在停止", "warning")
        self._refresh_search_control_state()
        worker.request_cancel()

    def _set_search_empty_state(self, title: str, detail: str, state: str = "idle") -> None:
        panel = getattr(self, "search_empty_panel", None)
        stack = getattr(self, "search_results_stack", None)
        normalized = str(state or "idle").strip().lower()
        if normalized not in ("idle", "busy", "empty", "error"):
            normalized = "idle"
        if isinstance(panel, QtWidgets.QFrame):
            try:
                panel.setProperty("searchState", normalized)
                panel.style().unpolish(panel)
                panel.style().polish(panel)
                panel.update()
                title_label = getattr(panel, "search_empty_title", None)
                detail_label = getattr(panel, "search_empty_detail", None)
                if isinstance(title_label, QtWidgets.QLabel):
                    title_label.setText(str(title or ""))
                if isinstance(detail_label, QtWidgets.QLabel):
                    detail_label.setText(str(detail or ""))
            except Exception:
                pass
        if isinstance(stack, QtWidgets.QStackedWidget) and isinstance(panel, QtWidgets.QWidget):
            try:
                stack.setCurrentWidget(panel)
            except Exception:
                pass

    def _show_search_table(self) -> None:
        stack = getattr(self, "search_results_stack", None)
        table = getattr(self, "search_table", None)
        if isinstance(stack, QtWidgets.QStackedWidget) and isinstance(table, QtWidgets.QWidget):
            try:
                stack.setCurrentWidget(table)
            except Exception:
                pass

    def populate_smoke_search_results(self, keyword: str = "GameGold") -> None:
        table = getattr(self, "search_table", None)
        combo = getattr(self, "search_combo", None)
        if not isinstance(table, QtWidgets.QTableWidget):
            return
        samples = [
            ("Mir200\\Envir\\Market_Def\\货币兑换-测试.txt", 12, "#IF CHECKGAMEGOLD > 0"),
            ("Mir200\\Envir\\Market_Def\\货币兑换-测试.txt", 16, "#ACT GAMEGOLD - 100"),
            ("Mir200\\Envir\\QuestDiary\\系统\\变量说明.txt", 28, "GameGold 元宝变量用于货币兑换脚本。"),
            ("Mir200\\!setup.txt", 233, "GameGold=元宝"),
        ]
        try:
            if isinstance(combo, QtWidgets.QComboBox):
                combo.setCurrentText(str(keyword or "GameGold"))
            table.setRowCount(0)
            for idx, (rel_path, line_no, content) in enumerate(samples, start=1):
                row = int(table.rowCount())
                table.insertRow(row)
                table.setItem(row, 0, self._make_search_table_item(idx))
                table.setItem(row, 1, self._make_search_table_item(rel_path))
                table.setItem(row, 2, self._make_search_table_item(line_no))
                table.setItem(row, 3, self._make_search_table_item(content))
            table.selectRow(0)
            self._show_search_table()
            self._set_search_status(f"搜索完成，共找到 {len(samples)} 条结果。", "done")
            self._set_search_count_badge(f"{len(samples)} 条结果", "info")
        except Exception:
            return

    def _set_search_count_badge(self, text: str, role: str = "muted") -> None:
        badge = getattr(self, "search_count_badge", None)
        if not isinstance(badge, QtWidgets.QLabel):
            return
        badge.setText(str(text or ""))
        badge.setProperty("badgeRole", str(role or "").strip() or "muted")
        try:
            badge.style().unpolish(badge)
            badge.style().polish(badge)
            badge.update()
        except Exception:
            pass
        summary = getattr(self, "search_results_summary", None)
        table = getattr(self, "search_table", None)
        if isinstance(summary, QtWidgets.QLabel) and isinstance(table, QtWidgets.QTableWidget):
            files = set()
            for row in range(table.rowCount()):
                item = table.item(row, 1)
                if item is not None and str(item.text() or "").strip():
                    files.add(str(item.text()).strip())
            summary.setText(f"{len(files)} 个文件 · {table.rowCount()} 条匹配")

