    @staticmethod
    def _ports_summary_value(value: object, fallback: str = "-", limit: int = 12) -> str:
        text = str(value or "").strip()
        if not text:
            return fallback
        if len(text) <= limit:
            return text
        return text[: max(1, limit - 3)] + "..."

    def _refresh_ports_summary(self, *_args) -> None:
        if not hasattr(self, "ports_game_summary"):
            return
        game = self._ports_summary_value(self.game_name_edit.text() if hasattr(self, "game_name_edit") else "", "未填", 12)
        ip = self._ports_summary_value(self.ip_edit.text() if hasattr(self, "ip_edit") else "", "-", 15)
        gate_count = self.run_gate_count_spin.value() if hasattr(self, "run_gate_count_spin") else 0
        if getattr(self, "log_enabled_cb", None) is not None and not self.log_enabled_cb.isChecked():
            log_text = "关"
        elif getattr(self, "log_proto_tcp", None) is not None and self.log_proto_tcp.isChecked():
            log_text = "TCP"
        else:
            log_text = "UDP"
        self.ports_game_summary.setText(f"游戏 {game}")
        self.ports_ip_summary.setText(f"IP {ip}")
        self.ports_gate_summary.setText(f"网关 {gate_count}")
        self.ports_log_summary.setText(f"日志 {log_text}")

    def _connect_ports_summary_signals(self) -> None:
        for widget in (
            getattr(self, "game_name_edit", None),
            getattr(self, "ip_edit", None),
            getattr(self, "log_service_port_edit", None),
        ):
            if isinstance(widget, QtWidgets.QLineEdit):
                widget.textChanged.connect(self._refresh_ports_summary)
        for widget in (
            getattr(self, "dynamic_ip_cb", None),
            getattr(self, "log_enabled_cb", None),
            getattr(self, "log_proto_tcp", None),
            getattr(self, "log_proto_udp", None),
        ):
            if isinstance(widget, (QtWidgets.QCheckBox, QtWidgets.QRadioButton)):
                widget.toggled.connect(self._refresh_ports_summary)
        spin = getattr(self, "run_gate_count_spin", None)
        if isinstance(spin, QtWidgets.QSpinBox):
            spin.valueChanged.connect(self._refresh_ports_summary)

