    def _build_currency_table_box(self) -> QtWidgets.QGroupBox:
        table_box = QtWidgets.QGroupBox("货币变量显示（来自 Mir200\\!setup.txt）")
        table_box.setObjectName("currencyTableBox")
        table_box.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
        layout = QtWidgets.QVBoxLayout(table_box)
        layout.setContentsMargins(
            UiMetrics.CURRENCY_TABLE_MARGIN_PX,
            UiMetrics.CURRENCY_TABLE_MARGIN_PX,
            UiMetrics.CURRENCY_TABLE_MARGIN_PX,
            UiMetrics.CURRENCY_TABLE_MARGIN_PX,
        )
        layout.setSpacing(UiMetrics.CURRENCY_TABLE_V_SPACING)

        layout.addWidget(self._build_currency_info_bar(), 0)

        table_wrap = QtWidgets.QWidget()
        table_wrap.setObjectName("currencyTokenGrid")
        self.currency_token_grid = table_wrap
        table = QtWidgets.QGridLayout(table_wrap)
        table.setContentsMargins(
            6,
            5,
            6,
            5,
        )
        table.setHorizontalSpacing(UiMetrics.CURRENCY_TABLE_H_SPACING)
        table.setVerticalSpacing(UiMetrics.CURRENCY_TABLE_V_SPACING)
        for col in range(0, 6):
            table.setColumnStretch(col, 0)
        table.setColumnStretch(6, 1)

        self._currency_labels = {}
        self._currency_defaults = {}

        self._add_currency_table_header(table)
        for row_idx, row_data in enumerate(self._currency_table_rows(), start=1):
            self._add_currency_table_row(table, row_idx, row_data)
