    @staticmethod
    def _currency_exchange_summary_value(value: object, fallback: str = "-", limit: int = 10) -> str:
        text = str(value or "").strip()
        if not text:
            return fallback
        if len(text) <= limit:
            return text
        return text[: max(1, limit - 3)] + "..."

    def _count_active_currency_exchange_rules(self) -> tuple[int, int]:
        rows = list(getattr(self, "_exchange_rows", []) or [])
        active = 0
        for row in rows:
            try:
                left_amount = str(row.get("left_amount").text() or "").strip()
                right_amount = str(row.get("right_amount").text() or "").strip()
                left_custom = str(row.get("left_custom").text() or "").strip()
                right_custom = str(row.get("right_custom").text() or "").strip()
                if left_amount or right_amount or left_custom or right_custom:
                    active += 1
            except Exception:
                continue
        return active, len(rows)

    def _refresh_currency_exchange_summary(self, *_args) -> None:
        if not hasattr(self, "currency_exchange_map_summary"):
            return
        map_text = self._currency_exchange_summary_value(
            self.exchange_npc_map_combo.currentText() if hasattr(self, "exchange_npc_map_combo") else "",
            "-",
            10,
        )
        npc_text = self._currency_exchange_summary_value(
            self.exchange_npc_name_edit.text() if hasattr(self, "exchange_npc_name_edit") else "",
            "-",
            10,
        )
        coord_text = self._currency_exchange_summary_value(
            self.exchange_npc_coord_edit.text() if hasattr(self, "exchange_npc_coord_edit") else "",
            "-",
            10,
        )
        active, total = self._count_active_currency_exchange_rules()
        self.currency_exchange_map_summary.setText(f"地图 {map_text}")
        self.currency_exchange_npc_summary.setText(f"NPC {npc_text}")
        self.currency_exchange_coord_summary.setText(f"坐标 {coord_text}")
        self.currency_exchange_rule_summary.setText(f"规则 {active}/{total}")

    def _connect_currency_exchange_summary_signals(self) -> None:
        combo = getattr(self, "exchange_npc_map_combo", None)
        if isinstance(combo, QtWidgets.QComboBox):
            combo.currentTextChanged.connect(self._refresh_currency_exchange_summary)
            line_edit = combo.lineEdit()
            if isinstance(line_edit, QtWidgets.QLineEdit):
                line_edit.textChanged.connect(self._refresh_currency_exchange_summary)
        for edit in (
            getattr(self, "exchange_npc_name_edit", None),
            getattr(self, "exchange_npc_coord_edit", None),
        ):
            if isinstance(edit, QtWidgets.QLineEdit):
                edit.textChanged.connect(self._refresh_currency_exchange_summary)
        for row in list(getattr(self, "_exchange_rows", []) or []):
            for key in ("left_amount", "left_custom", "right_amount", "right_custom"):
                widget = row.get(key)
                if isinstance(widget, QtWidgets.QLineEdit):
                    widget.textChanged.connect(self._refresh_currency_exchange_summary)
            for key in ("left_type", "right_type"):
                widget = row.get(key)
                if isinstance(widget, QtWidgets.QComboBox):
                    widget.currentIndexChanged.connect(self._refresh_currency_exchange_summary)

    def _configure_currency_exchange_action_button(self, button: QtWidgets.QPushButton, role: str, accessible_name: str, tooltip: str) -> None:
        button.setProperty("currencyExchangeActionRole", role)
        _apply_ui_button_role(button, "primary" if role == "write" else "secondary")
        width = UiMetrics.CURRENCY_EXCHANGE_WRITE_BUTTON_W if role == "write" else UiMetrics.CURRENCY_EXCHANGE_SCRIPT_BUTTON_W
        button.setFixedSize(
            width,
            UiMetrics.PRIMARY_BUTTON_H if role == "write" else UiMetrics.TABLE_ACTION_BUTTON_H,
        )
        button.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
        button.setAccessibleName(accessible_name)
        button.setToolTip(tooltip)

