    def _build_exchange_map_combo(self) -> QtWidgets.QComboBox:
        combo = _make_ui_combo("normal")
        combo.setObjectName("currencyExchangeMapCombo")
        combo.setEditable(True)
        combo.setInsertPolicy(QtWidgets.QComboBox.NoInsert)
        combo.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
        combo.setAccessibleName("兑换 NPC 地图")
        combo.setToolTip("选择或输入兑换 NPC 所在地图")
        try:
            combo.lineEdit().setPlaceholderText("请选择地图名称")
            combo.lineEdit().setClearButtonEnabled(True)
            combo.lineEdit().setAccessibleName("兑换 NPC 地图输入")
        except Exception:
            pass
        self._exchange_npc_map_entries: list[tuple[str, str]] = []
        self._exchange_npc_map_completer = None
        self.exchange_npc_map_combo = combo
        self._init_exchange_map_completer()
        self._connect_exchange_map_combo()
        return combo

    def _init_exchange_map_completer(self) -> None:
        if self.exchange_npc_map_combo.lineEdit() is None:
            return
        try:
            self._exchange_npc_map_completer = QtWidgets.QCompleter([], self.exchange_npc_map_combo)
            self._exchange_npc_map_completer.setCaseSensitivity(QtCore.Qt.CaseInsensitive)
            self._exchange_npc_map_completer.setCompletionMode(QtWidgets.QCompleter.PopupCompletion)
            try:
                self._exchange_npc_map_completer.setFilterMode(QtCore.Qt.MatchContains)
            except Exception:
                pass
            self.exchange_npc_map_combo.lineEdit().setCompleter(self._exchange_npc_map_completer)
            self._exchange_npc_map_completer.activated[str].connect(self._on_exchange_npc_map_completed)
            self.exchange_npc_map_combo.lineEdit().textEdited.connect(self._on_exchange_npc_map_text_edited)
        except Exception:
            pass

    def _connect_exchange_map_combo(self) -> None:
        try:
            self.exchange_npc_map_combo.activated[int].connect(self._on_exchange_npc_map_combo_activated)
        except Exception:
            pass

