    def _sync_currency_exchange_custom(self, combo: QtWidgets.QComboBox, custom: QtWidgets.QLineEdit) -> None:
        is_custom = combo.currentText() == "自定义"
        custom.setVisible(is_custom)
        if is_custom:
            combo.setStyleSheet(
                "QComboBox#currencyExchangeTypeCombo { "
                "min-width: 68px; max-width: 78px; "
                "}"
            )
            custom.setStyleSheet(
                "QLineEdit#currencyExchangeCustomEdit { "
                f"min-width: {UiMetrics.CURRENCY_EXCHANGE_CUSTOM_MIN_W}px; "
                f"max-width: {UiMetrics.CURRENCY_EXCHANGE_CUSTOM_MAX_W}px; "
                "}"
            )
        else:
            combo.setStyleSheet(
                "QComboBox#currencyExchangeTypeCombo { "
                f"min-width: {UiMetrics.CURRENCY_EXCHANGE_TYPE_MIN_W}px; "
                f"max-width: {UiMetrics.CURRENCY_EXCHANGE_TYPE_MAX_W}px; "
                "}"
            )
            custom.setStyleSheet(
                "QLineEdit#currencyExchangeCustomEdit { "
                f"min-width: {UiMetrics.CURRENCY_EXCHANGE_CUSTOM_MIN_W}px; "
                "}"
            )

    def _add_currency_exchange_row(self, rows_l: QtWidgets.QVBoxLayout, row_idx: int) -> None:
        left_amount, left_type, left_custom, left_box = self._make_currency_exchange_side()
        right_amount, right_type, right_custom, right_box = self._make_currency_exchange_side()
        self._configure_currency_exchange_side(left_amount, left_type, left_custom, row_idx, "left", "消耗")
        self._configure_currency_exchange_side(right_amount, right_type, right_custom, row_idx, "right", "获得")
        left_box.setMinimumWidth(UiMetrics.CURRENCY_EXCHANGE_TYPE_MIN_W)
        right_box.setMinimumWidth(UiMetrics.CURRENCY_EXCHANGE_TYPE_MIN_W)

        row_card = QtWidgets.QFrame()
        row_card.setObjectName("currencyExchangeRuleRow")
        row_card.setProperty("currencyRuleParity", "odd" if row_idx % 2 else "even")
        row_card.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
        row_l = QtWidgets.QHBoxLayout(row_card)
        row_l.setContentsMargins(
            UiMetrics.CURRENCY_EXCHANGE_ROWS_H_SPACING,
            0,
            UiMetrics.CURRENCY_EXCHANGE_ROWS_H_SPACING,
            0,
        )
        row_l.setSpacing(UiMetrics.CURRENCY_EXCHANGE_ROWS_H_SPACING)

        row_no = QtWidgets.QLabel(f"{row_idx + 1:02d}")
        row_no.setObjectName("currencyExchangeRuleIndex")
        row_no.setAlignment(QtCore.Qt.AlignCenter)
        row_no.setFixedWidth(30)
        row_l.addWidget(row_no)

        row_l.addWidget(left_amount)
        row_l.addWidget(left_box, 1)

        row_l.addWidget(right_amount)
        row_l.addWidget(right_box, 1)
        rows_l.addWidget(row_card)

        self._exchange_rows.append(
            {
                "left_amount": left_amount,
                "left_type": left_type,
                "left_custom": left_custom,
                "right_amount": right_amount,
                "right_type": right_type,
                "right_custom": right_custom,
            }
        )

