    def _refresh_compare_summary(self) -> None:
        if not hasattr(self, "compare_left_summary"):
            return
        state = getattr(self, "_compare_state", {}) or {}
        left_count = len(state.get("left_lines") or [])
        right_count = len(state.get("right_lines") or [])
        opts: list[str] = []
        if getattr(self, "compare_ignore_space_cb", None) is not None and self.compare_ignore_space_cb.isChecked():
            opts.append("全空白")
        if getattr(self, "compare_ignore_trailing_cb", None) is not None and self.compare_ignore_trailing_cb.isChecked():
            opts.append("尾空格")
        if getattr(self, "compare_ignore_case_cb", None) is not None and self.compare_ignore_case_cb.isChecked():
            opts.append("大小写")
        if getattr(self, "compare_sync_scroll_cb", None) is not None and self.compare_sync_scroll_cb.isChecked():
            opts.append("同步")
        option_text = "/".join(opts) if opts else "默认"
        self.compare_left_summary.setText(f"左 {left_count} 行")
        self.compare_right_summary.setText(f"右 {right_count} 行")
        self.compare_option_summary.setText(f"选项 {option_text}")
        self._refresh_compare_side_titles()

    @staticmethod
    def _compare_newline_name(ending: str) -> str:
        if ending == "\r\n":
            return "CRLF"
        if ending == "\r":
            return "CR"
        return "LF"

    def _refresh_compare_side_titles(self) -> None:
        state = getattr(self, "_compare_state", {}) or {}
        for side, side_name in (("left", "左侧"), ("right", "右侧")):
            label = getattr(self, f"compare_{side}_title", None)
            if not isinstance(label, QtWidgets.QLabel):
                continue
            path = str(state.get(f"{side}_path") or "").strip()
            if not path:
                edit = getattr(self, f"compare_{side}_path_edit", None)
                path = str(edit.text() if isinstance(edit, QtWidgets.QLineEdit) else "").strip()
            if not state.get(f"{side}_path"):
                text = f"{side_name} · {os.path.basename(path) if path else '未加载'}"
            else:
                filename = os.path.basename(path) or path
                encoding = str(state.get(f"{side}_encoding") or "未知").upper()
                newline = self._compare_newline_name(str(state.get(f"{side}_ending") or "\n"))
                dirty = "已修改" if bool(state.get(f"{side}_dirty")) else "已保存"
                line_count = len(state.get(f"{side}_lines") or [])
                text = f"{side_name} · {filename} · {encoding} · {newline} · {line_count} 行 · {dirty}"
            label.setText(text)
            label.setToolTip(path or text)

    def _configure_compare_option(self, button: QtWidgets.QToolButton, role: str, accessible_name: str) -> None:
        button.setObjectName("compareOptionButton")
        button.setCheckable(True)
        button.setProperty("compareOptionRole", role)
        button.setAccessibleName(accessible_name)
        button.setToolTip(accessible_name)
        button.setToolButtonStyle(QtCore.Qt.ToolButtonTextOnly)
        button.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
        button.setProperty("compareOptionText", button.text())
        button.setProperty("compareOptionChecked", False)

        def refresh_option_state(checked: bool, target: QtWidgets.QToolButton = button) -> None:
            base_text = str(target.property("compareOptionText") or target.text()).lstrip("✓ ")
            target.setText(("✓ " if checked else "") + base_text)
            target.setProperty("compareOptionChecked", bool(checked))
            target.style().unpolish(target)
            target.style().polish(target)
            self._refresh_compare_summary()
            state = getattr(self, "_compare_state", {}) or {}
            if state.get("left_path") and state.get("right_path"):
                self._compare_recalc(jump_first=False)

        button.toggled.connect(refresh_option_state)

