    def populate_smoke_compare_diff(self) -> None:
        smoke_dir = str(os.environ.get("XIAMI_COMPARE_SMOKE_DIR") or "").strip()
        if not smoke_dir:
            smoke_dir = os.path.join(_writable_app_dir(), "demo_compare_diff")
        left_path = os.path.join(smoke_dir, "left-version.txt")
        right_path = os.path.join(smoke_dir, "right-version.txt")
        left_lines = [
            "; 虾米工具箱文件对比示例",
            "[Info]",
            "ServerName=赤月沉默一区",
            "OpenDate=2026-06-16",
            "GameGoldName=元宝",
            "",
            "[Npc]",
            "#IF",
            "CHECKGAMEGOLD > 99",
            "#ACT",
            "GAMEGOLD - 100",
            "GIVE 金币 100000",
        ]
        right_lines = [
            "; 虾米工具箱文件对比示例",
            "[Info]",
            "ServerName=赤月沉默二区",
            "OpenDate=2026-06-16",
            "GameGoldName=元宝",
            "",
            "[Npc]",
            "#IF",
            "CHECKGAMEGOLD > 199",
            "#ACT",
            "GAMEGOLD - 200",
            "GIVE 金币 180000",
            "MESSAGEBOX 兑换完成",
        ]
        try:
            os.makedirs(smoke_dir, exist_ok=True)
            _write_text_file_best_effort(left_path, left_lines, "utf-8", "\n", True)
            _write_text_file_best_effort(right_path, right_lines, "utf-8", "\n", True)
            self.compare_left_path_edit.setText(left_path)
            self.compare_right_path_edit.setText(right_path)
            self.compare_left_path_edit.setCursorPosition(len(left_path))
            self.compare_right_path_edit.setCursorPosition(len(right_path))
            self.compare_ignore_space_cb.setChecked(False)
            self.compare_ignore_trailing_cb.setChecked(True)
            self.compare_ignore_case_cb.setChecked(False)
            self.compare_sync_scroll_cb.setChecked(True)
            self._compare_run()
        except Exception:
            return

    def _on_root_dir_changed(self) -> None:
        self._update_paths_state()
        self._refresh_search_control_state()
        self._schedule_currency_setup_read()

    def _schedule_currency_setup_read(self) -> None:
        self._currency_setup_seq += 1
        for label in self._currency_labels.values():
            self._set_currency_display_label_text(label, "")
        if self._currency_setup_timer.isActive():
            self._currency_setup_timer.stop()
        self._currency_setup_timer.start()

    def _cleanup_currency_setup_thread(self) -> None:
        thread = getattr(self, "_currency_setup_thread", None)
        self._currency_setup_thread = None
        self._currency_setup_worker = None
        if thread is not None:
            try:
                thread.quit()
            except Exception:
                pass
        if bool(getattr(self, "_currency_setup_closing", False)):
            return
        if getattr(self, "_currency_setup_timer", None) is not None and self._currency_setup_timer.isActive():
            return
        if self._currency_setup_applied_seq != self._currency_setup_seq:
            self._currency_setup_timer.start(0)

    def _shutdown_currency_workers(self) -> None:
        self._currency_setup_closing = True
        timer = getattr(self, "_currency_setup_timer", None)
        if timer is not None:
            try:
                timer.stop()
            except Exception:
                pass
        for attr in ("_currency_setup_thread", "_consume_thread"):
            thread = getattr(self, attr, None)
            if thread is None:
                continue
            try:
                thread.requestInterruption()
                thread.quit()
                thread.wait(3000)
            except Exception:
                pass
        self._currency_setup_thread = None
        self._currency_setup_worker = None
        self._consume_thread = None
        self._consume_worker = None

    def _start_currency_setup_read(self) -> None:
        if self._currency_setup_thread is not None:
            return
        raw_root = self._get_root_path()
        if not raw_root:
            self._apply_currency_loader_result({"seq": self._currency_setup_seq, "root": "", "mapping": {}, "maps": []})
            return
        try:
            normalized_root = _currency_normalize_server_root(raw_root)
        except Exception as exc:
            self._currency_setup_error = str(exc)
            self._apply_currency_setup_mapping({})
            self._apply_currency_map_entries([])
            self._currency_setup_applied_seq = self._currency_setup_seq
            return
        seq = self._currency_setup_seq
        worker = _CurrencySetupReadWorker(normalized_root, seq)
        thread = QtCore.QThread(self)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.finished.connect(self._apply_currency_loader_result)
        worker.failed.connect(lambda message, s=seq, r=normalized_root: self._on_currency_loader_failed(s, r, message))
        worker.finished.connect(thread.quit)
        worker.failed.connect(thread.quit)
        worker.finished.connect(worker.deleteLater)
        worker.failed.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        thread.finished.connect(self._cleanup_currency_setup_thread)
        self._currency_setup_worker = worker
        self._currency_setup_thread = thread
        thread.start()

    def _apply_currency_loader_result(self, payload: dict) -> None:
        seq = int((payload or {}).get("seq") or 0)
        result_root = str((payload or {}).get("root") or "")
        current_raw = self._get_root_path()
        try:
            current_root = _currency_normalize_server_root(current_raw) if current_raw else ""
        except Exception:
            current_root = ""
        if seq != self._currency_setup_seq or os.path.normcase(os.path.realpath(result_root)) != os.path.normcase(os.path.realpath(current_root)):
            return
        self._currency_setup_applied_seq = seq
        self._currency_setup_root = result_root
        self._currency_setup_error = ""
        self._apply_currency_setup_mapping(dict((payload or {}).get("mapping") or {}))
        self._apply_currency_map_entries(list((payload or {}).get("maps") or []))

    def _on_currency_loader_failed(self, seq: int, root: str, message: str) -> None:
        if int(seq) != self._currency_setup_seq:
            return
        try:
            current = _currency_normalize_server_root(self._get_root_path())
        except Exception:
            current = ""
        if os.path.normcase(os.path.realpath(str(root or ""))) != os.path.normcase(os.path.realpath(current)):
            return
        self._currency_setup_applied_seq = int(seq)
        self._currency_setup_error = str(message or "读取失败")
        self._apply_currency_setup_mapping({})
        self._apply_currency_map_entries([])

    def _set_currency_display_label_text(self, label: QtWidgets.QLabel, text: str) -> None:
        value = str(text or "").strip()
        try:
            label.setText(value)
            label.setProperty("currencyCellRole", "accent" if value else "display")
            _refresh_ui_dynamic_qss(label)
        except Exception:
            pass

    def _apply_currency_setup_mapping(self, mapping: dict) -> None:
        for code, label in self._currency_labels.items():
            text = ""
            try:
                key = str(code).strip().lower()
            except Exception:
                key = ""
            if key:
                try:
                    text = str(mapping.get(key) or "").strip()
                except Exception:
                    text = ""
            if not text:
                text = self._currency_defaults.get(code, "") or ""
            self._set_currency_display_label_text(label, text)
        self._refresh_exchange_type_options()

    def _on_currency_label_clicked(self, code: str) -> None:
        code = str(code or "")
        label = self._currency_labels.get(code)
        if label:
            text = (label.text() or "").strip()
        else:
            w = self.sender()
            text = (w.text() or "").strip() if isinstance(w, QtWidgets.QLabel) else ""
        if not text:
            return
        QtWidgets.QApplication.clipboard().setText(text)

    def _open_text_search_from_currency(self, keyword: str) -> None:
        keyword = str(keyword or "").strip()
        if not keyword:
            return
        context = getattr(self, "_dark_workbench_context", None)
        shell = getattr(self, "_dark_workbench_shell", None) or getattr(context, "shell", None)
        target_page = getattr(context, "search_page", None) or self
        combo = getattr(target_page, "search_combo", None)
        if combo is not None:
            try:
                combo.setCurrentText(keyword)
            except Exception:
                pass
            line_edit = getattr(combo, "lineEdit", lambda: None)()
            if line_edit is not None:
                try:
                    line_edit.setText(keyword)
                    line_edit.setFocus()
                except Exception:
                    pass
        starter = getattr(target_page, "_start_search", None)
        if callable(starter):
            try:
                starter()
            except Exception:
                pass
        setter = getattr(shell, "set_current_page", None)
        if callable(setter):
            try:
                setter("search")
                return
            except Exception:
                pass
        try:
            self.tabs.setCurrentWidget(self.basic_tab)
        except Exception:
            pass

    def _on_currency_label_double_clicked(self, code: str) -> None:
        code = str(code or "")
        label = self._currency_labels.get(code)
        if label:
            text = (label.text() or "").strip()
        else:
            w = self.sender()
            text = (w.text() or "").strip() if isinstance(w, QtWidgets.QLabel) else ""
        if not text:
            return
        self._open_text_search_from_currency(text)

    def _show_currency_help(self) -> None:
        QtWidgets.QMessageBox.information(
            self,
            "说明",
            "这里会扫描 Mir200\\!setup.txt 中常见的货币字段。\n"
            "也会统计脚本里的货币扣除与消耗写法。\n"
            "如果你用了自定义字段或特殊脚本，请结合实际再检查一遍。\n"
            "重点关注 Mir200\\Envir 中 DEC/Take 等相关语句。",
        )

    def _show_currency_consume_view(self) -> None:
        if self._consume_thread is not None:
            return
        raw_root = self._get_root_path()
        if not raw_root:
            QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
            return
        try:
            root = _currency_normalize_server_root(raw_root)
            mir200_path = _currency_existing_child(root, "Mir200", True)
            envir_path = _currency_existing_child(mir200_path, "Envir", True)
            _currency_assert_target(root, envir_path)
        except Exception as exc:
            QtWidgets.QMessageBox.warning(self, "提示", str(exc))
            return
        if not os.path.isdir(envir_path):
            QtWidgets.QMessageBox.warning(self, "提示", f"未找到目录：{envir_path}")
            return

        self.currency_consume_btn.setEnabled(False)

        custom_aliases: dict[str, str] = {}
        for row in getattr(self, "_exchange_rows", []) or []:
            for side in ("left", "right"):
                try:
                    name, code = self._resolve_exchange_side(row, side)
                except Exception:
                    continue
                if name and code:
                    custom_aliases[str(code).strip()] = str(name).strip()
        worker = _CurrencyConsumeWorker(envir_path, custom_aliases)
        thread = QtCore.QThread(self)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.finished.connect(self._show_currency_consume_result)
        worker.failed.connect(lambda m: QtWidgets.QMessageBox.critical(self, "错误", m or "扫描失败"))
        worker.finished.connect(thread.quit)
        worker.failed.connect(thread.quit)
        worker.finished.connect(worker.deleteLater)
        worker.failed.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        thread.finished.connect(self._cleanup_consume_thread)
        self._consume_worker = worker
        self._consume_thread = thread
        thread.start()

    def _cleanup_consume_thread(self) -> None:
        self._consume_thread = None
        self._consume_worker = None
        try:
            self.currency_consume_btn.setEnabled(True)
        except Exception:
            return

