    def _get_currency_exchange_types(self) -> list[str]:
        mapping = [
            ("GameGold", "金币"),
            ("GamePoint", "元宝"),
            ("GameDiamond", "钻石"),
            ("GameGird", "灵符"),
            ("GameGlory", "荣誉"),
            ("CreditPoint", "积分"),
            ("GoldCount", "金币"),
        ]
        types: list[str] = []
        for code, default_name in mapping:
            name = ""
            lbl = self._currency_labels.get(code)
            if lbl:
                name = (lbl.text() or "").strip()
            if name and name.strip().lower() == str(code).strip().lower():
                name = ""
            if not name:
                name = (self._currency_defaults.get(code, "") or "").strip()
            if not name:
                name = default_name
            types.append(f"{name}[{code}]")
        types.append("自定义")
        return types

    def _refresh_exchange_npc_map_options(self) -> None:
        self._apply_currency_map_entries(list(getattr(self, "_exchange_npc_map_entries", []) or []))

    def _apply_currency_map_entries(self, entries: list[tuple[str, str]]) -> None:
        combo = getattr(self, "exchange_npc_map_combo", None)
        if not isinstance(combo, QtWidgets.QComboBox):
            return
        current_text = (combo.currentText() or "").strip()
        current_code = str(combo.currentData() or "").strip()
        entries = list(entries or [])
        self._exchange_npc_map_entries = list(entries)
        combo.blockSignals(True)
        combo.clear()
        combo.addItem("请选择地图名称", "")
        for label, code in entries:
            combo.addItem(label, code)
        combo.blockSignals(False)
        try:
            cp = getattr(self, "_exchange_npc_map_completer", None)
            if cp is not None:
                cp.setModel(QtCore.QStringListModel([x[0] for x in entries], cp))
        except Exception:
            pass
        if current_code:
            for i in range(combo.count()):
                if i > 0 and str(combo.itemData(i) or "").strip().lower() == current_code.lower():
                    combo.setCurrentIndex(i)
                    try:
                        combo.setProperty("selected_map_code", current_code)
                        combo.setEditText(current_code)
                    except Exception:
                        pass
                    return
        if current_text:
            combo.setProperty("selected_map_code", "")
            combo.setEditText(current_text)
        else:
            combo.setCurrentIndex(0)
            combo.setProperty("selected_map_code", "")

    def _on_exchange_npc_map_text_edited(self, text: str) -> None:
        combo = getattr(self, "exchange_npc_map_combo", None)
        if not isinstance(combo, QtWidgets.QComboBox):
            return
        try:
            combo.setProperty("selected_map_code", "")
            cp = getattr(self, "_exchange_npc_map_completer", None)
            query = str(text or "").strip()
            if cp is not None and query:
                q = query.lower()
                entries = list(getattr(self, "_exchange_npc_map_entries", []) or [])
                exact_code = [x for x in entries if str(x[1] or "").strip().lower() == q]
                code_prefix = [x for x in entries if str(x[1] or "").strip().lower().startswith(q) and x not in exact_code]
                label_prefix = [x for x in entries if str(x[0] or "").strip().lower().startswith(q) and x not in exact_code and x not in code_prefix]
                code_contains = [x for x in entries if q in str(x[1] or "").strip().lower() and x not in exact_code and x not in code_prefix and x not in label_prefix]
                label_contains = [x for x in entries if q in str(x[0] or "").strip().lower() and x not in exact_code and x not in code_prefix and x not in label_prefix and x not in code_contains]
                ordered = exact_code + code_prefix + label_prefix + code_contains + label_contains
                cp.setModel(QtCore.QStringListModel([x[0] for x in ordered], cp))
                cp.setCompletionPrefix(query)
                cp.complete()
            elif cp is not None:
                cp.popup().hide()
        except Exception:
            return

    def _on_exchange_npc_map_completed(self, label: str) -> None:
        combo = getattr(self, "exchange_npc_map_combo", None)
        if not isinstance(combo, QtWidgets.QComboBox):
            return
        picked_label = str(label or "").strip()
        if not picked_label:
            return
        picked_code = ""
        for shown, code in getattr(self, "_exchange_npc_map_entries", []) or []:
            if str(shown or "").strip() == picked_label:
                picked_code = str(code or "").strip()
                break
        if not picked_code:
            m = re.search(r"\[([^\[\]]+)\]\s*$", picked_label)
            if m:
                picked_code = str(m.group(1) or "").strip()
        try:
            final_text = picked_code or picked_label
            combo.setProperty("selected_map_code", picked_code)
            QtCore.QTimer.singleShot(0, lambda t=final_text, c=combo: c.setEditText(t))
        except Exception:
            return

    def _on_exchange_npc_map_combo_activated(self, index: int) -> None:
        combo = getattr(self, "exchange_npc_map_combo", None)
        if not isinstance(combo, QtWidgets.QComboBox):
            return
        try:
            idx = int(index)
        except Exception:
            return
        if idx <= 0:
            try:
                combo.setProperty("selected_map_code", "")
            except Exception:
                pass
            return
        label = str(combo.itemText(idx) or "").strip()
        code = str(combo.itemData(idx) or "").strip()
        final_text = code or label
        try:
            combo.setProperty("selected_map_code", code)
            QtCore.QTimer.singleShot(0, lambda t=final_text, c=combo: c.setEditText(t))
        except Exception:
            return

    def _refresh_exchange_type_options(self) -> None:
        types = self._get_currency_exchange_types()
        code_to_value: dict[str, str] = {}
        for v in types:
            s = (v or "").strip()
            if not s or s == "自定义":
                continue
            if "[" in s and "]" in s:
                try:
                    _left, right = s.split("[", 1)
                    code = right.split("]", 1)[0].strip().upper()
                    if code:
                        code_to_value[code] = s
                except Exception:
                    continue

        for row in self._exchange_rows:
            for key in ("left_type", "right_type"):
                combo: QtWidgets.QComboBox = row.get(key)
                if not combo:
                    continue
                cur = (combo.currentText() or "").strip()
                combo.blockSignals(True)
                combo.clear()
                combo.addItems(types)
                combo.blockSignals(False)
                if cur == "自定义":
                    combo.setCurrentText("自定义")
                    continue
                if cur and "[" in cur and "]" in cur:
                    try:
                        _left, right = cur.split("[", 1)
                        code = right.split("]", 1)[0].strip().upper()
                        if code and code in code_to_value:
                            combo.setCurrentText(code_to_value[code])
                            continue
                    except Exception:
                        pass
                if not combo.currentText():
                    combo.setCurrentText(types[0] if types else "")

    def _resolve_exchange_side(self, row: dict, side: str) -> tuple[str, str]:
        if side == "left":
            combo: QtWidgets.QComboBox = row.get("left_type")
            custom: QtWidgets.QLineEdit = row.get("left_custom")
        else:
            combo = row.get("right_type")
            custom = row.get("right_custom")
        if combo and combo.currentText() == "自定义" and custom:
            text = (custom.text() or "").strip()
            if not text:
                return "", ""
            if "|" in text:
                name, code = text.split("|", 1)
                return name.strip(), code.strip()
            return text, text
        if not combo:
            return "", ""
        value = (combo.currentText() or "").strip()
        if not value:
            return "", ""
        if "[" in value and "]" in value:
            left, right = value.split("[", 1)
            code = right.split("]", 1)[0]
            return left.strip(), code.strip()
        return value, value

