    def _build_currency_exchange_output(self) -> dict:
        root_path = self._get_root_path()
        if not root_path:
            raise ValueError("请先选择服务端根目录。")

        def parse_int(text: str) -> int | None:
            try:
                return int(text)
            except Exception:
                return None

        parsed_rows: list[dict] = []
        for row_index, row in enumerate(self._exchange_rows, start=1):
            left_amount_text = (row["left_amount"].text() or "").strip()
            right_amount_text = (row["right_amount"].text() or "").strip()
            if not left_amount_text and not right_amount_text:
                continue
            la = parse_int(left_amount_text)
            ra = parse_int(right_amount_text)
            if la is None or ra is None or la <= 0 or ra <= 0:
                raise ValueError(f"第 {row_index} 条兑换规则数量必须为正整数。")
            left_name, left_code = self._resolve_exchange_side(row, "left")
            right_name, right_code = self._resolve_exchange_side(row, "right")
            if not left_name or not right_name or not left_code or not right_code:
                raise ValueError(f"第 {row_index} 条兑换规则的货币类型不完整。")
            for code in (left_code, right_code):
                if not re.match(r"^[A-Za-z][A-Za-z0-9_$\u4e00-\u9fff]*$", code):
                    raise ValueError(f"第 {row_index} 条兑换规则包含不安全的货币变量。")
            parsed_rows.append(
                {
                    "left_amount": la,
                    "right_amount": ra,
                    "left_name": left_name,
                    "left_code": left_code.upper(),
                    "right_name": right_name,
                    "right_code": right_code.upper(),
                }
            )

        if not parsed_rows:
            QtWidgets.QMessageBox.information(self, "提示", "请先填写至少一条完整的兑换规则。")
            return {}

        u_code_global = None
        for row in parsed_rows:
            if row["left_code"].startswith("U"):
                u_code_global = row["left_code"]
                break
            if row["right_code"].startswith("U"):
                u_code_global = row["right_code"]
                break
        if not u_code_global:
            u_code_global = "U20"

        def get_currency_ops(code: str):
            code_upper = code.upper()
            if code_upper == "GOLDCOUNT":
                check_expr = "<$GoldCount>"
                add_cmd = lambda amount: "Give 金币 " + amount
                sub_cmd = lambda amount: "Take 金币 " + amount
                return check_expr, add_cmd, sub_cmd
            if code_upper == "GAMEGOLD":
                check_expr = "<$GameGold>"
                add_cmd = lambda amount: "GameGold + " + amount
                sub_cmd = lambda amount: "GameGold - " + amount
                return check_expr, add_cmd, sub_cmd
            if code_upper == "GAMEPOINT":
                check_expr = "<$GamePoint>"
                add_cmd = lambda amount: "GamePoint + " + amount
                sub_cmd = lambda amount: "GamePoint - " + amount
                return check_expr, add_cmd, sub_cmd
            if code_upper == "GAMEDIAMOND":
                check_expr = "<$GameDiamond>"
                add_cmd = lambda amount: "GameDiamond + " + amount
                sub_cmd = lambda amount: "GameDiamond - " + amount
                return check_expr, add_cmd, sub_cmd
            if code_upper == "GAMEGIRD":
                check_expr = "<$GameGird>"
                add_cmd = lambda amount: "GameGird + " + amount
                sub_cmd = lambda amount: "GameGird - " + amount
                return check_expr, add_cmd, sub_cmd
            if code_upper == "GAMEGLORY":
                check_expr = "<$GameGlory>"
                add_cmd = lambda amount: "GameGlory + " + amount
                sub_cmd = lambda amount: "GameGlory - " + amount
                return check_expr, add_cmd, sub_cmd
            if code_upper == "CREDITPOINT":
                check_expr = "<$CreditPoint>"
                add_cmd = lambda amount: "CreditPoint + " + amount
                sub_cmd = lambda amount: "CreditPoint - " + amount
                return check_expr, add_cmd, sub_cmd
            if code_upper.startswith("U") or code_upper.startswith("J"):
                check_expr = "<$STR(" + code_upper + ")>"
                add_cmd = lambda amount, c=code_upper: "INC " + c + " " + amount
                sub_cmd = lambda amount, c=code_upper: "DEC " + c + " " + amount
                return check_expr, add_cmd, sub_cmd
            check_expr = "<$STR(" + code_upper + ")>"
            add_cmd = lambda amount, c=code_upper: "INC " + c + " " + amount
            sub_cmd = lambda amount, c=code_upper: "DEC " + c + " " + amount
            return check_expr, add_cmd, sub_cmd

        def build_rule(row: dict, idx: int, u_code: str):
            la = row["left_amount"]
            ra = row["right_amount"]
            lc = row["left_code"]
            rc = row["right_code"]
            ln = row["left_name"]
            rn = row["right_name"]
            if la <= 0 or ra <= 0:
                return None
            n = idx
            left_check, _left_add, left_sub = get_currency_ops(lc)
            _right_check, right_add, _right_sub = get_currency_ops(rc)
            amount_input = "<$STR(S" + str(n) + ")>"
            amount_result = "<$STR(S$给予货币)>"
            if la >= ra:
                ratio = la / ra
                if ratio <= 0:
                    return None
                ratio = int(ratio)
                header = (
                    "<>             <Text:"
                    + ln
                    + "兑换"
                    + rn
                    + "/@@InputString"
                    + str(n)
                    + ">      <Text:输入"
                    + ln
                    + "数量比例"
                    + str(ratio)
                    + "：1> \\ \\"
                )
                block = [
                    f"[@InputString{n}]",
                    "#IF",
                    f"large s{n} {left_check}",
                    "#ACT",
                    "messagebox 请输入正确的" + ln + "数量",
                    "break",
                    "",
                    "#IF",
                    f"small s{n} {ratio}",
                    "#ACT",
                    f"messagebox 最少输入{ratio}{ln}",
                    "break",
                    "",
                    "#IF",
                    "#ACT",
                    f"mov S$给予货币 <$STR(S{n})>",
                    f"DIV S$给予货币 {ratio}",
                    right_add(amount_result),
                    left_sub(amount_input),
                    "sendmsg 6 扣除" + amount_input + ln + "，获得" + amount_result + rn,
                    "goto @main",
                    "break",
                ]
                return header, block
            ratio = ra / la
            if ratio <= 0:
                return None
            ratio = int(ratio)
            header = (
                "<>             <Text:"
                + ln
                + "兑换"
                + rn
                + "/@@InputString"
                + str(n)
                + ">      <Text:输入"
                + ln
                + "数量比例1："
                + str(ratio)
                + "> \\ \\"
            )
            block = [
                f"[@InputString{n}]",
                "#IF",
                f"large s{n} {left_check}",
                "#ACT",
                "messagebox 请输入正确的" + ln + "数量",
                "break",
                "",
                "#IF",
                f"small s{n} 1",
                "#ACT",
                "messagebox 最少输入1" + ln,
                "break",
                "",
                "#IF",
                "#ACT",
                f"mov S$给予货币 <$STR(S{n})>",
                f"MUL S$给予货币 {ratio}",
                right_add(amount_result),
                left_sub(amount_input),
                "sendmsg 6 扣除" + amount_input + ln + "，获得" + amount_result + rn,
                "goto @main",
                "break",
            ]
            return header, block

        headers: list[str] = []
        blocks: list[list[str]] = []
        rule_index = 12
        for row in parsed_rows:
            built = build_rule(row, rule_index, u_code_global)
            if not built:
                continue
            header, block = built
            headers.append(header)
            blocks.append(block)
            rule_index += 1

        if not headers:
            QtWidgets.QMessageBox.warning(self, "提示", "未能根据填写内容生成任何兑换脚本，请检查数值是否大于 0。")
            return {}

        script_body_lines: list[str] = []
        npc_map_combo = getattr(self, "exchange_npc_map_combo", None)
        npc_map_text = str(npc_map_combo.currentText() or "").strip() if npc_map_combo else ""
        npc_map_code = str(npc_map_combo.property("selected_map_code") or "").strip() if npc_map_combo else ""
        if (not npc_map_code) and npc_map_combo:
            npc_map_code = str(npc_map_combo.currentData() or "").strip()
        npc_name_text = str(getattr(self, "exchange_npc_name_edit", None).text() or "").strip() if getattr(self, "exchange_npc_name_edit", None) else ""
        npc_coord_text = str(getattr(self, "exchange_npc_coord_edit", None).text() or "").strip() if getattr(self, "exchange_npc_coord_edit", None) else ""
        if any((npc_map_text, npc_name_text, npc_coord_text)):
            if not all((npc_map_text, npc_name_text, npc_coord_text)):
                raise ValueError("请完整填写兑换 NPC 地图、名称和坐标。")
            coordinate = re.fullmatch(r"([1-9]\d*) ([1-9]\d*)", npc_coord_text)
            if coordinate is None:
                raise ValueError("兑换 NPC 坐标必须是两个大于 0 的整数，格式为 X 空格 Y。")
            if any(ch in npc_name_text for ch in ("\r", "\n")):
                raise ValueError("兑换 NPC 名称不安全。")
            candidate_code = npc_map_code or npc_map_text
            if not re.fullmatch(r"[A-Za-z0-9_-]+", candidate_code):
                raise ValueError("兑换 NPC 地图编号不安全。")
        script_body_lines.append("[@main]")
        script_body_lines.append("#IF")
        script_body_lines.append("#ACT")
        script_body_lines.append("#SAY")
        script_body_lines.append("\\ \\ ")

        used_codes: dict[str, str] = {}
        for row in parsed_rows:
            lc = row["left_code"]
            rc = row["right_code"]
            ln = row["left_name"]
            rn = row["right_name"]
            lcu = lc.upper()
            rcu = rc.upper()
            if lcu not in used_codes:
                used_codes[lcu] = ln
            if rcu not in used_codes:
                used_codes[rcu] = rn

        header_parts: list[str] = []
        for code, name in used_codes.items():
            check_expr, _add_cmd, _sub_cmd = get_currency_ops(code)
            header_parts.append("<Text: " + name + "数量：" + check_expr + "/SCOLOR=250>")
        if header_parts:
            header_line = "<>   " + "    ".join(header_parts) + " \\ \\"
            script_body_lines.append(header_line)
        for h in headers:
            script_body_lines.append(h)

        for block in blocks:
            script_body_lines.append("")
            script_body_lines.extend(block)

        merchant_line = ""
        suggested_script_name = "虾米货币兑换"
        script_suffix = ""
        if npc_map_code:
            safe_map_code = re.sub(r'[\\/:*?"<>|\s]+', "", str(npc_map_code or "").strip())
            if safe_map_code:
                script_suffix = f"-{safe_map_code}"
        suggested_file_name = f"{suggested_script_name}{script_suffix}.txt"
        suggested_rel_path = f"Market_def\\{suggested_file_name}"
        text_lines: list[str] = []
        if npc_map_text and npc_name_text and npc_coord_text:
            merchant_map = npc_map_code or npc_map_text
            merchant_line = f"{suggested_script_name} {merchant_map} {npc_coord_text} {npc_name_text} 0 12 0 0 0 0 10"
            text_lines.append(";========== MerChant.txt ==========")
            text_lines.append(f";位置：Mir200\\Envir\\MerChant.txt")
            text_lines.append(merchant_line)
            text_lines.append("")
            text_lines.append(f";========== Market_def\\{suggested_file_name} ==========")
            text_lines.append(f";位置：Mir200\\Envir\\{suggested_rel_path}")
            text_lines.append(f";固定 NPC 名：{suggested_script_name}")
            text_lines.append(f";MerChant 显示名：{npc_name_text}")
            text_lines.append("")
        else:
            if npc_map_text:
                text_lines.append(f";兑换NPC地图：{npc_map_text}")
            if npc_name_text:
                text_lines.append(f";兑换NPC名称：{npc_name_text}")
            if npc_coord_text:
                text_lines.append(f";兑换NPC坐标：{npc_coord_text}")
            if npc_map_text or npc_name_text or npc_coord_text:
                text_lines.append("")

        text_lines.extend(script_body_lines)
        return {
            "preview": "\n".join(text_lines),
            "merchant_line": merchant_line,
            "script_body": "\n".join(script_body_lines),
            "script_rel_path": suggested_rel_path,
        }

    def _write_currency_exchange_files(self) -> None:
        root_path = self._get_root_path()
        if not root_path:
            QtWidgets.QMessageBox.warning(self, "提示", "请先选择服务端根目录。")
            return
        try:
            built = self._build_currency_exchange_output()
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", str(e))
            return
        if not built:
            return
        if not str(built.get("merchant_line") or "").strip():
            QtWidgets.QMessageBox.warning(self, "提示", "请先完整填写兑换NPC地图、兑换NPC名称、兑换NPC坐标。")
            return
        try:
            plan = _currency_build_write_plan(root_path, built)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", str(e))
            return
        lines = ["将以一个事务写入以下目标：", ""]
        for item in plan["writes"]:
            if item.get("original") is None:
                state = "create/创建"
            elif item.get("role") == "merchant":
                state = "update/更新"
            else:
                state = "overwrite/覆盖"
            lines.append(f"[{state}] {os.path.abspath(item['path'])}")
        lines.extend(("", "继续前会保存原始字节备份；取消不会产生任何文件或目录。"))
        answer = QtWidgets.QMessageBox.question(
            self,
            "确认写入货币兑换",
            "\n".join(lines),
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.Cancel,
            QtWidgets.QMessageBox.Cancel,
        )
        if answer != QtWidgets.QMessageBox.Yes:
            return
        try:
            result = _currency_execute_write_plan(plan, str(getattr(self, "_currency_fault_point", "") or ""))
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "写入失败", f"事务已回滚：{e}")
            return
        QtWidgets.QMessageBox.information(self, "成功", "已写入：\n" + "\n".join(result["targets"]))

    def _compare_pick_file(self, edit: QtWidgets.QLineEdit) -> None:
        start_dir = ""
        root = self._get_root_path()
        if root:
            start_dir = root
        path, _ = _qt_get_open_file_name(self, "选择文件", start_dir, "文本文件 (*.txt *.ini);;所有文件 (*.*)")
        if not path:
            return
        if not self._confirm_compare_discard("更换对比文件"):
            return
        edit.setText(path)

    def _compare_has_dirty(self) -> bool:
        state = getattr(self, "_compare_state", {}) or {}
        return bool(state.get("left_dirty") or state.get("right_dirty"))

    def _confirm_compare_discard(self, action: str) -> bool:
        if not self._compare_has_dirty():
            return True
        answer = QtWidgets.QMessageBox.question(
            self,
            "放弃未保存的合并结果？",
            f"当前左右文件存在未保存的合并结果。\n\n继续{action}将丢弃这些修改。",
            QtWidgets.QMessageBox.Discard | QtWidgets.QMessageBox.Cancel,
            QtWidgets.QMessageBox.Cancel,
        )
        return answer == QtWidgets.QMessageBox.Discard

    @staticmethod
    def _compare_canonical_path(path: str) -> str:
        return os.path.normcase(os.path.realpath(os.path.abspath(str(path or ""))))

    def _read_text_file_any(self, path: str) -> tuple[list[str], str, str, bool]:
        if not os.path.exists(path):
            return [], "gbk", "\r\n", False
        lines_keep, used_enc, ending, trailing_nl = _read_text_file_best_effort(path)
        text = "".join(lines_keep)
        return text.splitlines(), used_enc, ending, trailing_nl

    def _compare_read_text_file(self, path: str) -> tuple[list[str], str, str, bool]:
        lines_keep, used_enc, ending, trailing_nl = _read_text_file_best_effort(path)
        if lines_keep:
            last_line = str(lines_keep[-1])
            trailing_nl = last_line.endswith("\r\n") or last_line.endswith("\n") or last_line.endswith("\r")
        text = "".join(lines_keep)
        return text.splitlines(), used_enc, ending, trailing_nl

    def _write_text_file(self, path: str, lines: list[str], enc: str, ending: str, trailing_nl: bool) -> None:
        _write_text_file_best_effort(path, lines, enc, ending, trailing_nl)

    def _compare_sync_scroll(self, which: str, value: int) -> None:
        if not self.compare_sync_scroll_cb.isChecked():
            return
        st = getattr(self, "_compare_state", None)
        if not isinstance(st, dict):
            return
        if st.get("sync_lock"):
            return
        st["sync_lock"] = True
        try:
            if which == "left":
                self.compare_right_text.verticalScrollBar().setValue(value)
            else:
                self.compare_left_text.verticalScrollBar().setValue(value)
        finally:
            st["sync_lock"] = False

    def _compare_norm_line(self, line: str) -> str:
        s = line or ""
        if self.compare_ignore_trailing_cb.isChecked():
            s = s.rstrip()
        if self.compare_ignore_space_cb.isChecked():
            s = re.sub(r"\s+", "", s)
        if self.compare_ignore_case_cb.isChecked():
            s = s.lower()
        return s

    def _compare_run(self) -> None:
        left_path = (self.compare_left_path_edit.text() or "").strip()
        right_path = (self.compare_right_path_edit.text() or "").strip()
        if not left_path or not right_path:
            QtWidgets.QMessageBox.warning(self, "提示", "请先选择左右文件")
            return
        if not os.path.isfile(left_path) or not os.path.isfile(right_path):
            QtWidgets.QMessageBox.warning(self, "提示", "路径不存在或不是文件")
            return
        if self._compare_canonical_path(left_path) == self._compare_canonical_path(right_path):
            QtWidgets.QMessageBox.warning(self, "提示", "左右文件不能是同一个文件")
            return
        if not self._confirm_compare_discard("重新执行对比"):
            return

        left_lines, left_enc, left_end, left_tnl = self._compare_read_text_file(left_path)
        right_lines, right_enc, right_end, right_tnl = self._compare_read_text_file(right_path)

        self._compare_state.update(
            {
                "left_path": left_path,
                "right_path": right_path,
                "left_lines": left_lines,
                "right_lines": right_lines,
                "left_encoding": left_enc,
                "right_encoding": right_enc,
                "left_ending": left_end,
                "right_ending": right_end,
                "left_trailing_nl": left_tnl,
                "right_trailing_nl": right_tnl,
                "left_dirty": False,
                "right_dirty": False,
                "idx": -1,
            }
        )

        self.compare_left_text.setPlainText("\n".join(left_lines))
        self.compare_right_text.setPlainText("\n".join(right_lines))

        self._compare_recalc(jump_first=True)

    def _compare_recalc(self, jump_first: bool) -> None:
        left_lines = self._compare_state.get("left_lines") or []
        right_lines = self._compare_state.get("right_lines") or []

        a = [self._compare_norm_line(x) for x in left_lines]
        b = [self._compare_norm_line(x) for x in right_lines]
        sm = difflib.SequenceMatcher(a=a, b=b)
        diffs = [op for op in sm.get_opcodes() if op[0] != "equal"]
        self._compare_state["diffs"] = diffs
        self._compare_state["idx"] = -1
        self._compare_apply_highlight()
        if diffs:
            self._set_compare_status_text(f"共 {len(diffs)} 处差异")
            if jump_first:
                self._compare_jump(1)
        else:
            self._set_compare_status_text("未发现差异")

    def _compare_apply_highlight(self) -> None:
        diffs = self._compare_state.get("diffs") or []
        left_lines = self._compare_state.get("left_lines") or []
        right_lines = self._compare_state.get("right_lines") or []

        left_set: set[int] = set()
        right_set: set[int] = set()
        for tag, i1, i2, j1, j2 in diffs:
            for i in range(i1, min(i2, len(left_lines))):
                left_set.add(i)
            for j in range(j1, min(j2, len(right_lines))):
                right_set.add(j)

        def build_selections(editor: QtWidgets.QPlainTextEdit, lines_count: int, indices: set[int], color: QtGui.QColor):
            sels: list[QtWidgets.QTextEdit.ExtraSelection] = []
            fmt = QtGui.QTextCharFormat()
            fmt.setBackground(color)
            fmt.setProperty(QtGui.QTextFormat.FullWidthSelection, True)
            for idx in sorted(indices):
                if idx < 0 or idx >= lines_count:
                    continue
                cursor = QtGui.QTextCursor(editor.document().findBlockByNumber(idx))
                sel = QtWidgets.QTextEdit.ExtraSelection()
                sel.cursor = cursor
                sel.format = fmt
                sels.append(sel)
            editor.setExtraSelections(sels)

        left_color = _ui_theme_token_color(self, "compare_diff_left", QtGui.QPalette.Highlight)
        right_color = _ui_theme_token_color(self, "compare_diff_right", QtGui.QPalette.Highlight)
        if not left_color.isValid() or left_color.hue() in range(190, 250):
            left_color = _ui_theme_token_color(self, "accent_soft", QtGui.QPalette.Highlight)
        if not left_color.isValid() or left_color.hue() in range(190, 250):
            left_color = QtGui.QColor("#FFF1E6")
        if not right_color.isValid() or right_color.hue() in range(190, 250):
            right_color = _ui_theme_token_color(self, "nav_sel_grad_2", QtGui.QPalette.Highlight)
        if not right_color.isValid() or right_color.hue() in range(190, 250):
            right_color = QtGui.QColor("#FFF8EF")
        left_color.setAlpha(UiMetrics.COMPARE_DIFF_HIGHLIGHT_ALPHA)
        right_color.setAlpha(UiMetrics.COMPARE_DIFF_HIGHLIGHT_ALPHA)
        build_selections(self.compare_left_text, len(left_lines), left_set, left_color)
        build_selections(self.compare_right_text, len(right_lines), right_set, right_color)

    def _compare_jump(self, delta: int) -> None:
        diffs = self._compare_state.get("diffs") or []
        if not diffs:
            return
        idx = int(self._compare_state.get("idx", -1))
        idx = idx + delta
        if idx < 0:
            idx = 0
        if idx >= len(diffs):
            idx = len(diffs) - 1
        self._compare_state["idx"] = idx
        tag, i1, i2, j1, j2 = diffs[idx]
        self._scroll_to_line(self.compare_left_text, i1)
        self._scroll_to_line(self.compare_right_text, j1)
        self._set_compare_status_text(f"第 {idx+1}/{len(diffs)} 处：{tag}")

    @staticmethod
    def _scroll_to_line(editor: QtWidgets.QPlainTextEdit, line_no: int) -> None:
        try:
            block = editor.document().findBlockByNumber(max(0, int(line_no)))
            cursor = QtGui.QTextCursor(block)
            editor.setTextCursor(cursor)
            editor.centerCursor()
        except Exception:
            return

    def _compare_apply_copy(self, direction: str) -> None:
        diffs = self._compare_state.get("diffs") or []
        idx = int(self._compare_state.get("idx", -1))
        if idx < 0 or idx >= len(diffs):
            return
        _tag, i1, i2, j1, j2 = diffs[idx]
        left_lines: list[str] = list(self._compare_state.get("left_lines") or [])
        right_lines: list[str] = list(self._compare_state.get("right_lines") or [])
        if direction == "l2r":
            right_lines[j1:j2] = left_lines[i1:i2]
            self._compare_state["right_dirty"] = True
        else:
            left_lines[i1:i2] = right_lines[j1:j2]
            self._compare_state["left_dirty"] = True
        self._compare_state["left_lines"] = left_lines
        self._compare_state["right_lines"] = right_lines
        self.compare_left_text.setPlainText("\n".join(left_lines))
        self.compare_right_text.setPlainText("\n".join(right_lines))
        self._compare_recalc(jump_first=False)
        self._refresh_compare_side_titles()

    def _compare_save(self, which: str) -> None:
        if which == "left":
            path = self._compare_state.get("left_path") or ""
            lines = self._compare_state.get("left_lines") or []
            enc = self._compare_state.get("left_encoding") or "utf-8"
            ending = self._compare_state.get("left_ending") or "\n"
            trailing = bool(self._compare_state.get("left_trailing_nl"))
        else:
            path = self._compare_state.get("right_path") or ""
            lines = self._compare_state.get("right_lines") or []
            enc = self._compare_state.get("right_encoding") or "utf-8"
            ending = self._compare_state.get("right_ending") or "\n"
            trailing = bool(self._compare_state.get("right_trailing_nl"))
        if not path:
            return
        side_name = "左侧" if which == "left" else "右侧"
        newline_name = self._compare_newline_name(str(ending))
        answer = QtWidgets.QMessageBox.question(
            self,
            f"确认保存{side_name}文件",
            (
                f"将覆盖保存{side_name}合并结果。\n\n"
                f"完整路径：{path}\n"
                f"编码：{enc}\n"
                f"换行：{newline_name}\n"
                f"变更侧：{side_name}\n\n"
                "确认后将写入原文件。"
            ),
            QtWidgets.QMessageBox.Save | QtWidgets.QMessageBox.Cancel,
            QtWidgets.QMessageBox.Cancel,
        )
        if answer != QtWidgets.QMessageBox.Save:
            return
        try:
            self._write_text_file(path, list(lines), str(enc), str(ending), trailing)
            self._compare_state[f"{which}_dirty"] = False
            self._refresh_compare_side_titles()
            QtWidgets.QMessageBox.information(self, "成功", "保存完成")
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", f"保存失败: {e}")

    def _browse_root(self) -> None:
        d = _qt_get_existing_dir(self, "选择根目录", self.root_dir_edit.text().strip() or os.getcwd())
        if d:
            self.root_dir_edit.setText(d)

    def _update_paths_state(self) -> None:
        root = self._get_root_path()
        if not root:
            self._set_root_status("未选择根目录", "empty")
            return
        config_path = os.path.join(root, "Config.ini")
        if os.path.exists(config_path):
            self._set_root_status(f"Config.ini：{config_path}", "valid")
        else:
            self._set_root_status(f"未找到：{config_path}", "missing")

    def _get_root_path(self) -> str:
        root = (self.root_dir_edit.text() or "").strip()
        root = root.replace("/", "\\")
        try:
            looks_like_path = ("\\" in root) or ("/" in root) or (len(root) >= 2 and root[1] == ":") or root.startswith("\\\\")
            if looks_like_path:
                normalized = _CallRestoreWorker._normalize_server_root(root)
                if normalized:
                    return normalized
        except Exception:
            pass
        return root

    def _toggle_dynamic_ip(self, checked: bool) -> None:
        if checked:
            self._saved_ip = self.ip_edit.text().strip()
            self.ip_edit.setText("127.0.0.1")
            self.ip_edit.setEnabled(False)
        else:
            self.ip_edit.setEnabled(True)
            if self._saved_ip:
                self.ip_edit.setText(self._saved_ip)

    def _make_port_edit(self) -> QtWidgets.QLineEdit:
        e = _make_ui_line_edit("number", "1-65535")
        e.setObjectName("portNumberEdit")
        e.setAccessibleName("端口号")
        e.setToolTip("请输入 1 到 65535 之间的端口号")
        e.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
        e.setValidator(QtGui.QIntValidator(1, 65535, self))
        self._all_port_edits.append(e)
        return e

    def _rebuild_run_gate_rows(self) -> None:
        for i in reversed(range(self.run_gate_grid.count())):
            item = self.run_gate_grid.takeAt(i)
            w = item.widget()
            if w:
                w.deleteLater()
        self._run_gate_port_edits = []
        self._run_gate_db_port_edits = []

        n = int(self.run_gate_count_spin.value())
        gate_header = QtWidgets.QLabel("游戏网关端口")
        gate_header.setObjectName("runGateSectionLabel")
        self.run_gate_grid.addWidget(gate_header, 0, 0, 1, 4)
        for i in range(n):
            lbl = QtWidgets.QLabel(f"GatePort{i+1}")
            lbl.setObjectName("runGateFieldLabel")
            edit = self._make_port_edit()
            edit.setAccessibleName(f"RunGate GatePort{i+1}")
            self._run_gate_port_edits.append(edit)
            row = 1 + (i // 2)
            col = (i % 2) * 2
            self.run_gate_grid.addWidget(lbl, row, col, 1, 1)
            self.run_gate_grid.addWidget(edit, row, col + 1, 1, 1)

        base_row = 1 + ((n - 1) // 2) + 1
        db_header = QtWidgets.QLabel("RunGate 连接 DBServer")
        db_header.setObjectName("runGateSectionLabel")
        self.run_gate_grid.addWidget(db_header, base_row, 0, 1, 4)
        for i in range(n):
            lbl = QtWidgets.QLabel(f"DBPort{i+1}")
            lbl.setObjectName("runGateFieldLabel")
            edit = self._make_port_edit()
            edit.setAccessibleName(f"RunGate DBPort{i+1}")
            self._run_gate_db_port_edits.append(edit)
            row = base_row + 1 + (i // 2)
            col = (i % 2) * 2
            self.run_gate_grid.addWidget(lbl, row, col, 1, 1)
            self.run_gate_grid.addWidget(edit, row, col + 1, 1, 1)

        self.run_gate_grid.setColumnStretch(0, 0)
        self.run_gate_grid.setColumnStretch(1, 1)
        self.run_gate_grid.setColumnStretch(2, 0)
        self.run_gate_grid.setColumnStretch(3, 1)

        self._update_auto_setup_state()

    def _update_auto_setup_state(self) -> None:
        enabled = self.auto_setup_cb.isChecked()
        for e in self._run_gate_db_port_edits:
            e.setEnabled(enabled)

    @staticmethod
    def _read_lines_any(path: str) -> tuple[list[str], str]:
        if not os.path.exists(path):
            raise RuntimeError("配置文件不存在")
        lines, enc, _ending, _trailing = _read_text_file_best_effort(path)
        return lines, enc

    @staticmethod
    def _default_ending(lines: list[str]) -> str:
        cnt_crlf = sum(1 for line in (lines or []) if isinstance(line, str) and line.endswith("\r\n"))
        cnt_cr = sum(1 for line in (lines or []) if isinstance(line, str) and line.endswith("\r") and not line.endswith("\r\n"))
        cnt_lf = sum(1 for line in (lines or []) if isinstance(line, str) and line.endswith("\n") and not line.endswith("\r\n"))
        if cnt_crlf >= cnt_cr and cnt_crlf >= cnt_lf and cnt_crlf > 0:
            return "\r\n"
        if cnt_cr >= cnt_lf and cnt_cr > 0:
            return "\r"
        if cnt_lf > 0:
            return "\n"
        return "\r\n"

    @staticmethod
    def _parse_ini(lines: list[str]) -> dict[str, dict[str, str]]:
        cfg: dict[str, dict[str, str]] = {}
        sec: str | None = None
        for line in lines:
            s = line.strip()
            if not s or s.startswith(";") or s.startswith("#"):
                continue
            if s.startswith("[") and s.endswith("]"):
                sec = s[1:-1]
                cfg.setdefault(sec, {})
                continue
            if sec and "=" in line:
                k, _, v = line.partition("=")
                cfg[sec][k.strip()] = v.strip()
        return cfg

    def _config_path(self) -> str:
        root = self._get_root_path()
        return os.path.join(root, "Config.ini") if root else ""

    def _load_from_config(self) -> None:
        root = self._get_root_path()
        if not root:
            if os.path.exists(os.path.join(os.getcwd(), "Config.ini")):
                self.root_dir_edit.setText(os.getcwd())
                root = self._get_root_path()
            else:
                QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
                return

        config_path = os.path.join(root, "Config.ini")
        if not os.path.exists(config_path):
            QtWidgets.QMessageBox.critical(self, "错误", "未找到 Config.ini 文件")
            return

        try:
            lines, _enc = self._read_lines_any(config_path)
            cfg = self._parse_ini(lines)

            lg = cfg.get("LoginGate", {})
            self.start_port_edit.setText(lg.get("GatePort", lg.get("GatePort1", "")))

            sg = cfg.get("SelGate", {})
            self.sel_gate_1_edit.setText(sg.get("GatePort", ""))
            self.sel_gate_2_edit.setText(sg.get("GatePort1", ""))

            rg = cfg.get("RunGate", {})
            try:
                cnt = int(str(rg.get("Count", "")).strip() or "4")
                cnt = max(1, min(8, cnt))
            except Exception:
                cnt = 4
            self.run_gate_count_spin.setValue(cnt)
            self.run_gate_thread_cb.setChecked(str(rg.get("GetMultiThread", "0")).strip() == "1")
            for i, e in enumerate(self._run_gate_port_edits):
                e.setText(rg.get(f"GatePort{i+1}", ""))
            for i, e in enumerate(self._run_gate_db_port_edits):
                e.setText(rg.get(f"DBPort{i+1}", ""))

            m2 = cfg.get("M2Server", {})
            self.m2_connect_port_edit.setText(m2.get("GatePort", ""))
            self.m2_msg_port_edit.setText(m2.get("MsgSrvPort", ""))

            ls = cfg.get("LoginServer", {})
            self.ls_connect_port_edit.setText(ls.get("GatePort", ""))
            self.ls_msg_port_edit.setText(ls.get("ServerPort", ""))

            logs = cfg.get("LogServer", {})
            self.log_service_port_edit.setText(logs.get("Port", ""))
            self.log_enabled_cb.setChecked(str(logs.get("GetStart", "1")).strip() != "0")
            use_tcp = str(logs.get("LogUseTcpSocket", "0")).strip() == "1"
            self.log_proto_tcp.setChecked(use_tcp)
            self.log_proto_udp.setChecked(not use_tcp)

            dbs = cfg.get("DBServer", {})
            self.db_connect_port_edit.setText(dbs.get("GatePort", ""))
            self.db_msg_port_edit.setText(dbs.get("ServerPort", ""))

            gc = cfg.get("GameConf", {})
            self.game_name_edit.setText(gc.get("GameName", ""))
            ip = gc.get("ExtIPaddr", "")
            if self.dynamic_ip_cb.isChecked():
                self._saved_ip = ip
                self.ip_edit.setText("127.0.0.1")
                self.ip_edit.setEnabled(False)
            else:
                self.ip_edit.setText(ip)

            self._update_paths_state()
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", f"读取配置失败: {e}")

    def _generate_ports(self) -> None:
        try:
            start_port = int(self.start_port_edit.text().strip())
        except Exception:
            QtWidgets.QMessageBox.critical(self, "错误", "请输入有效的起始端口数字")
            return

        current_port = start_port
        self.start_port_edit.setText(str(current_port))
        current_port += 1

        self.sel_gate_1_edit.setText(str(current_port))
        current_port += 1
        self.sel_gate_2_edit.setText(str(current_port))
        current_port += 1

        for e in self._run_gate_port_edits:
            e.setText(str(current_port))
            current_port += 1

        self.m2_connect_port_edit.setText(str(current_port))
        current_port += 1
        self.m2_msg_port_edit.setText(str(current_port))
        current_port += 1

        self.ls_connect_port_edit.setText(str(current_port))
        current_port += 1
        self.ls_msg_port_edit.setText(str(current_port))
        current_port += 1

        for e in self._run_gate_db_port_edits:
            e.setText(str(current_port))
            current_port += 1

        self.log_service_port_edit.setText(str(current_port))
        current_port += 1

        self.db_connect_port_edit.setText(str(current_port))
        current_port += 1
        self.db_msg_port_edit.setText(str(current_port))

    def _reset_port_edit_style(self) -> None:
        alive: list[QtWidgets.QLineEdit] = []
        is_valid = None
        try:
            from shiboken6 import isValid as _is_valid

            is_valid = _is_valid
        except Exception:
            is_valid = None

        for e in self._all_port_edits:
            if e is None:
                continue
            if callable(is_valid) and not is_valid(e):
                continue
            try:
                self._set_port_edit_validation_state(e, "")
                alive.append(e)
            except RuntimeError:
                continue
            except Exception:
                alive.append(e)
        self._all_port_edits = alive

    @staticmethod
    def _set_port_edit_validation_state(edit: QtWidgets.QLineEdit, state: str) -> None:
        if edit is None:
            return
        edit.setProperty("validationState", state if state in {"error", "success"} else "")
        try:
            edit.style().unpolish(edit)
            edit.style().polish(edit)
            edit.update()
        except Exception:
            pass

    def _try_bind(self, port: int) -> bool:
        s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        try:
            s.bind(("0.0.0.0", port))
            return True
        except Exception:
            return False
        finally:
            try:
                s.close()
            except Exception:
                pass

    def _collect_ports(self) -> list[tuple[str, int, QtWidgets.QLineEdit]]:
        items: list[tuple[str, int, QtWidgets.QLineEdit]] = []
        is_valid = None
        try:
            from shiboken6 import isValid as _is_valid

            is_valid = _is_valid
        except Exception:
            is_valid = None

        def add(label: str, edit: QtWidgets.QLineEdit) -> None:
            if edit is None:
                return
            if callable(is_valid) and not is_valid(edit):
                return
            t = edit.text().strip()
            if not t:
                return
            try:
                p = int(t)
            except Exception:
                return
            if 1 <= p <= 65535:
                items.append((label, p, edit))

        add("LoginGate", self.start_port_edit)
        add("SelGate1", self.sel_gate_1_edit)
        add("SelGate2", self.sel_gate_2_edit)
        for i, e in enumerate(self._run_gate_port_edits, start=1):
            add(f"RunGate GatePort{i}", e)
        add("M2 Connect", self.m2_connect_port_edit)
        add("M2 Msg", self.m2_msg_port_edit)
        add("LoginSrv Connect", self.ls_connect_port_edit)
        add("LoginSrv Msg", self.ls_msg_port_edit)
        for i, e in enumerate(self._run_gate_db_port_edits, start=1):
            add(f"RunGate DBPort{i}", e)
        add("LogServer", self.log_service_port_edit)
        add("DB Connect", self.db_connect_port_edit)
        add("DB Msg", self.db_msg_port_edit)
        return items

    def _check_ports(self) -> None:
        self._reset_port_edit_style()
        items = self._collect_ports()
        if not items:
            QtWidgets.QMessageBox.information(self, "提示", "没有可检测的端口")
            return

        occupied: list[str] = []
        is_valid = None
        try:
            from shiboken6 import isValid as _is_valid

            is_valid = _is_valid
        except Exception:
            is_valid = None
        for label, port, edit in items:
            if callable(is_valid) and not is_valid(edit):
                continue
            ok = self._try_bind(port)
            if not ok:
                occupied.append(f"{label}: {port}")
                try:
                    self._set_port_edit_validation_state(edit, "error")
                except Exception:
                    pass
            else:
                try:
                    self._set_port_edit_validation_state(edit, "success")
                except Exception:
                    pass

        if occupied:
            QtWidgets.QMessageBox.warning(self, "占用提示", "以下端口可能已被占用：\n" + "\n".join(occupied))
        else:
            QtWidgets.QMessageBox.information(self, "提示", "端口检测完成，未发现占用")

    @staticmethod
    def _backup_file(path: str) -> None:
        try:
            bak = path + ".bak"
            shutil.copy2(path, bak)
        except Exception:
            return

    @staticmethod
    def _join_by_keyword(old_val: str, root_path: str, keywords: list[str]) -> str:
        low = old_val.lower().replace("/", "\\")
        for kw in keywords:
            idx = low.find(kw)
            if idx != -1:
                suffix = old_val[idx + 1 :]
                suffix = suffix.replace("/", "\\")
                return os.path.join(root_path, suffix)
        return old_val

    @staticmethod
    def _port_settings_file_paths(root_path: str) -> list[str]:
        return [
            os.path.join(root_path, "Config.ini"),
            os.path.join(root_path, "Mir200", "!setup.txt"),
            os.path.join(root_path, "LoginSrv", "Logsrv.ini"),
            os.path.join(root_path, "DBServer", "dbsrc.ini"),
            os.path.join(root_path, "LogServer", "dbsrc.ini"),
            os.path.join(root_path, "LogServer", "LogData.ini"),
            os.path.join(root_path, "LoginGate", "dbsrc.ini"),
            os.path.join(root_path, "LoginGate", "Config.ini"),
            os.path.join(root_path, "RunGate", "RunGate.ini"),
            os.path.join(root_path, "SelGate", "Config.ini"),
        ]

    @classmethod
    def _capture_port_settings_files(cls, root_path: str) -> dict[str, bytes | None]:
        snapshot: dict[str, bytes | None] = {}
        for path in cls._port_settings_file_paths(root_path):
            for candidate in (path, path + ".bak"):
                snapshot[candidate] = Path(candidate).read_bytes() if os.path.isfile(candidate) else None
        return snapshot

    @staticmethod
    def _restore_port_settings_files(snapshot: dict[str, bytes | None]) -> None:
        for path, raw in snapshot.items():
            target = Path(path)
            if raw is None:
                if target.exists():
                    target.unlink()
                continue
            target.parent.mkdir(parents=True, exist_ok=True)
            fd, temp_path = tempfile.mkstemp(prefix=".ports-rollback-", suffix=".tmp", dir=str(target.parent))
            try:
                with os.fdopen(fd, "wb") as stream:
                    stream.write(raw)
                    stream.flush()
                    os.fsync(stream.fileno())
                os.replace(temp_path, str(target))
                temp_path = ""
            finally:
                if temp_path:
                    try:
                        os.unlink(temp_path)
                    except Exception:
                        pass

    def _save_all(self) -> None:
        root_path = self._get_root_path()
        if not root_path:
            QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
            return

        config_path = os.path.join(root_path, "Config.ini")
        if not os.path.exists(config_path):
            QtWidgets.QMessageBox.critical(self, "错误", "未找到 Config.ini 文件")
            return

        answer = QtWidgets.QMessageBox.question(
            self,
            "确认保存",
            "将更新端口与相关服务配置，是否继续？",
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
            QtWidgets.QMessageBox.No,
        )
        if answer != QtWidgets.QMessageBox.Yes:
            return

        transaction_snapshot: dict[str, bytes | None] = {}
        try:
            transaction_snapshot = self._capture_port_settings_files(root_path)
            run_gate_count = str(int(self.run_gate_count_spin.value()))
            use_multi_thread = "1" if self.run_gate_thread_cb.isChecked() else "0"
            log_start = "1" if self.log_enabled_cb.isChecked() else "0"
            log_proto_tcp = self.log_proto_tcp.isChecked()

            data_map: dict[str, dict[str, str]] = {
                "LoginGate": {"GatePort": self.start_port_edit.text().strip(), "GatePort1": self.start_port_edit.text().strip()},
                "SelGate": {"GatePort": self.sel_gate_1_edit.text().strip(), "GatePort1": self.sel_gate_2_edit.text().strip()},
                "RunGate": {"Count": run_gate_count, "GetMultiThread": use_multi_thread},
                "M2Server": {"GatePort": self.m2_connect_port_edit.text().strip(), "MsgSrvPort": self.m2_msg_port_edit.text().strip()},
                "LoginServer": {"GatePort": self.ls_connect_port_edit.text().strip(), "ServerPort": self.ls_msg_port_edit.text().strip()},
                "LogServer": {"Port": self.log_service_port_edit.text().strip(), "GetStart": log_start},
                "DBServer": {"GatePort": self.db_connect_port_edit.text().strip(), "ServerPort": self.db_msg_port_edit.text().strip()},
                "GameConf": {"ExtIPaddr": self.ip_edit.text().strip(), "GameName": self.game_name_edit.text().strip()},
            }

            if log_proto_tcp:
                data_map["LogServer"]["LogUseTcpSocket"] = "1"
                data_map["LogServer"]["GetMinimize"] = "0"
            else:
                data_map["LogServer"]["GetMinimize"] = "1"
                data_map["LogServer"]["LogUseTcpSocket"] = "0"

            for i, e in enumerate(self._run_gate_port_edits):
                data_map["RunGate"][f"GatePort{i+1}"] = e.text().strip()
            if self.auto_setup_cb.isChecked():
                for i, e in enumerate(self._run_gate_db_port_edits):
                    data_map["RunGate"][f"DBPort{i+1}"] = e.text().strip()

            self._backup_file(config_path)
            lines, enc = self._read_lines_any(config_path)
            default_ending = self._default_ending(lines)

            new_lines: list[str] = []
            current_section: str | None = None
            remaining_data = {k: v.copy() for k, v in data_map.items()}

            backup_sections = ["BackUp_DBServer", "BackUp_LoginSrv", "BackUp_M2Server", "BackUp_M2Server_GuildBase", "BackUp_M2Server_Castle"]

            for line in lines:
                sline = line.strip()
                if sline.startswith("[") and sline.endswith("]"):
                    if current_section in remaining_data and remaining_data[current_section]:
                        for k, v in remaining_data[current_section].items():
                            new_lines.append(f"{k}={v}{default_ending}")
                        del remaining_data[current_section]
                    current_section = sline[1:-1]
                    new_lines.append(line)
                    continue

                if current_section == "GameConf" and "=" in line:
                    key_part, _, val_part = line.partition("=")
                    key = key_part.strip()
                    if key == "GameDirectory":
                        new_val = root_path
                        if not new_val.endswith("\\"):
                            new_val += "\\"
                        ending = "\r\n" if line.endswith("\r\n") else ("\r" if line.endswith("\r") else "\n")
                        new_lines.append(f"{key_part}={new_val}{ending}")
                        continue
                    if key in ["SqliteDBFile", "SqliteDBName"]:
                        old_val = val_part.strip()
                        new_val = self._join_by_keyword(old_val, root_path, ["\\mud2\\", "\\mir200\\"])
                        ending = "\r\n" if line.endswith("\r\n") else ("\r" if line.endswith("\r") else "\n")
                        new_lines.append(f"{key_part}={new_val}{ending}")
                        continue

                if current_section in backup_sections and "=" in line:
                    key_part, _, val_part = line.partition("=")
                    key = key_part.strip()
                    if key == "SaveDirectory":
                        old_val = val_part.strip()
                        new_val = self._join_by_keyword(old_val, root_path, ["\\数据备份\\"])
                        ending = "\r\n" if line.endswith("\r\n") else ("\r" if line.endswith("\r") else "\n")
                        new_lines.append(f"{key_part}={new_val}{ending}")
                        continue

                replaced = False
                if current_section in remaining_data and "=" in line:
                    key_part, _, _val_part = line.partition("=")
                    key = key_part.strip()
                    if key in remaining_data[current_section]:
                        new_val = remaining_data[current_section][key]
                        ending = "\r\n" if line.endswith("\r\n") else ("\r" if line.endswith("\r") else "\n")
                        new_lines.append(f"{key_part}={new_val}{ending}")
                        del remaining_data[current_section][key]
                        replaced = True

                if not replaced:
                    new_lines.append(line)

            if current_section in remaining_data and remaining_data[current_section]:
                for k, v in remaining_data[current_section].items():
                    new_lines.append(f"{k}={v}{default_ending}")
                del remaining_data[current_section]

            for section, keys in remaining_data.items():
                if keys:
                    new_lines.append(f"[{section}]{default_ending}")
                    for k, v in keys.items():
                        new_lines.append(f"{k}={v}{default_ending}")

            with open(config_path, "w", encoding=enc, newline="") as f:
                f.writelines(new_lines)

            self._update_other_files(root_path)
            QtWidgets.QMessageBox.information(self, "成功", "配置保存成功")
        except Exception as e:
            rollback_error = ""
            if transaction_snapshot:
                try:
                    self._restore_port_settings_files(transaction_snapshot)
                except Exception as restore_error:
                    rollback_error = f"；回滚失败: {restore_error}"
            QtWidgets.QMessageBox.critical(self, "错误", f"保存配置失败: {e}{rollback_error}")

    def _update_other_files(self, root_path: str) -> None:
        game_name = self.game_name_edit.text().strip()
        start_port = self.start_port_edit.text().strip()
        sel_gate_1 = self.sel_gate_1_edit.text().strip()
        m2_connect = self.m2_connect_port_edit.text().strip()
        m2_msg = self.m2_msg_port_edit.text().strip()
        ls_connect = self.ls_connect_port_edit.text().strip()
        ls_msg = self.ls_msg_port_edit.text().strip()
        log_port = self.log_service_port_edit.text().strip()
        db_connect = self.db_connect_port_edit.text().strip()
