class _ScriptInjectPage(QtWidgets.QWidget):
    def __init__(self, get_session, get_root_dir=None) -> None:
        super().__init__()
        self._get_session = get_session
        self._get_root_dir = get_root_dir
        self._store_path = self._get_store_path()
        self._templates: list[dict] = []
        self._current_name: str | None = None
        self._worker_thread: QtCore.QThread | None = None
        self._worker = None
        self._build()
        self._reload()

    @staticmethod
    def _get_data_dir() -> str:
        base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or os.path.expanduser("~")
        return os.path.join(base, "XiamiToolbox")

    @classmethod
    def _get_store_path(cls) -> str:
        # Resolving the path must be read-only.  Directory creation and legacy
        # migration belong to an explicit template mutation, never page load.
        try:
            return os.path.join(cls._get_data_dir(), "script_templates_store.json")
        except Exception:
            return os.path.join(os.path.abspath("."), "script_templates_store.json")

    @staticmethod
    def _store_style(path: str) -> tuple[str, str, bool]:
        """Return encoding, newline and trailing-newline state without writing."""
        try:
            raw = open(path, "rb").read() if path and os.path.isfile(path) else b""
        except Exception:
            raw = b""
        bom = raw.startswith(b"\xef\xbb\xbf")
        body = raw[3:] if bom else raw
        encoding = "utf-8"
        for candidate in (("utf-8",) if bom else ("utf-8", "gb18030", "gbk")):
            try:
                body.decode(candidate)
                encoding = candidate
                break
            except Exception:
                continue
        if b"\r\n" in body:
            newline = "\r\n"
        elif b"\r" in body:
            newline = "\r"
        else:
            newline = "\n"
        trailing = body.endswith((b"\r\n", b"\r", b"\n"))
        return ("utf-8-sig" if bom and encoding == "utf-8" else encoding, newline, trailing)

    @classmethod
    def _migrate_store_if_needed(cls, path: str) -> None:
        if path and os.path.exists(path):
            return
        candidates = [os.path.join(os.path.abspath("."), "script_templates_store.json")]
        try:
            exe_dir = os.path.dirname(os.path.abspath(sys.argv[0]))
            candidates.append(os.path.join(exe_dir, "script_templates_store.json"))
        except Exception:
            pass
        for candidate in candidates:
            if candidate and os.path.isfile(candidate) and os.path.abspath(candidate) != os.path.abspath(path):
                try:
                    raw = open(candidate, "rb").read()
                    os.makedirs(os.path.dirname(path), exist_ok=True)
                    fd, tmp = tempfile.mkstemp(prefix=".script_templates_store.", suffix=".tmp", dir=os.path.dirname(path))
                    try:
                        with os.fdopen(fd, "wb") as stream:
                            stream.write(raw)
                            stream.flush()
                            os.fsync(stream.fileno())
                        os.replace(tmp, path)
                        tmp = ""
                    finally:
                        if tmp:
                            try:
                                os.unlink(tmp)
                            except Exception:
                                pass
                except Exception:
                    pass
                return

    @staticmethod
    def _read_store(path: str) -> dict:
        if not path or not os.path.exists(path):
            return {"templates": []}
        last_err: Exception | None = None
        for enc in ("utf-8-sig", "utf-8", "gbk", "gb18030"):
            try:
                with open(path, "r", encoding=enc) as f:
                    data = json.load(f)
                if isinstance(data, list):
                    data = {"templates": data}
                if not isinstance(data, dict):
                    return {"templates": []}
                if not isinstance(data.get("templates", None), list):
                    data["templates"] = []
                return data
            except Exception as e:
                last_err = e
                continue
        _ = last_err
        return {"templates": []}

    @staticmethod
    def _write_store(path: str, store: dict) -> bool:
        if not path:
            return False
        original = b""
        try:
            if os.path.isfile(path):
                original = open(path, "rb").read()
        except Exception:
            return False
        try:
            parent = os.path.dirname(os.path.abspath(path))
            os.makedirs(parent, exist_ok=True)
            encoding, newline, trailing = _ScriptInjectPage._store_style(path)
            text = json.dumps(store, ensure_ascii=False, indent=2, sort_keys=False)
            if newline != "\n":
                text = text.replace("\n", newline)
            if trailing:
                text += newline
            codec = "utf-8" if encoding == "utf-8-sig" else encoding
            raw = text.encode(codec, "strict")
            if encoding == "utf-8-sig":
                raw = b"\xef\xbb\xbf" + raw
            fd, tmp = tempfile.mkstemp(prefix=".script_templates_store.", suffix=".tmp", dir=parent)
            try:
                with os.fdopen(fd, "wb") as stream:
                    stream.write(raw)
                    stream.flush()
                    os.fsync(stream.fileno())
                os.replace(tmp, path)
                tmp = ""
            finally:
                if tmp:
                    try:
                        os.unlink(tmp)
                    except Exception:
                        pass
            if open(path, "rb").read() != raw:
                raise IOError("模板库提交后校验失败")
            return True
        except Exception:
            if original:
                try:
                    parent = os.path.dirname(os.path.abspath(path))
                    fd, tmp = tempfile.mkstemp(prefix=".script_templates_store.rollback.", suffix=".tmp", dir=parent)
                    with os.fdopen(fd, "wb") as stream:
                        stream.write(original)
                        stream.flush()
                        os.fsync(stream.fileno())
                    os.replace(tmp, path)
                except Exception:
                    try:
                        if 'tmp' in locals() and tmp:
                            os.unlink(tmp)
                    except Exception:
                        pass
            return False

    @staticmethod
    def _normalize_space(s: str) -> str:
        if not isinstance(s, str):
            return str(s)
        s = s.replace("\u00A0", " ").replace("\u3000", " ")
        return re.sub(r"[ \t]+", " ", s.strip())

    @staticmethod
    def _normalize_extra_params(extra: object) -> dict:
        if not isinstance(extra, dict):
            base: dict = {}
        else:
            base = dict(extra)
        add_position = str(base.get("add_position") or base.get("add_method") or "").strip()
        root_type = str(base.get("root_type") or base.get("root") or "").strip()
        replace_var = str(base.get("replace_var") or base.get("replace_vars") or "").strip()
        replace_method = str(base.get("replace_method") or base.get("replace_mode") or "").strip()

        if add_position not in ("前", "后"):
            add_position = "后"
        if not root_type:
            root_type = "Envir(默认)"
        meta_prefixes = ("替换变量:", "替换方式:", "根目录类型:", "追加方式:", "追加位置:", "内容:")
        if replace_var in meta_prefixes or any(str(replace_var).startswith(p) for p in meta_prefixes):
            replace_var = ""
        if replace_method in meta_prefixes or any(str(replace_method).startswith(p) for p in meta_prefixes):
            replace_method = ""

        base["add_position"] = add_position
        base["root_type"] = root_type
        base["replace_var"] = replace_var
        base["replace_method"] = replace_method
        return base

    @staticmethod
    def _extract_item_from_embedded_template(it: dict) -> dict | None:
        if not isinstance(it, dict):
            return None
        content = str(it.get("content") or it.get("text") or "")
        raw = content.lstrip("\ufeff").strip()
        if not raw:
            return None
        has_block_marker = any(
            str(line or "").strip().startswith("===")
            and str(line or "").strip().endswith("===")
            and "脚本" in str(line or "")
            for line in raw.splitlines()
        )
        has_meta = (
            ("类型:" in raw and "文件:" in raw and "内容:" in raw)
            or ("追加方式:" in raw)
            or ("根目录类型:" in raw)
        )
        if not has_block_marker and not has_meta:
            return None
        parsed, _ = _ScriptInjectPage._parse_legacy_items_text(raw)
        if not parsed:
            return None
        first = _ScriptInjectPage._normalize_item(parsed[0] if parsed else None)
        if not first:
            return None
        if not str(first.get("address") or "").strip():
            first["address"] = str(it.get("address") or "").strip()
        if not str(first.get("keyword") or "").strip():
            first["keyword"] = str(it.get("keyword") or "").strip()
        return first

    @staticmethod
    def _is_abs_dir_path(path: str) -> bool:
        p = str(path or "").strip()
        if not p:
            return False
        try:
            return os.path.isabs(p)
        except Exception:
            return False

    @classmethod
    def _normalize_script_address(cls, address: object) -> str:
        raw = str(address or "").strip()
        if not raw:
            return ""

        has_drive = bool(re.match(r"^[A-Za-z]:[\\/]", raw))
        is_unc = raw.startswith("\\\\")
        normalized = raw.replace("/", "\\")
        while "\\\\" in normalized and not normalized.startswith("\\\\"):
            normalized = normalized.replace("\\\\", "\\")

        if not (has_drive or is_unc):
            normalized = normalized.lstrip("\\")

        parts = [part for part in normalized.split("\\") if part != ""]
        if not parts:
            return ""

        segment_map = {
            "mir200": "Mir200",
            "envir": "Envir",
            "mapquest_def": "MapQuest_def",
            "market_def": "Market_Def",
            "questdiary": "QuestDiary",
            "mud2": "Mud2",
        }
        file_map = {
            "qfunction-0.txt": "QFunction-0.txt",
            "qmanage.txt": "QManage.txt",
            "login.txt": "Login.txt",
            "effectimagelist.txt": "EffectImageList.txt",
        }

        normalized_parts: list[str] = []
        for idx, part in enumerate(parts):
            low = part.lower()
            if idx == len(parts) - 1 and low in file_map:
                normalized_parts.append(file_map[low])
            elif low in segment_map:
                normalized_parts.append(segment_map[low])
            else:
                normalized_parts.append(part)

        if has_drive:
            return "\\".join(normalized_parts)
        if is_unc:
            return "\\\\" + "\\".join(normalized_parts)
        return "\\".join(normalized_parts)

    @classmethod
    def _normalize_item(cls, it: object) -> dict | None:
        if not isinstance(it, dict):
            return None
        embedded = cls._extract_item_from_embedded_template(it)
        if embedded is not None:
            return embedded
        inj_type = str(it.get("type") or it.get("inject_type") or it.get("kind") or "").strip()
        if not inj_type:
            inj_type = "追加"
        address = str(
            it.get("address")
            or it.get("file")
            or it.get("file_path")
            or it.get("path")
            or it.get("filepath")
            or ""
        ).strip()
        address = cls._normalize_script_address(address)
        keyword = str(it.get("keyword") or it.get("tag") or "").strip()
        if any(x in keyword for x in ("追加方式:", "追加位置:", "根目录类型:", "替换变量:", "替换方式:", "内容:")):
            keyword = ""
        content = it.get("content")
        if content is None:
            content = it.get("text")
        content = str(content or "")
        extra_params = cls._normalize_extra_params(it.get("extra_params", None) or it.get("extra", None))

        return {"type": inj_type, "address": address, "keyword": keyword, "content": content, "extra_params": extra_params}

    @classmethod
    def _normalize_items(cls, items: object) -> list[dict]:
        if not isinstance(items, list):
            return []
        out: list[dict] = []
        for it in items:
            norm = cls._normalize_item(it)
            if norm is not None:
                out.append(norm)
        return out

    @staticmethod
    def _items_to_text(items: list[dict]) -> str:
        lines: list[str] = []
        try:
            ts = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            ts = ""
        lines.append(f"模板TXT导出时间: {ts}".rstrip())
        lines.append("")
        idx = 1
        for it in items or []:
            if not isinstance(it, dict):
                continue
            lines.append(f"=== 脚本 {idx} ===")
            inj_type = str(it.get("type") or "").strip()
            lines.append(f"类型: {inj_type}")
            lines.append(f"文件: {str(it.get('address') or '').strip()}")
            keyword = str(it.get("keyword") or "").strip()
            lines.append(f"关键字: {keyword}")
            extra = it.get("extra_params", {}) or {}
            if isinstance(extra, dict):
                if inj_type == "复制":
                    src = str(extra.get("source_path") or keyword or "").strip()
                    obj_type = str(extra.get("obj_type") or "文件").strip() or "文件"
                    rep = str(extra.get("replace_file") or "替换").strip() or "替换"
                    lines.append(f"复制对象: {src}")
                    lines.append(f"对象类型: {obj_type}")
                    lines.append(f"替换文件: {rep}")
                lines.append(f"追加方式: {str(extra.get('add_position') or '').strip()}")
                lines.append(f"根目录类型: {str(extra.get('root_type') or '').strip()}")
                lines.append(f"替换变量: {str(extra.get('replace_var') or '').strip()}")
                lines.append(f"替换方式: {str(extra.get('replace_method') or '').strip()}")
            lines.append("内容:")
            content = str(it.get("content") or "")
            if content:
                lines.extend([x.rstrip("\r") for x in content.split("\n")])
            lines.append("")
            idx += 1
        return "\n".join(lines).rstrip() + "\n"

    @staticmethod
    def _parse_items_text(text: str) -> tuple[list[dict] | None, str]:
        raw = (text or "").lstrip("\ufeff").strip()
        if not raw:
            return [], ""
        items, _ = _ScriptInjectPage._parse_legacy_items_text(raw)
        if items is not None:
            return _ScriptInjectPage._normalize_items(items), ""
        raw_upper = raw.upper()
        looks_like_script_body = bool(
            ("\n" in raw)
            and (
                ("#IF" in raw_upper)
                or ("#ACT" in raw_upper)
                or ("#SAY" in raw_upper)
                or ("#CALL" in raw_upper)
                or ("[@".upper() in raw_upper)
                or ("#ELSEACT" in raw_upper)
            )
        )
        if looks_like_script_body:
            return (
                [
                    _ScriptInjectPage._wrap_script_body_as_item(raw)
                ],
                "",
            )
        try:
            data = json.loads(raw)
        except Exception as e:
            if (
                ("\n" in raw)
                or ("#IF" in raw.upper())
                or ("#ACT" in raw.upper())
                or ("#SAY" in raw.upper())
                or ("[@" in raw)
                or (not raw.startswith("{") and not raw.startswith("["))
            ):
                return None, "未识别为脚本注入模板格式，请使用“导出 TXT”生成的模板，或导入有效的 JSON/TXT 模板。"

            return None, f"解析失败：{e}"
        if isinstance(data, dict) and isinstance(data.get("items", None), list):
            data = data.get("items", [])
        if not isinstance(data, list):
            return None, "模板内容必须是TXT模板或JSON数组(list)/items数组"
        items2 = _ScriptInjectPage._normalize_items(data)
        return items2, ""

    @staticmethod
    def _parse_exported_items_text(text: str) -> list[dict]:
        raw = str(text or "").replace("\r\n", "\n").replace("\r", "\n").lstrip("\ufeff")
        if not raw.strip():
            return []

        def _is_block_marker(line: str) -> bool:
            s = str(line or "").strip()
            if not s or not s.startswith("===") or not s.endswith("==="):
                return False
            if "脚本" in s:
                return True
            return bool(re.search(r"\d+", s))

        def _after_prefix(line: str, prefixes: tuple[str, ...]) -> str:
            s = str(line or "").strip()
            for p in prefixes:
                if s.startswith(p):
                    return s[len(p):].strip()
            return ""

        meta_map = {
            "type": ("类型:",),
            "address": ("文件:", "文件名/路径:", "地址:"),
            "keyword": ("关键字:",),
            "copy_source": ("复制对象:", "源路径/源文件/源目录:"),
            "copy_obj_type": ("对象类型:",),
            "copy_replace_file": ("替换文件:",),
            "add_position": ("追加方式:", "追加位置:"),
            "root_type": ("根目录类型:",),
            "replace_var": ("替换变量:",),
            "replace_method": ("替换方式:",),
            "content": ("内容:",),
        }

        lines = raw.split("\n")
        blocks: list[list[str]] = []
        current: list[str] = []
        for line in lines:
            if _is_block_marker(line):
                if current:
                    blocks.append(current)
                current = [line]
                continue
            if current:
                current.append(line)
        if current:
            blocks.append(current)

        items: list[dict] = []
        for block in blocks:
            item = _ScriptInjectPage._parse_exported_item_block(block)
            if item is not None:
                items.append(item)
        return items

    @staticmethod
    def _parse_exported_item_block(block: list[str]) -> dict | None:
        if not block:
            return None
        try:
            def _after_prefix(line: str, prefixes: tuple[str, ...]) -> str:
                s = str(line or "").strip()
                for p in prefixes:
                    if s.startswith(p):
                        return s[len(p):].strip()
                return ""

            meta_map = {
                "type": ("类型:",),
                "address": ("文件:", "文件名/路径:", "地址:"),
                "keyword": ("关键字:",),
                "copy_source": ("复制对象:", "源路径/源文件/源目录:"),
                "copy_obj_type": ("对象类型:",),
                "copy_replace_file": ("替换文件:",),
                "add_position": ("追加方式:", "追加位置:"),
                "root_type": ("根目录类型:",),
                "replace_var": ("替换变量:",),
                "replace_method": ("替换方式:",),
                "content": ("内容:",),
            }

            if not block:
                return None
            inj_type = ""
            address = ""
            keyword_raw = ""
            copy_source = ""
            copy_obj_type = ""
            copy_replace_file = ""
            add_position = ""
            root_type = ""
            replace_var = ""
            replace_method = ""
            content_lines: list[str] = []
            in_content = False

            body_lines = block[1:] if str(block[0] or "").strip().startswith("===") else block
            for line in body_lines:
                if in_content:
                    content_lines.append(str(line or "").rstrip("\r"))
                    continue
                hit = False
                for key, prefixes in meta_map.items():
                    val = _after_prefix(line, prefixes)
                    if val == "" and not any(str(line or "").strip().startswith(p) for p in prefixes):
                        continue
                    hit = True
                    if key == "type":
                        inj_type = val
                    elif key == "address":
                        address = val
                    elif key == "keyword":
                        keyword_raw = val
                    elif key == "copy_source":
                        copy_source = val
                    elif key == "copy_obj_type":
                        copy_obj_type = val
                    elif key == "copy_replace_file":
                        copy_replace_file = val
                    elif key == "add_position":
                        add_position = val
                    elif key == "root_type":
                        root_type = val
                    elif key == "replace_var":
                        replace_var = val
                    elif key == "replace_method":
                        replace_method = val
                    elif key == "content":
                        in_content = True
                        if val:
                            content_lines.append(val)
                    break
                if not hit and not in_content:
                    continue

            extra_params = {
                "add_position": add_position or "后",
                "root_type": root_type or "Envir(默认)",
                "replace_var": replace_var or "",
                "replace_method": replace_method or "",
            }
            if str(inj_type or "").strip() == "复制" or copy_source or copy_obj_type or copy_replace_file:
                if copy_source:
                    extra_params["source_path"] = copy_source
                    keyword_raw = copy_source
                if copy_obj_type:
                    extra_params["obj_type"] = copy_obj_type
                if copy_replace_file:
                    extra_params["replace_file"] = copy_replace_file
                if not str(inj_type or "").strip():
                    inj_type = "复制"
            item = {
                "type": inj_type or "",
                "address": address or "",
                "keyword": (
                    ""
                    if any(x in keyword_raw for x in ("追加方式:", "追加位置:", "根目录类型:", "替换变量:", "替换方式:", "内容:"))
                    else keyword_raw
                ),
                "content": "\n".join(content_lines).rstrip(),
                "extra_params": extra_params,
            }
            return _ScriptInjectPage._normalize_item(item)
        except Exception:
            return None

    @staticmethod
    def _parse_legacy_items_text(text: str) -> tuple[list[dict] | None, str]:
        raw = (text or "").strip()
        if not raw:
            return [], ""
        try:
            parsed_items = _ScriptInjectPage._parse_exported_items_text(raw)
        except Exception:
            parsed_items = []
        if parsed_items:
            return parsed_items, ""

        blocks = re.split(r"^\s*===\s*脚本\s*\d+\s*===\s*$", raw, flags=re.MULTILINE)
        segments = [seg.strip() for seg in (blocks[1:] if len(blocks) > 1 else []) if str(seg or "").strip()]
        if not segments and re.search(r"===\s*脚本\s*\d+\s*===", raw):
            blocks = re.split(r"===\s*脚本\s*\d+\s*===", raw)
            segments = [seg.strip() for seg in (blocks[1:] if len(blocks) > 1 else []) if str(seg or "").strip()]
        if not segments:
            if re.search(r"^\s*(?:类型)\s*:\s*.+$", raw, flags=re.MULTILINE) and re.search(
                r"^\s*(?:文件|文件名/路径|地址)\s*:\s*.+$", raw, flags=re.MULTILINE
            ):
                segments = [raw]
        if not segments:
            if re.search(r"^\s*(?:模板TXT导出时间)\s*:\s*", raw, flags=re.MULTILINE):
                return [], ""
            return None, "未识别为脚本注入TXT模板"

        def pick(seg: str, pattern: str) -> str:
            m = re.search(pattern, seg, flags=re.IGNORECASE | re.MULTILINE)
            return (m.group(1).strip() if m else "")

        items: list[dict] = []
        for seg in segments:
            block_lines = [line.rstrip("\r") for line in str(seg or "").split("\n")]
            norm = _ScriptInjectPage._parse_exported_item_block(block_lines)
            if norm is not None:
                items.append(norm)

        return items, ""

    @staticmethod
    def _parse_single_file_legacy_import(file_path: str, text: str) -> list[dict]:
        filename = os.path.basename(file_path or "")
        default_path = filename
        lower_name = filename.lower()
        if lower_name == "qmanage.txt":
            default_path = r"MapQuest_def\QManage.txt"
        elif lower_name == "qfunction-0.txt":
            default_path = r"Market_Def\QFunction-0.txt"
        elif lower_name == "login.txt":
            default_path = r"MapQuest_def\QManage.txt"

        keyword = ""
        m = re.search(r"\[(@[^\]]+)\]", text or "")
        if m:
            keyword = m.group(0)

        extra = {
            "add_position": "后",
            "root_type": "Envir(默认)",
            "replace_var": "",
            "replace_method": "",
        }
        return [{"type": "追加", "address": default_path, "keyword": keyword, "content": (text or "").strip(), "extra_params": extra}]

    @staticmethod
    def _wrap_script_body_as_item(text: str) -> dict:
        raw = str(text or "").strip()
        upper = raw.upper()
        address = r"MapQuest_def\QManage.txt"
        keyword = ""
        timer_id = None
        m_login = re.search(r"\[\s*@Login\s*\]", raw, flags=re.IGNORECASE)
        if m_login:
            keyword = "[@Login]"
        m_timer_tag = re.search(r"\[\s*@OnTimer\s*(\d+)\s*\]", raw, flags=re.IGNORECASE)
        if m_timer_tag:
            timer_id = str(m_timer_tag.group(1) or "").strip()
            if timer_id:
                keyword = f"[@OnTimer{timer_id}]"
        if not timer_id:
            m_set_timer = re.search(r"\bSetOnTimer\s+(\d+)\b", raw, flags=re.IGNORECASE)
            if m_set_timer:
                timer_id = str(m_set_timer.group(1) or "").strip()
        if not keyword:
            m = re.search(r"\[\s*@([^\]]+)\]", raw, flags=re.IGNORECASE)
            if m:
                keyword = f"[@{str(m.group(1) or '').strip()}]"

        if ("QFUNCTION" in upper) or ("FUNC" in upper and "[@LOGIN]" not in upper and "[@ONTIMER" not in upper):
            address = r"Market_Def\QFunction-0.txt"
        elif ("[@LOGIN]" in upper) or ("SETONTIMER" in upper) or ("[@ONTIMER" in upper) or ("#CALL" in upper):
            address = r"MapQuest_def\QManage.txt"

        return {
            "type": "追加",
            "address": address,
            "keyword": keyword,
            "content": raw,
            "extra_params": {
                "add_position": "后",
                "root_type": "Envir(默认)",
                "replace_var": "",
                "replace_method": "",
            },
        }

    @staticmethod
    def _split_mixed_script_items(text: str) -> list[dict]:
        raw = str(text or "").lstrip("\ufeff").strip()
        if not raw:
            return []

        lines = raw.splitlines()
        marker_indexes: list[int] = []
        for idx, line in enumerate(lines):
            s = str(line or "").strip()
            if s.startswith("===") and s.endswith("===") and "脚本" in s:
                marker_indexes.append(idx)
        if not marker_indexes:
            return [_ScriptInjectPage._wrap_script_body_as_item(raw)]

        items: list[dict] = []

        def append_script_chunk(chunk: str) -> None:
            s = str(chunk or "").strip()
            if not s:
                return
            if re.search(r"(?im)(^\s*#(?:IF|ACT|SAY|CALL|ELSEACT)\b|\[\s*@[^]\r\n]+\]|^\s*SetOnTimer\s+\d+\b)", s):
                items.append(_ScriptInjectPage._wrap_script_body_as_item(s))

        prefix = "\n".join(lines[: marker_indexes[0]]).strip()
        append_script_chunk(prefix)

        for pos, start_line in enumerate(marker_indexes):
            end_line = marker_indexes[pos + 1] if pos + 1 < len(marker_indexes) else len(lines)
            block = "\n".join(lines[start_line:end_line]).strip()
            if not block:
                continue
            parsed, _ = _ScriptInjectPage._parse_legacy_items_text(block)
            if parsed:
                items.extend(_ScriptInjectPage._normalize_items(parsed))
            else:
                append_script_chunk(block)

        return items

    @staticmethod
    def _parse_items_text_relaxed(text: str) -> tuple[list[dict] | None, str]:
        raw = str(text or "").lstrip("\ufeff").strip()
        if any(
            str(line or "").strip().startswith("===")
            and str(line or "").strip().endswith("===")
            and "脚本" in str(line or "")
            for line in raw.splitlines()
        ):
            split_items = _ScriptInjectPage._split_mixed_script_items(raw)
            if split_items:
                return _ScriptInjectPage._normalize_items(split_items), ""
        items, err = _ScriptInjectPage._parse_items_text(raw)
        if items is not None:
            return items, err
        looks_like_script_body = bool(
            raw
            and re.search(
                r"(?im)(^\s*#(?:IF|ACT|SAY|CALL|ELSEACT)\b|\[\s*@[^]\r\n]+\]|^\s*SetOnTimer\s+\d+\b)",
                raw,
            )
        )
        if looks_like_script_body:
            return [_ScriptInjectPage._wrap_script_body_as_item(raw)], ""
        return None, err

    @staticmethod
    def _looks_like_nonempty_template_text(text: str) -> bool:
        raw = str(text or "").strip()
        if not raw:
            return False
        raw_wo_header = re.sub(r"(?im)^\s*(?:模板TXT导出时间)\s*:[^\n]*\n?", "", raw).strip()
        if not raw_wo_header:
            return False
        if re.search(r"^\s*===\s*.*\d+\s*===\s*$", raw, flags=re.MULTILINE):
            return True
        if re.search(r"^\s*(?:类型|文件|文件名/路径|地址|关键字|追加方式|追加位置|根目录类型|替换变量|替换方式|内容)\s*:", raw_wo_header, flags=re.MULTILINE):
            return True
        return False

    @staticmethod
    def _preview_filename(address: str) -> str:
        s = str(address or "").strip().replace("\\", "/")
        if not s:
            return ""
        return os.path.basename(s)

    @staticmethod
    def _preview_content(content: str) -> str:
        text = str(content or "")
        if not text.strip():
            return ""
        lines = [ln.rstrip("\r") for ln in text.splitlines()]
        head = ""
        for ln in lines:
            s = ln.strip()
            if s:
                head = s
                break
        if not head:
            head = (lines[0].strip() if lines else "")
        if len(head) > 12:
            head = head[:12] + "..."
        if len(lines) > 1:
            return f"{head}...({len(lines)}行)"
        return head

    @staticmethod
    def _script_item_keyword_source(item: dict) -> str:
        data = item if isinstance(item, dict) else {}
        extra = data.get("extra_params", {}) or {}
        inject_type = str(data.get("type") or "").strip()
        if inject_type == "复制":
            source = str(extra.get("source_path") or data.get("keyword") or "").strip()
            return source
        return str(data.get("keyword") or "").strip()

    @staticmethod
    def _script_item_parameter_summary(item: dict) -> str:
        data = item if isinstance(item, dict) else {}
        extra = data.get("extra_params", {}) or {}
        parts: list[str] = []
        labels = (
            ("root_type", "根"),
            ("add_position", "追加"),
            ("replace_var", "替换变量"),
            ("replace_method", "替换方式"),
            ("source_path", "来源"),
            ("obj_type", "对象"),
            ("replace_file", "同名处理"),
        )
        for key, label in labels:
            value = str(extra.get(key) or "").strip()
            if value:
                parts.append(f"{label}={value}")
        return " · ".join(parts) if parts else "默认"

    @staticmethod
    def _infer_root_dir_from_file(file_path: str) -> str:
        p0 = str(file_path or "").strip().strip('"').strip("'")
        if not p0:
            return ""
        try:
            p_abs = os.path.abspath(p0)
        except Exception:
            p_abs = p0
        drive, tail = os.path.splitdrive(p_abs)
        parts = [x for x in os.path.normpath(tail).split(os.sep) if x]
        idx_mir = None
        for i, s in enumerate(parts):
            if str(s).lower() == "mir200":
                idx_mir = i
                break
        if idx_mir is None:
            return ""
        if idx_mir <= 0:
            return (drive + os.sep) if drive else ""
        root_tail = os.sep + os.path.join(*parts[:idx_mir])
        root_abs = drive + root_tail if drive else root_tail
        return os.path.abspath(root_abs)

    @staticmethod
    def _infer_address_and_root_type_from_file(root_dir: str, file_path: str) -> tuple[str, str]:
        p0 = str(file_path or "").strip().strip('"').strip("'")
        if not p0:
            return "", ""
        try:
            p_abs = os.path.abspath(p0)
        except Exception:
            p_abs = p0

        def canon_envir_rel(rel_path: str) -> str:
            rel = str(rel_path or "").replace("/", "\\").lstrip("\\")
            parts = [x for x in rel.split("\\") if x]
            if not parts:
                return rel
            head = parts[0].strip()
            key = head.lower()
            mapping = {
                "mapquest_def": "MapQuest_def",
                "market_def": "Market_Def",
                "questdiary": "QuestDiary",
                "robot_def": "Robot_def",
            }
            parts[0] = mapping.get(key, head)
            return "\\".join(parts)

        root0 = str(root_dir or "").strip().strip('"').strip("'")
        if not root0:
            drive, tail = os.path.splitdrive(p_abs)
            parts = [x for x in os.path.normpath(tail).split(os.sep) if x]
            idx_mir = None
            idx_envir = None
            for i, s in enumerate(parts):
                low = str(s).lower()
                if low == "mir200" and idx_mir is None:
                    idx_mir = i
                elif low == "envir" and idx_mir is not None and idx_envir is None:
                    idx_envir = i
                if idx_mir is not None and idx_envir is not None:
                    break
            if idx_mir is not None and idx_envir == idx_mir + 1:
                rel = "\\".join(parts[idx_envir + 1 :])
                return canon_envir_rel(rel), "Envir(默认)"
            if idx_mir is not None:
                rel = "\\".join(parts[idx_mir:])
                return rel, "版本根目录"
            return p_abs, ""
        try:
            root_abs = os.path.abspath(root0)
        except Exception:
            root_abs = root0
        envir_abs = os.path.abspath(os.path.join(root_abs, "Mir200", "Envir"))

        try:
            p_norm = os.path.normcase(p_abs)
            root_norm = os.path.normcase(root_abs)
            envir_norm = os.path.normcase(envir_abs)
        except Exception:
            p_norm, root_norm, envir_norm = p_abs, root_abs, envir_abs

        if p_norm == envir_norm or p_norm.startswith(envir_norm + os.sep):
            rel = os.path.relpath(p_abs, envir_abs)
            return canon_envir_rel(rel), "Envir(默认)"

        if p_norm == root_norm or p_norm.startswith(root_norm + os.sep):
            rel = os.path.relpath(p_abs, root_abs).replace("/", "\\").lstrip("\\")
            return rel, "版本根目录"

        return p_abs, ""

