    def _refresh_script_template_summary(self) -> None:
        badge = getattr(self, "template_count_badge", None)
        if isinstance(badge, QtWidgets.QLabel):
            total = len(getattr(self, "_templates", []) or [])
            visible = int(self.template_list.count())
            filtered = bool(getattr(self, "template_filter", None) and self.template_filter.text().strip())
            badge.setText(f"模板 {visible}/{total}" if filtered else f"模板 {total}")

