    def _refresh_script_editor_summary(self) -> None:
        table = getattr(self, "preview_table", None)
        row_count = table.rowCount() if isinstance(table, QtWidgets.QTableWidget) else 0
        type_names = set()
        if isinstance(table, QtWidgets.QTableWidget):
            for row in range(row_count):
                item = table.item(row, 1)
                value = str(item.text() if item else "").strip()
                if value:
                    type_names.add(value)
        selected = self._selected_index()
        selected_text = "未选中"
        if selected is not None and isinstance(table, QtWidgets.QTableWidget):
            item = table.item(selected, 1)
            value = str(item.text() if item else "").strip()
            selected_text = f"第 {selected + 1} 条" + (f" / {value}" if value else "")
        self.count_label.setText(f"条目 {row_count}")
        self.script_type_summary_label.setText(f"类型 {len(type_names)}")
        self.script_selected_summary_label.setText(selected_text)
        self.script_selected_summary_label.setToolTip(selected_text)

    def _refresh_script_mode_badge(self, mode: str) -> None:
        badge = getattr(self, "editor_mode_badge", None)
        if not isinstance(badge, QtWidgets.QLabel):
            return
        normalized = "txt" if str(mode or "") in ("txt", "json") else "preview"
        if normalized == "txt":
            badge.setText("TXT 编辑")
            badge.setProperty("badgeRole", "muted")
        else:
            badge.setText("预览模式")
            badge.setProperty("badgeRole", "muted")
        try:
            badge.style().unpolish(badge)
            badge.style().polish(badge)
            badge.update()
        except Exception:
            pass

