    def _configure_script_editor_action_button(self, btn: QtWidgets.QPushButton, role: str) -> None:
        fixed_widths = {
            "preview": 48,
            "edit": 64,
            "addItem": 64,
            "editItem": 64,
            "deleteItem": 64,
            "importTxt": 44,
            "exportTxt": 44,
            "reload": 68,
            "saveTemplate": 68,
        }
        if role in {"inject", "deleteInject"}:
            width = UiMetrics.SCRIPT_INJECT_EDITOR_EXEC_BUTTON_W
            height = UiMetrics.SCRIPT_INJECT_EDITOR_ACTION_BUTTON_H
        else:
            width = fixed_widths.get(role, UiMetrics.SCRIPT_INJECT_EDITOR_ACTION_BUTTON_W)
            height = UiMetrics.SCRIPT_INJECT_EDITOR_ACTION_BUTTON_H
        text_width = btn.fontMetrics().horizontalAdvance(btn.text()) + 22
        btn.setFixedSize(max(width, text_width), height)
        btn.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)

