    @staticmethod
    def _micro_summary_value(value: object, fallback: str = "-", limit: int = 16) -> str:
        text = str(value or "").strip()
        if not text:
            return fallback
        if len(text) <= limit:
            return text
        return text[: max(1, limit - 3)] + "..."

    def _refresh_micro_summary(self) -> None:
        if not hasattr(self, "micro_version_summary"):
            return
        name_edit = getattr(self, "name_edit", None)
        ip_edit = getattr(self, "ip_edit", None)
        list_port_spin = getattr(self, "list_port_spin", None)
        micro_port_spin = getattr(self, "micro_port_spin", None)
        server_port_spin = getattr(self, "server_port_spin", None)
        engine_combo = getattr(self, "engine_combo", None)
        version = self._micro_summary_value(name_edit.text() if name_edit is not None else "", "未命名", 18)
        ip = self._micro_summary_value(ip_edit.text() if ip_edit is not None else "", "-", 18)
        list_port = int(list_port_spin.value()) if list_port_spin is not None else 0
        micro_port = int(micro_port_spin.value()) if micro_port_spin is not None else 0
        server_port = int(server_port_spin.value()) if server_port_spin is not None else 0
        ports = "/".join(str(v) if v else "-" for v in (list_port, micro_port, server_port))
        engine = self._micro_summary_value(engine_combo.currentText() if engine_combo is not None else "", "-", 14)
        self.micro_version_summary.setText(f"版本 {version}")
        self.micro_ip_summary.setText(f"IP {ip}")
        self.micro_ports_summary.setText(f"端口 {ports}")
        self.micro_engine_summary.setText(f"引擎 {engine}")

