    def _sync_engine_dependent_ui(self, engine: str, user_action: bool) -> None:
        eng = str(engine or "").strip()
        is_gom = eng == "GOM引擎"
        chk_text = "64位无缓存" if is_gom else "无缓存"
        target_pw = "GameOfMir" if is_gom else "V8M2"
        cur_pw = str(self.password_edit.text() or "").strip()
        changed_from_gom = (self._last_engine == "GOM引擎") and (not is_gom)
        changed_to_gom = (self._last_engine != "GOM引擎") and is_gom

        prev_lock = self._form_lock
        self._form_lock = True
        try:
            if self.no_cache_chk.text() != chk_text:
                self.no_cache_chk.setText(chk_text)
            if user_action and (changed_from_gom or changed_to_gom):
                self.no_cache_chk.setChecked(False)
            if user_action:
                if (not cur_pw) or (cur_pw in ("V8M2", "GameOfMir")):
                    self.password_edit.setText(target_pw)
        finally:
            self._form_lock = prev_lock
        self._last_engine = eng

    def _on_engine_combo_changed(self, *_args) -> None:
        if self._form_lock:
            return
        self._sync_engine_dependent_ui(str(self.engine_combo.currentText() or ""), user_action=True)

    def _load_and_refresh(self) -> None:
        self._store_dirty_from_load = False
        self._items = self._load_items()
        self._templates = self._load_templates()
        if getattr(self, "_store_dirty_from_load", False):
            self._save_store()
        self._refresh_table()
        self._schedule_update_process_status_styles(50)

    def _load_store(self) -> dict:
        p = str(self._config_path or "").strip()
        if not p or (not os.path.exists(p)):
            return {}
        obj = None
        for enc in ("utf-8-sig", "utf-8", "gbk", "gb18030"):
            try:
                with open(p, "r", encoding=enc, errors="ignore") as f:
                    obj = json.load(f)
                break
            except Exception:
                obj = None
                continue
        if obj is None:
            return {}
        return obj if isinstance(obj, dict) else {}

    def _load_items(self) -> list[dict]:
        obj = self._load_store()
        items = obj.get("items") if isinstance(obj, dict) else None
        if not isinstance(items, list):
            return []
        out: list[dict] = []
        changed = False
        for it in items:
            if not isinstance(it, dict):
                continue
            cid = str(it.get("id") or "").strip()
            name = str(it.get("name") or "").strip()
            if not cid or not name:
                continue
            item, item_changed = self._normalize_micro_cfg_item(it)
            if item_changed:
                changed = True
            out.append(item)
        if changed:
            self._store_dirty_from_load = True
        return out

    def _load_templates(self) -> list[dict]:
        obj = self._load_store()
        items = obj.get("templates") if isinstance(obj, dict) else None
        if not isinstance(items, list):
            return []
        out: list[dict] = []
        for it in items:
            if not isinstance(it, dict):
                continue
            name = str(it.get("name") or "").strip()
            data = it.get("data")
            if not name or (not isinstance(data, dict)):
                continue
            out.append({"name": name, "data": dict(data)})
        return out

    def _save_store(self) -> bool:
        p = str(self._config_path or "").strip()
        if not p:
            return False
        try:
            self._micro_atomic_write_json(
                p,
                {"items": list(self._items or []), "templates": list(self._templates or [])},
            )
            return True
        except Exception:
            return False

    def _load_runtime_state(self) -> None:
        p = str(getattr(self, "_runtime_state_path", "") or "").strip()
        if not p or (not os.path.isfile(p)):
            return
        obj = None
        for enc in ("utf-8-sig", "utf-8", "gbk", "gb18030"):
            try:
                with open(p, "r", encoding=enc, errors="ignore") as f:
                    obj = json.load(f)
                break
            except Exception:
                obj = None
                continue
        if not isinstance(obj, dict):
            return
        hidden_src = obj.get("hidden_hwnds")
        if isinstance(hidden_src, dict):
            hidden_out: dict[str, list[int]] = {}
            for cid, arr in hidden_src.items():
                c = str(cid or "").strip()
                if not c or (not isinstance(arr, list)):
                    continue
                vals: list[int] = []
                for hwnd in arr:
                    try:
                        hwnd_i = int(hwnd)
                    except Exception:
                        continue
                    if hwnd_i > 0:
                        vals.append(hwnd_i)
                if vals:
                    hidden_out[c] = list(dict.fromkeys(vals))
            self._hidden_hwnds = hidden_out
        running_src = obj.get("running_pids")
        if isinstance(running_src, dict):
            running_out: dict[str, dict[str, list[int]]] = {}
            for cid, slot in running_src.items():
                c = str(cid or "").strip()
                if not c or (not isinstance(slot, dict)):
                    continue
                clean: dict[str, list[int]] = {}
                for k in ("micro", "gw"):
                    arr = slot.get(k)
                    if not isinstance(arr, list):
                        continue
                    vals: list[int] = []
                    for pid in arr:
                        try:
                            pid_i = int(pid)
                        except Exception:
                            continue
                        if pid_i > 0:
                            vals.append(pid_i)
                    if vals:
                        clean[k] = list(dict.fromkeys(vals))
                if clean:
                    running_out[c] = clean
            self._running_pids = running_out

    def _save_runtime_state(self) -> None:
        p = str(getattr(self, "_runtime_state_path", "") or "").strip()
        if not p:
            return
        hidden_out: dict[str, list[int]] = {}
        for cid, arr in (self._hidden_hwnds or {}).items():
            c = str(cid or "").strip()
            if not c or (not isinstance(arr, list)):
                continue
            vals: list[int] = []
            for hwnd in arr:
                try:
                    hwnd_i = int(hwnd)
                except Exception:
                    continue
                if hwnd_i > 0:
                    vals.append(hwnd_i)
            if vals:
                hidden_out[c] = list(dict.fromkeys(vals))
        running_out: dict[str, dict[str, list[int]]] = {}
        for cid, slot in (self._running_pids or {}).items():
            c = str(cid or "").strip()
            if not c or (not isinstance(slot, dict)):
                continue
            clean: dict[str, list[int]] = {}
            for k in ("micro", "gw"):
                arr = slot.get(k)
                if not isinstance(arr, list):
                    continue
                vals: list[int] = []
                for pid in arr:
                    try:
                        pid_i = int(pid)
                    except Exception:
                        continue
                    if pid_i > 0:
                        vals.append(pid_i)
                if vals:
                    clean[k] = list(dict.fromkeys(vals))
            if clean:
                running_out[c] = clean
        try:
            self._micro_atomic_write_json(
                p,
                {"hidden_hwnds": hidden_out, "running_pids": running_out},
            )
        except Exception:
            return

    def _refresh_table(self) -> None:
        try:
            self.table.setUpdatesEnabled(False)
        except Exception:
            pass
        try:
            self.table.blockSignals(True)
        except Exception:
            pass
        try:
            self.table.setRowCount(0)
            items = list(self._items or [])
            self.count_label.setText(f"已建微端 {len(items)}")
            for r, it in enumerate(items):
                self.table.insertRow(r)
                name = str(it.get("name") or "")
                cid = str(it.get("id") or "").strip()
                micro_running = self._is_cached_running(cid, "micro") if cid else False
                gw_running = self._is_cached_running(cid, "gw") if cid else False
                name_item = self._make_micro_table_item(
                    self._micro_list_status_text(name, micro_running, gw_running)
                )
                name_item.setToolTip(name.strip())
                self.table.setItem(r, 0, name_item)

                micro_btn = _make_ui_action_button("启动", "table-action")
                micro_btn.setObjectName("microTableStartButton")
                micro_btn.setProperty("microTableActionRole", "micro")
                self._prepare_micro_table_action_button(micro_btn)
                micro_btn.clicked.connect(lambda _=False, cid=str(it.get("id") or ""): self._on_micro_clicked(cid))
                self._set_play_btn_state(micro_btn, False)
                self.table.setCellWidget(r, 1, micro_btn)

                gw_btn = _make_ui_action_button("启动", "table-action")
                gw_btn.setObjectName("microTableGatewayButton")
                gw_btn.setProperty("microTableActionRole", "gateway")
                self._prepare_micro_table_action_button(gw_btn)
                gw_btn.clicked.connect(lambda _=False, cid=str(it.get("id") or ""): self._on_gateway_clicked(cid))
                self._set_play_btn_state(gw_btn, False)
                self.table.setCellWidget(r, 2, gw_btn)

                try:
                    self.table.setRowHeight(r, 46)
                except Exception:
                    pass

            if self.table.rowCount() > 0 and self.table.currentRow() < 0:
                self.table.selectRow(0)
            elif self.table.rowCount() == 0:
                self._current_id = None
                self._clear_form()
        finally:
            try:
                self.table.blockSignals(False)
            except Exception:
                pass
            try:
                self.table.setUpdatesEnabled(True)
            except Exception:
                pass
        try:
            self._on_table_selection_changed()
        except Exception:
            pass
        self._schedule_update_process_status_styles(0)

    @staticmethod
    def _make_micro_table_item(value: object) -> QtWidgets.QTableWidgetItem:
        text = str(value or "")
        item = QtWidgets.QTableWidgetItem(text)
        item.setToolTip(text.strip())
        return item

    @staticmethod
    def _micro_list_status_text(name: str, micro_running: bool, gw_running: bool) -> str:
        states = []
        if micro_running:
            states.append("微端运行")
        if gw_running:
            states.append("网关运行")
        status = " · ".join(states) if states else "未运行"
        return f"{str(name or '').strip()}\n{status}"

    def _update_micro_list_status(self, row: int, item: dict, micro_running: bool, gw_running: bool) -> None:
        name_item = self.table.item(row, 0)
        if not isinstance(name_item, QtWidgets.QTableWidgetItem):
            return
        name = str((item or {}).get("name") or "").strip()
        name_item.setText(self._micro_list_status_text(name, micro_running, gw_running))
        name_item.setToolTip(name)

    def _measure_micro_table_action_btn_width(self, text: str = "启动") -> int:
        label = str(text or "").strip() or "启动"
        try:
            app = QtWidgets.QApplication.instance()
            font = app.font() if app is not None else self.font()
            metrics = QtGui.QFontMetrics(font)
            width = metrics.horizontalAdvance(label) + 28
        except Exception:
            width = 56
        return max(_ui_button_min_width("table-action"), int(width) + 6)

    def _apply_micro_table_action_col_width(self) -> None:
        width = max(
            UiMetrics.MICRO_CONFIG_TABLE_ACTION_COL_W,
            int(getattr(self, "_micro_table_action_col_width", UiMetrics.MICRO_CONFIG_TABLE_ACTION_COL_W) or UiMetrics.MICRO_CONFIG_TABLE_ACTION_COL_W),
        )
        self.table.setColumnWidth(1, width)
        self.table.setColumnWidth(2, width)

    def _sync_micro_table_action_columns(self) -> None:
        table = getattr(self, "table", None)
        if not isinstance(table, QtWidgets.QTableWidget):
            return
        width = max(
            UiMetrics.MICRO_CONFIG_TABLE_ACTION_COL_W,
            int(getattr(self, "_micro_table_action_col_width", UiMetrics.MICRO_CONFIG_TABLE_ACTION_COL_W) or UiMetrics.MICRO_CONFIG_TABLE_ACTION_COL_W),
        )
        buttons: list[QtWidgets.QPushButton] = []
        for row in range(table.rowCount()):
            for col in (1, 2):
                btn = table.cellWidget(row, col)
                if not isinstance(btn, QtWidgets.QPushButton):
                    continue
                try:
                    btn.ensurePolished()
                except Exception:
                    pass
                try:
                    width = max(
                        width,
                        int(btn.minimumWidth()),
                        int(btn.sizeHint().width()),
                        int(btn.minimumSizeHint().width()),
                        int(btn.width()),
                    )
                except Exception:
                    pass
                buttons.append(btn)
        self._micro_table_action_col_width = width
        for btn in buttons:
            btn.setMinimumWidth(width)
            btn.setFixedWidth(width)
        self._apply_micro_table_action_col_width()

    def _prepare_micro_table_action_button(self, btn: object) -> None:
        if not isinstance(btn, QtWidgets.QPushButton):
            return
        _apply_ui_button_role(btn, "table-action")
        try:
            btn.ensurePolished()
        except Exception:
            pass
        width = self._measure_micro_table_action_btn_width(str(btn.text() or "").strip() or "启动")
        try:
            width = max(width, int(btn.sizeHint().width()), int(btn.minimumSizeHint().width()), int(btn.minimumWidth()))
        except Exception:
            pass
        self._micro_table_action_col_width = max(int(getattr(self, "_micro_table_action_col_width", 56) or 56), width)
        btn.setMinimumWidth(self._micro_table_action_col_width)
        btn.setFixedWidth(self._micro_table_action_col_width)
        try:
            final_width = max(
                int(self._micro_table_action_col_width),
                int(btn.sizeHint().width()),
                int(btn.minimumSizeHint().width()),
                int(btn.minimumWidth()),
            )
        except Exception:
            final_width = int(self._micro_table_action_col_width)
        if final_width > int(self._micro_table_action_col_width):
            self._micro_table_action_col_width = final_width
            btn.setMinimumWidth(final_width)
            btn.setFixedWidth(final_width)
        self._apply_micro_table_action_col_width()

    def _apply_uniform_button_widths(self, buttons: list[object], extra: int = 0, minimum: int = 0) -> None:
        btns: list[QtWidgets.QPushButton] = []
        max_width = int(minimum or 0)
        for btn in buttons or []:
            if not isinstance(btn, QtWidgets.QPushButton):
                continue
            btn.ensurePolished()
            width = max(btn.sizeHint().width(), btn.minimumSizeHint().width()) + int(extra or 0)
            max_width = max(max_width, int(width))
            btns.append(btn)
        if max_width <= 0:
            return
        for btn in btns:
            btn.setMinimumWidth(max_width)

    def _apply_uniform_button_heights(self, buttons: list[object], height: int) -> None:
        target_h = max(28, int(height or 0))
        for btn in buttons or []:
            if not isinstance(btn, QtWidgets.QPushButton):
                continue
            btn.setMinimumHeight(target_h)

    def _set_play_btn_state(self, btn: object, running: bool) -> None:
        if not isinstance(btn, QtWidgets.QPushButton):
            return
        self._prepare_micro_table_action_button(btn)
        state_text = "运行中" if running else "未运行"
        action_name = "网关" if str(btn.property("microTableActionRole") or "") == "gateway" else "微端"
        btn.setText(f"启动({state_text})")
        btn.setToolTip(f"{action_name}进程状态：{state_text}；点击启动")
        btn.setAccessibleName(f"{action_name}启动按钮，当前状态：{state_text}")
        btn.setProperty("microTableProcessState", "running" if running else "stopped")
        btn.setStyleSheet("")
        _refresh_ui_dynamic_qss(btn)
        self._prepare_micro_table_action_button(btn)

    def _pids_are_shown(self, pids: list[int]) -> bool:
        return True

    def _mark_running_pid(self, cid: str, kind: str, pid: int) -> None:
        c = str(cid or "").strip()
        k = str(kind or "").strip().lower()
        try:
            pid_i = int(pid)
        except Exception:
            pid_i = 0
        if not c or not k or pid_i <= 0:
            return
        slot = self._running_pids.get(c)
        if not isinstance(slot, dict):
            slot = {}
            self._running_pids[c] = slot
        arr = slot.get(k)
        if not isinstance(arr, list):
            arr = []
            slot[k] = arr
        if pid_i not in arr:
            arr.append(pid_i)
            self._save_runtime_state()

    def _prune_dead_running_pids(self, cid: str) -> None:
        c = str(cid or "").strip()
        if not c:
            return
        slot = self._running_pids.get(c)
        if not isinstance(slot, dict):
            return
        changed = False
        for k in list(slot.keys()):
            arr = slot.get(k)
            if not isinstance(arr, list):
                slot.pop(k, None)
                changed = True
                continue
            alive = []
            for pid in arr:
                try:
                    pid_i = int(pid)
                except Exception:
                    continue
                if pid_i > 0 and self._is_pid_alive(pid_i):
                    alive.append(pid_i)
            if alive:
                new_alive = list(dict.fromkeys(alive))
                if new_alive != arr:
                    changed = True
                slot[k] = new_alive
            else:
                slot.pop(k, None)
                changed = True
        if not slot:
            self._running_pids.pop(c, None)
            changed = True
        if changed:
            self._save_runtime_state()

    def _is_cached_running(self, cid: str, kind: str) -> bool:
        c = str(cid or "").strip()
        k = str(kind or "").strip().lower()
        if not c or not k:
            return False
        slot = self._running_pids.get(c)
        if not isinstance(slot, dict):
            return False
        arr = slot.get(k)
        return bool(isinstance(arr, list) and arr)

    def _scan_running_pids_for_all_items(self) -> None:
        if not platform.system().lower().startswith("win"):
            return
        pid_to_exe = self._pid_to_exe_map()
        port_to_pids = self._listening_pids_by_port()
        for it in list(self._items or []):
            cid = str((it or {}).get("id") or "").strip()
            if not cid:
                continue
            cfg_dir = self._resolve_micro_cfg_dir_from_item(it)
            if not cfg_dir:
                continue
            micro_pids = self._find_update_server_pids_for_item(it, pid_to_exe, port_to_pids)
            gate_pids = self._find_gateway_pids_for_item(it, pid_to_exe, port_to_pids)
            for pid in micro_pids or []:
                self._mark_running_pid(cid, "micro", pid)
            for pid in gate_pids or []:
                self._mark_running_pid(cid, "gw", pid)
            self._prune_dead_running_pids(cid)

    @staticmethod
    def _pid_to_exe_map() -> dict[int, str]:
        if not platform.system().lower().startswith("win"):
            return {}
        out: dict[int, str] = {}
        try:
            p = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                encoding="mbcs",
                errors="ignore",
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                check=False,
            )
            txt = (p.stdout or "").strip()
            if not txt:
                return {}
            for row in csv.reader(txt.splitlines()):
                if len(row) < 2:
                    continue
                exe = str(row[0] or "").strip().strip('"')
                pid_s = str(row[1] or "").strip().strip('"')
                if not pid_s.isdigit():
                    continue
                out[int(pid_s)] = exe
        except Exception:
            return out
        return out

    @staticmethod
    def _listening_pids_by_port() -> dict[int, set[int]]:
        if not platform.system().lower().startswith("win"):
            return {}
        out: dict[int, set[int]] = {}

        def _add(port: int, pid: int) -> None:
            if port <= 0 or pid <= 0:
                return
            slot = out.get(port)
            if slot is None:
                slot = set()
                out[port] = slot
            slot.add(pid)

        def _parse_lines(txt: str) -> None:
            for line in (txt or "").splitlines():
                s = (line or "").strip()
                if not s:
                    continue
                if not (s.startswith("TCP") or s.startswith("UDP")):
                    continue
                parts = s.split()
                if len(parts) < 4:
                    continue
                local = parts[1]
                pid_s = parts[-1]
                if not pid_s.isdigit():
                    continue
                try:
                    pid_i = int(pid_s)
                except Exception:
                    continue
                try:
                    port_s = str(local).rsplit(":", 1)[-1].strip()
                    port_i = int(port_s)
                except Exception:
                    continue
                _add(port_i, pid_i)

        try:
            p_tcp = subprocess.run(
                ["netstat", "-ano", "-p", "tcp"],
                capture_output=True,
                text=True,
                encoding="mbcs",
                errors="ignore",
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                check=False,
            )
            _parse_lines(p_tcp.stdout or "")
        except Exception:
            pass
        try:
            p_udp = subprocess.run(
                ["netstat", "-ano", "-p", "udp"],
                capture_output=True,
                text=True,
                encoding="mbcs",
                errors="ignore",
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                check=False,
            )
            _parse_lines(p_udp.stdout or "")
        except Exception:
            pass
        return out

    def _find_update_server_pids_for_item(self, it: dict, pid_to_exe: dict[int, str], port_to_pids: dict[int, set[int]]) -> list[int]:
        cfg_dir = self._resolve_micro_cfg_dir_from_item(it)
        if cfg_dir:
            found = self._find_update_server_pids_for_cfg_dir(cfg_dir)
            if found:
                return found
        if self._has_show_hide_port_conflict(str((it or {}).get("id") or "").strip(), it):
            return []

        ports: list[int] = []
        for k in ("micro_port", "server_port", "list_port"):
            try:
                v = int((it or {}).get(k) or 0)
            except Exception:
                v = 0
            if v > 0:
                ports.append(v)

        names = {
            "updateserver.exe",
            "updateserver(64位).exe",
            "updateserver（64位）.exe",
            "updateserver_x64.exe",
            "updateserver_x64(无缓存).exe",
            "updateserver_x64（无缓存）.exe",
        }
        candidates: list[int] = []
        for port in ports:
            for pid in (port_to_pids.get(int(port)) or set()):
                if pid > 0 and pid not in candidates:
                    candidates.append(pid)
        if not candidates:
            return []

        filtered = []
        for pid in candidates:
            exe = str((pid_to_exe or {}).get(int(pid)) or "").strip().lower()
            if exe and exe in names:
                filtered.append(int(pid))
        return filtered if filtered else candidates

    def _find_gateway_pids_for_item(self, it: dict, pid_to_exe: dict[int, str], port_to_pids: dict[int, set[int]]) -> list[int]:
        cfg_dir = self._resolve_micro_cfg_dir_from_item(it)
        if cfg_dir:
            found = self._find_gateway_pids_for_cfg_dir(cfg_dir)
            if found:
                return found
        if self._has_show_hide_port_conflict(str((it or {}).get("id") or "").strip(), it):
            return []

        ports: list[int] = []
        for k in ("list_port", "server_port"):
            try:
                v = int((it or {}).get(k) or 0)
            except Exception:
                v = 0
            if v > 0:
                ports.append(v)

        engine = str((it or {}).get("engine") or "").strip()
        names = {"updategate.exe"} if engine == "GOM引擎" else {"mirupdategate.exe"}

        candidates: list[int] = []
        for port in ports:
            for pid in (port_to_pids.get(int(port)) or set()):
                if pid > 0 and pid not in candidates:
                    candidates.append(pid)
        if not candidates:
            return []

        filtered = []
        for pid in candidates:
            exe = str((pid_to_exe or {}).get(int(pid)) or "").strip().lower()
            if exe and exe in names:
                filtered.append(int(pid))
        return filtered if filtered else candidates

    @staticmethod
    def _process_matches_cfg_dir(cfg_dir: str, img: str, cmdline: str) -> bool:
        base = str(cfg_dir or "").strip()
        if not base:
            return False
        try:
            base_abs = os.path.abspath(base)
        except Exception:
            base_abs = base
        base_l = base_abs.lower()
        if img:
            try:
                img_abs = os.path.abspath(str(img))
            except Exception:
                img_abs = str(img)
            if img_abs.lower().startswith(base_l):
                return True
        cl = str(cmdline or "").lower()
        return bool(cl and base_l and (base_l in cl))

    def _update_process_status_styles(self) -> None:
        if self._closing:
            return
        try:
            if QtCore.QCoreApplication.instance() and QtCore.QCoreApplication.closingDown():
                return
        except Exception:
            pass
        try:
            items = list(self._items or [])
            for r, it in enumerate(items):
                cid = str((it or {}).get("id") or "").strip()
                if cid:
                    self._prune_dead_running_pids(cid)
                micro_running = self._is_cached_running(cid, "micro") if cid else False
                gw_running = self._is_cached_running(cid, "gw") if cid else False
                micro_btn = self.table.cellWidget(r, 1)
                gw_btn = self.table.cellWidget(r, 2)
                self._set_play_btn_state(micro_btn, micro_running)
                self._set_play_btn_state(gw_btn, gw_running)
                self._update_micro_list_status(r, it, micro_running, gw_running)
            self._sync_micro_table_action_columns()
        except Exception:
            return

    def _on_status_tick(self) -> None:
        try:
            if self._closing:
                return
            try:
                if QtCore.QCoreApplication.instance() and QtCore.QCoreApplication.closingDown():
                    return
            except Exception:
                pass
            if not self.isVisible():
                return
            if not self.table:
                return
            if self.table.rowCount() <= 0:
                return
            self._update_process_status_styles()
        except Exception:
            return

    def _on_table_selection_changed(self) -> None:
        r = self.table.currentRow()
        if r < 0:
            self._current_id = None
            self._editing_new = False
            self._clear_form()
            return
        try:
            cid = str((self._items[r] or {}).get("id") or "").strip()
        except Exception:
            cid = ""
        if not cid:
            self._current_id = None
            self._editing_new = False
            self._clear_form()
            return
        self._current_id = cid
        self._editing_new = False
        self._load_into_form(self._get_item_by_id(cid) or {})

    def _get_item_by_id(self, cid: str) -> dict | None:
        c = str(cid or "").strip()
        if not c:
            return None
        for it in self._items:
            if str(it.get("id") or "").strip() == c:
                return it
        return None

