    def _on_form_changed(self, *_args) -> None:
        if self._form_lock:
            return
        if str(self.name_edit.text() or "").strip():
            self.name_edit.setProperty("validationState", "normal")
            self.name_edit.style().unpolish(self.name_edit)
            self.name_edit.style().polish(self.name_edit)
        self._refresh_micro_summary()
        if self._autosave_timer.isActive():
            self._autosave_timer.stop()
        cid = str(self._current_id or "").strip()
        if not cid:
            self._editing_new = True
            self._refresh_micro_primary_action_text()
            return
        it = self._get_item_by_id(cid) or {}
        cur_name = str((it or {}).get("name") or "").strip()
        now_name = str(self.name_edit.text() or "").strip()
        self._editing_new = bool(now_name and cur_name and (now_name != cur_name))
        self._refresh_micro_primary_action_text()

