    def _select_by_id(self, cid: str) -> None:
        c = str(cid or "").strip()
        if not c:
            return
        for i, it in enumerate(self._items):
            if str(it.get("id") or "").strip() == c:
                try:
                    self.table.selectRow(i)
                except Exception:
                    pass
                return

    def _choose_pak(self) -> None:
        start_dir = os.path.dirname(str(self.pak_edit.text() or "").strip()) or os.getcwd()
        path, _flt = _qt_get_open_file_name(self, "选择 PAK 文件", start_dir, "所有文件 (*.*)")
        path = str(path or "").strip()
        if not path:
            return
        self.pak_edit.setText(path)

    def _choose_legend_dir(self) -> None:
        start_dir = str(self.legend_dir_edit.text() or "").strip() or os.getcwd()
        chosen = _qt_get_existing_dir(self, "选择传奇目录", start_dir)
        chosen = str(chosen or "").strip()
        if not chosen:
            return
        self.legend_dir_edit.setText(chosen)

    def _choose_patch_dir(self) -> None:
        base = str(self.legend_dir_edit.text() or "").strip()
        start_dir = base if base and os.path.isdir(base) else os.getcwd()
        chosen = _qt_get_existing_dir(self, "选择补丁目录", start_dir)
        chosen = str(chosen or "").strip()
        if not chosen:
            return
        if base:
            try:
                base_abs = os.path.normcase(os.path.abspath(base))
                chosen_abs = os.path.normcase(os.path.abspath(chosen))
                if chosen_abs.startswith(base_abs + os.sep):
                    rel = os.path.relpath(chosen_abs, base_abs)
                    self.patch_dir_edit.setText(rel.replace("/", "\\"))
                    return
            except Exception:
                pass
        self.patch_dir_edit.setText(chosen)

    def _choose_micro_tpl_dir(self) -> None:
        start_dir = str(self.micro_tpl_dir_edit.text() or "").strip() or os.getcwd()
        chosen = _qt_get_existing_dir(self, "选择微端模板", start_dir)
        chosen = str(chosen or "").strip()
        if not chosen:
            return
        self.micro_tpl_dir_edit.setText(chosen)

    def _gen_password(self) -> None:
        pw = "".join(secrets.choice(string.digits) for _ in range(4))
        self.password_edit.setText(pw)

    def _apply_template(self) -> None:
        if self._form_lock:
            return
        name = str(self._selected_template or "").strip()
        if not name:
            QtWidgets.QMessageBox.information(self, "提示", "请先选择微端模板")
            return
        target = None
        for it in (self._templates or []):
            if str((it or {}).get("name") or "").strip() == name:
                target = it
                break
        if not isinstance(target, dict):
            QtWidgets.QMessageBox.information(self, "提示", "模板不存在，请重新选择")
            return
        self._apply_template_data(target.get("data") if isinstance(target.get("data"), dict) else {})

    def _create_or_update(self) -> None:
        active_rpc = self._pak_rpc_thread
        if active_rpc is not None:
            try:
                if active_rpc.isRunning():
                    QtWidgets.QMessageBox.information(self, "提示", "PAK 密码加密任务正在执行，请勿重复提交")
                    return
            except Exception:
                pass
        data = self._collect_form()
        name = str(data.get("name") or "").strip()
        if not name:
            self.name_edit.setProperty("validationState", "error")
            self.name_edit.style().unpolish(self.name_edit)
            self.name_edit.style().polish(self.name_edit)
            self.name_edit.setFocus(QtCore.Qt.OtherFocusReason)
            QtWidgets.QMessageBox.warning(self, "提示", "请填写版本名称")
            return
        safe_name = self._sanitize_dir_name(name)
        matched: list[dict] = []
        for it in list(self._items or []):
            try:
                n = str((it or {}).get("name") or "").strip()
            except Exception:
                n = ""
            if not n:
                continue
            if n == name:
                matched.append(it)
                continue
            if safe_name and (self._sanitize_dir_name(n) == safe_name):
                matched.append(it)

        primary = matched[0] if matched else None
        keep_id = str((primary or {}).get("id") or "").strip() if isinstance(primary, dict) else ""
        template = str(self.micro_tpl_dir_edit.text() or "").strip()
        if not template:
            QtWidgets.QMessageBox.information(self, "提示", "请选择微端模板文件夹。")
            return
        if not os.path.isdir(template) or self._micro_path_is_reparse(template):
            QtWidgets.QMessageBox.warning(self, "提示", "微端模板文件夹无效或包含链接。")
            return
        root = os.path.abspath(self._get_micro_configs_root_dir())
        try:
            target = self._micro_validate_target(os.path.join(root, safe_name), root, exact_child=True)
        except Exception as err:
            QtWidgets.QMessageBox.warning(self, "提示", "微端目标目录不安全：%s" % err)
            return
        if safe_name != name:
            QtWidgets.QMessageBox.information(self, "提示", "版本名称包含特殊字符，已自动处理为：%s" % safe_name)
        if (not keep_id) and os.path.exists(target):
            answer = QtWidgets.QMessageBox.question(self, "确认", "微端配置目录已存在，是否覆盖？\n%s" % target)
            if answer != QtWidgets.QMessageBox.Yes:
                return

        pak_prepared = None
        pak_encoded_passwords = None
        pak_path = str((data or {}).get("pak_path") or "").strip()
        if pak_path:
            if not os.path.isfile(pak_path):
                QtWidgets.QMessageBox.warning(self, "创建失败", "PAK 文件无效，未写入目标目录")
                return
            if self._is_micro_pak_password_list(pak_path):
                try:
                    pak_prepared = self._prepare_micro_pak_password_file(pak_path)
                    passwords = list(pak_prepared.get("passwords") or [])
                    pak_encoded_passwords = self._run_micro_pak_rpc(passwords) if passwords else []
                except _MicroPakRpcCancelled:
                    QtWidgets.QMessageBox.information(self, "已取消", "已取消 PAK 加密，未写入目标目录。")
                    return
                except Exception as err:
                    QtWidgets.QMessageBox.warning(
                        self,
                        "核心服务请求失败",
                        "%s\n\n目标目录未发生替换，请检查网络或授权后重试。" % err,
                    )
                    return

        transaction_id = uuid.uuid4().hex
        stage = target + ".xiami-stage-" + transaction_id
        backup = target + ".xiami-backup-" + transaction_id
        old_items = [dict(item) for item in (self._items or [])]
        old_current_id = self._current_id
        old_editing_new = self._editing_new
        store_existed, store_bytes = self._micro_file_snapshot(self._config_path)
        target_switched = False
        target_backed_up = False
        try:
            os.makedirs(root, exist_ok=True)
            for residue in (stage, backup):
                if os.path.lexists(residue):
                    raise RuntimeError("事务临时目录已存在")
            shutil.copytree(template, stage)
            if not os.path.isdir(stage):
                raise RuntimeError("模板复制结果无效")
            if not self._post_process_micro_cfg_dir(
                stage,
                data,
                pak_encoded_passwords=pak_encoded_passwords,
                pak_prepared=pak_prepared,
            ):
                raise RuntimeError("微端配置后处理失败")
            if os.path.exists(target):
                self._micro_replace_with_retry(target, backup)
                target_backed_up = True
            self._micro_replace_with_retry(stage, target)
            target_switched = True

            selected_id = keep_id or uuid.uuid4().hex
            new_data = dict(data)
            new_data["id"] = selected_id
            new_data["micro_cfg_dir"] = target
            next_items: list[dict] = []
            inserted = False
            for item in old_items:
                item_id = str((item or {}).get("id") or "").strip()
                item_safe = self._sanitize_dir_name(str((item or {}).get("name") or "").strip())
                if keep_id and item_id == keep_id and not inserted:
                    next_items.append(dict(new_data))
                    inserted = True
                elif safe_name and item_safe == safe_name:
                    continue
                else:
                    next_items.append(dict(item))
            if not inserted:
                next_items.append(dict(new_data))
            self._items = next_items
            if not self._save_store():
                raise OSError("写入微端配置存储失败")
            if target_backed_up and os.path.lexists(backup):
                self._remove_fs_target(backup)
            self._current_id = selected_id
            self._editing_new = False
            self._refresh_table()
            self._select_by_id(selected_id)
        except Exception as err:
            self._items = old_items
            self._current_id = old_current_id
            self._editing_new = old_editing_new
            try:
                self._micro_restore_file_snapshot(self._config_path, store_existed, store_bytes)
            except Exception:
                pass
            try:
                if target_switched and os.path.lexists(target):
                    self._remove_fs_target(target)
                if target_backed_up and os.path.lexists(backup):
                    self._micro_replace_with_retry(backup, target)
            except Exception:
                pass
            for residue in (stage, backup):
                if os.path.lexists(residue):
                    try:
                        self._remove_fs_target(residue)
                    except Exception:
                        pass
            self._refresh_table()
            if old_current_id:
                self._select_by_id(old_current_id)
                self._current_id = old_current_id
            QtWidgets.QMessageBox.warning(self, "创建失败", "微端事务已回滚：%s" % err)

    def _delete_selected(self) -> None:
        cid = str(self._current_id or "").strip()
        if not cid:
            QtWidgets.QMessageBox.information(self, "提示", "请选择要删除的微端")
            return
        it = self._get_item_by_id(cid) or {}
        if self._has_running_process_for_item(cid, it):
            QtWidgets.QMessageBox.information(self, "提示", "请先关闭微端！")
            return
        name = str((it or {}).get("name") or "").strip()
        cfg_dir = self._resolve_micro_cfg_dir_from_item(it)
        base = str((it or {}).get("legend_dir") or "").strip()
        patch = str((it or {}).get("patch_dir") or "").strip()
        patch_abs = ""
        if patch:
            if os.path.isabs(patch):
                patch_abs = patch
            elif base:
                patch_abs = os.path.join(base, patch)
            else:
                patch_abs = patch
        patch_abs = str(patch_abs or "").strip()

        tip = "确定删除当前微端配置吗？\n你可以选择是否同时删除补丁目录。"
        if name:
            tip += f"\n名称：{name}"
        if cfg_dir:
            tip += f"\n配置目录：{cfg_dir}"
        if patch_abs:
            tip += f"\n补丁目录：{patch_abs}"
        if patch_abs and (not os.path.exists(patch_abs)):
            tip += "\n补丁目录不存在"
        msg = QtWidgets.QMessageBox(self)
        msg.setIcon(QtWidgets.QMessageBox.Question)
        msg.setWindowTitle("确认")
        msg.setText(tip)
        longest_line_width = max((msg.fontMetrics().horizontalAdvance(line) for line in tip.splitlines()), default=0)
        msg.setMinimumWidth(max(640, longest_line_width + 120))
        yes_btn = msg.addButton("删除配置和补丁", QtWidgets.QMessageBox.YesRole)
        no_btn = msg.addButton("只删除配置", QtWidgets.QMessageBox.NoRole)
        close_btn = msg.addButton("取消", QtWidgets.QMessageBox.RejectRole)
        for button in (yes_btn, no_btn, close_btn):
            button.setMinimumWidth(button.fontMetrics().horizontalAdvance(button.text()) + 28)
        yes_btn.setObjectName("microDeleteDangerButton")
        no_btn.setObjectName("microDeleteConfigOnlyButton")
        close_btn.setObjectName("microDeleteCancelButton")
        yes_btn.setAutoDefault(False)
        yes_btn.setDefault(False)
        no_btn.setAutoDefault(False)
        no_btn.setDefault(False)
        close_btn.setAutoDefault(True)
        msg.setDefaultButton(close_btn)
        msg.setEscapeButton(close_btn)
        yes_btn.setStyleSheet(
            "QPushButton { color: #9f3a38; background: #ffffff; border: 1px solid #d8dee7; }"
            "QPushButton:hover { color: #842f2d; background: #fff5f5; border-color: #d7a4a2; }"
            "QPushButton:pressed { background: #fde8e8; }"
        )
        _qt_dialog_exec(msg)
        clicked = msg.clickedButton()
        delete_patch = self._resolve_delete_patch_choice(clicked, yes_btn, no_btn, close_btn)
        if delete_patch is None:
            return

        targets: list[str] = []
        try:
            if cfg_dir and os.path.lexists(cfg_dir):
                targets.append(self._micro_validate_target(cfg_dir, self._get_micro_configs_root_dir(), exact_child=True))
            if delete_patch and patch_abs and os.path.lexists(patch_abs):
                if not base:
                    raise ValueError("补丁目录缺少传奇根目录边界")
                targets.append(self._micro_validate_target(patch_abs, base, exact_child=False))
            norm_targets = [os.path.normcase(os.path.realpath(path)) for path in targets]
            if len(norm_targets) != len(set(norm_targets)):
                raise ValueError("配置目录与补丁目录发生重叠")
        except Exception as err:
            QtWidgets.QMessageBox.warning(self, "删除失败", "删除目标不安全：%s" % err)
            return

        old_items = [dict(item) for item in (self._items or [])]
        old_current_id = self._current_id
        store_existed, store_bytes = self._micro_file_snapshot(self._config_path)
        quarantines: list[tuple[str, str]] = []
        try:
            for target in targets:
                quarantine = target + ".xiami-quarantine-" + uuid.uuid4().hex
                self._micro_validate_target(quarantine, os.path.dirname(target), exact_child=True)
                if os.path.lexists(quarantine):
                    raise RuntimeError("隔离目录已存在")
                self._micro_replace_with_retry(target, quarantine)
                quarantines.append((target, quarantine))
            self._items = [item for item in old_items if str((item or {}).get("id") or "").strip() != cid]
            self._current_id = None
            if not self._save_store():
                raise OSError("写入微端配置存储失败")
        except Exception as err:
            self._items = old_items
            self._current_id = old_current_id
            try:
                self._micro_restore_file_snapshot(self._config_path, store_existed, store_bytes)
            except Exception:
                pass
            for target, quarantine in reversed(quarantines):
                if os.path.lexists(quarantine) and not os.path.lexists(target):
                    try:
                        self._micro_replace_with_retry(quarantine, target)
                    except Exception:
                        pass
            self._refresh_table()
            if old_current_id:
                self._select_by_id(old_current_id)
                self._current_id = old_current_id
            QtWidgets.QMessageBox.warning(self, "删除失败", "删除事务已回滚：%s" % err)
            return
        cleanup_errors: list[str] = []
        for _target, quarantine in quarantines:
            try:
                self._remove_fs_target(quarantine)
            except Exception as err:
                cleanup_errors.append(str(err))
        self._refresh_table()
        if cleanup_errors:
            QtWidgets.QMessageBox.warning(self, "清理提示", "配置已删除，但隔离目录清理失败：%s" % cleanup_errors[0])

    @staticmethod
    def _resolve_delete_patch_choice(
        clicked_btn: object, yes_btn: object, no_btn: object, close_btn: object | None = None
    ) -> bool | None:
        if clicked_btn == yes_btn:
            return True
        if clicked_btn == no_btn:
            return False
        if (close_btn is not None) and (clicked_btn == close_btn):
            return None
        return None

    @staticmethod
    def _is_delete_permission_error(err: Exception) -> bool:
        if isinstance(err, PermissionError):
            return True
        winerror = getattr(err, "winerror", None)
        errno_v = getattr(err, "errno", None)
        if winerror in (5, 32):
            return True
        if errno_v in (13,):
            return True
        msg = str(err or "").strip().lower()
        if not msg:
            return False
        if ("access is denied" in msg) or ("permission denied" in msg):
            return True
        if ("拒绝访问" in msg) or ("正在被另一进程使用" in msg) or ("正在使用中" in msg):
            return True
        return False

    @staticmethod
    def _make_path_writable(target: str) -> None:
        p = str(target or "").strip()
        if not p:
            return
        try:
            if os.path.isdir(p):
                for root, dirs, files in os.walk(p):
                    for dn in dirs:
                        dp = os.path.join(root, dn)
                        try:
                            os.chmod(dp, 0o777)
                        except Exception:
                            pass
                    for fn in files:
                        fp = os.path.join(root, fn)
                        try:
                            os.chmod(fp, 0o666)
                        except Exception:
                            pass
                os.chmod(p, 0o777)
                return
            if os.path.exists(p):
                os.chmod(p, 0o666)
        except Exception:
            return

    @staticmethod
    def _remove_fs_target(target: str) -> None:
        p = str(target or "").strip()
        if not p or (not os.path.exists(p)):
            return
        if os.path.isdir(p):
            shutil.rmtree(p, ignore_errors=False)
        else:
            os.remove(p)

    def _collect_related_pids_for_cfg_dir(self, cid: str, cfg_dir: str) -> list[int]:
        out: list[int] = []
        seen: set[int] = set()
        cached = self._running_pids.get(str(cid or "").strip()) or {}
        for group in ("micro", "gw"):
            for pid in (cached.get(group) or []):
                try:
                    pid_i = int(pid)
                except Exception:
                    continue
                if pid_i > 0 and pid_i not in seen:
                    seen.add(pid_i)
                    out.append(pid_i)
        for pid in self._find_update_server_pids_for_cfg_dir(cfg_dir):
            try:
                pid_i = int(pid)
            except Exception:
                continue
            if pid_i > 0 and pid_i not in seen:
                seen.add(pid_i)
                out.append(pid_i)
        for pid in self._find_gateway_pids_for_cfg_dir(cfg_dir):
            try:
                pid_i = int(pid)
            except Exception:
                continue
            if pid_i > 0 and pid_i not in seen:
                seen.add(pid_i)
                out.append(pid_i)
        return out

    @staticmethod
    def _taskkill_pids_blocking(pids: list[int]) -> None:
        for pid in pids or []:
            try:
                pid_i = int(pid)
            except Exception:
                continue
            if pid_i <= 0:
                continue
            try:
                subprocess.run(
                    ["taskkill", "/PID", str(pid_i), "/T", "/F"],
                    stdout=subprocess.DEVNULL,
                    stderr=subprocess.DEVNULL,
                    creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                    check=False,
                )
            except Exception:
                continue

    def _delete_target_with_permission_recovery(self, target: str, cfg_dir: str, cid: str) -> tuple[bool, str]:
        p = str(target or "").strip()
        if not p:
            return True, ""
        cfg = str(cfg_dir or "").strip()
        c = str(cid or "").strip()
        last_err: Exception | None = None
        for _ in range(3):
            if not os.path.exists(p):
                return True, ""
            try:
                self._remove_fs_target(p)
                return True, ""
            except Exception as e:
                last_err = e
                if not self._is_delete_permission_error(e):
                    break
                self._make_path_writable(p)
                if cfg:
                    pids = self._collect_related_pids_for_cfg_dir(c, cfg)
                    if pids:
                        self._taskkill_pids_blocking(pids)
                        self._running_pids.pop(c, None)
                time.sleep(0.25)
        if last_err is None:
            return False, "未知错误"
        return False, str(last_err)

    def _has_running_process_for_item(self, cid: str, it: dict) -> bool:
        c = str(cid or "").strip()
        if c:
            self._prune_dead_running_pids(c)
            cached = self._running_pids.get(c) or {}
            for group in ("micro", "gw"):
                for pid in (cached.get(group) or []):
                    try:
                        pid_i = int(pid)
                    except Exception:
                        continue
                    if pid_i > 0 and self._is_pid_alive(pid_i):
                        return True
        if c:
            return bool(self._collect_live_pids_for_show_hide(c, it))
        return False

    def _resolve_patch_abs(self) -> str:
        base = str(self.legend_dir_edit.text() or "").strip()
        patch = str(self.patch_dir_edit.text() or "").strip()
        if not patch:
            return ""
        if os.path.isabs(patch):
            return patch
        if base:
            return os.path.join(base, patch)
        return patch

    def _open_micro_dir(self) -> None:
        target = ""
        if self._current_id:
            it = self._get_item_by_id(self._current_id) or {}
            target = str((it or {}).get("micro_cfg_dir") or "").strip()
            if not target:
                name = str((it or {}).get("name") or "").strip()
                safe_name = self._sanitize_dir_name(name)
                if safe_name:
                    target = os.path.join(self._get_micro_configs_root_dir(), safe_name)
        if not target or (not os.path.isdir(target)):
            QtWidgets.QMessageBox.information(self, "提示", "目录无效，请先创建微端配置。")
            return
        try:
            os.startfile(target)  # type: ignore[attr-defined]
        except Exception:
            return

    def _delete_patch_dir(self) -> None:
        cid = str(self._current_id or "").strip()
        if cid:
            it = self._get_item_by_id(cid) or {}
            if self._has_running_process_for_item(cid, it):
                QtWidgets.QMessageBox.information(self, "提示", "请先关闭微端！")
                return
        target = self._resolve_patch_abs()
        if not target or (not os.path.exists(target)):
            QtWidgets.QMessageBox.information(self, "提示", "补丁不存在。")
            return
        tip = "确定删除补丁文件吗？\n" + str(target)
        if os.path.isdir(target):
            tip = "确定删除补丁目录吗？\n" + str(target)
        r = QtWidgets.QMessageBox.question(self, "确认", tip)
        if r != QtWidgets.QMessageBox.Yes:
            return
        it = self._get_item_by_id(cid) or {}
        cfg_dir = self._resolve_micro_cfg_dir_from_item(it)
        ok, err = self._delete_target_with_permission_recovery(target, cfg_dir, cid)
        if not ok:
            QtWidgets.QMessageBox.warning(self, "删除失败", f"错误：{err}")
            return
        QtWidgets.QMessageBox.information(self, "删除成功", "补丁已删除")

    @staticmethod
    def _port_is_free(port: int) -> bool:
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            try:
                s.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
                s.bind(("0.0.0.0", int(port)))
            finally:
                s.close()
            return True
        except Exception:
            return False

    def _check_ports(self) -> None:
        ports = [
            ("服务端口", int(self.server_port_spin.value())),
            ("列表端口", int(self.list_port_spin.value())),
            ("微端端口", int(self.micro_port_spin.value())),
        ]
        lines: list[str] = []
        for label, p in ports:
            if int(p) <= 0:
                continue
            ok = self._port_is_free(p)
            lines.append(f"{label} {p}：{'空闲' if ok else '已占用'}")
        QtWidgets.QMessageBox.information(self, "端口占用", "\n".join(lines) if lines else "请先填写端口")

    @staticmethod
    def _sanitize_dir_name(name: str) -> str:
        s = str(name or "").strip()
        if not s:
            return ""
        bad = '<>:"/\\|?*'
        out = "".join(("_" if ch in bad else ch) for ch in s)
        out = out.strip().strip(".")
        return out

    @classmethod
    def _iter_micro_config_root_candidates(cls, stored_target: str = "") -> list[str]:
        roots: list[str] = []
        seen: set[str] = set()

        def _add(path: str) -> None:
            p = str(path or "").strip()
            if not p:
                return
            try:
                norm = os.path.normcase(os.path.abspath(p))
            except Exception:
                norm = p.lower()
            if norm in seen:
                return
            seen.add(norm)
            roots.append(p)

        target = str(stored_target or "").strip()
        if target:
            try:
                _add(os.path.dirname(os.path.normpath(target)))
            except Exception:
                pass

        exe_dir = ""
        try:
            if getattr(sys, "frozen", False):
                exe_dir = os.path.dirname(str(sys.executable or ""))
        except Exception:
            exe_dir = ""
        if exe_dir:
            _add(os.path.join(exe_dir, "微端配置目录"))
            _add(os.path.join(exe_dir, "微端配置"))
            _add(os.path.join(exe_dir, "micro_configs"))
            _add(os.path.join(exe_dir, "micro_client_configs"))

        _add(_abs_path_here("微端配置目录"))
        _add(_abs_path_here("微端配置"))
        _add(_abs_path_here("micro_configs"))
        _add(_abs_path_here("micro_client_configs"))
        return roots

    @classmethod
    def _find_existing_micro_cfg_dir(cls, stored_target: str, version_name: str) -> str:
        target = str(stored_target or "").strip()
        if target and os.path.isdir(target):
            return os.path.normpath(target)
        safe_name = cls._sanitize_dir_name(version_name)
        if not safe_name:
            return ""
        for root in cls._iter_micro_config_root_candidates(target):
            try:
                cand = os.path.join(root, safe_name)
            except Exception:
                continue
            if os.path.isdir(cand):
                return os.path.normpath(cand)
        return ""

    def _normalize_micro_cfg_item(self, it: dict) -> tuple[dict, bool]:
        item = dict(it or {})
        changed = False
        target = str(item.get("micro_cfg_dir") or "").strip()
        name = str(item.get("name") or "").strip()

        if target:
            norm_target = os.path.normpath(target)
            if norm_target != target:
                item["micro_cfg_dir"] = norm_target
                target = norm_target
                changed = True

        resolved = self._find_existing_micro_cfg_dir(target, name)
        if resolved:
            if str(item.get("micro_cfg_dir") or "").strip() != resolved:
                item["micro_cfg_dir"] = resolved
                changed = True
            return item, changed

        safe_name = self._sanitize_dir_name(name)
        if safe_name:
            fallback = os.path.normpath(os.path.join(self._get_micro_configs_root_dir(), safe_name))
            if target and (target != fallback):
                item["micro_cfg_dir"] = fallback
                changed = True
        return item, changed

    @staticmethod
    def _get_micro_configs_root_dir() -> str:
        candidates: list[str] = []
        exe_dir = ""
        try:
            if getattr(sys, "frozen", False):
                exe_dir = os.path.dirname(str(sys.executable or ""))
        except Exception:
            exe_dir = ""
        if exe_dir:
            candidates.extend(
                [
                    os.path.join(exe_dir, "微端配置目录"),
                    os.path.join(exe_dir, "微端配置"),
                    os.path.join(exe_dir, "micro_configs"),
                    os.path.join(exe_dir, "micro_client_configs"),
                ]
            )
        candidates.extend(
            [
                _abs_path_here("微端配置目录"),
                _abs_path_here("微端配置"),
                _abs_path_here("micro_configs"),
                _abs_path_here("micro_client_configs"),
            ]
        )
        for p in candidates:
            try:
                if os.path.isdir(p):
                    return str(p)
            except Exception:
                continue
        return str(candidates[0])

    def _copy_micro_template_into_toolbox(self, version_name: str) -> str:
        src = str(self.micro_tpl_dir_edit.text() or "").strip()
        if not src:
            QtWidgets.QMessageBox.information(self, "提示", "请选择微端模板文件夹。")
            return ""
        if not os.path.isdir(src):
            QtWidgets.QMessageBox.warning(self, "提示", "微端模板文件夹无效。")
            return ""
        root = self._get_micro_configs_root_dir()
        safe_name = self._sanitize_dir_name(version_name)
        if not safe_name:
            QtWidgets.QMessageBox.warning(self, "提示", "版本名称无效")
            return ""
        if safe_name != str(version_name or "").strip():
            QtWidgets.QMessageBox.information(self, "提示", f"版本名称包含特殊字符，已自动处理为：{safe_name}")
        try:
            os.makedirs(root, exist_ok=True)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "提示", f"创建微端配置目录失败：{e}")
            return ""
        dst = os.path.join(root, safe_name)
        if os.path.exists(dst):
            r = QtWidgets.QMessageBox.question(self, "确认", f"微端配置目录已存在，是否覆盖？\n{dst}")
            if r != QtWidgets.QMessageBox.Yes:
                return ""
            try:
                shutil.rmtree(dst, ignore_errors=False)
            except Exception as e:
                QtWidgets.QMessageBox.warning(self, "提示", f"删除旧目录失败：{e}")
                return ""
        try:
            shutil.copytree(src, dst)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "提示", f"复制微端模板失败：{e}")
            return ""
        return dst

    @staticmethod
    def _find_dir_by_name(root_dir: str, dir_name: str, max_depth: int = 6) -> str:
        root = str(root_dir or "").strip()
        name = str(dir_name or "").strip()
        if not root or (not os.path.isdir(root)) or (not name):
            return ""
        base_sep = root.count(os.sep)
        for cur_root, dirs, _files in os.walk(root):
            depth = cur_root.count(os.sep) - base_sep
            if depth >= max_depth:
                dirs[:] = []
                continue
            for d in dirs:
                if d == name:
                    return os.path.join(cur_root, d)
        return ""

    @staticmethod
    def _pick_existing_file(folder: str, base_name: str, exts: list[str] | None = None) -> str:
        dir_path = str(folder or "").strip()
        base = str(base_name or "").strip()
        if not dir_path or (not os.path.isdir(dir_path)) or (not base):
            return ""
        e = [str(x or "").strip() for x in (exts or []) if str(x or "").strip()]
        if not e:
            e = ["", ".txt", ".ini", ".cfg", ".conf"]
        candidates = [base + x for x in e]
        if exts:
            candidates.append(base)
        for n in candidates:
            p = os.path.join(dir_path, n)
            if os.path.isfile(p):
                if exts and (not n.endswith(tuple(e))):
                    ext0 = e[0] if e else ""
                    if ext0:
                        fixed = os.path.join(dir_path, base + ext0)
                        if not os.path.exists(fixed):
                            try:
                                os.replace(p, fixed)
                                return fixed
                            except Exception:
                                return p
                return p
        if exts and e:
            return os.path.join(dir_path, base + e[0])
        return os.path.join(dir_path, base)

    @staticmethod
    def _ensure_trailing_sep(p: str) -> str:
        s = str(p or "").strip()
        if not s:
            return ""
        if s.endswith("\\") or s.endswith("/"):
            return s
        return s + "\\"

    @staticmethod
    def _is_micro_pak_password_list(path: str) -> bool:
        return os.path.basename(str(path or "").strip()).lower() == "pak.txt"

    @staticmethod
    def _rewrite_micro_pak_path(pak_path: str, patch_root: str, source_root: str = "") -> str:
        source = str(pak_path or "").strip()
        target = os.path.normpath(str(patch_root or "").strip())
        if not source or not target:
            return source

        target_name = os.path.basename(target.rstrip("\\/"))
        source_norm = source.replace("/", "\\")
        _drive, tail = os.path.splitdrive(source_norm)
        parts = [part for part in tail.strip("\\").split("\\") if part]
        relative = ""
        if target_name:
            matches = [index for index, part in enumerate(parts) if part.lower() == target_name.lower()]
            if matches:
                relative = os.path.join(*parts[matches[-1] + 1:]) if matches[-1] + 1 < len(parts) else ""
        if not relative and source_root and os.path.isabs(source_norm):
            try:
                candidate = os.path.relpath(source_norm, source_root)
                if candidate != os.curdir and not candidate.startswith(os.pardir + os.sep):
                    relative = candidate
            except (OSError, ValueError):
                pass
        if not relative:
            if not os.path.isabs(source_norm):
                relative = os.path.join(*parts) if parts else source_norm
            else:
                relative = os.path.basename(source_norm)
        return os.path.normpath(os.path.join(target, relative))

    def _convert_micro_pak_password_line(
        self,
        line: str,
        patch_root: str = "",
        source_root: str = "",
        encoded_password: str | None = None,
    ) -> str:
        text = str(line or "")
        if "|" not in text:
            return text
        pak_path, password = text.split("|", 1)
        output_path = self._rewrite_micro_pak_path(pak_path, patch_root, source_root)
        password = str(password or "").strip()
        if not password:
            return f"{output_path}|"
        encoded = str(encoded_password or "").strip()
        if not encoded:
            raise RuntimeError("PAK 密码服务未返回加密结果")
        return f"{output_path}|{encoded}"

    def _prepare_micro_pak_password_file(self, src_path: str) -> dict:
        source = os.path.abspath(str(src_path or "").strip())
        if not source or not os.path.isfile(source):
            raise OSError("PAK 文件无效，无法读取")
        with open(source, "rb") as stream:
            source_bytes = stream.read()
        lines, enc, ending, trailing_nl = _read_text_file_best_effort(source)
        body_lines = [_strip_any_line_ending(value) for value in lines]
        absolute_paths: list[str] = []
        passwords: list[str] = []
        for line in body_lines:
            if "|" not in line:
                continue
            pak_path, password = line.split("|", 1)
            value = str(pak_path or "").strip().replace("/", "\\")
            if value and os.path.isabs(value):
                absolute_paths.append(os.path.normpath(value))
            normalized_password = str(password or "").strip()
            if normalized_password:
                passwords.append(normalized_password)
        source_root = ""
        if absolute_paths:
            try:
                source_root = os.path.commonpath(absolute_paths)
                if len(absolute_paths) == 1 or os.path.isfile(source_root):
                    source_root = os.path.dirname(source_root)
            except (OSError, ValueError):
                source_root = ""
        return {
            "source_path": source,
            "source_bytes": source_bytes,
            "body_lines": body_lines,
            "encoding": enc or "gbk",
            "ending": ending or "\r\n",
            "trailing_nl": bool(trailing_nl),
            "source_root": source_root,
            "passwords": passwords,
        }

    def _run_micro_pak_rpc(self, passwords: list[str]) -> list[str]:
        values = [str(value or "").strip() for value in list(passwords or [])]
        if not values:
            return []
        active = self._pak_rpc_thread
        if active is not None:
            try:
                active_running = bool(active.isRunning())
            except Exception:
                active_running = False
                self._pak_rpc_thread = None
            if active_running:
                raise RuntimeError("PAK 密码加密任务正在执行，请勿重复提交")
        if self._closing:
            raise _MicroPakRpcCancelled("页面正在关闭")
        session = self._get_session() if callable(self._get_session) else None
        if not isinstance(session, dict):
            raise RuntimeError("请先登录工具箱后再创建微端")
        server_base = str(session.get("server") or "").strip()
        try:
            allow_local_http = _is_backend_loopback_host(urllib.parse.urlsplit(server_base).hostname or "")
        except Exception:
            allow_local_http = False

        thread = QtCore.QThread(self)
        worker = _MicroPakRpcWorker(dict(session), values, VERSION, allow_local_http)
        dialog = _MicroPakRpcProgressDialog(self)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.progress.connect(dialog.set_status, QtCore.Qt.QueuedConnection)
        worker.finished.connect(dialog.finish, QtCore.Qt.QueuedConnection)
        worker.finished.connect(thread.quit)
        worker.finished.connect(worker.deleteLater)
        thread.finished.connect(self._on_pak_rpc_thread_finished)
        dialog.cancel_requested.connect(lambda: worker.request_stop())

        self._pak_rpc_thread = thread
        self._pak_rpc_worker = worker
        self._pak_rpc_dialog = dialog
        button = getattr(self, "create_btn", None)
        if isinstance(button, QtWidgets.QPushButton):
            button.setEnabled(False)
            button.setText("核心处理中...")
            button.setAccessibleName("核心处理中")
        try:
            thread.start()
            # This is a real progress dialog, not a QMessageBox.  Keep its
            # native nested event loop so test/dialog compatibility shims for
            # message boxes cannot short-circuit the worker lifecycle.
            dialog.exec_()
            if thread.isRunning():
                thread.quit()
                thread.wait(35000)
            if thread.isRunning():
                raise RuntimeError("PAK 密码加密任务未能安全结束")
            cancel_requested = dialog.cancel_was_requested()
            result = dict(dialog.result or {})
        finally:
            # A defensive timeout must not drop the only references to a still
            # running QThread. The finished callback owns cleanup in that case.
            try:
                thread_running = bool(thread.isRunning())
            except RuntimeError:
                thread_running = False
            except Exception:
                thread_running = True
            if not thread_running:
                self._on_pak_rpc_thread_finished()
            elif isinstance(button, QtWidgets.QPushButton):
                button.setEnabled(False)

        if self._closing:
            raise _MicroPakRpcCancelled("页面正在关闭")
        if cancel_requested:
            raise _MicroPakRpcCancelled("用户取消 PAK 加密")
        if result.get("cancelled"):
            raise _MicroPakRpcCancelled("用户取消 PAK 加密")
        if result.get("ok") is not True:
            message = str(result.get("error") or "PAK 密码加密服务调用失败")
            code = str(result.get("code") or "core_rpc_error")
            status = result.get("http_status")
            suffix = " [%s%s]" % (code, ("/HTTP %s" % status) if status else "")
            raise RuntimeError(message + suffix)
        encoded = result.get("encoded")
        if not isinstance(encoded, list) or len(encoded) != len(values):
            raise RuntimeError("PAK 密码加密服务返回数量不一致")
        return [str(value or "").strip() for value in encoded]

    def _copy_micro_pak_password_file(
        self,
        src_path: str,
        dst_path: str,
        patch_root: str = "",
        encoded_passwords: list[str] | None = None,
        prepared: dict | None = None,
    ) -> None:
        if isinstance(prepared, dict):
            source = os.path.abspath(str(src_path or "").strip())
            expected_source = os.path.abspath(str(prepared.get("source_path") or "").strip())
            existed, current_bytes = self._micro_file_snapshot(source)
            if (
                not existed
                or os.path.normcase(source) != os.path.normcase(expected_source)
                or current_bytes != bytes(prepared.get("source_bytes") or b"")
            ):
                raise RuntimeError("PAK 文件在核心服务处理期间发生变化，请重新执行")
            body_lines = [str(value) for value in list(prepared.get("body_lines") or [])]
            enc = str(prepared.get("encoding") or "gbk")
            ending = str(prepared.get("ending") or "\r\n")
            trailing_nl = bool(prepared.get("trailing_nl"))
            source_root = str(prepared.get("source_root") or "")
        else:
            prepared = self._prepare_micro_pak_password_file(src_path)
            body_lines = [str(value) for value in list(prepared.get("body_lines") or [])]
            enc = str(prepared.get("encoding") or "gbk")
            ending = str(prepared.get("ending") or "\r\n")
            trailing_nl = bool(prepared.get("trailing_nl"))
            source_root = str(prepared.get("source_root") or "")
        passwords = []
        for line in body_lines:
            if "|" not in line:
                continue
            password = str(line.split("|", 1)[1] or "").strip()
            if password:
                passwords.append(password)
        if encoded_passwords is None:
            raise RuntimeError("正在使用同步网络路径，已拒绝这次 PAK 加密")
        values = list(encoded_passwords)
        if len(values) != len(passwords):
            raise RuntimeError("PAK 密码加密服务返回数量不一致")
        encrypted = iter(values)
        converted = []
        for line in body_lines:
            encoded_password = None
            if "|" in line and str(line.split("|", 1)[1] or "").strip():
                encoded_password = next(encrypted)
            converted.append(
                self._convert_micro_pak_password_line(
                    line,
                    patch_root,
                    source_root,
                    encoded_password=encoded_password,
                )
            )
        _write_text_file_best_effort(dst_path, converted, enc or "gbk", ending or "\r\n", trailing_nl)

    def _post_process_micro_cfg_dir(
        self,
        cfg_dir: str,
        data: dict,
        pak_encoded_passwords: list[str] | None = None,
        pak_prepared: dict | None = None,
    ) -> bool:
        root = str(cfg_dir or "").strip()
        if not root or (not os.path.isdir(root)):
            QtWidgets.QMessageBox.warning(self, "提示", "微端配置目录无效")
            return False

        ip = str((data or {}).get("local_ip") or "").strip() or "127.0.0.1"
        engine = str((data or {}).get("engine") or "").strip()
        version_name = str((data or {}).get("name") or "").strip()
        list_port = int((data or {}).get("list_port") or 0)
        server_port = int((data or {}).get("server_port") or 0)
        micro_port = int((data or {}).get("micro_port") or 0)
        legend_dir = self._ensure_trailing_sep(str((data or {}).get("legend_dir") or "").strip())
        password = str((data or {}).get("password") or "").strip()
        patch_dir = str((data or {}).get("patch_dir") or "").strip()
        patch_root = patch_dir
        if patch_root and not os.path.isabs(patch_root) and legend_dir:
            patch_root = os.path.join(legend_dir, patch_root)
        patch_root = os.path.normpath(patch_root) if patch_root else ""
        patch_name = os.path.basename(os.path.normpath(patch_dir.replace("/", "\\").strip())) if patch_dir else ""
        resources_dir = patch_name or "Resources"

        gw_dir_name = "UpdateGate" if engine == "GOM引擎" else "微端网关"
        gw_dir = (
            self._find_dir_by_name(root, gw_dir_name)
            or self._find_dir_by_name(os.path.join(root, "微端"), gw_dir_name)
            or self._find_dir_by_name(root, "微端网关")
            or self._find_dir_by_name(os.path.join(root, "微端"), "微端网关")
            or self._find_dir_by_name(root, "UpdateGate")
            or self._find_dir_by_name(os.path.join(root, "微端"), "UpdateGate")
            or os.path.join(root, gw_dir_name)
        )
        try:
            os.makedirs(gw_dir, exist_ok=True)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "提示", f"创建微端网关文件目录失败：{e}")
            return False

        if engine == "GOM引擎":
            config_text = "\r\n".join(
                [
                    "[Setup]",
                    "ServerAddr=0.0.0.0",
                    f"ServerPort={int(micro_port)}",
                    "GateAddr=0.0.0.0",
                    f"GatePort={int(list_port)}",
                    "ShowLog=1",
                    "",
                ]
            )
        else:
            config_text = "\r\n".join(
                [
                    "[Setup]",
                    "GateAddr=0.0.0.0",
                    f"GatePort={int(list_port)}",
                    "ShowLog=1",
                    "CheckTime=3000",
                    "",
                ]
            )
        serverinfo_text = f"{ip}:{int(micro_port)} 默认\t0\r\n"
        if engine == "GOM引擎":
            update_server_text = "\r\n".join(
                [
                    "[Setup]",
                    "ServerAddr=0.0.0.0",
                    f"ServerHost={ip}",
                    f"ServerPort={int(server_port)}",
                    "GateAddr=127.0.0.1",
                    f"GatePort={int(micro_port)}",
                    f"MirFilePath={legend_dir}",
                    f"Password={password}",
                    f"Resources={resources_dir}",
                    "ShowSetPakPassword=1",
                    "",
                ]
            )
        else:
            update_server_text = "\r\n".join(
                [
                    "[Setup]",
                    f"MirClientPath={legend_dir}",
                    "ServerAddr=0.0.0.0",
                    f"UpdateServerPort={int(server_port)}",
                    f"UpdateGatePort={int(micro_port)}",
                    f"Password={password}",
                    f"ResourcesDir={resources_dir}",
                    "ShowLogLevel=4",
                    "ClientSendBlockSize=4",
                    "MaxPreAllocatedMemoryCount=4096",
                    f"AppTitle={version_name}",
                    "[LogData]",
                    "IsLogIPData=0",
                    "LogDataIP=",
                    "LogDataFileType=1",
                    "LogDataImageType=1",
                    "LogDataIndexType=1",
                    "LogDataFilterFile=",
                    "EnableAllUpdateGateLink=1",
                    "HideNoRegUpdateGateLinkLog=0",
                    "EnableProtectFile=0",
                    "ProtectFileTriggerAttack=0",
                    "",
                ]
            )

        try:
            gw_cfg_name = "UpdateGate" if engine == "GOM引擎" else "Config"
            with open(self._pick_existing_file(gw_dir, gw_cfg_name, exts=[".ini"]), "w", encoding="gbk", errors="replace", newline="") as f:
                f.write(config_text)
            if engine != "GOM引擎":
                with open(self._pick_existing_file(gw_dir, "!serverinfo", exts=[".txt"]), "w", encoding="gbk", errors="replace", newline="") as f:
                    f.write(serverinfo_text)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "提示", f"写入网关配置失败：{e}")
            return False

        micro_prog_dir_name = "UpdateServer" if engine == "GOM引擎" else "微端程序"
        micro_prog_dir = (
            self._find_dir_by_name(root, micro_prog_dir_name)
            or self._find_dir_by_name(os.path.join(root, "微端"), micro_prog_dir_name)
            or self._find_dir_by_name(root, "微端程序")
            or self._find_dir_by_name(os.path.join(root, "微端"), "微端程序")
            or self._find_dir_by_name(root, "UpdateServer")
            or self._find_dir_by_name(os.path.join(root, "微端"), "UpdateServer")
            or os.path.join(root, micro_prog_dir_name)
        )
        try:
            os.makedirs(micro_prog_dir, exist_ok=True)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "提示", f"创建微端程序目录失败：{e}")
            return False

        try:
            micro_cfg_name = "Config" if engine == "GOM引擎" else "UpdateServer"
            with open(self._pick_existing_file(micro_prog_dir, micro_cfg_name, exts=[".ini"]), "w", encoding="gbk", errors="replace", newline="") as f:
                f.write(update_server_text)
        except Exception as e:
            QtWidgets.QMessageBox.warning(self, "提示", f"写入微端程序配置失败：{e}")
            return False

        pak_path = str((data or {}).get("pak_path") or "").strip()
        if pak_path:
            if not os.path.isfile(pak_path):
                QtWidgets.QMessageBox.warning(self, "提示", "PAK 文件无效，复制失败")
                return False
            try:
                dst_path = os.path.join(micro_prog_dir, os.path.basename(pak_path))
                if self._is_micro_pak_password_list(pak_path):
                    self._copy_micro_pak_password_file(
                        pak_path,
                        dst_path,
                        patch_root,
                        encoded_passwords=pak_encoded_passwords,
                        prepared=pak_prepared,
                    )
                else:
                    shutil.copy2(pak_path, dst_path)
            except Exception as e:
                QtWidgets.QMessageBox.warning(self, "提示", f"复制 PAK 文件失败：{e}")
                return False

        return True

    def _auto_ports(self) -> None:
        def pick(start: int, reserved: set[int]) -> int:
            p = int(start)
            for _ in range(20000):
                if 1 <= p <= 65535 and (p not in reserved) and self._port_is_free(p):
                    return p
                p += 1
            return 0

        start = 8000
        reserved: set[int] = set()
        cur_id = str(self._current_id or "").strip()
        for it in (self._items or []):
            if not isinstance(it, dict):
                continue
            if (not self._editing_new) and cur_id and str(it.get("id") or "").strip() == cur_id:
                continue
            for k in ("list_port", "server_port", "micro_port"):
                try:
                    p = int(it.get(k) or 0)
                except Exception:
                    p = 0
                if p > 0:
                    reserved.add(p)
        p_list = pick(start, reserved)
        if p_list:
            reserved.add(p_list)
        p_server = pick((p_list + 1) if p_list else (start + 1), reserved)
        if p_server:
            reserved.add(p_server)
        p_micro = pick((p_server + 1) if p_server else (start + 2), reserved)

        self.list_port_spin.setValue(int(p_list or 0))
        self.server_port_spin.setValue(int(p_server or 0))
        self.micro_port_spin.setValue(int(p_micro or 0))
        self._check_ports()

    def _refresh_status_clicked(self) -> None:
        self._check_ports()
        self._schedule_status_scan(delay_ms=0, force=True)

    def _not_implemented(self, name: str) -> None:
        QtWidgets.QMessageBox.information(self, "提示", f"{name} 功能正在完善中，当前版本暂未开放。")

    def _resolve_micro_cfg_dir_from_item(self, it: dict) -> str:
        if not isinstance(it, dict):
            return ""
        name = str(it.get("name") or "").strip()
        target = str(it.get("micro_cfg_dir") or "").strip()
        return self._find_existing_micro_cfg_dir(target, name)

    def _start_exe(self, exe_path: str) -> int:
        p = str(exe_path or "").strip()
        if not p or (not os.path.isfile(p)):
            return 0
        try:
            proc = subprocess.Popen([p], cwd=os.path.dirname(p))
            return int(getattr(proc, "pid", 0) or 0)
        except Exception:
            return 0

    @staticmethod
    def _find_exe_under(root_dir: str, file_names: list[str], max_depth: int = 4) -> str:
        root = str(root_dir or "").strip()
        if not root or (not os.path.isdir(root)):
            return ""
        targets = {str(n or "").strip() for n in (file_names or []) if str(n or "").strip()}
        if not targets:
            return ""
        base_sep = root.count(os.sep)
        for cur_root, dirs, files in os.walk(root):
            depth = cur_root.count(os.sep) - base_sep
            if depth >= max_depth:
                dirs[:] = []
            for f in files:
                if f in targets:
                    return os.path.join(cur_root, f)
        return ""

    def _start_micro_from_item(self, it: dict) -> int:
        cfg_dir = self._resolve_micro_cfg_dir_from_item(it)
        if not cfg_dir:
            return 0
        engine = str((it or {}).get("engine") or "").strip()
        no_cache = bool(it.get("no_cache") or False)
        if engine == "GOM引擎":
            exe_names = ["UpdateServer(64位).exe", "UpdateServer（64位）.exe"] if no_cache else ["UpdateServer.exe"]
            folders = ("UpdateServer", "UpdateServer文件", "微端程序", "微端程序文件")
        else:
            exe_names = ["UpdateServer_x64.exe"] if not no_cache else ["UpdateServer_x64(无缓存).exe", "UpdateServer_x64（无缓存）.exe"]
            folders = ("微端程序", "微端程序文件")
        bases = [cfg_dir, os.path.join(cfg_dir, "微端")]
        for base in bases:
            for exe_name in exe_names:
                for folder in folders:
                    p = os.path.join(base, folder, exe_name)
                    pid = self._start_exe(p)
                    if pid:
                        return pid
        found = self._find_exe_under(cfg_dir, exe_names, max_depth=5)
        return self._start_exe(found) if found else 0

    def _start_gateway_from_item(self, it: dict) -> int:
        cfg_dir = self._resolve_micro_cfg_dir_from_item(it)
        if not cfg_dir:
            return 0
        engine = str((it or {}).get("engine") or "").strip()
        exe_names = ["UpdateGate.exe"] if engine == "GOM引擎" else ["MirUpdateGate.exe"]
        folders = ("UpdateGate", "UpdateGate文件", "微端网关", "微端网关文件") if engine == "GOM引擎" else ("微端网关", "微端网关文件")
        bases = [cfg_dir, os.path.join(cfg_dir, "微端")]
        for base in bases:
            for folder in folders:
                for exe_name in exe_names:
                    p = os.path.join(base, folder, exe_name)
                    pid = self._start_exe(p)
                    if pid:
                        return pid
        found = self._find_exe_under(cfg_dir, exe_names, max_depth=5)
        return self._start_exe(found) if found else 0

    @staticmethod
    def _enum_processes_by_name(exe_names: set[str]) -> list[tuple[int, str]]:
        names = {str(n or "").strip().lower() for n in (exe_names or set()) if str(n or "").strip()}
        if not names:
            return []
        if not platform.system().lower().startswith("win"):
            return []

        out: list[tuple[int, str]] = []
        try:
            p = subprocess.run(
                ["tasklist", "/FO", "CSV", "/NH"],
                capture_output=True,
                text=True,
                encoding="mbcs",
                errors="ignore",
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
                check=False,
            )
            txt = (p.stdout or "").strip()
            if not txt:
                return []
            for row in csv.reader(txt.splitlines()):
                if len(row) < 2:
                    continue
                exe = str(row[0] or "").strip().strip('"')
                pid_s = str(row[1] or "").strip().strip('"')
                if (exe or "").lower() not in names:
                    continue
                if not pid_s.isdigit():
                    continue
                out.append((int(pid_s), exe))
        except Exception:
            return []
        return out

