    def _find_update_server_pids_for_cfg_dir(self, cfg_dir: str) -> list[int]:
        if not platform.system().lower().startswith("win"):
            return []
        base = os.path.abspath(str(cfg_dir or "").strip()) if str(cfg_dir or "").strip() else ""
        if not base:
            return []
        names = {
            "updateserver.exe",
            "updateserver(64位).exe",
            "updateserver（64位）.exe",
            "updateserver_x64.exe",
            "updateserver_x64(无缓存).exe",
            "updateserver_x64（无缓存）.exe",
        }
        infos = self._query_processes_info_by_names({n for n in names})
        if infos:
            matched: list[int] = []
            for pid, _name, img, cl in infos:
                if self._process_matches_cfg_dir(base, img, cl):
                    matched.append(pid)
            return list(dict.fromkeys(matched))
        procs = self._enum_processes_by_name({n for n in names})
        matched2: list[int] = []
        for pid, _exe in procs:
            img = self._query_process_image_path(pid)
            cl = "" if img else self._query_process_command_line(pid)
            if self._process_matches_cfg_dir(base, img, cl):
                matched2.append(pid)
        return list(dict.fromkeys(matched2))

