    def _backup_cdk_files(self, paths: list[str], action: str = "") -> tuple[list[str], list[str]]:
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        action_tag = re.sub(r"[^a-z0-9_-]+", "", str(action or "").strip().lower())
        backups: list[str] = []
        errors: list[str] = []
        for raw_path in paths:
            path = str(raw_path or "").strip()
            if not path or not os.path.isfile(path):
                continue
            suffix = f".{timestamp}.{action_tag}.bak" if action_tag else f".{timestamp}.bak"
            backup_path = f"{path}{suffix}"
            try:
                shutil.copy2(path, backup_path)
                backups.append(backup_path)
            except Exception as exc:
                errors.append(f"{path}: {exc}")
        return backups, errors

    def _cleared_cdk_codes_from_backups(self, used_path: str) -> set[str]:
        path = str(used_path or "").strip()
        folder = os.path.dirname(path)
        prefix = os.path.basename(path) + "."
        cleared: set[str] = set()
        if not folder or not os.path.isdir(folder):
            return cleared
        try:
            names = os.listdir(folder)
        except Exception:
            return cleared
        for name in names:
            lower = str(name or "").lower()
            if not name.startswith(prefix) or not lower.endswith(".clear.bak"):
                continue
            for code in self._read_codes_file(os.path.join(folder, name)):
                if code:
                    cleared.add(code)
        return cleared

    @staticmethod
    def _filter_redeem_detail_for_codes(text: str, codes: list[str]) -> str:
        code_set = {str(code or "").strip() for code in codes if str(code or "").strip()}
        if not code_set:
            return str(text or "")
        source = str(text or "")
        kept: list[str] = []
        for raw_line in source.splitlines():
            line = str(raw_line or "")
            stripped = line.replace("\x00", "").strip().lstrip("\ufeff")
            code = stripped.split("_", 1)[0].strip() if "_" in stripped else ""
            if code and code in code_set:
                continue
            kept.append(line)
        result = "\n".join(kept)
        if source.endswith(("\r\n", "\n", "\r")):
            # Keep the source's trailing-record marker even when every record
            # was filtered; this preserves legacy file shape byte-for-byte
            # apart from the intentionally removed records.
            result += "\r\n" if source.endswith("\r\n") else ("\r" if source.endswith("\r") else "\n")
        return result

