    @staticmethod
    def _cdk_summary_value(value: object, fallback: str = "-", limit: int = 8) -> str:
        text = str(value or "").strip()
        if not text:
            return fallback
        if len(text) <= limit:
            return text
        return text[: max(1, limit - 3)] + "..."

    def _refresh_cdk_generation_summary(self, *_args) -> None:
        if not hasattr(self, "cdk_type_preview"):
            return
        type_text = self._cdk_summary_value(self.type_combo.currentText() if hasattr(self, "type_combo") else "", "-", 8)
        charset_text = self._cdk_summary_value(self.charset_combo.currentText() if hasattr(self, "charset_combo") else "", "-", 8)
        length = self.len_spin.value() if hasattr(self, "len_spin") else 0
        count = self.count_spin.value() if hasattr(self, "count_spin") else 0
        self.cdk_type_preview.setText(f"类型 {type_text}")
        self.cdk_len_preview.setText(f"长度 {length}")
        self.cdk_count_preview.setText(f"数量 {count}")
        self.cdk_charset_preview.setText(f"字符 {charset_text}")

    def _connect_cdk_generation_summary_signals(self) -> None:
        for widget in (getattr(self, "type_combo", None), getattr(self, "charset_combo", None)):
            if isinstance(widget, QtWidgets.QComboBox):
                widget.currentIndexChanged.connect(self._refresh_cdk_generation_summary)
                widget.currentTextChanged.connect(self._refresh_cdk_generation_summary)
        for widget in (getattr(self, "len_spin", None), getattr(self, "count_spin", None)):
            if isinstance(widget, QtWidgets.QSpinBox):
                widget.valueChanged.connect(self._refresh_cdk_generation_summary)

