    def _refresh_cdk_summary_pills(
        self,
        *,
        type_name: str | None = None,
        unused: int | None = None,
        used: int | None = None,
        parsed: int | None = None,
        query: str = "",
    ) -> None:
        values = getattr(self, "_base_stats_values", {}) or {}
        raw_type = str(type_name if type_name is not None else values.get("type") or "-").strip() or "-"
        unused_count = int(unused if unused is not None else values.get("unused") or 0)
        used_count = int(used if used is not None else values.get("used") or 0)
        parsed_count = int(parsed if parsed is not None else values.get("parsed") or 0)
        query = str(query or "").strip()

        type_display = raw_type if len(raw_type) <= 12 else raw_type[:11] + "..."
        if query:
            unused_text = f"未使用 {unused_count}/{len(getattr(self, '_view_unused_all', []) or [])}"
            used_text = f"已使用 {used_count}/{len(getattr(self, '_view_used_all', []) or [])}"
        else:
            unused_text = f"未使用 {unused_count}"
            used_text = f"已使用 {used_count}"

        pairs = (
            ("cdk_type_summary", f"类型 {type_display}", f"当前类型：{raw_type}"),
            ("cdk_unused_summary", unused_text, unused_text),
            ("cdk_used_summary", used_text, used_text),
            ("cdk_parsed_summary", f"已解析 {parsed_count}", f"已解析详情：{parsed_count}"),
        )
        for attr, text, tooltip in pairs:
            label = getattr(self, attr, None)
            if isinstance(label, QtWidgets.QLabel):
                label.setText(text)
                label.setToolTip(tooltip)

