        def refill_check_list(lst: QtWidgets.QListWidget, items: list[str]) -> None:
            lst.clear()
            for s in items or []:
                lst.addItem(self._make_spawn_check_list_item(s))

        def do_generate() -> None:
            root2 = self.root_edit.text().strip()
            if not root2:
                QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
                return
            if not self._data:
                QtWidgets.QMessageBox.warning(self, "提示", "当前表格没有数据，请先加载 MonGen.txt")
                return
            ex_map_labels = self._checked_texts(maps_list)
            ex_maps = [str(mapping.get(lbl, lbl)).strip() for lbl in ex_map_labels if str(mapping.get(lbl, lbl)).strip()]
            ex_mons = self._checked_texts(mons_list)
            cfg = {
                "trigger_percent": str(trigger_percent.value()),
                "trigger_people": str(trigger_people.value()),
                "spawn_percent": str(spawn_percent.value()),
                "spawn_interval": str(spawn_interval.value()),
                "clear_interval": str(clear_interval.value()),
                "engine": engine.currentText().strip(),
                "trigger_count_percent": str(trigger_count_percent.value()),
                "exclude_map": ex_maps,
                "exclude_monster": ex_mons,
                "exclude_time_min": ex_time.text().strip(),
                "exclude_count_max": ex_count.text().strip(),
            }
            before = len(self._data)
            try:
                p2 = self._make_spawn_tool(root2, self._data)
                p2._apply_dynamic_spawn(cfg)
                self._data = list(getattr(p2, "data", []) or [])
                self._refresh_table()
                p3 = self._make_spawn_tool(root2, self._data)
                try:
                    map_labels2 = p3._maps_list() or []
                except Exception:
                    map_labels2 = []
                try:
                    mons2 = p3._monsters_list() or []
                except Exception:
                    mons2 = []
                mapping.clear()
                mapping.update(dict(getattr(p3, "_maps_label_to_code", {}) or {}))
                refill_check_list(maps_list, map_labels2)
                refill_check_list(mons_list, mons2)
            except Exception as e:
                QtWidgets.QMessageBox.critical(self, "错误", f"处理失败：{e}")
                return
            after = len(self._data)
            removed = max(0, before - after)
            QtWidgets.QMessageBox.information(self, "完成", f"动态刷怪处理完成，当前共移除 {removed} 条记录")

        btn_gen.clicked.connect(do_generate)

        def do_restore() -> None:
            root2 = self.root_edit.text().strip()
            if not root2:
                QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
                return
            try:
                p2 = self._make_spawn_tool(root2, self._data)
                res = p2._restore_dynamic_spawn_from_backup()
                restored = list(res.get("restored") or [])
                mon_path = str(res.get("mon_path") or "")
            except Exception as e:
                QtWidgets.QMessageBox.critical(self, "错误", f"恢复失败：{e}")
                return

            if mon_path and os.path.exists(mon_path):
                self._load_file(mon_path)
            else:
                self._refresh_table()

            p3 = self._make_spawn_tool(root2, self._data)
            try:
                map_labels2 = p3._maps_list() or []
            except Exception:
                map_labels2 = []
            try:
                mons2 = p3._monsters_list() or []
            except Exception:
                mons2 = []
            mapping.clear()
            mapping.update(dict(getattr(p3, "_maps_label_to_code", {}) or {}))
            refill_check_list(maps_list, map_labels2)
            refill_check_list(mons_list, mons2)

            if not restored:
                QtWidgets.QMessageBox.information(self, "完成", "未找到可用备份（.bak）")
                return
            msg = "\n".join([f"{p} <- {b}" for p, b in restored])
            QtWidgets.QMessageBox.information(self, "完成", "已从备份恢复：\n" + msg)

        btn_restore.clicked.connect(do_restore)

        self._dlg_dynamic_spawn = dlg
        dlg.destroyed.connect(lambda _=None: setattr(self, "_dlg_dynamic_spawn", None))
        dlg.show()

