def _map_settings_is_reparse_point(path: str) -> bool:
    """Reject symlink/junction traversal for the MapInfo-only editor."""
    try:
        st = os.lstat(path)
    except OSError:
        return False
    if stat.S_ISLNK(st.st_mode):
        return True
    attrs = int(getattr(st, "st_file_attributes", 0) or 0)
    return bool(attrs & int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400)))


def _map_settings_resolve_mapinfo(root: str) -> str:
    selected = os.path.abspath(str(root or "").strip().strip('"').strip("'"))
    if not selected or not os.path.isdir(selected):
        raise ValueError("服务端根目录不存在或不可访问")
    if _map_settings_is_reparse_point(selected):
        raise ValueError("根目录不能是符号链接或联接点")
    candidates = []
    if os.path.basename(os.path.normpath(selected)).lower() == "mir200":
        candidates.append(os.path.join(selected, "Envir", "MapInfo.txt"))
    candidates.append(os.path.join(selected, "Mir200", "Envir", "MapInfo.txt"))
    seen = set()
    for candidate in candidates:
        normalized = os.path.normcase(os.path.abspath(candidate))
        if normalized in seen:
            continue
        seen.add(normalized)
        if not os.path.isfile(candidate):
            continue
        try:
            if os.path.commonpath((selected, candidate)) != os.path.commonpath((selected, selected)):
                continue
        except ValueError:
            continue
        current = selected
        relative = os.path.relpath(candidate, selected)
        escaped = False
        for part in relative.split(os.sep):
            current = os.path.join(current, part)
            if _map_settings_is_reparse_point(current):
                escaped = True
                break
        real_root = os.path.normcase(os.path.realpath(selected))
        real_candidate = os.path.normcase(os.path.realpath(candidate))
        try:
            contained = os.path.commonpath((real_root, real_candidate)) == real_root
        except ValueError:
            contained = False
        if escaped or not contained:
            raise ValueError("MapInfo.txt 路径越出所选根目录")
        if os.path.basename(candidate).lower() != "mapinfo.txt":
            continue
        return os.path.abspath(candidate)
    raise ValueError("未找到 Mir200\\Envir\\MapInfo.txt")


def _map_settings_decode(raw: bytes) -> tuple[str, str]:
    if raw.startswith(b"\xef\xbb\xbf"):
        return raw.decode("utf-8-sig", errors="strict"), "utf-8-sig"
    for encoding in ("utf-8", "gbk", "gb18030"):
        try:
            return raw.decode(encoding, errors="strict"), encoding
        except UnicodeDecodeError:
            pass
    raise UnicodeError("MapInfo.txt 不是受支持的 UTF-8/GBK/GB18030 严格编码")


def _map_settings_read_strict(path: str) -> dict:
    with open(path, "rb") as stream:
        raw = stream.read()
        opened_stat = os.fstat(stream.fileno())
    text, encoding = _map_settings_decode(raw)
    ending = _detect_dominant_line_ending(text)
    trailing_nl = text.endswith(("\r\n", "\n", "\r"))
    return {
        "raw": raw,
        "sha256": hashlib.sha256(raw).hexdigest(),
        "text": text,
        "lines": _normalize_line_endings(text.splitlines(True), ending),
        "encoding": encoding,
        "ending": ending,
        "trailing_nl": trailing_nl,
        "identity": (
            int(getattr(opened_stat, "st_dev", 0) or 0),
            int(getattr(opened_stat, "st_ino", 0) or 0),
            os.path.normcase(os.path.realpath(path)),
        ),
    }


def _map_settings_encode_strict(lines: list[str], encoding: str, ending: str, trailing_nl: bool) -> bytes:
    clean = [_strip_any_line_ending(str(line or "")) for line in lines]
    text = str(ending or "\r\n").join(clean)
    if trailing_nl:
        text += str(ending or "\r\n")
    raw = text.encode(str(encoding or "gbk"), errors="strict")
    decoded, _detected = _map_settings_decode(raw)
    if decoded != text:
        raise UnicodeError("MapInfo.txt 编码往返校验失败")
    return raw


def _map_settings_failure_hook(_stage: str) -> None:
    """Probe-only failure seam; production execution is intentionally inert."""
    return None


def _map_settings_write_all(fd: int, payload: bytes) -> None:
    view = memoryview(payload)
    offset = 0
    while offset < len(view):
        written = os.write(fd, view[offset:])
        if written <= 0:
            raise OSError("MapInfo.txt 写入中断")
        offset += written


def _map_settings_unique_backup(path: str, original: bytes) -> str:
    directory = os.path.dirname(path)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    for _attempt in range(32):
        name = "MapInfo_backup_%s_%s.txt" % (stamp, uuid.uuid4().hex[:8])
        backup = os.path.join(directory, name)
        try:
            fd = os.open(backup, os.O_WRONLY | os.O_CREAT | os.O_EXCL | int(getattr(os, "O_BINARY", 0)), 0o600)
        except FileExistsError:
            continue
        valid = False
        try:
            _map_settings_write_all(fd, original)
            os.fsync(fd)
        finally:
            os.close(fd)
        try:
            with open(backup, "rb") as stream:
                valid = stream.read() == original
            if not valid:
                raise OSError("MapInfo.txt 备份校验失败")
            return backup
        finally:
            if not valid:
                try:
                    os.remove(backup)
                except OSError:
                    pass
    raise OSError("无法创建唯一 MapInfo.txt 备份")


def _map_settings_stage_bytes(path: str, payload: bytes, prefix: str) -> str:
    fd, staged = tempfile.mkstemp(prefix=prefix, suffix=".stage", dir=os.path.dirname(path))
    try:
        _map_settings_failure_hook("stage-write")
        _map_settings_write_all(fd, payload)
        _map_settings_failure_hook("fsync")
        os.fsync(fd)
    except Exception:
        os.close(fd)
        try:
            os.remove(staged)
        except OSError:
            pass
        raise
    os.close(fd)
    with open(staged, "rb") as stream:
        if stream.read() != payload:
            try:
                os.remove(staged)
            except OSError:
                pass
            raise OSError("MapInfo.txt 暂存文件校验失败")
    return staged


def _map_settings_atomic_commit(path: str, expected_raw: bytes, new_raw: bytes, expected_identity: tuple) -> str:
    with open(path, "rb") as stream:
        current = stream.read()
    initial_stat = os.stat(path, follow_symlinks=False)
    initial_identity = (
        int(getattr(initial_stat, "st_dev", 0) or 0),
        int(getattr(initial_stat, "st_ino", 0) or 0),
        os.path.normcase(os.path.realpath(path)),
    )
    if _map_settings_is_reparse_point(path):
        raise RuntimeError("MapInfo.txt 路径已变为符号链接或联接点")
    if current != expected_raw or tuple(expected_identity or ()) != initial_identity:
        raise RuntimeError("MapInfo.txt 已被外部修改，已停止保存")
    backup = _map_settings_unique_backup(path, expected_raw)
    staged = ""
    restore = ""
    replaced = False
    try:
        staged = _map_settings_stage_bytes(path, new_raw, ".MapInfo-write-")
        _map_settings_failure_hook("replace")
        if _map_settings_is_reparse_point(path):
            raise RuntimeError("MapInfo.txt 路径已变为符号链接或联接点")
        final_stat = os.stat(path, follow_symlinks=False)
        final_identity = (
            int(getattr(final_stat, "st_dev", 0) or 0),
            int(getattr(final_stat, "st_ino", 0) or 0),
            os.path.normcase(os.path.realpath(path)),
        )
        with open(path, "rb") as stream:
            final_raw = stream.read()
            opened_stat = os.fstat(stream.fileno())
        opened_identity = (
            int(getattr(opened_stat, "st_dev", 0) or 0),
            int(getattr(opened_stat, "st_ino", 0) or 0),
            final_identity[2],
        )
        if (
            final_identity != tuple(expected_identity or ())
            or opened_identity != final_identity
            or final_raw != expected_raw
            or hashlib.sha256(final_raw).digest() != hashlib.sha256(expected_raw).digest()
        ):
            raise RuntimeError("MapInfo.txt 已在替换窗口被外部修改，已停止保存")
        os.replace(staged, path)
        staged = ""
        replaced = True
        _map_settings_failure_hook("post-verify")
        with open(path, "rb") as stream:
            if stream.read() != new_raw:
                raise OSError("MapInfo.txt 保存后校验失败")
        return backup
    except Exception:
        if replaced:
            restore = _map_settings_stage_bytes(path, expected_raw, ".MapInfo-restore-")
            os.replace(restore, path)
            restore = ""
            with open(path, "rb") as stream:
                if stream.read() != expected_raw:
                    raise OSError("MapInfo.txt 故障回滚校验失败")
        raise
    finally:
        for residue in (staged, restore):
            if residue:
                try:
                    os.remove(residue)
                except OSError:
                    pass


