    def __init__(self, session_getter, get_root_dir):
        super().__init__()
        self._session_getter = session_getter
        self._get_root_dir = get_root_dir
        self._maps_data: dict[str, dict] = {}
        self._maps_order: list[str] = []
        self._map_list_keys: list[str] = []
        self._current_key = ""
        self._current_file_path = ""
        self._current_encoding = "gbk"
        self._current_line_ending = "\r\n"
        self._current_trailing_nl = True
        self._loaded_source_raw = b""
        self._loaded_source_sha256 = ""
        self._map_form_loading = False
        self._map_dirty = False
        self._build_ui()
        try:
            self.root_edit.setText(str(self._get_root_path() or ""))
        except Exception:
            pass

