        outer.setSpacing(UiMetrics.MAP_SETTINGS_PAGE_SPACING)

        self.map_settings_bar = self._build_map_settings_bar()
        outer.addWidget(self.map_settings_bar, 0)
        outer.addWidget(self._build_map_workspace(), 1)
        self._connect_map_controls()

