    def _build_map_panel_header(self, title: str, badge_text: str = "", object_name: str = "mapPanelHeader") -> QtWidgets.QFrame:
        header = QtWidgets.QFrame()
        header.setObjectName(object_name)
        layout = QtWidgets.QHBoxLayout(header)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(8)
        title_label = QtWidgets.QLabel(str(title or ""))
        title_label.setObjectName("mapPanelTitle")
        layout.addWidget(title_label, 0)
        layout.addStretch(1)
        badge = QtWidgets.QLabel(str(badge_text or ""))
        badge.setObjectName("mapPanelBadge")
        badge.setProperty("badgeRole", "muted")
        badge.setAlignment(QtCore.Qt.AlignCenter)
        layout.addWidget(badge, 0)
        badge.setVisible(bool(str(badge_text or "").strip()))
        _refresh_ui_dynamic_qss(badge)
