    def _set_map_panel_badge(self, badge: QtWidgets.QLabel | None, text: str, role: str = "muted") -> None:
        if not isinstance(badge, QtWidgets.QLabel):
            return
        raw_text = str(text or "").strip()
        display_text = raw_text
        if len(display_text) > 18:
            display_text = display_text[:17] + "..."
        badge.setText(display_text)
        badge.setToolTip(raw_text)
        badge.setMaximumWidth(132)
        badge.setVisible(bool(raw_text))
        badge.setProperty("badgeRole", str(role or "").strip() or "muted")
        try:
            badge.style().unpolish(badge)
            badge.style().polish(badge)
            badge.update()
        except Exception:
            pass

    def _refresh_map_list_badge(self) -> None:
        badge = getattr(self, "map_list_badge", None)
        if not isinstance(badge, QtWidgets.QLabel):
            return
        visible_count = len(getattr(self, "_map_list_keys", []) or [])
        total_count = len(getattr(self, "_maps_order", []) or [])
        keyword = str(self.search_edit.text() or "").strip() if hasattr(self, "search_edit") else ""
        if keyword and total_count > 0:
            self._set_map_panel_badge(badge, f"{visible_count} / {total_count} 张", "info")
        else:
            self._set_map_panel_badge(badge, f"{visible_count} 张地图", "muted")

    def _refresh_map_editor_badge(self, text: str = "", role: str = "muted") -> None:
        raw_text = str(text or "").strip()
        display_text = raw_text
        if " / " in raw_text:
            display_text = raw_text.split(" / ", 1)[0].strip()
        self._set_map_panel_badge(getattr(self, "map_editor_badge", None), display_text, role)
        badge = getattr(self, "map_editor_badge", None)
        if isinstance(badge, QtWidgets.QLabel):
            badge.setToolTip(raw_text)

    def _make_map_summary_pill(self, text: str, role: str = "metric") -> QtWidgets.QLabel:
        label = QtWidgets.QLabel(str(text or ""))
