    def _refresh_map_editor_summary(self, *_args) -> None:
        map_id = str(self.map_id_edit.text() or "").strip() if hasattr(self, "map_id_edit") else ""
        map_name = str(self.map_name_edit.text() or "").strip() if hasattr(self, "map_name_edit") else ""
        current_text = f"当前 {map_id or '未选择'}"
        current_tip = map_name or map_id or "等待选择地图"
        flag_count = 0
        for cb in getattr(self, "boolean_vars", {}).values():
            if isinstance(cb, QtWidgets.QCheckBox) and cb.isChecked():
                flag_count += 1
        value_count = 0
        for edit in getattr(self, "value_vars", {}).values():
            if isinstance(edit, QtWidgets.QLineEdit) and str(edit.text() or "").strip():
                value_count += 1
        custom_text = ""
        custom_edit = getattr(self, "custom_param_edit", None)
        if isinstance(custom_edit, QtWidgets.QPlainTextEdit):
            custom_text = str(custom_edit.toPlainText() or "")
        custom_count = len([line for line in custom_text.splitlines() if str(line or "").strip()])
        self._set_map_summary_pill(getattr(self, "map_summary_current_pill", None), current_text, current_tip)
        self._set_map_summary_pill(
            getattr(self, "map_summary_flags_pill", None),
            f"开关 {flag_count}",
            "当前地图已启用的开关参数数量",
        )
        self._set_map_summary_pill(
            getattr(self, "map_summary_values_pill", None),
            f"带值 {value_count}",
            "当前地图已填写的带值参数数量",
        )
        self._set_map_summary_pill(
            getattr(self, "map_summary_custom_pill", None),
            f"自定义 {custom_count}",
            "当前地图自定义参数行数",
        )

