    def _build_map_boolean_params_box(self) -> QtWidgets.QGroupBox:
        bool_box, body = self._build_map_section("开关参数")
        bool_grid = QtWidgets.QGridLayout(body)
        bool_grid.setContentsMargins(0, 0, 0, 0)
        bool_grid.setHorizontalSpacing(UiMetrics.MAP_SETTINGS_BOOLEAN_GRID_H_SPACING)
        bool_grid.setVerticalSpacing(UiMetrics.MAP_SETTINGS_BOOLEAN_GRID_V_SPACING)
        self.boolean_vars: dict[str, QtWidgets.QCheckBox] = {}
        bool_items = list(self.BOOLEAN_PARAMETERS.items())
        bool_cols = max(2, int(getattr(UiMetrics, "MAP_SETTINGS_BOOLEAN_COLS", 3)))
        bool_rows = (len(bool_items) + bool_cols - 1) // bool_cols
        for idx, (param, desc) in enumerate(bool_items):
            row = idx % bool_rows
            col = idx // bool_rows
            cb = QtWidgets.QCheckBox(desc)
            cb.setObjectName("mapBooleanParamCheck")
            cb.setProperty("mapBooleanParam", True)
            cb.setToolTip(f"{desc}\n{param}")
            cb.setAccessibleName(f"{param}：{desc}")
            cb.setFixedHeight(UiMetrics.MAP_SETTINGS_BOOLEAN_ROW_H)
            cb.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
            self.boolean_vars[param] = cb
            bool_grid.addWidget(cb, row, col)
        return bool_box

    def _build_map_value_params_box(self) -> QtWidgets.QGroupBox:
        val_box, body = self._build_map_section("带值参数")
        val_grid = QtWidgets.QGridLayout(body)
        val_grid.setContentsMargins(0, 0, 0, 0)
        val_grid.setHorizontalSpacing(UiMetrics.MAP_SETTINGS_VALUE_GRID_H_SPACING)
        val_grid.setVerticalSpacing(UiMetrics.MAP_SETTINGS_VALUE_GRID_V_SPACING)
        self.value_vars: dict[str, QtWidgets.QLineEdit] = {}
        for row, (param, desc) in enumerate(self.VALUE_PARAMETERS.items()):
            val_grid.addWidget(QtWidgets.QLabel(param), row, 0)
            val_grid.addWidget(QtWidgets.QLabel(desc), row, 1)
            edit = _make_ui_line_edit("normal")
            edit.setObjectName(f"mapValueParamEdit_{param}")
            self.value_vars[param] = edit
            val_grid.addWidget(edit, row, 2)
        val_grid.setColumnStretch(2, 1)
        return val_box

    def _build_map_custom_params_box(self) -> QtWidgets.QGroupBox:
        custom_box, body = self._build_map_section("自定义参数")
        custom_l = QtWidgets.QVBoxLayout(body)
        custom_l.setContentsMargins(0, 0, 0, 0)
        self.custom_param_edit = QtWidgets.QPlainTextEdit()
        self.custom_param_edit.setObjectName("mapCustomParamEdit")
        self.custom_param_edit.setPlaceholderText("每行一个参数，支持 PARAM 或 PARAM(value) 格式")
        self.custom_param_edit.setMinimumHeight(UiMetrics.MAP_SETTINGS_CUSTOM_PARAM_EDIT_MIN_H)
        self.custom_param_edit.setMaximumHeight(UiMetrics.MAP_SETTINGS_CUSTOM_PARAM_EDIT_MAX_H)
        custom_l.addWidget(self.custom_param_edit)
        return custom_box

    def _connect_map_controls(self) -> None:
        self.browse_btn.clicked.connect(self._choose_root_dir)
        self.reload_btn.clicked.connect(self._request_reload_map_info)
        self.save_btn.clicked.connect(self.save_current_map)
        self.search_edit.textChanged.connect(self._refill_map_list)
        self.map_list.currentItemChanged.connect(self._on_map_selected)
        self.map_id_edit.textChanged.connect(self._on_map_form_changed)
        self.map_name_edit.textChanged.connect(self._on_map_form_changed)
        self.parent_id_edit.textChanged.connect(self._on_map_form_changed)
        self.copy_id_edit.textChanged.connect(self._on_map_form_changed)
        for cb in self.boolean_vars.values():
            cb.toggled.connect(self._on_map_form_changed)
        for edit in self.value_vars.values():
            edit.textChanged.connect(self._on_map_form_changed)
        self.custom_param_edit.textChanged.connect(self._on_map_form_changed)

    def _set_map_edit_state(self, text: str, role: str = "muted") -> None:
        label = getattr(self, "edit_state_label", None)
        if not isinstance(label, QtWidgets.QLabel):
            return
        label.setText(str(text or ""))
        label.setProperty("stateRole", str(role or "muted"))
        _refresh_ui_dynamic_qss(label)

    def _set_map_dirty(self, dirty: bool, saved: bool = False) -> None:
        self._map_dirty = bool(dirty)
        if self._map_dirty:
            self._set_map_edit_state("已修改", "warning")
        elif saved:
            self._set_map_edit_state("已保存", "success")
        else:
            self._set_map_edit_state("未修改", "muted")

    def _on_map_form_changed(self, *_args) -> None:
        self._refresh_map_editor_summary()
        if not self._map_form_loading and self._current_key:
            self._set_map_dirty(True)

    def _confirm_dirty_action(self, action_text: str) -> str:
        box = QtWidgets.QMessageBox(self)
        box.setIcon(QtWidgets.QMessageBox.Warning)
        box.setWindowTitle("地图尚未保存")
        box.setText(f"当前地图有未保存修改，{action_text}前要如何处理？")
        save_button = box.addButton("保存", QtWidgets.QMessageBox.AcceptRole)
        discard_button = box.addButton("放弃修改", QtWidgets.QMessageBox.DestructiveRole)
        cancel_button = box.addButton("取消", QtWidgets.QMessageBox.RejectRole)
        box.setDefaultButton(cancel_button)
        box.exec_()
        clicked = box.clickedButton()
        if clicked is save_button:
            return "save"
        if clicked is discard_button:
            return "discard"
        return "cancel"

    def _resolve_dirty_action(self, action_text: str) -> bool:
        if not self._map_dirty:
            return True
        decision = self._confirm_dirty_action(action_text)
        if decision == "save":
            return bool(self.save_current_map())
        if decision == "discard":
            self._set_map_dirty(False)
            return True
        return False

    def _request_reload_map_info(self, _checked: bool = False) -> None:
        if not self._resolve_dirty_action("重新读取"):
            return
        current = self._maps_data.get(self._current_key) or {}
        self.reload_map_info(
            preferred_map_id=str(current.get("id") or ""),
            preferred_map_name=str(current.get("name") or ""),
        )

