    def _get_root_path(self) -> str:
        try:
            return str(self._get_root_dir() or "").strip()
        except Exception:
            return ""

    def _set_status(self, text: str) -> None:
        self.status_label.setText(str(text or ""))
        header_status = getattr(self, "header_status_label", None)
        if isinstance(header_status, QtWidgets.QLabel):
            header_status.setText(str(text or ""))

    def _choose_root_dir(self) -> None:
        cur = self.root_edit.text().strip() or self._get_root_path()
        folder = QtWidgets.QFileDialog.getExistingDirectory(self, "选择服务端根目录", cur or os.getcwd())
        if folder:
            self.root_edit.setText(folder)
            self.reload_map_info()

    def _locate_mapinfo_path(self) -> str:
        root = str(self.root_edit.text() or "").strip()
        if not root:
            return ""
        return _map_settings_resolve_mapinfo(root)

    @staticmethod
    def _extract_map_id_from_def_line(line: str) -> str:
        s = _strip_any_line_ending(str(line or "")).strip()
        if not s.startswith("[") or "]" not in s:
            return ""
        inner = s[1:s.find("]")]
        first = re.split(r"[\t ]+", inner.strip(), maxsplit=1)[0].strip()
        if "|" in first:
            first = first.split("|", 1)[0].strip()
        return first

    @classmethod
    def _parse_parameters(cls, params_text: str) -> dict[str, str]:
        params: dict[str, str] = {}
        for part in re.split(r"[\s\t]+", str(params_text or "").strip()):
            piece = str(part or "").strip()
            if not piece:
                continue
            if "(" in piece and piece.endswith(")"):
                name = piece[:piece.find("(")].strip()
                value = piece[piece.find("(") + 1:-1]
                if not name:
                    continue
                key = name.upper()
                if key in cls.BOOLEAN_PARAMETERS:
                    params[key] = ""
                elif key in cls.VALUE_PARAMETERS:
                    params[key] = value
                else:
                    params[name] = value
                continue
            key = piece.upper()
            if key in cls.BOOLEAN_PARAMETERS:
                params[key] = ""
            elif key in cls.VALUE_PARAMETERS:
                params[key] = ""
            elif piece not in params:
                params[piece] = ""
        return params

    @classmethod
    def _build_parameter_string(cls, params: dict[str, str]) -> str:
        parts: list[str] = []
        for key, value in (params or {}).items():
            name = str(key or "").strip()
            if not name:
                continue
            if value is None or str(value) == "":
                parts.append(name.upper() if name.upper() in cls.BOOLEAN_PARAMETERS else name)
            else:
                parts.append(f"{name.upper() if name.upper() in cls.VALUE_PARAMETERS else name}({value})")
        return " ".join(parts)

    @staticmethod
    def _build_unique_key(map_id: str, map_name: str) -> str:
        return f"{str(map_id or '').strip()}__{str(map_name or '').strip()}"

    @staticmethod
    def _display_encoding_name(encoding: str) -> str:
        enc = str(encoding or "").strip()
        normalized = enc.lower()
        if normalized in ("utf-8-sig", "utf-8-sid"):
            return "UTF-8 BOM"
        if normalized == "utf-8":
            return "UTF-8"
        if normalized in ("gbk", "gb18030", "utf-16"):
            return normalized.upper()
        return enc or "unknown"

    def reload_map_info(self, preferred_map_id: str = "", preferred_map_name: str = "") -> None:
        try:
            path = self._locate_mapinfo_path()
        except Exception as e:
            self._maps_data = {}
            self._maps_order = []
            self._current_key = ""
            self._current_file_path = ""
            self._loaded_source_raw = b""
            self._loaded_source_sha256 = ""
            self._refill_map_list()
            self._clear_form()
            self._set_status("加载失败：%s" % e)
            return
        try:
            source = _map_settings_read_strict(path)
            lines = list(source["lines"])
            enc = str(source["encoding"])
            ending = str(source["ending"])
            trailing_nl = bool(source["trailing_nl"])
            self._current_file_path = path
            self._current_encoding = enc
            self._current_line_ending = ending
            self._current_trailing_nl = trailing_nl
            self._loaded_source_raw = bytes(source["raw"])
            self._loaded_source_sha256 = str(source["sha256"])
            self._parse_map_lines(lines)
            self._refill_map_list(preferred_map_id=preferred_map_id, preferred_map_name=preferred_map_name)
            self._set_status(f"已加载 {len(self._maps_order)} 张地图，编码：{self._display_encoding_name(enc)}")
            self._set_map_dirty(False)
        except Exception as e:
            self._set_status(f"加载失败：{e}")

    def _parse_map_lines(self, lines: list[str]) -> None:
        self._maps_data = {}
        self._maps_order = []
        current_key = ""
        for raw_line in lines or []:
            line = _strip_any_line_ending(str(raw_line or ""))
            s = line.strip()
            if not s or s.startswith(";"):
                continue
            if s.startswith("[") and "]" in s:
                end_bracket = s.find("]")
                map_def = s[1:end_bracket]
                rest = s[end_bracket + 1:].strip()
                parts = re.split(r"[\t ]+", map_def.strip())
                if len(parts) < 2:
                    current_key = ""
                    continue
                map_id = str(parts[0] or "").strip()
                map_name = str(parts[1] or "").strip()
                copy_id = ""
                if "|" in map_id:
                    map_id, copy_id = [x.strip() for x in map_id.split("|", 1)]
                parent_id = str(parts[2] or "").strip() if len(parts) >= 3 else ""
                key = self._build_unique_key(map_id, map_name)
                self._maps_data[key] = {
                    "id": map_id,
                    "name": map_name,
                    "parent_id": parent_id,
                    "copy_id": copy_id,
                    "parameters": {},
                    "source_id": map_id,
                    "source_name": map_name,
                    "definition_parameters": self._parse_parameters(rest),
                    "independent_parameters": {},
                }
                if rest:
                    self._maps_data[key]["parameters"].update(self._parse_parameters(rest))
                self._maps_order.append(key)
                current_key = key
                continue
            if ("\t" in s) and ("->" not in s):
                parts = s.split("\t", 1)
                if len(parts) >= 2:
                    map_id = str(parts[0] or "").strip()
                    params = self._parse_parameters(parts[1])
                    for key in self._maps_order:
                        item = self._maps_data.get(key) or {}
                        if str(item.get("id") or "").strip() == map_id:
                            item.setdefault("parameters", {}).update(params)
                            item.setdefault("independent_parameters", {}).update(params)
                            current_key = key
                            break
                continue
            if current_key and self._maps_data.get(current_key):
                continue

    def _make_map_list_item(self, label: object, key: str) -> QtWidgets.QListWidgetItem:
        text = str(label or "")
        item = QtWidgets.QListWidgetItem(text)
        item.setToolTip(text.strip())
        item.setData(QtCore.Qt.UserRole, key)
        return item

    def _refresh_map_list_current_style(self) -> None:
        if not hasattr(self, "map_list"):
            return
        base_font = QtGui.QFont(self.map_list.font())
        selected_font = QtGui.QFont(base_font)
        selected_font.setWeight(QtGui.QFont.DemiBold)
        selected_fg = QtGui.QBrush(QtGui.QColor("#92400E"))
        current_row = self.map_list.currentRow()
        for row in range(self.map_list.count()):
            item = self.map_list.item(row)
            if item is None:
                continue
            if row == current_row:
                item.setFont(selected_font)
                item.setForeground(selected_fg)
            else:
                item.setFont(base_font)
                item.setData(QtCore.Qt.ForegroundRole, None)

    def _refill_map_list(self, _text: str = "", preferred_map_id: str = "", preferred_map_name: str = "") -> None:
        kw = self.search_edit.text().strip().lower()
        self.map_list.blockSignals(True)
        self.map_list.clear()
        self._map_list_keys = []
        selected_row = -1
        for key in self._maps_order:
            item = self._maps_data.get(key) or {}
            map_id = str(item.get("id") or "").strip()
            map_name = str(item.get("name") or "").strip()
            label = f"{map_id}  {map_name}" if map_id and map_name else (map_id or map_name)
            full_label = f"{map_id}  {map_name}" if map_id and map_name else (map_name or map_id)
            hay = f"{map_id} {map_name}".lower()
            if kw and kw not in hay:
                continue
            lw_item = self._make_map_list_item(label, key)
            lw_item.setToolTip(full_label)
            self.map_list.addItem(lw_item)
            self._map_list_keys.append(key)
            if preferred_map_id and map_id == preferred_map_id and (not preferred_map_name or map_name == preferred_map_name):
                selected_row = self.map_list.count() - 1
            elif key == self._current_key and selected_row < 0:
                selected_row = self.map_list.count() - 1
        self.map_list.blockSignals(False)
        self._refresh_map_list_badge()
        if self.map_list.count() <= 0:
            self._clear_form()
            return
        if selected_row < 0:
            selected_row = 0
        self.map_list.setCurrentRow(selected_row)
        self._refresh_map_list_current_style()

    def _clear_form(self) -> None:
        self._map_form_loading = True
        try:
            self.map_id_edit.clear()
            self.map_name_edit.clear()
            self.parent_id_edit.clear()
            self.copy_id_edit.clear()
            self.custom_param_edit.clear()
            for cb in self.boolean_vars.values():
                cb.setChecked(False)
            for edit in self.value_vars.values():
                edit.clear()
        finally:
            self._map_form_loading = False
        self._set_map_dirty(False)
        self._refresh_map_editor_badge("等待选择", "muted")
        self._refresh_map_editor_summary()

    def _on_map_selected(self, current: QtWidgets.QListWidgetItem, previous: QtWidgets.QListWidgetItem) -> None:
        self._refresh_map_list_current_style()
        key = str(current.data(QtCore.Qt.UserRole) or "").strip() if current else ""
        if key != self._current_key and self._map_dirty and not self._resolve_dirty_action("切换地图"):
            self.map_list.blockSignals(True)
            try:
                if previous is not None:
                    self.map_list.setCurrentItem(previous)
                else:
                    self.map_list.clearSelection()
            finally:
                self.map_list.blockSignals(False)
            self._refresh_map_list_current_style()
            return
        self._current_key = key
        item = self._maps_data.get(key) or {}
        if not item:
            self._clear_form()
            return
        map_id = str(item.get("id") or "")
        map_name = str(item.get("name") or "")
        self._map_form_loading = True
        try:
            self.map_id_edit.setText(map_id)
            self.map_name_edit.setText(map_name)
            self.parent_id_edit.setText(str(item.get("parent_id") or ""))
            self.copy_id_edit.setText(str(item.get("copy_id") or ""))
            params = dict(item.get("parameters") or {})
            custom_lines: list[str] = []
            for name, cb in self.boolean_vars.items():
                cb.setChecked(name in params)
            for name, edit in self.value_vars.items():
                edit.setText(str(params.get(name) or ""))
            for p_name, p_value in params.items():
                if p_name in self.boolean_vars or p_name in self.value_vars:
                    continue
                custom_lines.append(f"{p_name}({p_value})" if str(p_value or "") else str(p_name))
            self.custom_param_edit.setPlainText("\n".join(custom_lines))
        finally:
            self._map_form_loading = False
        self._set_map_dirty(False)
        badge_text = f"{map_id} / {map_name}" if map_name else map_id
        self._refresh_map_editor_badge(badge_text, "info")
        self._refresh_map_editor_summary()

    def _collect_form_parameters(self) -> dict[str, str]:
        params: dict[str, str] = {}
        for name, cb in self.boolean_vars.items():
            if cb.isChecked():
                params[name] = ""
        for name, edit in self.value_vars.items():
            value = str(edit.text() or "").strip()
            if value:
                params[name] = value
        for raw_line in str(self.custom_param_edit.toPlainText() or "").splitlines():
            line = raw_line.strip()
            if not line:
                continue
            if "(" in line and line.endswith(")"):
                name = line[:line.find("(")].strip()
                value = line[line.find("(") + 1:-1]
                if name:
                    params[name] = value
            else:
                params[line] = ""
        return params

    def _prepare_map_save(self) -> dict:
        if not self._current_key or self._current_key not in self._maps_data:
            raise ValueError("请先选择地图")
        path = self._current_file_path or self._locate_mapinfo_path()
        if not path or not os.path.isfile(path):
            raise ValueError("未找到 MapInfo.txt")
        item = self._maps_data.get(self._current_key) or {}
        source_id = str(item.get("source_id") or item.get("id") or "").strip()
        source_name = str(item.get("source_name") or item.get("name") or "").strip()
        new_id = str(self.map_id_edit.text() or "").strip()
        new_name = str(self.map_name_edit.text() or "").strip()
        if not new_id or not new_name:
            raise ValueError("地图编号和地图名称不能为空")
        new_parent = str(self.parent_id_edit.text() or "").strip()
        new_copy = str(self.copy_id_edit.text() or "").strip()
        new_params = self._collect_form_parameters()
        source = _map_settings_read_strict(path)
        if not self._loaded_source_raw or str(source["sha256"]) != self._loaded_source_sha256:
            raise RuntimeError("MapInfo.txt 已被外部修改，请重新读取")
        lines = list(source["lines"])
        enc = str(source["encoding"])
        ending = str(source["ending"])
        trailing_nl = bool(source["trailing_nl"])
        def_idx = -1
        end_idx = len(lines)
        param_idx = -1
        for i, raw_line in enumerate(lines):
            s = _strip_any_line_ending(str(raw_line or "")).strip()
            if not s:
                continue
            if s.startswith("[") and "]" in s:
                map_id = self._extract_map_id_from_def_line(s)
                bracket = s[1:s.find("]")].strip()
                bracket_parts = re.split(r"[\t ]+", bracket)
                candidate_name = str(bracket_parts[1] or "").strip() if len(bracket_parts) >= 2 else ""
                if def_idx < 0:
                    if map_id == source_id and (not source_name or candidate_name == source_name):
                        def_idx = i
                        continue
                elif i > def_idx:
                    end_idx = i
                    break
            if def_idx >= 0 and i > def_idx and ("\t" in s) and ("->" not in s):
                parts = s.split("\t", 1)
                if len(parts) >= 2 and str(parts[0] or "").strip() == source_id:
                    param_idx = i
        if def_idx < 0:
            raise ValueError(f"未找到地图定义：{source_id}")

        old_def = _strip_any_line_ending(str(lines[def_idx] or ""))
        old_param = _strip_any_line_ending(str(lines[param_idx] or "")) if param_idx >= 0 else "(无独立参数行)"
        definition_keys = list((item.get("definition_parameters") or {}).keys())
        independent_keys = list((item.get("independent_parameters") or {}).keys())
        definition_params = {key: new_params[key] for key in definition_keys if key in new_params}
        independent_params = {key: new_params[key] for key in independent_keys if key in new_params and key not in definition_params}
        for key, value in new_params.items():
            if key not in definition_params and key not in independent_params:
                independent_params[key] = value
        if new_copy:
            new_def = f"[{new_id}|{new_copy}\t{new_name}]"
        else:
            new_def = f"[{new_id}\t{new_name}"
            if new_parent and new_parent != "0":
                new_def += f"\t{new_parent}"
            new_def += "]"
        definition_param_text = self._build_parameter_string(definition_params)
        if definition_param_text:
            new_def += " " + definition_param_text
        param_text = self._build_parameter_string(independent_params)
        new_param_line = f"{new_id}\t{param_text}" if param_text else "(删除独立参数行)"
        lines[def_idx] = new_def

        for i in range(def_idx + 1, end_idx):
            s = _strip_any_line_ending(str(lines[i] or ""))
            stripped = s.strip()
            if ("\t" in stripped) and ("->" in stripped):
                parts = s.split("\t")
                if parts and str(parts[0] or "").strip() == source_id:
                    parts[0] = new_id
                    lines[i] = "\t".join(parts)
            elif ("\t" in stripped) and ("->" not in stripped):
                parts = s.split("\t", 1)
                if len(parts) >= 2 and str(parts[0] or "").strip() == source_id:
                    lines[i] = f"{new_id}\t{parts[1]}"

        if param_text:
            if param_idx >= 0:
                lines[param_idx] = new_param_line
            else:
                insert_at = end_idx
                while insert_at > def_idx + 1:
                    prev = _strip_any_line_ending(str(lines[insert_at - 1] or ""))
                    if prev.strip():
                        break
                    insert_at -= 1
                lines.insert(insert_at, new_param_line)
        elif param_idx >= 0:
            lines.pop(param_idx)
        preview = (
            f"文件：{path}\n\n"
            f"地图定义\n修改前：{old_def}\n修改后：{new_def}\n\n"
            f"参数行\n修改前：{old_param}\n修改后：{new_param_line}\n\n"
            "确认后将先创建唯一备份，再以同目录原子事务写入 MapInfo.txt。"
        )
        return {
            "path": path, "lines": lines, "encoding": enc, "ending": ending,
            "trailing_nl": trailing_nl, "new_id": new_id, "new_name": new_name,
            "preview": preview, "expected_raw": bytes(source["raw"]),
            "expected_identity": tuple(source["identity"]),
        }

    def _confirm_map_save_preview(self, preview: str) -> bool:
        dialog = QtWidgets.QDialog(self)
        dialog.setObjectName("mapSavePreviewDialog")
        dialog.setWindowTitle("保存地图预检")
        dialog.setModal(True)
        dialog.setMinimumSize(760, 430)
        layout = QtWidgets.QVBoxLayout(dialog)
        layout.setContentsMargins(16, 14, 16, 14)
        layout.setSpacing(10)
        title = QtWidgets.QLabel("请确认 MapInfo.txt 原始行变更")
        title.setObjectName("mapSavePreviewTitle")
        title.setWordWrap(True)
        layout.addWidget(title, 0)
        preview_view = QtWidgets.QPlainTextEdit(dialog)
        preview_view.setObjectName("mapSavePreviewText")
        preview_view.setReadOnly(True)
        preview_view.setLineWrapMode(QtWidgets.QPlainTextEdit.WidgetWidth)
        preview_view.setPlainText(str(preview or ""))
        preview_view.setMinimumHeight(300)
        preview_view.setFocusPolicy(QtCore.Qt.NoFocus)
        layout.addWidget(preview_view, 1)
        buttons = QtWidgets.QDialogButtonBox(dialog)
        buttons.setObjectName("mapSavePreviewButtons")
        save_button = buttons.addButton("确认保存", QtWidgets.QDialogButtonBox.AcceptRole)
        save_button.setObjectName("mapSavePreviewConfirmButton")
        cancel_button = buttons.addButton("取消", QtWidgets.QDialogButtonBox.RejectRole)
        cancel_button.setObjectName("mapSavePreviewCancelButton")
        cancel_button.setDefault(True)
        cancel_button.setAutoDefault(True)
        save_button.setDefault(False)
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons, 0)
        dialog.setProperty("mapSavePreviewDialog", True)
        return dialog.exec_() == QtWidgets.QDialog.Accepted

    def save_current_map(self, _checked: bool = False) -> bool:
        try:
            prepared = self._prepare_map_save()
        except ValueError as e:
            self._set_status(f"保存预检失败：{e}")
            if self._current_key:
                self._set_map_dirty(True)
            QtWidgets.QMessageBox.warning(self, "提示", str(e))
            return False
        except Exception as e:
            self._set_status(f"保存预检失败：{e}")
            if self._current_key:
                self._set_map_dirty(True)
            QtWidgets.QMessageBox.critical(self, "错误", f"保存预检失败：{e}")
            return False
        if not self._confirm_map_save_preview(str(prepared.get("preview") or "")):
            return False
        try:
            path = str(prepared["path"])
            _map_settings_failure_hook("encode")
            new_raw = _map_settings_encode_strict(
                list(prepared["lines"]),
                str(prepared["encoding"]),
                str(prepared["ending"]),
                bool(prepared["trailing_nl"]),
            )
            backup_path = _map_settings_atomic_commit(
                path,
                bytes(prepared["expected_raw"]),
                new_raw,
                tuple(prepared["expected_identity"]),
            )
            backup_name = os.path.basename(backup_path)
            # The committed bytes are authoritative; suppress the dirty guard while reselecting.
            self._set_map_dirty(False)
            self.reload_map_info(
                preferred_map_id=str(prepared["new_id"]),
                preferred_map_name=str(prepared["new_name"]),
            )
            self._set_map_dirty(False, saved=True)
            self._set_status(f"保存成功，已创建备份：{backup_name}")
            QtWidgets.QMessageBox.information(self, "完成", f"地图已保存，备份文件：{backup_name}")
            return True
        except Exception as e:
            self._set_map_dirty(True)
            self._set_status(f"保存失败：{e}")
            QtWidgets.QMessageBox.critical(self, "错误", f"保存失败：{e}")
            return False


