    def _sync_root_from_basic(self) -> None:
        root = ""
        try:
            if callable(self._get_root_dir):
                root = str(self._get_root_dir() or "").strip()
        except Exception:
            root = ""
        if not root:
            try:
                sess = self._get_session() or {}
                root = str(sess.get("root_dir") or "").strip()
            except Exception:
                root = ""
        if root and self.version_edit.text().strip() != root:
            self.version_edit.setText(root)
            self._schedule_auto_fill()

    def _browse_version(self) -> None:
        d = _qt_get_existing_dir(self, "选择版本根目录", self.version_edit.text().strip() or os.getcwd())
        if d:
            self.version_edit.setText(d)
            self._schedule_auto_fill()
            self._auto_fill_from_version()

    def _on_shared_store_root_changed(self, _root: str = "") -> None:
        self._schedule_auto_fill()
        self._auto_fill_from_version()

    def _browse_common_dir(self) -> None:
        d = _qt_get_existing_dir(self, "选择通区目录路径", self.common_dir_edit.text().strip() or os.getcwd())
        if d:
            self.common_dir_edit.setText(d)

    def _sync_common_dir_folder_name(self, text: str = "") -> None:
        folder_name = str(text or "").strip().strip("/\\")
        if not folder_name:
            return
        cur = self.common_dir_edit.text().strip()
        if cur:
            parent = os.path.dirname(cur.rstrip("/\\"))
            new_path = os.path.join(parent or os.path.abspath(os.sep), folder_name)
        else:
            new_path = os.path.join("D:\\", folder_name)
        if self.common_dir_edit.text().strip() != new_path:
            self.common_dir_edit.setText(new_path)

    def _schedule_auto_fill(self) -> None:
        if self._auto_fill_timer.isActive():
            self._auto_fill_timer.stop()
        self._auto_fill_timer.start()

    def _resolve_version_root_for_read(self, raw_path: str) -> str:
        p0 = str(raw_path or "").strip().strip('"').strip("'")
        if not p0:
            return ""
        try:
            p0 = os.path.abspath(p0)
        except Exception:
            pass
        candidates: list[str] = []
        try:
            candidates.append(p0)
            if os.path.basename(p0).lower() == "mir200":
                candidates.append(os.path.dirname(p0))
            if os.path.basename(p0).lower() == "envir":
                candidates.append(os.path.dirname(os.path.dirname(p0)))
        except Exception:
            pass
        try:
            cur = p0
            for _ in range(4):
                parent = os.path.dirname(cur)
                if not parent or parent == cur:
                    break
                candidates.append(parent)
                cur = parent
        except Exception:
            pass

        for c in candidates:
            try:
                if os.path.exists(os.path.join(c, "Config.ini")) and os.path.isdir(os.path.join(c, "Mir200")):
                    return c
            except Exception:
                continue
        return p0

    @staticmethod
    def _read_text_best_effort(path: str) -> str:
        try:
            with open(path, "rb") as f:
                raw = f.read()
        except Exception:
            return ""
        for enc in ("utf-8", "gbk", "gb18030", "utf-16"):
            try:
                return raw.decode(enc)
            except Exception:
                continue
        try:
            return raw.decode("gb18030", errors="ignore")
        except Exception:
            return ""

    @staticmethod
    def _extract_gamename_from_config_ini_text(text: str) -> str:
        for ln in (text or "").replace("\r\n", "\n").replace("\r", "\n").split("\n"):
            try:
                m = re.match(r"^\s*GameName\s*=\s*(.+)\s*$", ln)
            except Exception:
                m = None
            if m:
                return (m.group(1) or "").strip()
        return ""

    def _auto_fill_from_version(self) -> None:
        root = self._resolve_version_root_for_read(self.version_edit.text().strip())
        if not root:
            return
        try:
            root_norm = os.path.normcase(os.path.abspath(root))
        except Exception:
            root_norm = root
        lock_root = self._resolve_version_root_for_read(self._resource_id_lock_root) if self._resource_id_lock_root else ""
        try:
            lock_norm = os.path.normcase(os.path.abspath(lock_root)) if lock_root else ""
        except Exception:
            lock_norm = lock_root
        if self._resource_id_locked and lock_norm and lock_norm != root_norm:
            self._resource_id_locked = False
            self._resource_id_lock_root = ""
        ini = os.path.join(root, "Config.ini")
        if os.path.exists(ini):
            txt = self._read_text_best_effort(ini)
            name = self._extract_gamename_from_config_ini_text(txt)
            if name:
                self.zone_name_edit.setText(name)
        ef = os.path.join(root, "Mir200", "Envir", "EffectImageList.txt")
        if os.path.exists(ef):
            txt = self._read_text_best_effort(ef)
            try:
                lines = [ln.strip() for ln in (txt or "").splitlines() if ln.strip()]
            except Exception:
                lines = []
            try:
                idx = next(
                    (
                        i + 1
                        for i, ln in enumerate(lines)
                        if ln.strip().lower().replace(" ", "") in {"咕咕鸡素材.pak", "咕咕鸡素材pak"}
                    ),
                    0,
                )
            except Exception:
                idx = 0
            if idx <= 0:
                idx = (len(lines) + 1) if lines else 1
            if idx > 0:
                self.resource_id_edit.setText(str(max(0, idx - 1)))
            else:
                try:
                    count = len(lines)
                except Exception:
                    count = 0
                if count > 0:
                    self.resource_id_edit.setText(str(max(0, count - 1)))

    def _cfg_path(self) -> str:
        clean_name = "存销系统配置.json"
        try:
            if getattr(sys, "frozen", False):
                exe_dir = os.path.dirname(getattr(sys, "executable", "") or os.path.abspath("."))
                clean_path = os.path.join(exe_dir, clean_name)
                return clean_path
        except Exception:
            pass
        try:
            clean_path = _abs_path_here(clean_name)
            return clean_path
        except Exception:
            clean_path = os.path.join(os.getcwd(), clean_name)
            return clean_path

    @staticmethod
    def _int_or(text: str, default: int) -> int:
        try:
            return int(str(text).strip())
        except Exception:
            return default

    def _cfg_dict(self) -> dict:
        version_path = self.version_edit.text().strip()
        feature_folder = self.folder_feature_edit.text().strip() or "游戏功能"
        category_folder = self.folder_category_edit.text().strip() or "咕咕鸡物品分类"
        common_folder = self.folder_common_edit.text().strip() or "通区文件"
        script_name = self.script_name_edit.text().strip() or "咕咕鸡过滤"
        script_method = self.script_method_edit.text().strip() or script_name
        qr_method = self.qr_method_edit.text().strip() or "掉落前检测"
        filter_tip = self.filter_tip_edit.text().strip() or "咕咕鸡过滤"
        store_tip = self.store_tip_edit.text().strip() or "咕咕鸡存储"
        teleport_condition = self.teleport_condition_edit.text().strip() or "LARGE U599 499"
        common_dir = self.common_dir_edit.text().strip() or r"D:\通区文件"
        zone_name = self.zone_name_edit.text().strip() or ""
        instance_path = str(self._instance_path or "").strip()
        rid_text = self.resource_id_edit.text().strip()
        rid_display = self._int_or(rid_text, 0)
        rid_cfg = 0
        if rid_text != "":
            if rid_display >= 0:
                rid_cfg = rid_display
        return {
            "版本路径": version_path,
            "实例路径": instance_path,
            "存销功能文件夹名": feature_folder,
            "分类文件夹名": category_folder,
            "通区文件夹名": common_folder,
            "存销脚本文件名": script_name,
            "存销脚本方法名": script_method,
            "QR触发序号": self._int_or(self.qr_index_edit.text(), 200),
            "QR过滤方法名": qr_method,
            "过滤提示文本": filter_tip,
            "存储提示文本": store_tip,
            "传送条件": teleport_condition,
            "资源编号": rid_cfg,
            "资源编号基准": 0,
            "资源编号锁定": bool(self._resource_id_locked),
            "资源编号锁定版本路径": str(self._resource_id_lock_root or "").strip(),
            "QManage路径": str(self._qmanage_path or "").strip() or r"Mir200\Envir\MapQuest_def\QManage.txt",
            "QFunction路径": str(self._qfunction_path or "").strip() or r"Mir200\Envir\Market_Def\QFunction-0.txt",
            "功能目录路径": str(self._feature_dir_path or "").strip() or r"Mir200\Envir\QuestDiary",
            "分类目录路径": str(self._category_dir_path or "").strip() or r"Mir200\Envir\QuestDiary",
            "通区目录路径": common_dir,
            "区服文件夹名": zone_name,
            "版本": "2025.1124.9",
        }

    def _store_worker_cfg(self) -> dict:
        return self._cfg_dict()

    @staticmethod
    def _cfg_needs_migration(cfg: dict) -> bool:
        if not isinstance(cfg, dict):
            return False
        if "资源编号" in cfg and "资源编号基准" not in cfg:
            return True
        # 以下键名为历史错误编码遗留值，仅用于识别并迁移旧配置
        legacy_markers = (
            LEGACY_STORE_VERSION_PATH_KEY,
            LEGACY_STORE_INSTANCE_PATH_KEY,
            LEGACY_STORE_FEATURE_DIR_PATH_KEY,

            LEGACY_STORE_CATEGORY_DIR_PATH_KEY,
            LEGACY_STORE_QMANAGE_PATH_KEY,
            LEGACY_STORE_QFUNCTION_PATH_KEY,
            LEGACY_STORE_RESOURCE_ID_KEY,
            LEGACY_STORE_RESOURCE_ID_LOCKED_KEY,
            LEGACY_STORE_RESOURCE_ID_LOCK_ROOT_KEY,
        )
        return any(k in cfg for k in legacy_markers)

    def _apply_cfg(self, cfg: dict) -> None:
        def _pick(*keys, default=""):
            for key in keys:
                try:
                    value = cfg.get(key)
                except Exception:
                    value = None
                if value is None:
                    continue
                if isinstance(value, str):
                    if value.strip():
                        return value.strip()
                    continue
                if isinstance(value, (dict, list, tuple, set)) and not value:
                    continue
                return value
            return default

        self.version_edit.setText(str(_pick("版本路径", "工程根目录", default="")))
        self.folder_feature_edit.setText(str(_pick("存销功能文件夹名", default="游戏功能")))
        self.folder_category_edit.setText(str(_pick("分类文件夹名", default="咕咕鸡物品分类")))
        self.folder_common_edit.setText(str(_pick("通区文件夹名", default="通区文件")))
        script_name = str(_pick("存销脚本文件名", default="咕咕鸡过滤"))
        self.script_name_edit.setText(script_name)
        self.script_method_edit.setText(str(_pick("存销脚本方法名", default=script_name)))
        rid_cfg_raw = _pick("资源编号", default=0)
        try:
            rid_cfg = int(str(rid_cfg_raw).strip() or "0")
        except Exception:
            rid_cfg = 0
        try:
            rid_base = int(str(_pick("资源编号基准", default=1)).strip() or "1")
        except Exception:
            rid_base = 1
        if rid_base == 0:
            rid_display = max(0, rid_cfg)
            self.resource_id_edit.setText(str(rid_display))
        else:
            # Historical configs stored the UI's zero-based value as value + 1.
            rid_display = max(0, rid_cfg - 1) if rid_cfg > 0 else 0
            self.resource_id_edit.setText("" if rid_cfg <= 0 else str(rid_display))
        self._resource_id_locked = bool(_pick("资源编号锁定", LEGACY_STORE_RESOURCE_ID_LOCKED_KEY, default=False))
        self._resource_id_lock_root = str(_pick("资源编号锁定版本路径", LEGACY_STORE_RESOURCE_ID_LOCK_ROOT_KEY, default=""))
        self.qr_index_edit.setText(str(_pick("QR触发序号", default="200")))
        self.qr_method_edit.setText(str(_pick("QR过滤方法名", default="掉落前检测")))
        self.filter_tip_edit.setText(str(_pick("过滤提示文本", default="咕咕鸡过滤")))
        self.store_tip_edit.setText(str(_pick("存储提示文本", default="咕咕鸡存储")))
        self.teleport_condition_edit.setText(str(_pick("传送条件", default="LARGE U599 499")))
        self._instance_path = str(_pick("实例路径", LEGACY_STORE_INSTANCE_PATH_KEY, default=""))
        self._qmanage_path = str(_pick("QManage路径", LEGACY_STORE_QMANAGE_PATH_KEY, default=r"Mir200\Envir\MapQuest_def\QManage.txt"))
        self._qfunction_path = str(_pick("QFunction路径", LEGACY_STORE_QFUNCTION_PATH_KEY, default=r"Mir200\Envir\Market_Def\QFunction-0.txt"))
        self._feature_dir_path = str(_pick("功能目录路径", LEGACY_STORE_FEATURE_DIR_PATH_KEY, default=r"Mir200\Envir\QuestDiary"))
        self._category_dir_path = str(_pick("分类目录路径", LEGACY_STORE_CATEGORY_DIR_PATH_KEY, default=r"Mir200\Envir\QuestDiary"))
        self.common_dir_edit.setText(str(_pick("通区目录路径", default=r"D:\通区文件")))
        self.zone_name_edit.setText(str(_pick("区服文件夹名", default="")))

    def _load_config_quiet(self) -> None:
        path = self._cfg_path()
        try:
            if not os.path.exists(path):
                return
            with open(path, "r", encoding="utf-8") as f:
                cfg = json.load(f)
            if isinstance(cfg, dict):
                self._apply_cfg(cfg)
                if self._cfg_needs_migration(cfg):
                    self._save_config_quiet()
        except Exception:
            return

    def _load_config(self) -> None:
        path = self._cfg_path()
        if not os.path.exists(path):
            QtWidgets.QMessageBox.warning(self, "提示", f"未找到配置文件：{path}")
            return
        try:
            with open(path, "r", encoding="utf-8") as f:
                cfg = json.load(f)
            if not isinstance(cfg, dict):
                raise ValueError("配置格式不正确")
            self._apply_cfg(cfg)
            if self._cfg_needs_migration(cfg):
                self._save_config_quiet()
            QtWidgets.QMessageBox.information(self, "成功", "配置已加载")
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", f"加载失败：{e}")

    def _save_config(self) -> None:
        path = self._cfg_path()
        cfg = self._cfg_dict()
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
        except Exception:
            pass
        try:
            with open(path, "w", encoding="utf-8", newline="") as f:
                json.dump(cfg, f, ensure_ascii=False, indent=2)
            QtWidgets.QMessageBox.information(self, "成功", f"配置已保存：{path}")
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", f"保存失败：{e}")

    def _save_config_quiet(self) -> None:
        path = self._cfg_path()
        cfg = self._cfg_dict()
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
        except Exception:
            pass
        try:
            with open(path, "w", encoding="utf-8", newline="") as f:
                json.dump(cfg, f, ensure_ascii=False, indent=2)
        except Exception:
            return

    def _start_generate(self) -> None:
        if self._thread is not None:
            return
        try:
            cfg = self._store_worker_cfg()
        except _StoreTxError as exc:
            QtWidgets.QMessageBox.warning(self, "授权不可用", str(exc))
            return
        if not str(cfg.get("版本路径") or cfg.get("\u9417\u581f\u6e70\u74ba\ue21a\u7dde") or "").strip():
            QtWidgets.QMessageBox.warning(self, "提示", "请先填写“版本根目录”")

            return
        self._save_config()
        self.generate_btn.setEnabled(False)
        try:
            self.delete_store_btn.setEnabled(False)
        except Exception:
            pass
        self.progress.setValue(0)
        self.status.setText("开始生成...")

        self._thread = QtCore.QThread()
        self._worker = _StoreGenerateWorker(cfg)
        self._worker.moveToThread(self._thread)
        self._thread.started.connect(self._worker.run)
        self._worker.progress.connect(self._on_progress)
        self._worker.finished.connect(self._on_finished)
        self._worker.finished.connect(self._thread.quit)
        self._thread.finished.connect(self._cleanup_thread)
        self._thread.start()

    def _start_delete_generated(self) -> None:
        if self._thread is not None:
            return
        try:
            cfg = self._store_worker_cfg()
        except _StoreTxError as exc:
            QtWidgets.QMessageBox.warning(self, "授权不可用", str(exc))
            return
        if not str(cfg.get("版本路径") or cfg.get("\u9417\u581f\u6e70\u74ba\ue21a\u7dde") or "").strip():
            QtWidgets.QMessageBox.warning(self, "提示", "请先填写“版本根目录”")
            return
        confirm = QtWidgets.QMessageBox.question(
            self,
            "确认删除",
            "确定执行“一键删除存销”吗？\n\n"
            "将删除/清理本工具生成的存销功能脚本、分类目录、QManage/QFunction 注入段、EffectImageList 素材行，以及 MonItems/QuestDiary 中挂接的存销掉落触发。\n"
            "不会删除通区目录中的玩家仓库数据。",
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No | QtWidgets.QMessageBox.Cancel,
            QtWidgets.QMessageBox.Cancel,
        )
        if confirm != QtWidgets.QMessageBox.Yes:
            return
        try:
            self._save_config_quiet()
        except Exception:
            pass
        self.generate_btn.setEnabled(False)
        self.delete_store_btn.setEnabled(False)
        self.progress.setValue(0)
        self.status.setText("开始删除存销...")

        self._thread = QtCore.QThread()
        self._worker = _StoreDeleteWorker(cfg)
        self._worker.moveToThread(self._thread)
        self._thread.started.connect(self._worker.run)
        self._worker.progress.connect(self._on_progress)
        self._worker.finished.connect(self._on_delete_finished)
        self._worker.finished.connect(self._thread.quit)
        self._thread.finished.connect(self._cleanup_thread)
        self._thread.start()

    def _on_progress(self, v: int, text: str) -> None:
        self.progress.setValue(int(v))
        self.status.setText(text or "")

    def _on_finished(self, ok: object, msg: str) -> None:
        self.generate_btn.setEnabled(True)
        try:
            self.delete_store_btn.setEnabled(True)
        except Exception:
            pass
        if ok:
            try:
                root = self._resolve_version_root_for_read(self.version_edit.text().strip())
                if root:
                    self._resource_id_locked = True
                    self._resource_id_lock_root = root
                    self._save_config_quiet()
            except Exception:
                pass
            QtWidgets.QMessageBox.information(self, "完成", msg or "存销生成完成")
        else:
            QtWidgets.QMessageBox.critical(self, "生成失败", msg or "未知错误")

    def _on_delete_finished(self, ok: object, msg: str) -> None:
        self.generate_btn.setEnabled(True)
        try:
            self.delete_store_btn.setEnabled(True)
        except Exception:
            pass
        if ok:
            self.status.setText("删除完成")
            QtWidgets.QMessageBox.information(self, "完成", msg or "存销删除完成")
        else:
            self.status.setText("删除失败")
            QtWidgets.QMessageBox.critical(self, "删除失败", msg or "未知错误")

    def _cleanup_thread(self) -> None:
        try:
            if self._thread is not None:
                self._thread.deleteLater()
        except Exception:
            pass
        self._thread = None
        self._worker = None

