    @staticmethod
    def _get_data_dir() -> str:
        base = os.environ.get("LOCALAPPDATA") or os.environ.get("APPDATA") or os.path.expanduser("~")
        return os.path.join(base, "XiamiToolbox")

    @classmethod
    def _get_store_path(cls) -> str:
        try:
            return os.path.join(cls._get_data_dir(), "recycle_settings.json")
        except Exception:
            return os.path.join(os.path.abspath("."), "recycle_settings.json")

    @staticmethod
    def _read_json(path: str) -> dict | None:
        try:
            if not os.path.exists(path):
                return None
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            return data if isinstance(data, dict) else None
        except Exception:
            return None

    @staticmethod
    def _write_json(path: str, data: dict) -> bool:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
        except Exception:
            pass
        try:
            with open(path, "w", encoding="utf-8", newline="") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
            return True
        except Exception:
            return False

    def _ensure_item_names_loaded(self) -> None:
        if _load_all_item_names is None:
            return
        root_dir = ""
        try:
            if callable(self._get_root_dir):
                root_dir = str(self._get_root_dir() or "").strip()
        except Exception:
            root_dir = ""
        if root_dir == self._item_names_root and self._item_names_list:
            return
        self._item_names_root = root_dir
        names: list[str] = []
        if root_dir:
            try:
                raw = _load_all_item_names(root_dir)  # type: ignore[misc]
                if isinstance(raw, list):
                    names = [str(x).strip() for x in raw if str(x or "").strip()]
            except Exception:
                names = []
        try:
            self._item_names_model.setStringList(names)
        except Exception:
            pass
        self._item_names_list = list(names or [])
        self._item_names_lower = [str(x).lower() for x in (self._item_names_list or [])]

    def _get_recycle_currency_type_options(self) -> list[tuple[str, str]]:
        mapping = [
            ("GameGold", "金币", "GameGold +"),
            ("GamePoint", "元宝", "GamePoint +"),
            ("GameDiamond", "钻石", "GameDiamond +"),
            ("GameGird", "灵符", "GameGird +"),
            ("GameGlory", "荣誉", "GameGlory +"),
            ("CreditPoint", "积分", "CreditPoint +"),
            ("GoldCount", "金币", "Give 金币"),
        ]
        setup_names: dict[str, str] = {}
        root_dir = ""
        try:
            if callable(self._get_root_dir):
                root_dir = str(self._get_root_dir() or "").strip()
        except Exception:
            root_dir = ""
        if root_dir:
            setup_path = os.path.join(root_dir, "Mir200", "!setup.txt")
            setup_lines: list[str] = []
            for enc in ("utf-8-sig", "utf-8", "gbk", "gb18030"):
                try:
                    with open(setup_path, "r", encoding=enc) as f:
                        setup_lines = f.readlines()
                    break
                except Exception:
                    continue
            for line in setup_lines:
                sline = str(line or "").strip()
                if not sline or sline.startswith(";") or sline.startswith("#") or "=" not in sline:
                    continue
                key_part, _, val_part = sline.partition("=")
                key = key_part.strip()
                val = val_part.strip()
                if key and val:
                    setup_names[key.lower()] = val
        options: list[tuple[str, str]] = []
        for code, default_name, command in mapping:
            display_name = str(setup_names.get(code.lower()) or "").strip() or default_name
            options.append((display_name, command))
        return options

