        self.recycle_workspace_splitter.setChildrenCollapsible(False)
        self.recycle_workspace_splitter.setProperty("toolboxResponsiveSplitterPolicy", "recycle-wide-table")
        self.recycle_workspace_splitter.addWidget(self._build_recycle_table_panel())
