        self.recycle_workspace_splitter.setSizes([UiMetrics.RECYCLE_WORKSPACE_TABLE_W, UiMetrics.RECYCLE_WORKSPACE_SCRIPT_W])
        outer.addWidget(self.recycle_workspace_splitter, 1)

