        try:
            total_rows = int(self.table.rowCount())
            rows = self._rows_from_table()
            filled_rows = len(rows)
        except Exception:
            pass
        if isinstance(badge, QtWidgets.QLabel):
            if total_rows and filled_rows != total_rows:
                badge.setText(f"{filled_rows}/{total_rows} 条规则")
            else:
                badge.setText(f"{filled_rows} 条规则")

        categories = {str(row.get("category") or "").strip() for row in rows if str(row.get("category") or "").strip()}
        currencies = {str(row.get("currency_type") or "").strip() for row in rows if str(row.get("currency_type") or "").strip()}
