    def _configure_recycle_table(self, table: QtWidgets.QTableWidget) -> None:
        table.setObjectName("recycleRulesTable")
        table.setColumnCount(len(self._cols))
        table.setHorizontalHeaderLabels(["类别", "物品名称", "货币类型", "价格", "分解物品", "物品数量", "经验", "颜色"])
        header = table.horizontalHeader()
        header.setFixedHeight(UiMetrics.RECYCLE_TABLE_HEADER_H)
        header.setStretchLastSection(False)
        for col, width in enumerate(UiMetrics.RECYCLE_TABLE_COL_WIDTHS):
            if col >= len(self._cols):
                break
            header.setSectionResizeMode(col, QtWidgets.QHeaderView.Fixed)
            table.setColumnWidth(col, int(width))
        try:
            items_col = self._cols.index("items")
            header.setSectionResizeMode(items_col, QtWidgets.QHeaderView.Stretch)
            table.setColumnWidth(items_col, int(UiMetrics.RECYCLE_TABLE_COL_WIDTHS[items_col]))
        except Exception:
            pass
        table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        table.verticalHeader().setVisible(False)
        table.verticalHeader().setDefaultSectionSize(UiMetrics.RECYCLE_TABLE_ROW_H)
        table.setAlternatingRowColors(False)
        table.setShowGrid(False)
        table.setEditTriggers(
            QtWidgets.QAbstractItemView.DoubleClicked
            | QtWidgets.QAbstractItemView.SelectedClicked
            | QtWidgets.QAbstractItemView.EditKeyPressed
        )
        table.itemChanged.connect(self._on_recycle_table_item_changed)

