    def _refresh_recycle_script_summary(self) -> None:
        line_label = getattr(self, "recycle_script_lines_badge", None)
        status_label = getattr(self, "recycle_script_status_badge", None)
        if not isinstance(line_label, QtWidgets.QLabel):
            return
        text = ""
        try:
            text = self.script_edit.toPlainText()
        except Exception:
            text = ""
        lines = len([line for line in str(text or "").splitlines() if str(line or "").strip()])
        line_label.setText(f"脚本 {lines} 行")
        line_label.setToolTip("当前预览脚本行数")
        if isinstance(status_label, QtWidgets.QLabel):
            state = str(getattr(self, "_recycle_preview_state", "empty") or "empty")
            if state == "ready" and lines > 0:
                status_label.setText("可复制")
                status_label.setProperty("badgeRole", "ready")
                status_label.setToolTip("脚本已生成，可以复制到剪贴板")
            elif state == "stale" and lines > 0:
                status_label.setText("需重新生成")
                status_label.setProperty("badgeRole", "warn")
                status_label.setToolTip("配置或回收条目已变化，复制前需要重新生成脚本")
            else:
                status_label.setText("待生成")
                status_label.setProperty("badgeRole", "warn")
                status_label.setToolTip("点击生成脚本后可复制")
            status_label.setVisible(True)
            status_label.style().unpolish(status_label)
            status_label.style().polish(status_label)

    def _mark_recycle_preview_stale(self, *_args) -> None:
        has_preview = False
        try:
            has_preview = bool(self.script_edit.toPlainText().strip())
        except Exception:
            has_preview = False
        if str(getattr(self, "_recycle_preview_state", "empty") or "empty") == "ready" or has_preview:
            self._recycle_preview_state = "stale"
            self._refresh_recycle_script_summary()

