class _DropOptimizeWorker(QtCore.QObject):
    log = QtCore.Signal(str)
    progress = QtCore.Signal(int, str)
    finished = QtCore.Signal(object, str)

    def __init__(self, root_path: str) -> None:
        super().__init__()
        self._input_path = root_path
        self._backup_folder = "二级爆率优化备份"

    @staticmethod
    def _normalize_server_root(path: str) -> str:
        return _CallRestoreWorker._normalize_server_root(path)

    @staticmethod
    def _detect_encoding(data: bytes) -> str:
        if data.startswith(b"\xef\xbb\xbf"):
            return "utf-8-sig"
        try:
            txt = data.decode("utf-8")
            if all(ord(c) < 128 for c in txt):
                return "gb18030"
            return "utf-8"
        except Exception:
            pass
        try:
            data.decode("gb18030")
            return "gb18030"
        except Exception:
            pass
        return "gb18030"

    @classmethod
    def _detect_file_encoding(cls, file_path: str) -> str:
        try:
            with open(file_path, "rb") as f:
                data = f.read(4096)
            return cls._detect_encoding(data)
        except Exception:
            return "gb18030"

    def _optimize_content(self, content: str) -> str:
        lines = content.splitlines()
        result: list[str] = []
        in_target_child = False
        in_target_bracket = False
        current_child_x: int | None = None
        current_items: list[tuple[int, str]] = []
        current_raw: list[str] = []
        temp_unoptimized: list[str] = []
        in_unoptimized_child = False

        target_child_pattern = re.compile(r"^\s*#CHILD\s+1/(\d+)\s+RANDOM\s*$", re.IGNORECASE)
        any_child_pattern = re.compile(r"^\s*#CHILD\s+", re.IGNORECASE)
        target_item_pattern = re.compile(r"^\s*1/(\d+)\s+(.*?)\s*$")
        block_end_pattern = re.compile(r"^\s*\)\s*$")

        for line in lines:
            stripped_line = line.strip()
            original_line = line

            if in_unoptimized_child:
                temp_unoptimized.append(original_line)
                if block_end_pattern.match(original_line):
                    result.extend(temp_unoptimized)
                    temp_unoptimized = []
                    in_unoptimized_child = False
                continue

            if in_target_child:
                if not in_target_bracket:
                    current_raw.append(original_line)
                    if "(" in stripped_line and ")" not in stripped_line:
                        in_target_bracket = True
                    continue

                if in_target_bracket:
                    if block_end_pattern.match(original_line):
                        if any(y <= 0 for y, _equip in current_items):
                            # Preserve the original block untouched.
                            result.extend(current_raw)
                            result.append(original_line)
                            in_target_child = False
                            in_target_bracket = False
                            current_child_x = None
                            current_items = []
                            current_raw = []
                            continue
                        if current_items and current_child_x:
                            item_groups: dict[int, list[str]] = {}
                            for y, equip in current_items:
                                item_groups.setdefault(y, []).append(equip)
                            for y, equips in item_groups.items():
                                new_denominator = current_child_x * y
                                result.append(f"#CHILD 1/{new_denominator} RANDOM")
                                result.append("(")
                                for equip in equips:
                                    result.append(f"1/1 {equip}")
                                result.append(")")
                        else:
                            if current_child_x:
                                result.append(f"#CHILD 1/{current_child_x} RANDOM")
                            result.append("(")
                            result.append(original_line)

                        in_target_child = False
                        in_target_bracket = False
                        current_child_x = None
                        current_items = []
                        continue

                    if not stripped_line:
                        continue

                    item_match = target_item_pattern.match(original_line)
                    if item_match:
                        y = int(item_match.group(1))
                        equip_name = item_match.group(2)
                        current_items.append((y, equip_name))
                        current_raw.append(original_line)
                    else:
                        y_match = re.search(r"1/(\d+)", original_line)
                        if y_match:
                            y = int(y_match.group(1))
                            equip_name = re.sub(r"1/\d+\s*", "", original_line).strip()
                            current_items.append((y, equip_name))
                            current_raw.append(original_line)
                        else:
                            if current_child_x:
                                result.append(f"#CHILD 1/{current_child_x} RANDOM")
                            result.append(original_line)
                            in_target_child = False
                            in_target_bracket = False
                            current_child_x = None
                            current_items = []
                    continue

            if not in_target_child and not in_unoptimized_child:
                target_match = target_child_pattern.match(original_line)
                if target_match:
                    denominator = int(target_match.group(1))
                    if denominator <= 0:
                        # 1/0 cannot be merged; hand the block to the
                        # verbatim passthrough instead of rewriting it.
                        in_unoptimized_child = True
                        temp_unoptimized.append(original_line)
                        continue
                    current_child_x = denominator
                    current_raw = [original_line]
                    in_target_child = True
                    continue

                if any_child_pattern.match(original_line):
                    in_unoptimized_child = True
                    temp_unoptimized.append(original_line)
                    continue

                result.append(original_line)

        if temp_unoptimized:
            result.extend(temp_unoptimized)

        if in_target_child or in_target_bracket:
            if current_child_x:
                result.append(f"#CHILD 1/{current_child_x} RANDOM")
            if in_target_bracket:
                result.append(")")

        return "\r\n".join(result)

    def _optimize_content_in_section(self, content: str, target_section: str | None) -> str:
        if target_section is None:
            return self._optimize_content(content)
        normalized = (content or "").replace("\r\n", "\n").replace("\r", "\n")
        lines = normalized.split("\n")
        section_pattern = re.compile(r"^\s*\[@(.+?)\]\s*$", re.IGNORECASE)
        out: list[str] = []
        buf: list[str] = []
        cur_section: str | None = None
        in_target = False

        def flush() -> None:
            nonlocal buf, out
            if not buf:
                return
            if in_target:
                optimized = self._optimize_content("\n".join(buf))
                if optimized:
                    out.extend(optimized.replace("\r\n", "\n").split("\n"))
            else:
                out.extend(buf)
            buf = []

        for ln in lines:
            m = section_pattern.match(ln)
            if m:
                flush()
                cur_section = (m.group(1) or "").strip()
                in_target = cur_section == target_section
                out.append(ln)
                continue
            buf.append(ln)
        flush()
        return "\r\n".join(out)

    def run(self) -> None:
        _drop_optimize_run(self)


