            self._item_names_lower = [s.lower() for s in self._item_names_list]
            self._map_names_root_key = os.path.normpath(smoke_root).lower()
            self._map_names_list = ["赤月峡谷-精英刷新区", "沙巴克藏宝阁-超长地图名称测试"]
            self._map_names_lower = [s.lower() for s in self._map_names_list]
            self._monster_names_root_key = os.path.normpath(smoke_root).lower()
            self._monster_names_list = ["赤月恶魔", "双头金刚", "暗之牛魔王"]
            self._monster_names_lower = [s.lower() for s in self._monster_names_list]
