    def _build_drop_workspace(self) -> QtWidgets.QSplitter:
        self.drop_workspace_splitter = QtWidgets.QSplitter(QtCore.Qt.Vertical)
        self.drop_workspace_splitter.setObjectName("dropWorkspaceSplitter")
        self.drop_workspace_splitter.addWidget(self._build_drop_task_grid_panel())
        self.drop_workspace_splitter.addWidget(self._build_drop_detail_panel())
        self.drop_workspace_splitter.setStretchFactor(0, 5)
        self.drop_workspace_splitter.setStretchFactor(1, 1)
        self.drop_workspace_splitter.setCollapsible(0, False)
        self.drop_workspace_splitter.setCollapsible(1, False)
        self.drop_workspace_splitter.setSizes([
            UiMetrics.DROP_RATE_WORKSPACE_TASK_H,
            UiMetrics.DROP_RATE_WORKSPACE_DETAIL_H,
        ])
        return self.drop_workspace_splitter

