    def _build_drop_task_cards(self) -> None:
        self._tab_call = self._build_drop_task_card("#CALL还原", "dropCallTaskCard")
        self._tab_opt = self._build_drop_task_card("二级爆率优化", "dropOptTaskCard")
        self._tab_overall_opt = self._build_drop_task_card("整体爆率优化", "dropOverallOptTaskCard")
        self._tab_group = self._build_drop_task_card("普通爆率分组", "dropGroupTaskCard")
        self._tab_add = self._build_drop_task_card("新增爆率", "dropAddTaskCard")
        self._tab_delete = self._build_drop_task_card("指定删除", "dropDeleteTaskCard")

    def _build_drop_task_card(self, title: str, object_name: str) -> QtWidgets.QGroupBox:
        card = QtWidgets.QGroupBox(title)
        card.setObjectName(object_name)
        if object_name == "dropCallTaskCard":
            card.setMinimumHeight(UiMetrics.DROP_RATE_SHORT_TASK_CARD_MIN_H)
        elif object_name == "dropOptTaskCard":
            card.setMinimumHeight(UiMetrics.DROP_RATE_SHORT_TASK_CARD_MIN_H)
        elif object_name == "dropDeleteTaskCard":
            card.setMinimumHeight(UiMetrics.DROP_RATE_DELETE_TASK_CARD_MIN_H)
        return card

    def _compact_drop_task_button(self, button: QtWidgets.QPushButton, max_width: int = 76) -> QtWidgets.QPushButton:
        button.setProperty("dropCompactButton", True)
        role = str(button.property("buttonRole") or "")
        if role not in ("primary", "danger"):
            _apply_ui_button_role(button, "compact")
        target_height = UiMetrics.PRIMARY_BUTTON_H if role == "primary" else UiMetrics.TABLE_ACTION_BUTTON_H
        button.setFixedSize(max_width, target_height)
        button.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
        content_width = max(1, max_width - 14)
        content_height = max(1, target_height - 2)
        button.setStyleSheet(
            "QPushButton { "
            f"min-width: {content_width}px; max-width: {content_width}px; "
            f"min-height: {content_height}px; max-height: {content_height}px; "
            "padding: 0 6px; border-radius: 4px; "
            "}"
        )
        return button

    def _add_drop_task_cards(self, body_l: QtWidgets.QGridLayout) -> None:
        self.drop_task_tabs = QtWidgets.QTabWidget()
        self.drop_task_tabs.setObjectName("dropTaskTabs")
        self.drop_task_tabs.setDocumentMode(True)
        self.drop_task_tabs.setUsesScrollButtons(False)
        self.drop_task_tabs.setStyleSheet(
            "QTabWidget::pane { background: #FFFFFF; border: 1px solid #D9E0E8; "
            "border-radius: 6px; top: -1px; }"
            "QTabBar::tab { min-width: 86px; min-height: 30px; padding: 0 12px; "
            "margin-right: 4px; background: #FFFFFF; border: 1px solid #D9E0E8; "
            "border-radius: 4px; color: #657184; font-weight: 600; }"
            "QTabBar::tab:hover:!selected { background: #F5F7FA; border-color: #C9D2DC; "
            "color: #172033; }"
            "QTabBar::tab:selected { background: #FFF1E6; border-color: #E87924; "
            "color: #A64200; font-weight: 700; }"
        )
        self.drop_task_tabs.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Expanding)
        for card, title in (
            (self._tab_overall_opt, "整体优化"),
            (self._tab_add, "新增爆率"),
            (self._tab_group, "普通分组"),
            (self._tab_call, "#CALL还原"),
            (self._tab_opt, "二级优化"),
            (self._tab_delete, "指定删除"),
        ):
            card.setTitle("")
            self.drop_task_tabs.addTab(card, title)
        body_l.addWidget(self.drop_task_tabs, 1, 0, 1, 2)

