    def _init_item_name_autocomplete(self) -> None:
        if self._multi_popup is None:
            self._multi_popup = _MultiSelectNamePopup(self)
            self._multi_popup.hide()

        self._multi_targets.clear()
        if hasattr(self, "overall_maps_edit") and isinstance(self.overall_maps_edit, QtWidgets.QLineEdit):
            self._multi_targets.add(self.overall_maps_edit)
            self.overall_maps_edit.installEventFilter(self)
        if hasattr(self, "overall_monsters_edit") and isinstance(self.overall_monsters_edit, QtWidgets.QLineEdit):
            self._multi_targets.add(self.overall_monsters_edit)
            self.overall_monsters_edit.installEventFilter(self)
        if hasattr(self, "overall_items_edit") and isinstance(self.overall_items_edit, QtWidgets.QLineEdit):
            self._multi_targets.add(self.overall_items_edit)
            self.overall_items_edit.installEventFilter(self)

    @staticmethod
    def _find_token_bounds(text: str, cursor: int) -> tuple[int, int]:
        seps = {",", "，", "、", ";", "；", "\n", "\r"}
        try:
            cursor = int(cursor)
        except Exception:
            cursor = len(text)
        if cursor < 0:
            cursor = 0
        if cursor > len(text):
            cursor = len(text)
        start = cursor
        while start > 0 and text[start - 1] not in seps:
            start -= 1
        end = cursor
        while end < len(text) and text[end] not in seps:
            end += 1
        return start, end

    def eventFilter(self, obj: QtCore.QObject, event: QtCore.QEvent) -> bool:
        try:
            if obj in self._multi_targets:
                et = event.type()
                if et == QtCore.QEvent.InputMethod:
                    self._update_multi_ime_state(obj, event)
                    if self._is_multi_ime_composing(obj):
                        self._multi_last_query_by_obj.pop(id(obj), None)
                        self._multi_last_indices_by_obj.pop(id(obj), None)
                        if self._multi_popup is not None:
                            self._multi_popup.hide()
                    else:
                        self._schedule_multi_popup_update(obj)
                    return False
                if et in (QtCore.QEvent.FocusOut,):
                    self._multi_ime_composing_ids.discard(id(obj))
                    QtCore.QTimer.singleShot(0, self._hide_multi_popup_if_needed)
                    return False
                if et == QtCore.QEvent.KeyPress:
                    if self._is_multi_ime_composing(obj):
                        return False
                    if self._handle_multi_popup_key(obj, event):
                        return True
                if et in (QtCore.QEvent.KeyRelease, QtCore.QEvent.MouseButtonRelease, QtCore.QEvent.FocusIn):
                    try:
                        if et == QtCore.QEvent.KeyRelease and isinstance(event, QtGui.QKeyEvent):
                            if event.key() in (
                                QtCore.Qt.Key_Up,
                                QtCore.Qt.Key_Down,
                                QtCore.Qt.Key_PageUp,
                                QtCore.Qt.Key_PageDown,
                                QtCore.Qt.Key_Enter,
                                QtCore.Qt.Key_Return,
                                QtCore.Qt.Key_Escape,
                                    QtCore.Qt.Key_Tab,
                                    QtCore.Qt.Key_Backtab,
                            ):
                                return False
                    except Exception:
                        pass
                    if self._is_multi_ime_composing(obj):
                        return False
                    self._schedule_multi_popup_update(obj)
                    return False
        except Exception:
            return False
        return super().eventFilter(obj, event)

    def _handle_multi_popup_key(self, obj: QtCore.QObject, event: QtCore.QEvent) -> bool:
        popup = self._multi_popup
        if popup is None:
            return False
        try:
            if not popup.isVisible():
                return False
        except Exception:
            return False
        if not isinstance(event, QtGui.QKeyEvent):
            return False
        key = event.key()
        return False

    def _update_multi_ime_state(self, obj: QtCore.QObject, event: QtCore.QEvent) -> None:
        if not isinstance(event, QtGui.QInputMethodEvent):
            return
        try:
            preedit = str(event.preeditString() or "")
        except Exception:
            preedit = ""
        if preedit:
            self._multi_ime_composing_ids.add(id(obj))
        else:
            self._multi_ime_composing_ids.discard(id(obj))

    def _is_multi_ime_composing(self, obj: QtCore.QObject | None) -> bool:
        if obj is None:
            return False
        if id(obj) in self._multi_ime_composing_ids:
            return True
        if not isinstance(obj, QtWidgets.QWidget):
            return False
        try:
            if bool(obj.inputMethodQuery(QtCore.Qt.ImEnabled)):
                return False
        except Exception:
            pass
        return False

    def _hide_multi_popup_if_needed(self) -> None:
        popup = self._multi_popup
        if popup is None:
            return
        try:
            fw = QtWidgets.QApplication.focusWidget()
        except Exception:
            fw = None
        if fw is None:
            try:
                popup.hide()
            except Exception:
                pass
            return
        try:
            p = fw
            while p is not None:
                if p is popup:
                    return
                p = p.parentWidget()
        except Exception:
            pass
        try:
            popup.hide()
        except Exception:
            pass

    def _schedule_multi_popup_update(self, obj: QtCore.QObject) -> None:
        self._multi_update_obj = obj
        try:
            self._multi_update_timer.start()
        except Exception:
            self._update_multi_popup(obj)

    def _run_multi_update(self) -> None:
        obj = self._multi_update_obj
        if obj is None:
            return
        self._update_multi_popup(obj)

    def _filter_item_name_indices(
        self,
        query_lower: str,
        indices: list[int] | None,
        limit: int,
        names: list[str] | None = None,
        names_lower: list[str] | None = None,
    ) -> tuple[list[str], list[int]]:
        if not query_lower:
            return [], []
        out: list[str] = []
        out_idx: list[int] = []
        picked: set[int] = set()
        names = self._item_names_list if names is None else names
        names_lower = self._item_names_lower if names_lower is None else names_lower
        base_iter = indices if indices is not None else range(len(names_lower))

        try:
            for i in base_iter:
                if names_lower[i].startswith(query_lower):
                    out.append(names[i])
                    out_idx.append(i)
                    picked.add(i)
                    if len(out) >= limit:
                        break
        except Exception:
            out = []
            out_idx = []
            picked = set()
        if len(out) >= limit:
            return out, out_idx

        try:
            for i in base_iter:
                if i in picked:
                    continue
                if query_lower in names_lower[i]:
                    out.append(names[i])
                    out_idx.append(i)
                    picked.add(i)
                    if len(out) >= limit:
                        break
        except Exception:
            return out, out_idx
        return out, out_idx

    def _filter_item_names(self, query: str, limit: int = 80) -> list[str]:
        q = str(query or "").strip().lower()
        if not q:
            return []
        out: list[str] = []
        names = self._item_names_list
        names_lower = self._item_names_lower
        for i, s_lower in enumerate(names_lower):
            if q in s_lower:
                out.append(names[i])
                if len(out) >= limit:
                    break
        return out

    def _get_server_root_for_suggest(self) -> str:
        root = str(getattr(self, "root_edit", None).text() if hasattr(self, "root_edit") else "").strip()
        if not root:
            return ""
        try:
            root_norm = _CallRestoreWorker._normalize_server_root(os.path.abspath(root.strip().strip('"').strip("'")))
        except Exception:
            root_norm = os.path.abspath(root.strip().strip('"').strip("'"))
        try:
            if os.path.basename(root_norm).lower() == "mir200":
                root_norm = os.path.dirname(root_norm)
        except Exception:
            pass
        return root_norm

    def _get_map_suggest_data(self) -> tuple[list[str], list[str]]:
        root_dir = self._get_server_root_for_suggest()
        key = os.path.normpath(root_dir).lower() if root_dir else ""
        if key and key == self._map_names_root_key and self._map_names_list:
            return self._map_names_list, self._map_names_lower
        if not root_dir:
            self._map_names_root_key = ""
            self._map_names_list = []
            self._map_names_lower = []
            return [], []
        try:
            code_to_name, _name_to_code = _DropOverallOptimizeWorker._load_mapinfo(root_dir)
        except Exception:
            code_to_name = {}
        names_set: set[str] = set()
        try:
            for v in (code_to_name or {}).values():
                s = str(v or "").strip()
                if s:
                    names_set.add(s)
        except Exception:
            pass
        items = sorted(names_set)
        self._map_names_root_key = key
        self._map_names_list = items
        self._map_names_lower = [s.lower() for s in items]
        return items, self._map_names_lower

    def _get_monster_suggest_data(self) -> tuple[list[str], list[str]]:
        root_dir = self._get_server_root_for_suggest()
        key = os.path.normpath(root_dir).lower() if root_dir else ""
        if key and key == self._monster_names_root_key and self._monster_names_list:
            return self._monster_names_list, self._monster_names_lower
        if not root_dir:
            self._monster_names_root_key = ""
            self._monster_names_list = []
            self._monster_names_lower = []
            return [], []
        try:
            mon_dir = _DropOverallOptimizeWorker._find_monitems_dir(root_dir)
        except Exception:
            mon_dir = ""
        names_set: set[str] = set()
        if mon_dir and os.path.isdir(mon_dir):
            try:
                for f in os.listdir(mon_dir):
                    if not str(f).lower().endswith(".txt"):
                        continue
                    fp = os.path.join(mon_dir, f)
                    try:
                        if not os.path.isfile(fp):
                            continue
                    except Exception:
                        continue
                    base = os.path.splitext(os.path.basename(f))[0]
                    s = str(base or "").strip()
                    if s:
                        names_set.add(s)
            except Exception:
                names_set = set()
        items = sorted(names_set)
        self._monster_names_root_key = key
        self._monster_names_list = items
        self._monster_names_lower = [s.lower() for s in items]
        return items, self._monster_names_lower

    def _update_multi_popup(self, obj: QtCore.QObject) -> None:
        if self._multi_popup is None:
            return
        is_item_source = obj in (
            getattr(self, "add_mon_items_edit", None),
            getattr(self, "overall_items_edit", None),
            getattr(self, "delete_text", None),
        )
        if is_item_source:
            if _load_item_names is None:
                self._multi_popup.hide()
                return
            try:
                if self._item_names_model.rowCount() <= 0:
                    self._multi_popup.hide()
                    return
            except Exception:
                pass

        if isinstance(obj, QtWidgets.QLineEdit):
            text = obj.text() or ""
            pos = obj.cursorPosition()
            start, end = self._find_token_bounds(text, pos)
            query = (text[start:end] or "").strip()
            if not query:
                self._multi_popup.hide()
                return
            qkey = id(obj)
            last_q = self._multi_last_query_by_obj.get(qkey, "")
            qlower = str(query).strip().lower()
            last_lower = str(last_q).strip().lower()
            last_idx = self._multi_last_indices_by_obj.get(qkey)
            idx_base = last_idx if (last_idx is not None and last_lower and qlower.startswith(last_lower)) else None
            if obj is getattr(self, "overall_maps_edit", None):
                names, names_lower = self._get_map_suggest_data()
                matches, idx = self._filter_item_name_indices(qlower, idx_base, 80, names, names_lower)
            elif obj is getattr(self, "overall_monsters_edit", None):
                names, names_lower = self._get_monster_suggest_data()
                matches, idx = self._filter_item_name_indices(qlower, idx_base, 80, names, names_lower)
            else:
                matches, idx = self._filter_item_name_indices(qlower, idx_base, 80)
            if not matches:
                self._multi_popup.hide()
                return
            self._multi_last_query_by_obj[qkey] = query
            self._multi_last_indices_by_obj[qkey] = idx
            if query != last_q or not self._multi_popup.isVisible():
                self._multi_popup.set_items(matches)
                gp = obj.mapToGlobal(obj.cursorRect().bottomLeft())
                self._multi_popup.open_at(gp, obj.width(), lambda names, w=obj: self._apply_multi_selection_lineedit(w, names))
            return

        if isinstance(obj, QtWidgets.QPlainTextEdit):
            tc = obj.textCursor()
            block_text = tc.block().text()
            pos = tc.positionInBlock()
            start, end = self._find_token_bounds(block_text, pos)
            query = (block_text[start:end] or "").strip()
            if not query:
                self._multi_popup.hide()
                return
            qkey = id(obj)
            last_q = self._multi_last_query_by_obj.get(qkey, "")
            qlower = str(query).strip().lower()
            last_lower = str(last_q).strip().lower()
            last_idx = self._multi_last_indices_by_obj.get(qkey)
            idx_base = last_idx if (last_idx is not None and last_lower and qlower.startswith(last_lower)) else None
            matches, idx = self._filter_item_name_indices(qlower, idx_base, 80)
            if not matches:
                self._multi_popup.hide()
                return
            self._multi_last_query_by_obj[qkey] = query
            self._multi_last_indices_by_obj[qkey] = idx
            if query != last_q or not self._multi_popup.isVisible():
                self._multi_popup.set_items(matches)
                try:
                    gp = obj.viewport().mapToGlobal(obj.cursorRect().bottomLeft())
                except Exception:
                    gp = obj.mapToGlobal(obj.cursorRect().bottomLeft())
                self._multi_popup.open_at(gp, max(UiMetrics.MULTI_SELECT_POPUP_MIN_W, obj.viewport().width()), lambda names, w=obj: self._apply_multi_selection_plaintext(w, names))
            return

        self._multi_popup.hide()

    @classmethod
    def _apply_multi_selection_lineedit(cls, edit: QtWidgets.QLineEdit, names: list[str]) -> None:
        joined = ",".join([str(x).strip() for x in (names or []) if str(x).strip()])
        if not joined:
            return
        text = edit.text() or ""
        cursor = edit.cursorPosition()
        start, end = cls._find_token_bounds(text, cursor)
        seps = {",", "，", "、", ";", "；", "\n", "\r"}
        after = text[end : end + 1] if end < len(text) else ""
        suffix = "" if after in seps else ","
        new_text = text[:start] + joined + suffix + text[end:]
        edit.setText(new_text)
        edit.setCursorPosition(start + len(joined) + len(suffix))
        try:
            edit.setFocus()
        except Exception:
            pass

    @classmethod
    def _apply_multi_selection_plaintext(cls, edit: QtWidgets.QPlainTextEdit, names: list[str]) -> None:
        joined = ",".join([str(x).strip() for x in (names or []) if str(x).strip()])
        if not joined:
            return
        tc = edit.textCursor()
        block_text = tc.block().text()
        pos = tc.positionInBlock()
        start, end = cls._find_token_bounds(block_text, pos)
        seps = {",", "，", "、", ";", "；", "\n", "\r"}
        after = block_text[end : end + 1] if end < len(block_text) else ""
        suffix = "" if after in seps else ","
        start_pos = tc.position() - tc.positionInBlock() + start
        tc.setPosition(start_pos)
        tc.movePosition(QtGui.QTextCursor.Right, QtGui.QTextCursor.KeepAnchor, end - start)
        tc.insertText(joined + suffix)
        edit.setTextCursor(tc)
        try:
            edit.setFocus()
        except Exception:
            pass

    def _schedule_item_names_refresh(self) -> None:
        if bool(getattr(self, "_drop_closing", False)):
            return
        try:
            self._item_name_timer.start()
        except Exception:
            return

    def _refresh_item_names(self) -> None:
        if _load_item_names is None or bool(getattr(self, "_drop_closing", False)):
            return
        root = self.root_edit.text().strip()
        if not root:
            self._item_names_model.setStringList([])
            self._item_names_list = []
            self._item_names_lower = []
            self._multi_last_query_by_obj.clear()
            self._multi_last_indices_by_obj.clear()
            self._item_name_root_norm = ""
            try:
                if self._multi_popup is not None:
                    self._multi_popup.hide()
            except Exception:
                pass
            return
        try:
            root_norm = _CallRestoreWorker._normalize_server_root(os.path.abspath(root.strip().strip('"').strip("'")))
        except Exception:
            root_norm = os.path.abspath(root.strip().strip('"').strip("'"))
        candidates: list[str] = []
        if root_norm:
            candidates.append(root_norm)
        try:
            if os.path.basename(root_norm).lower() == "mir200":
                candidates.append(os.path.dirname(root_norm))
        except Exception:
            pass
        try:
            if os.path.isdir(os.path.join(root_norm, "Mir200")):
                candidates.append(root_norm)
        except Exception:
            pass
        for c in list(candidates):
            try:
                parent = os.path.dirname(c)
                if parent and parent not in candidates:
                    candidates.append(parent)
            except Exception:
                pass

        key = "|".join([os.path.normpath(x) for x in candidates if x])
        if key == self._item_name_root_norm:
            return
        self._item_name_root_norm = key
        self._item_name_load_seq += 1
        seq = self._item_name_load_seq

        def _job(cands: list[str]) -> list[str]:
            names: list[str] = []
            for c in cands:
                try:
                    names = _load_item_names(c)  # type: ignore[misc]
                except Exception:
                    names = []
                if names:
                    break
            return list(names or [])

        page_ref = weakref.ref(self)

        def _done(fut: concurrent.futures.Future) -> None:
            try:
                names = fut.result()
            except Exception:
                names = []
            page = page_ref()
            if page is None or bool(getattr(page, "_drop_closing", False)):
                return
            try:
                page.item_names_loaded.emit(seq, names)
            except Exception:
                return

        try:
            future = self._item_name_executor.submit(_job, list(candidates))
            self._item_name_future = future
            future.add_done_callback(_done)
        except Exception:
            try:
                names = _job(list(candidates))
            except Exception:
                names = []
            self.item_names_loaded.emit(seq, names)

    @QtCore.Slot(int, object)
    def _on_item_names_loaded(self, seq: int, names: object) -> None:
        if bool(getattr(self, "_drop_closing", False)) or seq != self._item_name_load_seq:
            return
        try:
            items = [str(x or "").strip() for x in (names or []) if str(x or "").strip()]
        except Exception:
            items = []
        self._item_names_list = items
        self._item_names_lower = [s.lower() for s in items]
        self._multi_last_query_by_obj.clear()
        self._multi_last_indices_by_obj.clear()
        self._item_names_model.setStringList(list(items or []))
        if not items:
            try:
                if self._multi_popup is not None:
                    self._multi_popup.hide()
            except Exception:
                pass

