    @staticmethod
    def _split_picker_names(text: str) -> list[str]:
        parts = re.split(r"[|,，、;；\r\n]+", str(text or ""))
        out: list[str] = []
        seen: set[str] = set()
        for part in parts:
            name = str(part or "").strip()
            if not name:
                continue
            low = name.lower()
            if low in seen:
                continue
            seen.add(low)
            out.append(name)
        return out

    @classmethod
    def _normalize_picker_names(cls, text_or_items) -> list[str]:
        if isinstance(text_or_items, str):
            items = cls._split_picker_names(text_or_items)
        else:
            items = cls._split_picker_names(",".join([str(x or "") for x in (text_or_items or [])]))
        return sorted(items, key=lambda s: (str(s).lower(), str(s)))

    @classmethod
    def _join_picker_names(cls, text_or_items) -> str:
        return ",".join(cls._normalize_picker_names(text_or_items))

    def _ensure_drop_item_names_ready(self) -> bool:
        self._schedule_item_names_refresh()
        try:
            self._refresh_item_names()
        except Exception:
            pass
        try:
            self._ensure_item_names_loaded()
        except Exception:
            pass
        if self._item_names_list:
            return True
        QtWidgets.QMessageBox.warning(self, "提示", "未加载到物品名称列表，请先选择正确的服务端目录")
        return False

    def _open_drop_item_picker_for_lineedit(self, edit: QtWidgets.QLineEdit) -> None:
        if not isinstance(edit, QtWidgets.QLineEdit):
            return
        if not self._ensure_drop_item_names_ready():
            return
        dlg = _RecycleItemPickerDialog(self, list(self._item_names_list or []), edit.text().strip())
        if dlg.exec_() != QtWidgets.QDialog.Accepted:
            return
        edit.setText(self._join_picker_names(dlg.selected_value()))
        try:
            edit.setFocus()
        except Exception:
            pass

    def _open_drop_item_picker_for_plaintext(self, edit: QtWidgets.QPlainTextEdit) -> None:
        if not isinstance(edit, QtWidgets.QPlainTextEdit):
            return
        if not self._ensure_drop_item_names_ready():
            return
        dlg = _RecycleItemPickerDialog(self, list(self._item_names_list or []), edit.toPlainText().strip())
        if dlg.exec_() != QtWidgets.QDialog.Accepted:
            return
        edit.setPlainText(self._join_picker_names(dlg.selected_value()))
        try:
            edit.setFocus()
        except Exception:
            pass

