    def _drop_worker_task_name(self, worker: QtCore.QObject) -> str:
        name = worker.__class__.__name__
        if name == "_DropFolderRestoreWorker":
            folder = str(getattr(worker, "_backup_folder", "") or "")
            if "整体爆率" in folder:
                return "整体爆率优化恢复"
            if "普通爆率分组" in folder:
                return "普通爆率分组恢复"
            if "指定删除" in folder:
                return "指定删除恢复"
            if "新增爆率" in folder:
                return "新增爆率恢复"
            return "备份恢复"
        return {
            "_DropOverallOptimizeWorker": "整体爆率优化",
            "_CallRestoreWorker": "#CALL还原",
            "_CallRestoreBackupWorker": "#CALL还原恢复",
            "_DropOptimizeWorker": "二级爆率优化",
            "_DropOptimizeRestoreWorker": "二级爆率优化恢复",
            "_DropGroupingWorker": "普通爆率分组",
            "_DropSpecificDeleteWorker": "指定删除",
            "_MonItemsAddWorker": "新增爆率",
        }.get(name, "爆率处理")

    def _handle_drop_worker_progress(self, value: int, text: str) -> None:
        task = str(getattr(self, "_current_drop_task_name", "") or "爆率处理")
        try:
            v = max(0, min(100, int(value)))
        except Exception:
            v = 0
        progress_text = str(text or "").strip() or f"{v}%"
        self._refresh_drop_detail_badges(task, progress_text, "info")

    def _handle_drop_worker_finished(self, ok: object, msg: str) -> bool:
        task = str(getattr(self, "_current_drop_task_name", "") or "爆率处理")
        success = bool(ok)
        role = "success" if success else "warn"
        phase = "已完成" if success else "失败"
        message = str(msg or (phase if success else "处理失败")).strip()
        self._refresh_drop_detail_badges(task, phase, role)
        try:
            self.detail_progress.setValue(100 if success else self.detail_progress.value())
        except Exception:
            pass
        try:
            self._append_log(self.detail_log, f"\n===== {task}{phase} =====\n{message}")
        except Exception:
            pass
        return True

