    @staticmethod
    def _split_overall_input(text: str) -> list[str]:
        return [x.strip() for x in re.split(r"[,，、；;\n\r]+", str(text or "")) if x.strip()]

    @staticmethod
    def _pick_db_for_root(root_dir: str, inject_type: str) -> str:
        try:
            cand_dirs = _ItemInjectWorker._guess_db_dirs(root_dir)
            return _ItemInjectWorker._choose_target_db(cand_dirs, inject_type, None)
        except Exception:
            return ""

    @staticmethod
    def _load_names_from_sqlite(db_path: str, table_hint: str, name_cols: list[str]) -> set[str]:
        if not db_path or not os.path.exists(db_path):
            return set()
        conn = None
        try:
            conn = sqlite3.connect(db_path, timeout=4.0)
            cur = conn.cursor()
            cur.execute("SELECT name FROM sqlite_master WHERE type='table'")
            tables = [r[0] for r in cur.fetchall() if r and r[0]]
            best_table = ""
            best_score = -1
            best_name_col = ""
            for t in tables:
                tl = str(t).lower()
                if tl.startswith("sqlite_"):
                    continue
                try:
                    cur.execute(f"PRAGMA table_info({t})")
                    cols = [row[1] for row in cur.fetchall() if row and row[1]]
                except Exception:
                    cols = []
                cols_low = {str(c).lower() for c in cols}
                score = 0
                if table_hint and table_hint.lower() in tl:
                    score += 5
                picked_col = ""
                for cand in name_cols:
                    if cand.lower() in cols_low:
                        score += 10
                        picked_col = cand
                        break
                if score > best_score:
                    best_score = score
                    best_table = t
                    best_name_col = picked_col
            if not best_table:
                return set()
            if not best_name_col:
                try:
                    cur.execute(f"PRAGMA table_info({best_table})")
                    cols = [row[1] for row in cur.fetchall() if row and row[1]]
                except Exception:
                    cols = []
                for c in cols:
                    if str(c).lower() in {x.lower() for x in name_cols}:
                        best_name_col = c
                        break
            if not best_name_col:
                return set()
            cur.execute(f"SELECT {best_name_col} FROM {best_table}")
            out: set[str] = set()
            for (v,) in cur.fetchall():
                s = str(v or "").strip()
                if s:
                    out.add(s)
            return out
        except Exception:
            return set()
        finally:
            try:
                if conn is not None:
                    conn.close()
            except Exception:
                pass

    def _on_overall_method_changed(self, _text: str) -> None:
        method = ""
        try:
            method = str(self.overall_method_combo.currentText() or "").strip()
        except Exception:
            method = ""

        show_maps = method == "按地图调整"
        show_monsters = method == "按怪物调整"
        show_items = method == "按物品调整"
        try:
            self.overall_maps_label.setVisible(show_maps)
            self.overall_maps_edit.setVisible(show_maps)
        except Exception:
            pass
        try:
            self.overall_monsters_label.setVisible(show_monsters)
            self.overall_monsters_edit.setVisible(show_monsters)
        except Exception:
            pass
        try:
            self.overall_items_label.setVisible(show_items)
            self.overall_items_edit.setVisible(show_items)
        except Exception:
            pass

        range_mode = ""
        try:
            range_mode = str(self.overall_range_combo.currentText() or "").strip()
        except Exception:
            range_mode = ""
        try:
            self.overall_range_value_edit.setEnabled(range_mode in ("大于", "小于", "等于"))
        except Exception:
            pass

    def _start_overall_optimize(self) -> None:
        root = self.root_edit.text().strip()
        if not root:
            QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
            return

        method = str(self.overall_method_combo.currentText() or "").strip() or "全服调整"
        maps_text = self.overall_maps_edit.text().strip()
        monsters_text = self.overall_monsters_edit.text().strip()
        items_text = self.overall_items_edit.text().strip()
        range_mode = str(self.overall_range_combo.currentText() or "默认").strip()
        range_val = 0
        if range_mode in ("大于", "小于", "等于"):
            try:
                range_val = int(self.overall_range_value_edit.text().strip() or "0")
            except Exception:
                QtWidgets.QMessageBox.warning(self, "提示", "范围阈值必须为整数")
                return

        op = str(self.overall_op_combo.currentText() or "").strip()
        op_val_raw = self.overall_op_value_edit.text().strip()
        if not op_val_raw:
            QtWidgets.QMessageBox.warning(self, "提示", "请输入修改值")
            return
        try:
            op_val = float(op_val_raw)
        except Exception:
            QtWidgets.QMessageBox.warning(self, "提示", "修改值必须为数字")
            return
        if op == "除" and op_val == 0:
            QtWidgets.QMessageBox.warning(self, "提示", "除法模式下修改值不能为 0")
            return

        if method == "按地图调整":
            maps = self._split_overall_input(maps_text)
            if not maps:
                QtWidgets.QMessageBox.warning(self, "提示", "请填写地图名称")
                return
            try:
                parser = _SpawnToolLite(root)
                code_to_name = parser._load_mapinfo_names()
            except Exception:
                code_to_name = {}
            if code_to_name:
                names_low = {str(v).strip().lower() for v in code_to_name.values() if str(v).strip()}
                unknown = []
                for m in maps:
                    k = str(m).strip().lower()
                    if k in code_to_name:
                        continue
                    if k in names_low:
                        continue
                    unknown.append(m)
                if unknown:
                    QtWidgets.QMessageBox.warning(self, "提示", f"以下地图未在 MapInfo.txt 中找到：{', '.join(unknown[:20])}{'...' if len(unknown) > 20 else ''}")
                    return
        if method == "按怪物调整":
            monsters = self._split_overall_input(monsters_text)
            if not monsters:
                QtWidgets.QMessageBox.warning(self, "提示", "请填写怪物名称")
                return
            db_path = self._pick_db_for_root(root, "怪物库")
            names = self._load_names_from_sqlite(db_path, "monster", ["name", "mobname"])
            if names:
                miss = [m for m in monsters if str(m).strip() and (str(m).strip() not in names)]
                if miss:
                    QtWidgets.QMessageBox.warning(self, "提示", f"以下怪物未在怪物库中找到：{', '.join(miss[:20])}{'...' if len(miss) > 20 else ''}")
                    return
        if method == "按物品调整":
            items = self._split_overall_input(items_text)
            if not items:
                QtWidgets.QMessageBox.warning(self, "提示", "请填写物品名称")
                return
            if not self._item_names_list:
                QtWidgets.QMessageBox.warning(self, "提示", "未加载到物品名称列表，请先选择正确的服务端目录")
                return
            names_low = {str(x).strip().lower() for x in self._item_names_list if str(x).strip()}
            miss = [x for x in items if str(x).strip() and (str(x).strip().lower() not in names_low)]
            if miss:
                QtWidgets.QMessageBox.warning(self, "提示", f"以下物品未在物品库中找到：{', '.join(miss[:20])}{'...' if len(miss) > 20 else ''}")
                return

        confirm = QtWidgets.QMessageBox.question(
            self,
            "确认",
            f"即将执行整体爆率优化：{method}\n范围：{range_mode}{(' ' + str(range_val)) if range_mode != '默认' else ''}\n修改：{op} {op_val_raw}\n是否继续？",
        )
        if confirm != QtWidgets.QMessageBox.Yes:
            return

        self.overall_progress.setValue(0)
        self.overall_log.clear()

        def _on_log(s: str) -> None:
            self._append_log(self.overall_log, s)

        def _on_progress(v: int, text: str) -> None:
            self.overall_progress.setValue(int(v))

        def _on_finished(ok: object, msg: str) -> None:
            if ok:
                QtWidgets.QMessageBox.information(self, "完成", msg or "处理完成")
            else:
                QtWidgets.QMessageBox.critical(self, "失败", msg or "处理失败")

        self._start_worker(
            _DropOverallOptimizeWorker(
                root,
                method,
                maps_text,
                monsters_text,
                items_text,
                range_mode,
                range_val,
                op,
                op_val,
            ),
            _on_log,
            _on_progress,
            _on_finished,
        )

