    @QtCore.Slot()
    def _shutdown_drop_resources(self) -> None:
        if bool(getattr(self, "_drop_closing", False)):
            return
        self._drop_closing = True
        self._item_name_load_seq += 1
        for timer in (getattr(self, "_item_name_timer", None), getattr(self, "_multi_update_timer", None)):
            try:
                timer.stop()
            except Exception:
                pass
        try:
            future = getattr(self, "_item_name_future", None)
            if future is not None:
                future.cancel()
        except Exception:
            pass
        try:
            executor = getattr(self, "_item_name_executor", None)
            if executor is not None:
                executor.shutdown(wait=True)
        except Exception:
            pass
        self._item_name_executor = None
        self._item_name_future = None
        try:
            if self._multi_popup is not None:
                self._multi_popup.hide()
                self._multi_popup.deleteLater()
        except Exception:
            pass
        self._multi_popup = None
        thread = getattr(self, "_thread", None)
        if thread is not None:
            try:
                thread.requestInterruption()
                thread.quit()
                if thread.isRunning():
                    thread.wait()
            except Exception:
                pass
            try:
                thread.deleteLater()
            except Exception:
                pass
        self._thread = None
        self._worker = None
        self._bridge = None

    def closeEvent(self, event: QtGui.QCloseEvent) -> None:
        self._shutdown_drop_resources()
        super().closeEvent(event)

    def _cleanup_thread(self) -> None:
        try:
            if self._thread is not None:
                self._thread.deleteLater()
        except Exception:
            pass
        self._thread = None
        self._worker = None
        self._bridge = None
        self._set_busy(False)

    def _start_worker(self, worker: QtCore.QObject, on_log, on_progress, on_finished) -> None:
        if self._thread is not None:
            self._append_log(self.detail_log, "已有爆率任务正在执行，请等待当前任务完成。")
            return
        self._current_drop_task_name = self._drop_worker_task_name(worker)
        self._refresh_drop_detail_badges(self._current_drop_task_name, "执行中", "info")
        self._append_log(self.detail_log, f"===== {self._current_drop_task_name} 开始 =====")
        self._set_busy(True)
        self._bridge = _DropRateUiBridge(on_log, on_progress, on_finished, parent=self)
        self._thread = QtCore.QThread()
        self._worker = worker
        worker.moveToThread(self._thread)
        self._thread.started.connect(getattr(worker, "run"))
        if hasattr(worker, "log"):
            getattr(worker, "log").connect(getattr(self._bridge, "on_log"))
        if hasattr(worker, "progress"):
            getattr(worker, "progress").connect(getattr(self._bridge, "on_progress"))
        getattr(worker, "finished").connect(getattr(self._bridge, "on_finished"))
        getattr(worker, "finished").connect(self._thread.quit)
        getattr(worker, "finished").connect(worker.deleteLater)
        self._thread.finished.connect(self._cleanup_thread)
        self._thread.start()

