        root = self.root_edit.text().strip()
        if not root:
            QtWidgets.QMessageBox.warning(self, "提示", "请先选择根目录")
            return

        items_raw = str(self.add_mon_items_edit.text() or "").strip()
        if not items_raw:
            QtWidgets.QMessageBox.warning(self, "提示", "请输入物品名称")
            return
        normalized_items_text = self._join_picker_names(items_raw)
        if normalized_items_text != items_raw:
            self.add_mon_items_edit.setText(normalized_items_text)
            items_raw = normalized_items_text

        rate_raw = str(self.add_mon_rate_edit.text() or "").strip()
        if not rate_raw:
            QtWidgets.QMessageBox.warning(self, "提示", "请输入爆率值")
            return

        try:
            rate_val = float(rate_raw)
            if rate_val <= 0:
                raise ValueError("rate must be > 0")
            if float(rate_val).is_integer():
                rate = str(int(rate_val))
            else:
                rate = str(rate_val)
        except Exception:
            QtWidgets.QMessageBox.critical(self, "错误", "爆率值必须为大于 0 的数字")
            return

        items = [x.strip() for x in re.split(r"[,，、\s]+", items_raw) if x.strip()]
        if not items:
            QtWidgets.QMessageBox.warning(self, "提示", "请输入有效的物品名称")
            return

