                "*{box-sizing:border-box}\n"
                "html{scroll-behavior:smooth}\n"
                "body{margin:0;min-height:100vh;background:radial-gradient(circle at 50% 0,rgba(215,162,63,.16),transparent 26%),radial-gradient(circle at 18% 18%,rgba(121,34,23,.28),transparent 32%),radial-gradient(circle at 82% 10%,rgba(93,20,14,.24),transparent 28%),linear-gradient(180deg,#1a0a08 0,#090403 54%,#040202 100%);color:var(--text);font-family:'Segoe UI','Microsoft YaHei','PingFang SC',sans-serif;line-height:1.65;text-rendering:optimizeLegibility}\n"

                "a{color:var(--acc);text-decoration:none;transition:color .2s ease,transform .2s ease,border-color .2s ease,background .2s ease,box-shadow .2s ease}\n"
                "a:hover{color:var(--acc-2)}\n"
                "a:focus-visible,button:focus-visible{outline:none;box-shadow:0 0 0 3px rgba(244,196,76,.22)}\n"
                ".wrap{width:min(1240px,calc(100% - 40px));margin:0 auto}\n"
                ".muted{color:var(--muted)}\n"
                ".mono{font-family:Consolas,monospace}\n"
