                ".header .inner{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px 0}\n"
                ".brand h1{margin:0;font-size:clamp(24px,3vw,32px);color:var(--acc);letter-spacing:.02em;text-shadow:0 4px 18px rgba(0,0,0,.45);font-weight:900}\n"
                ".brand .sub{color:#d7bb8b;font-size:13px;margin-top:4px;letter-spacing:.14em;text-transform:uppercase}\n"

