                ".nav a{display:inline-flex;align-items:center;min-height:42px;font-size:15px;font-weight:800;padding:6px 0;position:relative}\n"
                ".nav a.active{color:var(--acc-2)}\n"
                ".nav a::after{content:'';position:absolute;bottom:0;left:0;width:0;height:2px;border-radius:999px;background:var(--acc);transition:width .22s ease}\n"
                ".nav a:hover::after,.nav a.active::after{width:100%}\n"
                ".hero{position:relative;overflow:hidden;padding:92px 0 72px;border-bottom:1px solid var(--line)}\n"
