                ".eyebrow{display:inline-flex;align-items:center;gap:8px;min-height:34px;padding:0 14px;border:1px solid rgba(244,196,76,.24);border-radius:999px;background:rgba(255,255,255,.04);color:var(--acc-2);font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase;box-shadow:inset 0 0 0 1px rgba(255,255,255,.03)}\n"
                ".hero h2{font-size:clamp(40px,5vw,64px);margin:20px 0 18px;line-height:1.08;color:#fff;text-shadow:0 8px 30px rgba(0,0,0,.42)}\n"
                ".hero p{font-size:17px;color:#d3dbeb;max-width:680px;margin:0 0 26px;white-space:pre-wrap}\n"
                ".hero-actions{display:flex;gap:14px;flex-wrap:wrap;margin-bottom:18px}\n"
                ".btn-dl{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:52px;padding:0 26px;border-radius:16px;border:1px solid transparent;background:linear-gradient(135deg,var(--acc),var(--acc-2));color:#1b1609;font-size:15px;font-weight:900;letter-spacing:.02em;box-shadow:0 18px 30px rgba(244,196,76,.16)}\n"
                ".btn-dl:hover{transform:translateY(-2px);color:#120f08;box-shadow:0 22px 36px rgba(244,196,76,.22);text-decoration:none}\n"
                ".btn-outline{background:linear-gradient(180deg,rgba(109,31,22,.76),rgba(57,18,14,.76));border-color:rgba(244,196,76,.34);color:var(--acc-2);box-shadow:none}\n"

                ".btn-outline:hover{background:rgba(244,196,76,.92);border-color:transparent;color:#16120b}\n"
                ".hero-badges{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:18px}\n"
                ".tag-pill{display:inline-flex;align-items:center;min-height:34px;padding:0 14px;border-radius:999px;background:rgba(255,255,255,.05);border:1px solid var(--line);color:#dfe7f7;font-size:13px;font-weight:700;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}\n"
                ".hero-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}\n"
                ".metric-card{padding:18px 18px 16px;border-radius:18px;border:1px solid var(--line);background:linear-gradient(180deg,rgba(255,255,255,.05),rgba(255,255,255,.02));box-shadow:var(--shadow-soft);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}\n"
                ".metric-value{display:block;font-size:28px;font-weight:900;color:#fff;letter-spacing:.02em}\n"
                ".metric-label{display:block;margin-top:6px;font-size:13px;color:var(--muted)}\n"
                ".hero-side{display:flex;flex-direction:column;gap:18px}\n"
                ".hero-panel{position:relative;padding:24px;border-radius:24px;border:1px solid rgba(255,224,173,.12);background:linear-gradient(180deg,rgba(43,23,19,.94),rgba(20,9,8,.98));box-shadow:var(--shadow)}\n"

