                "@media (max-width: 780px){.wrap{width:min(100%,calc(100% - 28px))}.header .inner{flex-direction:column;align-items:flex-start}.nav{width:100%}.nav a{min-height:38px}.hero{padding:76px 0 60px}.hero h2{font-size:38px}.hero-metrics{grid-template-columns:1fr}.stack-cards{grid-template-columns:1fr}.v-grid{grid-template-columns:1fr}.download-card{flex-direction:column;align-items:flex-start}.btn-dl,.hero-actions .btn-dl{width:100%}}\n"
