                "<script>(function(){"
                "const reduce=!!(window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches);"
                "const bindBook=(box)=>{"
                "const book=box.querySelector('.v-book');if(!book) return;"
                "let srcs=[];try{srcs=JSON.parse(book.getAttribute('data-srcs')||'[]');}catch(e){}"
                "if((!srcs||!srcs.length)&&book.getAttribute('data-srcs2')) srcs=String(book.getAttribute('data-srcs2')||'').split('||').filter(Boolean);"
                "const front=book.querySelector('.v-front'),back=book.querySelector('.v-back'),prev=box.querySelector('.v-arrow.prev'),next=box.querySelector('.v-arrow.next'),dots=Array.from(box.querySelectorAll('.v-dot'));"
                "if(!front||!back||!srcs.length) return;"
                "let idx=0,timer=0,busy=false;"
                "const sync=()=>{dots.forEach((d,i)=>d.classList.toggle('active',i===idx));};sync();"
                "const stop=()=>{if(timer){clearInterval(timer);timer=0;}};"
                "const go=(to,dir)=>{if(busy||to===idx||!srcs[to]) return;busy=true;back.src=srcs[to];box.classList.remove('flip-next','flip-prev');box.classList.add('animating',dir<0?'flip-prev':'flip-next');setTimeout(()=>{try{front.src=srcs[to];idx=to;sync();}catch(e){}box.classList.remove('animating','flip-next','flip-prev');busy=false;},reduce?30:780);};"
                "const start=()=>{if(reduce||srcs.length<=1||timer) return;timer=setInterval(()=>{if(document.hidden||busy) return;go((idx+1)%srcs.length,1);},3200);};"
                "box._startAuto=start;box._stopAuto=stop;"
                "if(prev) prev.onclick=(ev)=>{try{ev.preventDefault();ev.stopPropagation();}catch(e){}stop();go((idx-1+srcs.length)%srcs.length,-1);start();};"
                "if(next) next.onclick=(ev)=>{try{ev.preventDefault();ev.stopPropagation();}catch(e){}stop();go((idx+1)%srcs.length,1);start();};"
                "dots.forEach((d,i)=>{d.onclick=(ev)=>{try{ev.preventDefault();ev.stopPropagation();}catch(e){}stop();go(i,i<idx?-1:1);start();};});"
                "if(srcs.length<=1){if(prev) prev.style.display='none';if(next) next.style.display='none';const dotsBox=box.querySelector('.v-dots');if(dotsBox) dotsBox.style.display='none';return;}"
                "if('IntersectionObserver' in window){const io=new IntersectionObserver((entries)=>{entries.forEach(en=>{if(en.isIntersecting) start();else stop();});},{threshold:.35});io.observe(box);}else{start();}"
                "box.addEventListener('mouseenter',stop);box.addEventListener('mouseleave',start);box.addEventListener('focusin',stop);box.addEventListener('focusout',start);"
                "};"
                "document.querySelectorAll('.v-img').forEach(bindBook);"
