    def _build(self) -> None:
        self.setProperty("toolboxResponsiveStackWidth", True)
        outer = QtWidgets.QVBoxLayout(self)
        outer.setContentsMargins(0, 0, 0, 0)
        outer.setSpacing(UiMetrics.WEBSITE_PAGE_SPACING)

        self.pageTitleRow = _build_page_title_row(self, "网站管理")
        outer.addWidget(self.pageTitleRow)

        desc = QtWidgets.QLabel("创建/管理传奇相关网站：游戏发布、简介、下载、QQ群、爆率查询数据导出。")
        desc.setObjectName("pageDesc")
        desc.setWordWrap(True)
        self.pageDesc = desc
        outer.addWidget(desc)

        root_panel = QtWidgets.QFrame()
        root_panel.setObjectName("websiteRootPanel")
        root_panel_l = QtWidgets.QVBoxLayout(root_panel)
        root_panel_l.setContentsMargins(0, 0, 0, 0)
        root_panel_l.setSpacing(UiMetrics.WEBSITE_ROOT_PANEL_SPACING)
        self.website_root_bar = self._build_website_root_bar()
        root_panel_l.addWidget(self.website_root_bar, 0)
        root_panel_l.addWidget(self._build_website_toolbar(), 0)
        outer.addWidget(root_panel, 0)
        outer.addWidget(self._build_website_workspace(), 1)
        outer.addWidget(self._build_website_output_panel(), 0)

    def _apply_website_immersive_mode(self) -> None:
        for widget in (getattr(self, "pageTitleRow", None), getattr(self, "pageDesc", None)):
            if isinstance(widget, QtWidgets.QWidget):
                try:
                    widget.setVisible(False)
                except Exception:
                    pass
        root_bar = getattr(self, "website_root_bar", None)
        if isinstance(root_bar, QtWidgets.QWidget):
            try:
                root_layout = root_bar.layout()
                if root_layout is not None:
                    root_layout.setContentsMargins(0, 0, 0, 0)
                    root_layout.setSpacing(UiMetrics.WEBSITE_ROOT_BAR_H_SPACING)
                root_bar.setParent(None)
            except Exception:
                pass

