    def _build_website_root_bar(self) -> QtWidgets.QFrame:
        top = QtWidgets.QFrame()
        top.setObjectName("websiteRootBar")
        top_l = QtWidgets.QGridLayout(top)
        top_l.setContentsMargins(
            UiMetrics.WEBSITE_ROOT_PANEL_MARGIN_PX,
            UiMetrics.WEBSITE_ROOT_PANEL_MARGIN_PX,
            UiMetrics.WEBSITE_ROOT_PANEL_MARGIN_PX,
            UiMetrics.WEBSITE_ROOT_PANEL_MARGIN_PX,
        )
        top_l.setHorizontalSpacing(UiMetrics.WEBSITE_ROOT_BAR_H_SPACING)
        top_l.setVerticalSpacing(UiMetrics.WEBSITE_ROOT_BAR_V_SPACING)
        top_l.addWidget(QtWidgets.QLabel("根目录："), 0, 0)
        self.root_edit = _make_ui_line_edit("path-compact", "选择服务端根目录（包含 Mir200）…")
        self.root_edit.setObjectName("websiteRootEdit")
        self.root_edit.textChanged.connect(self._on_field_changed)
        self.root_edit.textChanged.connect(self._maybe_autofill_drop_query_name_from_root)
        self.root_edit.textChanged.connect(lambda text: self._sync_line_edit_tooltip(self.root_edit, text))
        top_l.addWidget(self.root_edit, 0, 1)
        btn_browse = _make_ui_action_button("浏览…", "secondary")
        btn_browse.setObjectName("websiteRootBrowseButton")
        btn_browse.clicked.connect(self._browse_root)
        top_l.addWidget(btn_browse, 0, 2)
        top_l.setColumnStretch(1, 1)
