        self.btn_open_dir.clicked.connect(self._open_output_dir)
        toolbar_l.addWidget(self.btn_open_dir, 0, 2)
        self.btn_open_home = _make_ui_action_button("打开首页", "secondary")
        self.btn_open_home.setObjectName("websiteOpenHomeButton")
        self.btn_open_home.clicked.connect(self._open_home)
        toolbar_l.addWidget(self.btn_open_home, 0, 3)

        self.btn_toggle_output = _make_ui_action_button("日志", "toolbar")
        self.btn_toggle_output.setObjectName("websiteToggleOutputButton")
