    def _build_website_workspace(self) -> QtWidgets.QFrame:
        workspace = QtWidgets.QFrame()
        workspace.setObjectName("websiteWorkspacePanel")
        workspace_l = QtWidgets.QVBoxLayout(workspace)
        workspace_l.setContentsMargins(0, 0, 0, 0)
        workspace_l.setSpacing(UiMetrics.WEBSITE_WORKSPACE_PANEL_SPACING)

        tabs = QtWidgets.QTabWidget()
        tabs.setObjectName("websiteTabs")
        self.website_tabs = tabs
        workspace_l.addWidget(tabs, 1)

        self.site_list = QtWidgets.QListWidget()
        self.site_list.currentRowChanged.connect(self._on_site_changed)
        self.site_list.hide()

        self._build_website_site_tab(tabs)
        self._build_website_content_tab(tabs)

        def _make_tab(title: str) -> QtWidgets.QVBoxLayout:
            return self._make_website_tab(tabs, title)

        self._build_website_versions_tab(tabs)
        self._build_website_qq_tab(tabs)
        self._build_website_drop_query_tab(tabs)

        return workspace

    def _make_website_tab(self, tabs: QtWidgets.QTabWidget, title: str) -> QtWidgets.QVBoxLayout:
        scroll = QtWidgets.QScrollArea()
        scroll.setWidgetResizable(True)
        scroll.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
        scroll.setObjectName(f"websiteTabScroll_{title}")
        if not hasattr(self, "_website_tab_scrolls"):
            self._website_tab_scrolls = {}
        try:
            self._website_tab_scrolls[str(title or "").strip()] = scroll
        except Exception:
            pass
        body = QtWidgets.QWidget()
        scroll.setWidget(body)
        lay = QtWidgets.QVBoxLayout(body)
        lay.setContentsMargins(0, 0, 0, 0)
        lay.setSpacing(UiMetrics.WEBSITE_TAB_SPACING)
        tabs.addTab(scroll, title)
        return lay

