    def _set_version_remote_panel_expanded(self, expanded: bool) -> None:
        self._version_remote_expanded = bool(expanded)
        box = getattr(self, "website_version_remote_box", None)
        btn = getattr(self, "btn_toggle_version_remote", None)
        version_list = getattr(self, "ver_list", None)
        version_pane = getattr(self, "website_version_list_pane", None)
        if box is not None:
            box.setVisible(bool(expanded))
        if btn is not None:
            btn.setChecked(bool(expanded))
            btn.setText("收起远端控制" if expanded else "远端控制")
        if isinstance(version_list, QtWidgets.QListWidget):
            try:
                if expanded:
                    version_list.setFixedHeight(132)
                else:
                    version_list.setMinimumHeight(UiMetrics.WEBSITE_VERSION_LIST_MIN_H)
                    version_list.setMaximumHeight(16777215)
            except Exception:
                pass
        if isinstance(version_pane, QtWidgets.QWidget):
            try:
                if expanded:
                    version_pane.setFixedHeight(214)
                    version_pane.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
                else:
                    version_pane.setMinimumHeight(0)
                    version_pane.setMaximumHeight(16777215)
                    version_pane.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Expanding)
            except Exception:
                pass
        if expanded and isinstance(box, QtWidgets.QWidget):
            try:
                scrolls = getattr(self, "_website_tab_scrolls", {}) or {}
                scroll = scrolls.get("版本")
                if isinstance(scroll, QtWidgets.QScrollArea):
                    QtCore.QTimer.singleShot(0, lambda s=scroll, w=box: s.ensureWidgetVisible(w, 0, 12))
            except Exception:
                pass

