    @staticmethod
    def _guess_version_name_from_root_dir(root_dir: str) -> str:
        p = os.path.abspath(str(root_dir or "").strip().strip('"').strip("'"))
        if not p:
            return ""
        cfg_path = os.path.join(p, "Config.ini")
        if os.path.isfile(cfg_path):
            try:
                lines, _enc, _ending, _trailing = _read_text_file_best_effort(cfg_path)
                sec = ""
                sec_low = ""
                keymap: dict[str, str] = {}
                for ln in lines:
                    s = str(ln or "").strip()
                    if not s or s.startswith(";") or s.startswith("#"):
                        continue
                    if s.startswith("[") and s.endswith("]"):
                        sec = s[1:-1].strip()
                        sec_low = sec.lower()
                        continue
                    if "=" not in s:
                        continue
                    k, _, v = s.partition("=")
                    k = k.strip()
                    if not k:
                        continue
                    val = v.strip().strip('"').strip("'").strip()
                    if not val:
                        continue
                    if sec_low:
                        keymap[f"{sec_low}.{k.lower()}"] = val
                    keymap[k.lower()] = val
                for kk in (
                    "gameconf.gamename",
                    "gameconf.versionname",
                    "gameconf.servername",
                    "gamename",
                    "versionname",
                    "servername",
                ):
                    val = str(keymap.get(kk) or "").strip()
                    if val:
                        return val
            except Exception:
                pass
        base = os.path.basename(p.rstrip("\\/"))
        if base.lower() in ("mir200", "envir", "map", "data"):
            parent = os.path.dirname(p.rstrip("\\/"))
            if parent:
                base = os.path.basename(parent.rstrip("\\/")) or base
        low = base.lower()
        if low.startswith("mirserver"):
            rest = base[len("mirserver") :].strip()
            rest = rest.lstrip(" _-—")
            if rest:
                return rest
        return base.strip()

    def _maybe_autofill_drop_query_name_from_root(self) -> None:
        root = ""
        try:
            root = str(self.drop_root_edit.text() or "").strip() if hasattr(self, "drop_root_edit") and self.drop_root_edit else ""
            if not root:
                root = str(self.root_edit.text() or "").strip() if hasattr(self, "root_edit") and self.root_edit else ""
        except Exception:
            root = ""
        if not root:
            return
        guess = self._guess_version_name_from_root_dir(root)
        if not guess:
            return
        cur = ""
        try:
            cur = str(self.drop_name_edit.text() or "").strip()
        except Exception:
            cur = ""
        auto_allowed = (not cur) or (cur == "未命名") or bool(re.fullmatch(r"查询\d*", cur))
        if not auto_allowed:
            return
        existing: set[str] = set()
        try:
            cur_item = self.drop_query_list.currentItem()
        except Exception:
            cur_item = None
        try:
            for i in range(int(self.drop_query_list.count())):
                it = self.drop_query_list.item(i)
                if not it:
                    continue
                if cur_item is not None and it is cur_item:
                    continue
                s = str(it.text() or "").strip()
                if s:
                    existing.add(s)
        except Exception:
            existing = set()
        target = guess
        if target in existing:
            for k in range(2, 1000):
                cand = f"{guess}({k})"
                if cand not in existing:
                    target = cand
                    break
        if cur == target:
            return
        blocker = QtCore.QSignalBlocker(self.drop_name_edit)
        try:
            self.drop_name_edit.setText(target)
        finally:
            del blocker

