    def _default_drop_types(self) -> list[str]:
        return ["沉默服", "复古版", "微变", "中变", "超变", "合击", "单职业", "沉默", "暗黑", "专属", "三职业"]

    def _set_drop_types(self, types: list[str]) -> None:
        out: list[str] = []
        for x in list(types or []):
            s = str(x or "").strip()
            if s and s not in out:
                out.append(s)
        if not out:
            out = self._default_drop_types()
        self._drop_types = list(out)
        cur = ""
        try:
            cur = str(self.drop_type_cb.currentText() or "").strip()
        except Exception:
            cur = ""
        blocker = QtCore.QSignalBlocker(self.drop_type_cb)
        try:
            self.drop_type_cb.clear()
            self.drop_type_cb.addItems(self._drop_types)
        finally:
            del blocker
        if cur and cur in self._drop_types:
            try:
                self.drop_type_cb.setCurrentText(cur)
            except Exception:
                pass

    def _open_drop_common_settings(self) -> None:
        init = "\n".join(list(getattr(self, "_drop_types", []) or []) or self._default_drop_types())
        text, ok = QtWidgets.QInputDialog.getMultiLineText(self, "通用设置", "版本类型（每行一个）：", init)
        if not ok:
            return
        types: list[str] = []
        for ln in str(text or "").splitlines():
            raw = str(ln or "")
            s0 = raw.strip()
            if not s0 or s0.startswith(";"):
                continue
            if ";" in raw:
                raw = raw.split(";", 1)[0]
            s = raw.strip()
            if s:
                types.append(s)
        self._set_drop_types(types)
        self._dirty = True

    
