    def _append_log(self, s: str) -> None:
        text = str(s or "")
        status = getattr(self, "website_status_label", None)
        if status is not None:
            try:
                line = text.strip().splitlines()[-1] if text.strip() else "就绪"
                summary = line
                if "：" in summary and len(summary) > 34:
                    summary = summary.split("：", 1)[0].strip() or summary
                if len(summary) > 38:
                    summary = summary[:35].rstrip() + "..."
                status.setText(summary or "就绪")
                status.setToolTip(line)
            except Exception:
                pass
        try:
            self.log.appendPlainText(text)
        except Exception:
            return

    @staticmethod
    def _upsert_list_item_by_id(list_widget: QtWidgets.QListWidget, data: dict, *, label_key: str = "name") -> None:
        if list_widget is None or not isinstance(data, dict):
            return
        target_id = str(data.get("id") or "").strip()
        if not target_id:
            return
        existing_item = None
        try:
            for i in range(int(list_widget.count())):
                it = list_widget.item(i)
                if not it:
                    continue
                row_data = it.data(QtCore.Qt.UserRole)
                if isinstance(row_data, dict) and str(row_data.get("id") or "").strip() == target_id:
                    existing_item = it
                    break
        except Exception:
            existing_item = None

        label = str(data.get(label_key) or "未命名").strip() or "未命名"
        if existing_item is None:
            item = QtWidgets.QListWidgetItem(label)
            _WebsiteManagerPage._sync_list_item_text_tooltip(item, label)
            item.setData(QtCore.Qt.UserRole, data)
            list_widget.insertItem(0, item)
            list_widget.setCurrentItem(item)
            return

        existing_item.setData(QtCore.Qt.UserRole, data)
        _WebsiteManagerPage._sync_list_item_text_tooltip(existing_item, label)
        list_widget.setCurrentItem(existing_item)

    @staticmethod
    def _sync_list_item_text_tooltip(item: QtWidgets.QListWidgetItem | None, text: object) -> None:
        if item is None:
            return
        label = str(text or "未命名").strip() or "未命名"
        item.setText(label)
        item.setToolTip(label)

    @staticmethod
    def _sync_version_list_item(item: QtWidgets.QListWidgetItem | None, data: object) -> None:
        if item is None:
            return
        v = data if isinstance(data, dict) else {}
        name = str(v.get("name") or "未命名").strip() or "未命名"
        desc = str(v.get("desc") or "").strip()
        download = str(v.get("download_url") or "").strip()
        images = v.get("images")
        image_count = len([x for x in images if str(x or "").strip()]) if isinstance(images, list) else (1 if str(v.get("image") or "").strip() else 0)
        meta_parts = []
        if desc:
            meta_parts.append(desc.replace("\r", " ").replace("\n", " ")[:42])
        meta_parts.append(f"图片 {image_count}")
        meta_parts.append("已配置下载" if download else "未配置下载")
        text = "■ " + name + "\n   " + "  ·  ".join(meta_parts)
        item.setText(text)
        item.setToolTip(text)
        try:
            item.setSizeHint(QtCore.QSize(0, UiMetrics.WEBSITE_VERSION_LIST_ITEM_H))
        except Exception:
            pass

