    @staticmethod
    def _remote_safe_id(v: str) -> str:
        s = str(v or "").strip()
        if not s:
            return ""
        s = re.sub(r"[^a-zA-Z0-9_\\-]+", "_", s)
        s = s.strip("_")
        if len(s) > 40:
            s = s[:40]
        return s

    @staticmethod
    def _normalize_remote_peer_base_url(peer_url: str) -> str:
        u = str(peer_url or "").strip()
        if not u:
            return ""
        if not (u.lower().startswith("http://") or u.lower().startswith("https://")):
            u = "http://" + u
        p = urllib.parse.urlsplit(u)
        scheme = str(p.scheme or "http").strip() or "http"
        netloc = str(p.netloc or "").strip()
        if not netloc:
            return u.rstrip("/")
        if not netloc.startswith("[") and netloc.count(":") > 1:
            raise ValueError("远端地址格式错误（端口重复），请填写如 1.2.3.4:8000 或 域名:8000")
        return f"{scheme}://{netloc}".rstrip("/")

    @classmethod
    def _remote_endpoints_from_peer_input(cls, peer_url: str, action: str) -> list[str]:
        base = cls._normalize_remote_peer_base_url(peer_url)
        if not base:
            return []
        a = str(action or "").strip().lstrip("/")
        if not a:
            return []
        candidates = [
            base + "/__toolbox_remote__/" + a,
            base + "/_toolbox_remote_/" + a,
        ]
        out: list[str] = []
        for c in candidates:
            if c not in out:
                out.append(c)
        return out

    @staticmethod
    def _drop_query_detail_file_name(base_name: str) -> str:
        """根据主爆率 JSON 文件名生成对应的明细文件名。"""
        name = os.path.basename(str(base_name or "").strip())
        if not name:
            return ""
        if name.lower().endswith(".json"):
            return name[:-5] + "_detail.json"
        return name + "_detail.json"

    @staticmethod
    def _format_remote_sync_error(e: Exception) -> str:
        try:
            if isinstance(e, urllib.error.HTTPError):
                code = getattr(e, "code", None)
                reason = str(getattr(e, "reason", "") or "").strip()
                try:
                    url = str(e.geturl() or "").strip()
                except Exception:
                    url = ""
                remote_msg = ""
                try:
                    raw = e.read() or b""
                    if raw:
                        txt = raw.decode("utf-8", errors="replace")
                        obj = json.loads(txt) if txt else {}
                        if isinstance(obj, dict):
                            remote_msg = str(obj.get("msg") or obj.get("error") or "").strip()
                        elif txt:
                            remote_msg = txt.strip()
                except Exception:
                    remote_msg = ""
                head = f"HTTP {code}" if code else "HTTP错误"
                if reason:
                    head = head + f": {reason}"
                if remote_msg:
                    head = head + f"\n{remote_msg}"
                extra = ""
                if code == 404:
                    extra = "\n可能原因：远端地址填成了完整接口，导致重复拼接，或远端工具箱版本的路由不同（`/_toolbox_remote_/` 与 `/__toolbox_remote__/`）。"
                elif code == 413:
                    extra = f"\n当前远端单次接收上限约为 {REMOTE_SYNC_MAX_BODY // (1024 * 1024)}MB。"
                return head + (f"\n{url}" if url else "") + extra
            if isinstance(e, urllib.error.URLError):
                r = getattr(e, "reason", None)
                if isinstance(r, OSError):
                    w = getattr(r, "winerror", None)
                    if w in (10060, 10061, 10065):
                        return str(e) + "\n可能原因：内网 IP 无法从外网访问，或端口未放行 / 未做端口映射。"
            if isinstance(e, OSError):
                w = getattr(e, "winerror", None)
                if w in (10060, 10061, 10065):
                    return str(e) + "\n可能原因：内网 IP 无法从外网访问，或端口未放行 / 未做端口映射。"
        except Exception:
            pass
        return str(e or "").strip() or "远端同步失败"


