    def _remote_sync_drop_query_dict(self, q: dict, list_item: object = None) -> None:
        qid0 = self._remote_safe_id(str(q.get("id") or "").strip())
        if not qid0:
            qid0 = self._remote_safe_id(str(uuid.uuid4()))
            q["id"] = qid0
            try:
                if list_item is not None:
                    list_item.setData(QtCore.Qt.UserRole, dict(q))
            except Exception:
                pass

        out_dir = ""
        try:
            out_dir = str(self.output_edit.text() or "").strip()
        except Exception:
            out_dir = ""
        if not out_dir:
            try:
                base_dir = _writable_app_dir()
            except Exception:
                base_dir = os.getcwd()
            out_dir = os.path.join(base_dir, "Website")
        out_dir = os.path.abspath(out_dir)
        data_dir = os.path.join(out_dir, "data")
        try:
            os.makedirs(data_dir, exist_ok=True)
        except Exception:
            pass

        json_fn = f"droprate_{qid0}.json"
        json_path = os.path.join(data_dir, json_fn)
        if not os.path.isfile(json_path):
            q_root = str(q.get("root_dir") or "").strip()
            site_root = ""
            try:
                site_root = str(self.root_edit.text() or "").strip()
            except Exception:
                site_root = ""
            final_root = q_root or site_root
            if not final_root:
                QtWidgets.QMessageBox.information(self, "提示", "该查询未设置服务端目录，无法生成爆率数据。")
                return
            self._append_log(f"同步前生成爆率数据：{str(q.get('name') or '版本')}")
            self.progress.setValue(0)
            ok0 = bool(self._export_droprate_json_standalone(final_root, json_path))
            self.progress.setValue(100)
            if not ok0:
                QtWidgets.QMessageBox.warning(self, "失败", "生成爆率数据失败，已取消同步。")
                return

        try:
            peer_url = str(self.remote_peer_endpoint_edit.text() or "").strip()
        except Exception:
            peer_url = ""
        if not peer_url:
            QtWidgets.QMessageBox.information(self, "提示", "请先填写远端地址。")
            return
        try:
            endpoints = self._remote_endpoints_from_peer_input(peer_url, "drop_query")
        except Exception as e:
            QtWidgets.QMessageBox.information(self, "提示", f"远端地址格式错误：{e}")
            return
        if not endpoints:
            QtWidgets.QMessageBox.information(self, "提示", "远端地址无效。")
            return

        try:
            peer_token = str(self.remote_peer_token_edit.text() or "").strip()
        except Exception:
            peer_token = ""
        if not peer_token:
            QtWidgets.QMessageBox.information(self, "提示", "请填写远端密钥（对方工具箱的本机密钥）。")
            return

        payload: dict[str, object] = {
            "query": {
                "id": str(qid0),
                "enabled": True,
                "show_rate": bool(q.get("show_rate", True)),
                "name": str(q.get("name") or "").strip(),
                "type": str(q.get("type") or "").strip(),
                "intro": str(q.get("intro") or ""),
                "url": str(q.get("url") or "").strip(),
            },
            "files": {},
        }

        try:
            with open(json_path, "rb") as f:
                droprate_b64 = base64.b64encode(f.read() or b"").decode("ascii")
        except Exception:
            droprate_b64 = ""
        if droprate_b64:
            payload["files"] = dict(payload.get("files") or {})
            payload["files"]["droprate"] = {"name": json_fn, "b64": droprate_b64}

        img_path = str(q.get("image") or "").strip()
        if img_path and os.path.isfile(img_path):
            try:
                with open(img_path, "rb") as f:
                    b64 = base64.b64encode(f.read() or b"").decode("ascii")
                payload["files"]["image"] = {"name": os.path.basename(img_path), "b64": b64}
            except Exception:
                pass

        guide_path = str(q.get("guide") or "").strip()
        if guide_path and os.path.isfile(guide_path):
            try:
                with open(guide_path, "rb") as f:
                    b64 = base64.b64encode(f.read() or b"").decode("ascii")
                payload["files"]["guide"] = {"name": os.path.basename(guide_path), "b64": b64}
            except Exception:
                pass

        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        if len(body) > REMOTE_SYNC_MAX_BODY:
            body_mb = len(body) / (1024 * 1024)
            limit_mb = REMOTE_SYNC_MAX_BODY // (1024 * 1024)
            msg = f"当前同步数据约为 {body_mb:.1f}MB，已超过远端接收上限 {limit_mb}MB。请优先检查爆率数据文件、查询图片或攻略附件是否过大。"
            QtWidgets.QMessageBox.warning(self, "失败", msg)
            try:
                self.remote_status.setText(f"同步失败：{msg}")
            except Exception:
                pass
            return
        obj = None
        last_err: Optional[Exception] = None
        for endpoint in endpoints:

            req = urllib.request.Request(endpoint, data=body, method="POST")
            req.add_header("Content-Type", "application/json; charset=utf-8")
            req.add_header("X-Toolbox-Token", peer_token)
            try:
                with urllib.request.urlopen(req, timeout=25) as resp:
                    resp_body = resp.read() or b""
                    txt = resp_body.decode("utf-8", errors="replace")
                    try:
                        obj = json.loads(txt) if txt else {}
                    except Exception:
                        obj = {"raw": txt}
                    last_err = None
                    break
            except urllib.error.HTTPError as e:
                last_err = e
                code = getattr(e, "code", None)
                if code in (404, 405) and endpoint != endpoints[-1]:
                    continue
                break
            except Exception as e:
                last_err = e
                break
        if obj is None:
            msg = self._format_remote_sync_error(last_err or Exception("远端同步失败"))
            QtWidgets.QMessageBox.warning(self, "失败", f"远端同步失败：{msg}")
            try:
                self.remote_status.setText(f"同步失败：{msg}")
            except Exception:
                pass
            return

        ok = bool(isinstance(obj, dict) and obj.get("ok") is True)
        msg = str(obj.get("msg") or "")
        if ok:
            try:
                self.remote_status.setText(f"同步成功：{msg or '已提交到远端'}")
            except Exception:
                pass
            return
        QtWidgets.QMessageBox.warning(self, "失败", f"远端返回失败：{msg or obj}")
        try:
            self.remote_status.setText(f"同步失败：{msg or '远端返回失败'}")
        except Exception:
            pass

