    def _refresh_site_list(self) -> None:
        self.site_list.clear()
        for it in list(self._sites or [])[:1]:
            nm = str((it or {}).get("name") or "").strip()
            sid = str((it or {}).get("id") or "").strip()
            if not nm or not sid:
                continue
            w = QtWidgets.QListWidgetItem()
            self._sync_list_item_text_tooltip(w, nm)
            w.setData(QtCore.Qt.UserRole, sid)
            self.site_list.addItem(w)

    def _get_selected_id(self, row: int | None = None) -> str:
        it = None
        try:
            if row is not None and int(row) >= 0:
                it = self.site_list.item(int(row))
            else:
                it = self.site_list.currentItem()
        except Exception:
            it = self.site_list.currentItem()
        if not it:
            return ""
        try:
            return str(it.data(QtCore.Qt.UserRole) or "").strip()
        except Exception:
            return ""

    def _prompt_save_if_dirty(self) -> bool:
        if not self._dirty:
            return True
        mb = QtWidgets.QMessageBox(self)
        mb.setWindowTitle("未保存")
        mb.setText("当前站点内容尚未保存，是否保存？")
        btn_save = mb.addButton("保存", QtWidgets.QMessageBox.AcceptRole)
        btn_discard = mb.addButton("不保存", QtWidgets.QMessageBox.DestructiveRole)
        btn_cancel = mb.addButton("取消", QtWidgets.QMessageBox.RejectRole)
        mb.setDefaultButton(btn_save)
        _qt_dialog_exec(mb)
        clicked = mb.clickedButton()
        if clicked is btn_cancel:
            return False
        if clicked is btn_save:
            return self._save_current_site()
        _ = btn_discard
        return True

    def _on_site_changed(self, _row: int) -> None:
        sid = self._get_selected_id(_row)
        if sid == self._current_id:
            return
        if not self._prompt_save_if_dirty():
            self._reselect_current()
            return
        self._current_id = sid
        self._dirty = False
        self._apply_site_to_form(self._find_site_by_id(sid))
        try:
            self._ensure_preview_server()
        except Exception:
            pass

    def _reselect_current(self) -> None:
        if not self._current_id:
            return
        for i in range(self.site_list.count()):
            it = self.site_list.item(i)
            if not it:
                continue
            if str(it.data(QtCore.Qt.UserRole) or "").strip() == self._current_id:
                blocker = QtCore.QSignalBlocker(self.site_list)
                try:
                    self.site_list.setCurrentRow(i)
                finally:
                    del blocker
                return

    def _find_site_by_id(self, sid: str) -> dict | None:
        sid = str(sid or "").strip()
        if not sid:
            return None
        for it in self._sites:
            if str((it or {}).get("id") or "").strip() == sid:
                return dict(it)
        return None

