        hint.setObjectName("dbWelcomeHint")
        hint.setAlignment(QtCore.Qt.AlignCenter)
        card_l.addWidget(title, 0)
        card_l.addWidget(intro, 0)
        card_l.addWidget(status_pill, 0, QtCore.Qt.AlignHCenter)
        card_l.addWidget(hint, 0)
        l.addWidget(card, 0, QtCore.Qt.AlignHCenter)
        l.addStretch(1)
        self.tabs.addTab(w, "")
