    def _sync_root_from_basic(self) -> None:
        root = ""
        try:
            if callable(self._get_root_dir):
                root = str(self._get_root_dir() or "").strip()
        except Exception:
            root = ""
        if root:
            self.root_edit.setText(root)

    def _browse_root(self) -> None:
        d = _qt_get_existing_dir(self, "选择服务端根目录", self.root_edit.text().strip() or os.getcwd())
        if d:
            self.root_edit.setText(d)

    def _schedule_auto_scan(self, _text: str) -> None:
        if self._root_scan_timer.isActive():
            self._root_scan_timer.stop()
        self._root_scan_timer.start()

    def _on_shared_root_changed(self, root: str) -> None:
        root_text = str(root or "").strip()
        if not root_text:
            return
        current_text = str(self.root_edit.text() or "").strip()
        try:
            root_key = os.path.normcase(os.path.abspath(root_text))
            boundary_key = os.path.normcase(os.path.abspath(self._db_boundary)) if self._db_boundary else ""
        except Exception:
            root_key = root_text.casefold()
            boundary_key = str(self._db_boundary or "").strip().casefold()
        if current_text != root_text:
            blocker = QtCore.QSignalBlocker(self.root_edit)
            try:
                self.root_edit.setText(root_text)
            finally:
                del blocker
        if (self._db_connected or self._db_path) and root_key != boundary_key:
            self._root_scan_timer.stop()
            self._close_db()
            self._set_db_path_display("")
            self._set_actions_enabled(False)
            self._show_welcome()
            self._set_db_status_text(
                "项目路径已切换，正在识别数据库",
                f"已断开旧项目数据库，正在新路径中识别：{root_text}",
                "info",
            )
        self._schedule_auto_scan(root_text)

    def _set_db_path_display(self, path: str) -> None:
        path = str(path or "").strip()
        label = os.path.basename(path) if path else "未连接"
        self.db_edit.setText(label)
        self.db_edit.setToolTip(path or "当前数据库")

    def _auto_scan_find_only(self) -> None:
        if self._db_connected or str(self._db_path or "").strip():
            return
        root_dir = self.root_edit.text().strip()
        if not root_dir or not os.path.isdir(root_dir):
            return
        db_path = self._find_db_in_root(root_dir)
        if not db_path:
            self._set_db_status_text("未识别到数据库", "原因：根目录和 Mud2/DB 中没有支持的数据库文件。请选择数据库文件。", "warn")
            return
        self._set_db_path_display(db_path)
        self._set_db_status_text("已识别数据库，点击连接", f"已识别：{db_path}", "success")


    def _auto_scan_connect(self) -> None:
        shared_root = ""
        try:
            if callable(self._get_root_dir):
                shared_root = str(self._get_root_dir() or "").strip()
        except Exception:
            shared_root = ""
        if shared_root and os.path.isdir(shared_root):
            self._on_shared_root_changed(shared_root)
        root_dir = self.root_edit.text().strip()
        if not root_dir or not os.path.isdir(root_dir):
            self._set_db_status_text("根目录无效", "请重新选择包含 Mud2/DB 的服务端根目录。", "warn")
            return
        db_path = self._find_db_in_root(root_dir)
        if not db_path:
            self._set_db_status_text("未识别到数据库", "原因：根目录和 Mud2/DB 中没有支持的数据库文件。请选择数据库文件。", "warn")
            return
        self._connect_db(db_path)

    def _pick_db_file(self) -> None:
        start_dir = self.root_edit.text().strip() or os.getcwd()
        p, _ = _qt_get_open_file_name(self, "选择数据库文件", start_dir, "SQLite DB (*.db *.sqlite *.sqlite3);;所有文件 (*.*)")
        if p:
            self._connect_db(p)

    def _close_db(self, *args) -> None:
        self._db_generation += 1
        self._stop_db_worker(wait_ms=1800)
        self._conn = None
        self._cursor = None
        self._db_connected = False
        self._db_state = {}
        self._db_boundary = ""
        self._db_path = ""
        self._db_schema = {}
        self._db_schema_generation = ""
        self._db_write_pending = {}
        self._table_col_types = {}
        self._tab_contexts = {}

    def _connect_db(self, path: str) -> None:
        try:
            self._close_db()
            selected = os.path.abspath(str(path or "").strip())
            root_text = os.path.abspath(str(self.root_edit.text() or "").strip()) if str(self.root_edit.text() or "").strip() else ""
            boundary = root_text if root_text and os.path.isdir(root_text) else os.path.dirname(selected)
            preview_state = _db_read_path_state(selected, boundary, with_sha=False)
            self._db_path = selected
            self._db_boundary = boundary
            self._set_db_path_display(selected)
            self._set_db_status_text("正在验证数据库：控件已锁定", "正在验证路径、文件身份和表结构；完成后自动恢复控件。", "working")
            self._set_actions_enabled(False)
            self._start_db_worker({
                "kind": "schema",
                "path": preview_state["path"],
                "boundary": boundary,
            })
        except Exception as e:
            self._close_db()
            self._set_db_path_display("")
            self._set_actions_enabled(False)
            self._show_welcome()
            QtWidgets.QMessageBox.critical(self, "连接失败", str(e))

    def _find_db_in_root(self, root_dir: str) -> str:
        root = os.path.abspath(str(root_dir or "").strip())
        if not root or not os.path.isdir(root) or _db_read_is_reparse(root):
            return ""
        names = ("GEEM2.db", "ApexM2.db", "StdItems.db", "GOM.db")
        db_dir = os.path.join(root, "Mud2", "DB")
        candidates = [os.path.join(db_dir, name) for name in names]
        candidates.extend(os.path.join(root, name) for name in names)
        if os.path.isdir(db_dir) and not _db_read_is_reparse(db_dir):
            try:
                fallback = [
                    os.path.join(db_dir, name)
                    for name in os.listdir(db_dir)
                    if os.path.splitext(str(name))[1].lower() in _DB_READ_EXTENSIONS
                ]
                candidates.extend(sorted(fallback, key=lambda p: (os.path.normcase(os.path.relpath(p, root)), p)))
            except Exception:
                pass
        seen: set[str] = set()
        for candidate in candidates:
            key = os.path.normcase(os.path.abspath(candidate))
            if key in seen:
                continue
            seen.add(key)
            try:
                return str(_db_read_path_state(candidate, root, with_sha=False)["path"])
            except Exception:
                continue
        return ""

    def _stop_db_worker(self, wait_ms: int = 0) -> None:
        thread = self._db_thread
        if thread is None:
            return
        try:
            thread.requestInterruption()
            if wait_ms > 0:
                thread.wait(int(wait_ms))
        except Exception:
            pass
        self._db_thread = None
        self._db_worker = None

    def _start_db_worker(self, task: dict) -> None:
        self._db_generation += 1
        generation = self._db_generation
        self._stop_db_worker(wait_ms=1800)
        thread = QtCore.QThread(self)
        worker = _DbReadWorker(generation, task)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.completed.connect(self._on_db_worker_completed)
        worker.failed.connect(self._on_db_worker_failed)
        worker.cancelled.connect(self._on_db_worker_cancelled)
        worker.completed.connect(thread.quit)
        worker.failed.connect(thread.quit)
        worker.cancelled.connect(thread.quit)
        thread.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        self._db_thread = thread
        self._db_worker = worker
        self._set_actions_enabled(self._db_connected)
        thread.start()

    def _start_db_write_worker(self, task: dict, pending: dict | None = None) -> None:
        if not self._db_connected or not self._db_path or not self._db_state:
            raise RuntimeError("当前没有可写数据库会话")
        self._db_generation += 1
        generation = self._db_generation
        self._stop_db_worker(wait_ms=1800)
        payload = dict(task)
        payload.update({
            "path": self._db_path,
            "boundary": self._db_boundary,
            "expected_state": dict(self._db_state),
            "schema_generation": self._db_schema_generation,
        })
        thread = QtCore.QThread(self)
        worker = _DbWriteWorker(generation, payload)
        worker.moveToThread(thread)
        thread.started.connect(worker.run)
        worker.completed.connect(self._on_db_write_completed)
        worker.failed.connect(self._on_db_write_failed)
        worker.cancelled.connect(self._on_db_write_cancelled)
        worker.progress.connect(self._on_db_write_progress)
        worker.completed.connect(thread.quit)
        worker.failed.connect(thread.quit)
        worker.cancelled.connect(thread.quit)
        thread.finished.connect(worker.deleteLater)
        thread.finished.connect(thread.deleteLater)
        self._db_thread = thread
        self._db_worker = worker
        self._db_write_pending = dict(pending or {})
        self._set_actions_enabled(False)
        for ctx in self._tab_contexts.values():
            self._set_db_ctx_actions_enabled(ctx, False)
        thread.start()

    @QtCore.Slot(int, str)
    def _on_db_write_progress(self, generation: int, message: str) -> None:
        if int(generation) == self._db_generation:
            self._set_db_status_text("数据库任务执行中：控件已锁定", "正在执行写入并校验完整性；完成后自动恢复控件。", "working")

    def _restore_pending_db_ui(self) -> None:
        pending = dict(self._db_write_pending or {})
        self._db_write_pending = {}
        table = pending.get("table")
        if not isinstance(table, QtWidgets.QTableWidget):
            return
        row = int(pending.get("row", -1))
        column = int(pending.get("column", -1))
        item = table.item(row, column) if row >= 0 and column >= 0 else None
        if item is None:
            return
        table.blockSignals(True)
        self._loading_table = True
        try:
            item.setText(str(pending.get("old_display", "")))
            self._sync_db_table_item_tooltip(item)
        finally:
            self._loading_table = False
            table.blockSignals(False)

    @QtCore.Slot(int, object)
    def _on_db_write_completed(self, generation: int, payload: object) -> None:
        if int(generation) != self._db_generation or not isinstance(payload, dict):
            return
        self._db_thread = None
        self._db_worker = None
        self._db_write_pending = {}
        kind = str(payload.get("kind") or "")
        if kind in ("export", "backup"):
            done = "导出完成" if kind == "export" else "数据库备份完成"
            self._set_db_status_text(done, done + "，数据库原文件保持完整。", "success")
            self._set_actions_enabled(True)
            self._ensure_current_tab_loaded(force=False)
            return
        state = dict(payload.get("state") or {})
        if state:
            self._db_state = state
        self._db_schema_generation = str(payload.get("schema_generation") or self._db_schema_generation)
        self._set_db_status_text("数据库操作完成", "操作已提交并将重新读取表结构。", "success")
        self._start_db_worker({"kind": "schema", "path": self._db_path, "boundary": self._db_boundary})

    @QtCore.Slot(int, str)
    def _on_db_write_failed(self, generation: int, message: str) -> None:
        if int(generation) != self._db_generation:
            return
        self._db_thread = None
        self._db_worker = None
        self._restore_pending_db_ui()
        self._set_actions_enabled(True)
        self._ensure_current_tab_loaded(force=False)
        user_message = self._db_user_error_text(message, rollback=True)
        self._set_db_status_text("数据库操作失败：已回滚", user_message, "error")
        QtWidgets.QMessageBox.critical(self, "数据库操作失败", user_message)

    @QtCore.Slot(int)
    def _on_db_write_cancelled(self, generation: int) -> None:
        if int(generation) != self._db_generation:
            return
        self._db_thread = None
        self._db_worker = None
        self._restore_pending_db_ui()
        self._set_actions_enabled(True)
        self._ensure_current_tab_loaded(force=False)
        self._set_db_status_text("数据库任务已取消：未保留更改", "任务已取消并恢复操作前状态，可重新执行。", "warn")

    @QtCore.Slot(int, object)
    def _on_db_worker_completed(self, generation: int, payload: object) -> None:
        if int(generation) != self._db_generation or not isinstance(payload, dict):
            return
        completed_thread = self._db_thread
        self._db_thread = None
        self._db_worker = None
        state = dict(payload.get("state") or {})
        if state:
            self._db_state = state
        if payload.get("kind") == "schema":
            self._db_connected = True
            self._db_schema_generation = str(payload.get("schema_generation") or "")
            self._db_schema = {str(row.get("name") or ""): dict(row) for row in payload.get("tables", [])}
            self._table_col_types = {}
            self._set_db_status_text("数据库连接成功", f"已只读验证并连接：{self._db_path}", "success")
            self._set_actions_enabled(True)
            self._load_tables_to_tabs(list(payload.get("tables") or []))
        elif payload.get("kind") == "page":
            self._apply_db_page_result(payload)
            self._set_actions_enabled(self._db_connected)
        if self._db_smoke_state and isinstance(completed_thread, QtCore.QThread):
            try:
                completed_thread.quit()
                completed_thread.wait(1500)
            except Exception:
                pass

    @QtCore.Slot(int, str)
    def _on_db_worker_failed(self, generation: int, message: str) -> None:
        if int(generation) != self._db_generation:
            return
        self._db_thread = None
        self._db_worker = None
        user_message = self._db_user_error_text(message, rollback=False)
        self._set_db_status_text("数据库读取失败", user_message, "error")
        if not self._db_connected:
            self._db_path = ""
            self._db_state = {}
            self._set_db_path_display("")
            self._set_actions_enabled(False)
            self._show_welcome()
        else:
            self._set_actions_enabled(True)

    @QtCore.Slot(int)
    def _on_db_worker_cancelled(self, generation: int) -> None:
        if int(generation) != self._db_generation:
            return
        self._db_thread = None
        self._db_worker = None
        self._set_db_status_text("数据库读取已取消", "未修改数据库，可重新连接或刷新。", "warn")
        self._set_actions_enabled(self._db_connected)

    def _quote_ident(self, name: str) -> str:
        s = str(name or "")
        return '"' + s.replace('"', '""') + '"'

    def _get_column_text(self, col: str) -> str:
        if not self._show_chinese:
            return str(col)
        key = str(col)
        mapping = self._column_mapping()
        if key in mapping:
            return str(mapping.get(key, key))
        low = key.lower()
        if low in mapping:
            return str(mapping.get(low, key))
        norm = low.replace("_", "").replace("-", "")
        if norm in mapping:
            return str(mapping.get(norm, key))
        m = re.match(r"^(?:l|lv|level)(\d+)$", norm)
        if m:
            n = int(m.group(1))
            if n > 0:
                return f"{n}级等级"
        m = re.match(r"^(\d+)(?:l|lv|level)$", norm)
        if m:
            n = int(m.group(1))
            if n > 0:
                return f"{n}级等级"
        m = re.match(r"^(?:train|practice|proficiency|needexp|skillexp|exp)(\d+)$", norm)
        if m:
            n = int(m.group(1))
            if n > 0:
                return f"{n}级熟练度"
        m = re.match(r"^(\d+)(?:train|practice|proficiency|needexp|skillexp|exp)$", norm)
        if m:
            n = int(m.group(1))
            if n > 0:
                return f"{n}级熟练度"
        m = re.match(r"^needl(\d+)$", norm)
        if m:
            n = int(m.group(1))
            if n > 0:
                return f"{n}级等级"
        m = re.match(r"^l(\d+)train$", norm)
        if m:
            n = int(m.group(1))
            if n > 0:
                return f"{n}级熟练度"
        if low.endswith("name"):
            return "名称"
        if low.endswith("id") and low != "grid":
            return "ID"
        if low in ("idx", "index", "no", "sn", "serial"):
            return "序号"
        if low in ("lv", "lvl") or low.endswith("level") or "level" in low:
            return "等级"
        if low in ("hp", "hpmax", "maxhp"):
            return "生命值"
        if low in ("mp", "mpmax", "maxmp"):
            return "魔法值"
        if low in ("exp", "experience"):
            return "经验值"
        if low in ("gold", "money", "coin"):
            return "金币"
        if ("damage" in low or "dmg" in low) and ("min" in low or "low" in low):
            return "伤害下限"
        if ("damage" in low or "dmg" in low) and ("max" in low or "high" in low or "up" in low):
            return "伤害上限"
        if ("action" in low or "act" in low) and ("effect" in low or "eff" in low):
            return "动作效果"
        if ("magic" in low or "spell" in low or "skill" in low) and ("effect" in low or "eff" in low):
            return "技能效果"
        if low.endswith("speed"):
            return "速度"
        if low.endswith("spd"):
            return "速度"
        if low.endswith("range"):
            return "范围"
        if low in ("desc", "description"):
            return "描述"
        if low in ("memo", "note", "remark"):
            return "备注"
        return key

