    def _load_tables_to_tabs(self, table_rows: list[dict] | None = None) -> None:
        self.tabs.clear()
        self._tab_contexts = {}
        self.tabs.tabBar().show()

        try:
            rows = list(table_rows or self._db_schema.values())
            tables = [str(row.get("name") or "") for row in rows if str(row.get("name") or "")]
            metadata = {str(row.get("name") or ""): row for row in rows}

            def get_cols(table_name: str) -> set:
                return {
                    str(item.get("name") or "").lower()
                    for item in metadata.get(table_name, {}).get("columns", [])
                    if int(item.get("hidden") or 0) != 1
                }

            def score_table(table_name: str, kind: str) -> int:
                name_low = (table_name or "").lower()
                cols = get_cols(table_name)
                if not cols:
                    return -10
                bad_words = ["old", "bak", "backup", "copy", "tmp", "temp", "history", "record", "log", "test"]
                penalty = 0
                for w in bad_words:
                    if w in name_low:
                        penalty += 50
                score = 0
                if kind == "items":
                    if name_low == "stditems":
                        score += 300
                    elif name_low == "std_items":
                        score += 280
                    elif name_low.startswith("stditems"):
                        score += 240
                    elif "stditems" in name_low:
                        score += 180
                    elif name_low == "items":
                        score += 60
                    if "name" in cols or "itemname" in cols:
                        score += 40
                    if "idx" in cols or "id" in cols or "itemid" in cols:
                        score += 30
                    if "stdmode" in cols or "std_mode" in cols:
                        score += 20
                elif kind == "monster":
                    if name_low == "monster":
                        score += 300
                    elif name_low.startswith("monster"):
                        score += 240
                    elif "monster" in name_low:
                        score += 180
                    if "name" in cols or "monname" in cols or "monstername" in cols:
                        score += 40
                    if "idx" in cols or "id" in cols:
                        score += 20
                elif kind == "magic":
                    if name_low == "magic":
                        score += 300
                    elif name_low.startswith("magic"):
                        score += 240
                    elif "magic" in name_low:
                        score += 180
                    if "name" in cols or "magicname" in cols or "spellname" in cols:
                        score += 40
                    if "idx" in cols or "id" in cols:
                        score += 20
                return score - penalty

            def pick_best(kind: str) -> str | None:
                best_name = None
                best_score = -10**9
                for t in tables:
                    if (t or "").lower().startswith("sqlite_"):
                        continue
                    s = score_table(t, kind)
                    if s > best_score:
                        best_score = s
                        best_name = t
                if best_score < 200:
                    return None
                return best_name

            items_table = pick_best("items")
            monster_table = pick_best("monster")
            magic_table = pick_best("magic")

            selected: set[str] = set()
            if items_table:
                self._create_table_tab(items_table, "物品数据")
                selected.add(items_table)
            if monster_table:
                self._create_table_tab(monster_table, "怪物数据")
                selected.add(monster_table)
            if magic_table:
                self._create_table_tab(magic_table, "技能数据")
                selected.add(magic_table)

            if not selected:
                fallback_table = None
                for t in tables:
                    if (t or "").lower().startswith("sqlite_"):
                        continue
                    cols = get_cols(t)
                    if cols:
                        fallback_table = t
                        break
                if fallback_table:
                    self._create_table_tab(fallback_table, str(fallback_table))

            if self.tabs.count() > 0:
                self.tabs.setCurrentIndex(0)
                self._ensure_current_tab_loaded(force=True)
            else:
                w = QtWidgets.QWidget()
                w.setObjectName("dbEmptyTablesTab")
                l = QtWidgets.QVBoxLayout(w)
                l.setContentsMargins(0, 0, 0, 0)
                l.setSpacing(UiMetrics.DB_TAB_SPACING)
                t = QtWidgets.QLabel("未找到可用的数据表，请确认连接的是正确数据库。")
                t.setWordWrap(True)
                l.addWidget(t)
                l.addStretch(1)
                self.tabs.addTab(w, "未找到")
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "错误", f"读取表列表失败：{e}")
            self._show_welcome()

