    def _refresh_var_browser_summary(self) -> None:
        badge = getattr(self, "var_browser_badge", None)
        if not isinstance(badge, QtWidgets.QLabel):
            return
        v_type = str(self._selected_type or "").strip() or "A"
        used_map = (self._usage_data or {}).get(v_type, {}) or {}
        count = 0
        try:
            count = len(used_map)
        except Exception:
            count = 0
        badge.setText(f"{v_type} · 已占用 {count}")

    def _refresh_var_detail_summary(self, text: str = "", role: str = "muted") -> None:
        badge = getattr(self, "var_detail_badge", None)
        if not isinstance(badge, QtWidgets.QLabel):
            return
        badge.setText(str(text or ""))
        badge.setVisible(bool(str(text or "").strip()))
        badge.setProperty("badgeRole", str(role or "").strip() or "muted")
        try:
            badge.style().unpolish(badge)
            badge.style().polish(badge)
            badge.update()
        except Exception:
            pass

