        self.var_type_tree.setObjectName("varTypeTree")
        self.var_type_tree.setAccessibleName("变量类型分组")
        self.var_type_tree.setColumnCount(1)
        self.var_type_tree.setHeaderHidden(True)
        self.var_type_tree.setRootIsDecorated(True)
        self.var_type_tree.setIndentation(14)
        self.var_type_tree.setUniformRowHeights(True)
        self.var_type_tree.setSelectionMode(QtWidgets.QAbstractItemView.SingleSelection)
        self.var_type_tree.setHorizontalScrollBarPolicy(QtCore.Qt.ScrollBarAlwaysOff)
        self.var_type_tree.setMinimumHeight(UiMetrics.VAR_QUERY_TYPE_TREE_MIN_H)
        self.var_type_tree.setFocusPolicy(QtCore.Qt.StrongFocus)
        self._type_buttons: dict[str, QtWidgets.QTreeWidgetItem] = {}
        categories = (
            ("常规数值", ("A", "G", "I", "J", "M", "N", "S", "P", "U", "T", "Z")),
            ("计时与标识", ("定时器", "个人标识")),
            ("输入与交互", ("输入字符串", "输入整数", "OK框", "自定义按钮")),
            ("触发与主体", ("物品触发", "HUMAN", "魔法触发")),
            ("命名变量", ("N$", "S$")),
        )
        display_labels = {"OK框": "OK 框"}
        leaf_flags = QtCore.Qt.ItemIsEnabled | QtCore.Qt.ItemIsSelectable
        root_flags = QtCore.Qt.ItemIsEnabled
        for category, keys in categories:
            root_item = QtWidgets.QTreeWidgetItem([category])
            root_item.setFlags(root_flags)
            root_item.setData(0, QtCore.Qt.UserRole + 1, "category")
            self.var_type_tree.addTopLevelItem(root_item)
            for key in keys:
                leaf = QtWidgets.QTreeWidgetItem([display_labels.get(key, key)])
                leaf.setFlags(leaf_flags)
                leaf.setData(0, QtCore.Qt.UserRole, key)
                leaf.setToolTip(0, str(key))
                root_item.addChild(leaf)
                self._type_buttons[key] = leaf
            root_item.setExpanded(True)
        self.var_type_tree.currentItemChanged.connect(self._on_var_type_tree_current_changed)
        type_l.addWidget(self.var_type_tree, 1)
        return type_box

