    # Member file handling stays local and transactional so legacy GBK files do not
    # get rewritten merely by opening the page.
    @staticmethod
    def _member_decode(raw: bytes) -> tuple[str, str, bytes, str, bool]:
        bom = b""
        payload = raw
        encoding = "gb18030"
        if raw.startswith(b"\xef\xbb\xbf"):
            bom, payload, encoding = raw[:3], raw[3:], "utf-8"
        elif raw.startswith(b"\xff\xfe"):
            bom, payload, encoding = raw[:2], raw[2:], "utf-16-le"
        elif raw.startswith(b"\xfe\xff"):
            bom, payload, encoding = raw[:2], raw[2:], "utf-16-be"
        else:
            try:
                payload.decode("utf-8", "strict")
                encoding = "utf-8"
            except UnicodeDecodeError:
                encoding = "gb18030"
        text = payload.decode(encoding, "strict")
        crlf, cr, lf = text.count("\r\n"), text.count("\r") - text.count("\r\n"), text.count("\n") - text.count("\r\n")
        ending = "\r\n" if crlf >= max(cr, lf) and crlf else ("\r" if cr > lf else "\n")
        return text, encoding, bom, ending, text.endswith(("\r\n", "\n", "\r"))

    def _member_read_doc(self, path: str) -> dict:
        raw = b""
        if os.path.isfile(path):
            with open(path, "rb") as stream:
                raw = stream.read()
        text, encoding, bom, ending, trailing = self._member_decode(raw)
        return {"path": path, "raw": raw, "text": text, "lines": text.splitlines(), "encoding": encoding, "bom": bom, "ending": ending, "trailing": trailing}

    @staticmethod
    def _member_encode(doc: dict, lines: list[str]) -> bytes:
        text = str(doc.get("ending") or "\r\n").join(str(x).rstrip("\r\n") for x in lines)
        if bool(doc.get("trailing")) and lines:
            text += str(doc.get("ending") or "\r\n")
        return bytes(doc.get("bom") or b"") + text.encode(str(doc.get("encoding") or "utf-8"), "strict")

    @staticmethod
    def _member_valid_stem(value: str) -> str:
        stem = str(value or "").strip()
        if not stem or stem in (".", "..") or any(ch in stem for ch in '<>:"/\\|?*'):
            raise ValueError("会员等级包含非法路径字符")
        return stem.rstrip(" .") or "默认"

    def _member_validate_path(self, path: str, allow_missing: bool = True) -> str:
        base = os.path.abspath(str(self.data_dir or ""))
        target = os.path.abspath(str(path or ""))
        if not base or os.path.commonpath([base, target]).lower() != base.lower():
            raise ValueError("会员文件路径越界")
        real_base = os.path.realpath(base)
        real_target = os.path.realpath(target)
        if os.path.commonpath([real_base, real_target]).lower() != real_base.lower():
            raise ValueError("会员文件路径经过越界链接")
        current = base
        while True:
            if os.path.lexists(current):
                stat_result = os.lstat(current)
                attributes = int(getattr(stat_result, "st_file_attributes", 0) or 0)
                if os.path.islink(current) or bool(attributes & int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))):
                    raise ValueError("会员数据路径不能包含重解析点")
            if os.path.normcase(current) == os.path.normcase(target):
                break
            relative = os.path.relpath(target, current).split(os.sep, 1)[0]
            current = os.path.join(current, relative)
        if os.path.exists(target) and not os.path.isfile(target):
            raise ValueError("会员目标不是普通文件")
        if not allow_missing and not os.path.isfile(target):
            raise ValueError("会员文件不存在")
        return target

    def _member_commit(self, changes: dict[str, bytes], expected: dict[str, str] | None = None) -> None:
        expected = dict(expected or {})
        snapshots: dict[str, bytes] = {}
        existed: dict[str, bool] = {}
        stages: dict[str, str] = {}
        applied: list[str] = []
        tx = uuid.uuid4().hex
        try:
            for raw_path in changes:
                path = self._member_validate_path(raw_path)
                existed[path] = os.path.exists(path)
                if os.path.exists(path):
                    with open(path, "rb") as stream:
                        snapshots[path] = stream.read()
                else:
                    snapshots[path] = b""
                if path in expected and hashlib.sha256(snapshots[path]).hexdigest() != expected[path]:
                    raise RuntimeError("会员文件已被外部修改")
            for raw_path, payload in changes.items():
                path = self._member_validate_path(raw_path)
                stage = os.path.join(os.path.dirname(path), ".xiami-member-%s-%s.tmp" % (tx, os.path.basename(path)))
                with open(stage, "xb") as stream:
                    stream.write(payload); stream.flush(); os.fsync(stream.fileno())
                stages[path] = stage
            for path in list(changes):
                path = self._member_validate_path(path)
                current_raw = b""
                if os.path.exists(path):
                    with open(path, "rb") as stream:
                        current_raw = stream.read()
                if current_raw != snapshots[path] or os.path.exists(path) != existed[path]:
                    raise RuntimeError("会员文件在替换窗口被外部修改")
                os.replace(stages[path], path); applied.append(path)
            for path, payload in changes.items():
                with open(path, "rb") as stream:
                    if stream.read() != payload:
                        raise RuntimeError("会员文件提交校验失败")
        except Exception:
            for path in reversed(applied):
                try:
                    if not existed.get(path):
                        if os.path.exists(path):
                            os.remove(path)
                    else:
                        with open(path, "wb") as stream:
                            stream.write(snapshots[path]); stream.flush(); os.fsync(stream.fileno())
                except Exception:
                    pass
            raise
        finally:
            for stage in stages.values():
                try:
                    if os.path.exists(stage): os.remove(stage)
                except Exception:
                    pass

    def _ensure_data_dir(self) -> tuple[bool, str]:
        try:
            self.data_dir = str(self.data_dir or "").strip().strip('"').strip("'").replace("/", "\\")
            if not self.data_dir:
                return False, "数据目录为空，请先选择目录。"
            if not os.path.isdir(self.data_dir):
                return False, f"数据目录不是文件夹：{self.data_dir}"
            self.expired_file = os.path.join(self.data_dir, "到期账号.ini")
            return True, ""
        except PermissionError:
            return False, f"无权限访问：{self.data_dir}，请以管理员身份运行。"
        except Exception as e:
            return False, f"初始化失败：{str(e)}"

    def _set_data_dir(self, path: str, persist: bool) -> None:
        p = str(path or "").strip().strip('"').strip("'").replace("/", "\\")
        if not p:
            return
        p = os.path.abspath(p)
        self.data_dir = p
        self.expired_file = os.path.join(self.data_dir, "到期账号.ini")
        self.data_dir_edit.setText(self.data_dir)
        if persist:
            sess = None
            try:
                sess = self._get_session()
            except Exception:
                sess = None
            if isinstance(sess, dict):
                try:
                    sess["member_data_dir"] = self.data_dir
                except Exception:
                    pass
            try:
                _save_login_extras({"member_data_dir": self.data_dir})
            except Exception:
                pass
        self._init_data_dir_ui()

    def _choose_data_dir(self) -> None:
        start_dir = self.data_dir if os.path.isdir(self.data_dir) else os.getcwd()
        chosen = _qt_get_existing_dir(self, "选择会员系统数据目录", start_dir)
        if not chosen:
            return
        self._set_data_dir(chosen, persist=True)
        self._reload_data()

    def _open_data_dir(self) -> None:
        if os.path.exists(self.data_dir):
            QtGui.QDesktopServices.openUrl(QtCore.QUrl.fromLocalFile(self.data_dir))

    def _reload_data(self) -> None:
        ok, msg = self._ensure_data_dir()
        if not ok:
            self._set_error(msg)
            return
        self._set_error("")

        self.table.setRowCount(0)
        try:
            for file_name in os.listdir(self.data_dir):
                if not (file_name.startswith(self.active_file_prefix) and file_name.lower().endswith(".ini")):
                    continue
                level = file_name[len(self.active_file_prefix) : -4]
                file_path = os.path.join(self.data_dir, file_name)
                try:
                    doc = self._member_read_doc(file_path)
                    self._member_docs[level] = doc
                    lines = doc["lines"]
                except Exception:
                    continue
                for line in lines[1:] if lines and str(lines[0]).strip().startswith("[") else lines:
                    s = str(line or "").strip()
                    if not s or "=" not in s:
                        continue
                    account, expire_raw = s.split("=", 1)
                    account = str(account or "").strip()
                    expire_raw = str(expire_raw or "").strip()
                    if not account or not expire_raw:
                        continue
                    expire_date_str = expire_raw
                    remark = ""
                    if ";" in expire_raw:
                        expire_date_str, remark = expire_raw.split(";", 1)
                        expire_date_str = str(expire_date_str or "").strip()
                        remark = str(remark or "").strip()
                    elif "|" in expire_raw:
                        expire_date_str, remark = expire_raw.split("|", 1)
                        expire_date_str = str(expire_date_str or "").strip()
                        remark = str(remark or "").strip()
                    try:
                        datetime.strptime(expire_date_str, "%Y-%m-%d")
                    except Exception:
                        continue
                    self._append_row(level, account, expire_date_str, remark)
        except Exception:
            pass

        self._update_remainders_only()
        self._sort_member_list()

    def _make_member_table_item(self, value: object) -> QtWidgets.QTableWidgetItem:
        text = str(value or "")
        item = QtWidgets.QTableWidgetItem(text)
        item.setToolTip(text.strip())
        return item

    def _append_row(self, level: str, account: str, expire_date_str: str, remark: str = "") -> None:
        r = self.table.rowCount()
        self.table.insertRow(r)
        for c, val in enumerate((level, account, expire_date_str, "", remark)):
            item = self._make_member_table_item(val)
            item.setTextAlignment(
                (QtCore.Qt.AlignRight if c == 3 else QtCore.Qt.AlignLeft) | QtCore.Qt.AlignVCenter
            )
            item.setFlags(QtCore.Qt.ItemIsSelectable | QtCore.Qt.ItemIsEnabled)
            self.table.setItem(r, c, item)

    def _get_row_values(self, r: int) -> tuple[str, str, str, str, str]:
        def _cell(c: int) -> str:
            it = self.table.item(r, c)
            return str(it.text() if it else "")

        return _cell(0), _cell(1), _cell(2), _cell(3), _cell(4)

    def _refresh_member_summary(self) -> None:
        table = getattr(self, "table", None)
        if not isinstance(table, QtWidgets.QTableWidget):
            return

        total = table.rowCount()
        expired = 0
        for r in range(total):
            expire_item = table.item(r, 2)
            expire_text = str(expire_item.text() if expire_item else "").strip()
            if self._calc_actual_remainder(expire_text) <= 0:
                expired += 1

        rows = {i.row() for i in table.selectedIndexes()}
        selected_text = "未选中"
        if rows:
            row = sorted(rows)[0]
            level_item = table.item(row, 0)
            account_item = table.item(row, 1)
            level = str(level_item.text() if level_item else "").strip()
            account = str(account_item.text() if account_item else "").strip()
            if account:
                selected_text = account
                if level:
                    selected_text = f"{account}（{level}）"

        widgets = (
            ("member_total_label", f"账号 {total}"),
            ("member_expired_label", f"到期 {expired}"),
            ("member_selected_label", selected_text),
        )
        for attr, text in widgets:
            label = getattr(self, attr, None)
            if isinstance(label, QtWidgets.QLabel):
                display_text = text
                if attr == "member_selected_label":
                    base_text = display_text.split("（", 1)[0]
                    display_text = base_text[:14] + ("..." if len(base_text) > 14 else "")
                label.setText(display_text)
                label.setToolTip(text)

    def _calc_actual_remainder(self, expire_date_str: str) -> int:
        try:
            current_date = datetime.now().date()
            expire_date = datetime.strptime(str(expire_date_str), "%Y-%m-%d").date()
            return (expire_date - current_date).days
        except Exception:
            return 0

    def _calc_display_remainder(self, expire_date_str: str) -> str:
        days = self._calc_actual_remainder(expire_date_str)
        return f"{days}天" if days > 0 else "已到期"

    def _member_row_foreground(self, is_expired: bool) -> QtGui.QColor:
        return _ui_theme_token_color(self.table, "danger_text" if is_expired else "text", QtGui.QPalette.Text)

    def _update_remainders_only(self) -> None:
        for r in range(self.table.rowCount()):
            level, account, expire_date_str, _, _remark = self._get_row_values(r)
            display = self._calc_display_remainder(expire_date_str)
            it = self.table.item(r, 3)
            if it:
                it.setText(display)
                it.setToolTip(display.strip())
            is_expired = display == "已到期"
            color = self._member_row_foreground(is_expired)
            for c in range(5):
                cell = self.table.item(r, c)
                if cell:
                    cell.setForeground(color)
        self._refresh_member_summary()

    def _sort_member_list(self) -> None:
        selected_account = ""
        selected_rows = {i.row() for i in self.table.selectedIndexes()}
        if selected_rows:
            r0 = sorted(selected_rows)[0]
            selected_account = (self.table.item(r0, 1).text() if self.table.item(r0, 1) else "").strip()

        items: list[tuple[int, int, tuple[str, str, str, str, str]]] = []
        for r in range(self.table.rowCount()):
            level, account, expire_date_str, display, remark = self._get_row_values(r)
            remain = self._calc_actual_remainder(expire_date_str)
            key1 = 0 if remain <= 0 else 1
            key2 = remain if remain > 0 else 9999
            items.append((key1, key2, (level, account, expire_date_str, display, remark)))
        items.sort(key=lambda x: (x[0], x[1]))

        self.table.setRowCount(0)
        for _k1, _k2, vals in items:
            self._append_row(vals[0], vals[1], vals[2], vals[4])
        self._update_remainders_only()

        if selected_account:
            for r in range(self.table.rowCount()):
                acct = (self.table.item(r, 1).text() if self.table.item(r, 1) else "").strip()
                if acct == selected_account:
                    self.table.selectRow(r)
                    break

    def _check_midnight_sort(self) -> None:
        if self.is_processing_action:
            return
        current_date = datetime.now().date()
        if current_date != self.last_midnight_sort:
            self._sort_member_list()
            self.last_midnight_sort = current_date

    def _tick(self) -> None:
        self.time_label.setText(datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
        self._check_midnight_sort()
        if self.is_running:
            self._update_remainder_and_check_expire()

    def _update_remainder_and_check_expire(self) -> None:
        if self.is_processing_action:
            return
        expired_map: dict[str, list[str]] = {}
        for r in range(self.table.rowCount()):
            level, account, expire_date_str, _, _remark = self._get_row_values(r)
            display = self._calc_display_remainder(expire_date_str)
            it = self.table.item(r, 3)
            if it:
                it.setText(display)
                it.setToolTip(display.strip())
            is_expired = display == "已到期"
            color = self._member_row_foreground(is_expired)
            for c in range(5):
                cell = self.table.item(r, c)
                if cell:
                    cell.setForeground(color)
            if self._calc_actual_remainder(expire_date_str) <= 0:
                expired_map.setdefault(str(level), [])
                if str(account) not in expired_map[str(level)]:
                    expired_map[str(level)].append(str(account))
        for level, accounts in expired_map.items():
            if accounts:
                self._save_expired_data(accounts, level)
        self._sort_member_list()

    def _is_account_expired_recorded(self, account: str, level: str = "") -> bool:
        if not os.path.exists(self.expired_file):
            return False
        try:
            doc = self._member_read_doc(self._member_validate_path(self.expired_file))
            for line in doc.get("lines", []):
                    s = str(line or "").strip()
                    if not s or "=" not in s:
                        continue
                    logged_account = s.split("=", 1)[0].strip()
                    logged_level = s.split(",等级=", 1)[1].strip() if ",等级=" in s else ""
                    if str(logged_account) == str(account) and (not level or logged_level == str(level)):
                        return True
            return False
        except Exception:
            return False

    def _save_active_data(self, level: str, exclude_expired: bool = True) -> bool:
        try:
            self._member_save_level_files(level, exclude_expired=exclude_expired)
            return True
        except Exception:
            return False

    def _member_save_level_files(self, level: str, exclude_expired: bool = True, expired_payload: bytes | None = None) -> None:
        level = self._member_valid_stem(level)
        file_path = self._member_validate_path(os.path.join(self.data_dir, f"{self.active_file_prefix}{level}.ini"))
        txt_path = self._member_validate_path(os.path.join(self.data_dir, f"{self.account_txt_prefix}{level}.TXT"))
        doc = self._member_docs.get(level) or self._member_read_doc(file_path)
        txt_doc = self._member_read_doc(txt_path)
        level_data: list[str] = []
        for r in range(self.table.rowCount()):
            lv, account, expire_date_str, _, remark = self._get_row_values(r)
            if str(lv) != str(level) or (exclude_expired and self._calc_actual_remainder(expire_date_str) <= 0):
                continue
            remark = str(remark or "").replace("\r", " ").replace("\n", " ").strip().replace(";", "；").replace("|", "｜")
            level_data.append(f"{account}={expire_date_str}" + (f";{remark}" if remark else ""))
        original_lines = [str(line) for line in doc.get("lines", [])]
        section_index = next((i for i, line in enumerate(original_lines) if str(line).strip() == "[时长记录]"), -1)
        if section_index < 0:
            ini_lines = ["[时长记录]"] + level_data + original_lines
        else:
            section_end = next(
                (i for i in range(section_index + 1, len(original_lines)) if str(original_lines[i]).strip().startswith("[") and str(original_lines[i]).strip().endswith("]")),
                len(original_lines),
            )
            preserved_section = []
            for line in original_lines[section_index + 1 : section_end]:
                s = str(line).strip()
                if "=" in s:
                    _key, _value = s.split("=", 1)
                    if re.match(r"^\d{4}-\d{2}-\d{2}(?:;|\||$)", _value.strip()):
                        continue
                preserved_section.append(str(line))
            ini_lines = original_lines[: section_index + 1] + level_data + preserved_section + original_lines[section_end:]
        txt_lines = [str(self.table.item(r, 1).text()) for r in range(self.table.rowCount()) if self.table.item(r, 0) and self.table.item(r, 0).text() == level and self._calc_actual_remainder(self.table.item(r, 2).text()) > 0]
        txt_unknown = [
            str(line) for line in txt_doc.get("lines", [])
            if str(line).strip() and (
                str(line).lstrip().startswith(("#", ";", "[")) or "=" in str(line)
            )
        ]
        txt_lines.extend(txt_unknown)
        changes = {file_path: self._member_encode(doc, ini_lines), txt_path: self._member_encode(txt_doc, txt_lines)}
        expected = {file_path: hashlib.sha256(bytes(doc.get("raw") or b"")).hexdigest(), txt_path: hashlib.sha256(bytes(txt_doc.get("raw") or b"")).hexdigest()}
        if expired_payload is not None:
            expired_path = self._member_validate_path(self.expired_file)
            expired_doc = self._member_read_doc(expired_path)
            changes[expired_path] = bytes(expired_payload)
            expected[expired_path] = hashlib.sha256(bytes(expired_doc.get("raw") or b"")).hexdigest()
        self._member_commit(changes, expected)
        self._member_docs[level] = dict(doc, raw=changes[file_path], lines=ini_lines)

    def _find_row_by_account(self, account: str, level: str = "") -> int:
        acct = str(account or "").strip()
        if not acct:
            return -1
        for r in range(self.table.rowCount()):
            v = (self.table.item(r, 1).text() if self.table.item(r, 1) else "").strip()
            lv = (self.table.item(r, 0).text() if self.table.item(r, 0) else "").strip()
            if v == acct and (not level or lv == str(level)):
                return r
        return -1

