    def _on_cell_double_clicked(self, row: int, column: int) -> None:
        if int(column) != 4:
            return
        if row is None or int(row) < 0:
            return
        try:
            level, account, _expire_date_str, _display, remark = self._get_row_values(int(row))
        except Exception:
            return
        self.is_processing_action = True
        try:
            try:
                if hasattr(self, "_timer") and self._timer and self._timer.isActive():
                    self._timer.stop()
            except Exception:
                pass
            text, ok = self._edit_remark_dialog(account, str(remark or ""))
        finally:
            try:
                if hasattr(self, "_timer") and self._timer and (not self._timer.isActive()):
                    self._timer.start()
            except Exception:
                pass
            self.is_processing_action = False
        if not ok:
            return
        new_remark = str(text or "").strip()
        target_row = self._find_row_by_account(account, level)
        if target_row < 0:
            return
        it = self.table.item(target_row, 4)
        if it:
            it.setText(new_remark)
            it.setToolTip(new_remark.strip())
        else:
            item = self._make_member_table_item(new_remark)
            item.setTextAlignment(QtCore.Qt.AlignCenter)
            item.setFlags(QtCore.Qt.ItemIsSelectable | QtCore.Qt.ItemIsEnabled)
            self.table.setItem(target_row, 4, item)
        self._update_remainders_only()
        self._save_active_data(level, exclude_expired=True)

    def _save_account_txt(self, level: str) -> bool:
        try:
            self._member_save_level_files(level, exclude_expired=True)
            return True
        except Exception:
            return False

    def _save_expired_data(self, expired_accounts: list[str], level: str) -> bool:
        try:
            unrecorded = [a for a in (expired_accounts or []) if not self._is_account_expired_recorded(a, level)]
            if not unrecorded:
                return True
            expire_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            ending = "\r\n"
            need_prefix = False
            try:
                with open(self.expired_file, "rb") as fb:
                    raw = fb.read()
                need_prefix = bool(raw and not (raw.endswith(b"\r\n") or raw.endswith(b"\n") or raw.endswith(b"\r")))
                crlf_count = raw.count(b"\r\n")
                cr_count = raw.count(b"\r") - crlf_count
                lf_count = raw.count(b"\n") - crlf_count
                if cr_count > max(crlf_count, lf_count):
                    ending = "\r"
                elif crlf_count > lf_count:
                    ending = "\r\n"
                else:
                    ending = "\n"
            except Exception:
                ending = "\r\n"
                need_prefix = False

            expired_doc = self._member_read_doc(self._member_validate_path(self.expired_file))
            expired_text = str(expired_doc.get("text") or "")
            if need_prefix:
                expired_text += ending
            expired_text += "".join(f"{str(account)}={expire_time},等级={level}{ending}" for account in unrecorded)
            expired_payload = bytes(expired_doc.get("bom") or b"") + expired_text.encode(str(expired_doc.get("encoding") or "utf-8"), "strict")
            self._member_save_level_files(level, exclude_expired=True, expired_payload=expired_payload)
            return True
        except Exception:
            return False

    def _get_selected_row(self) -> int:
        rows = {i.row() for i in self.table.selectedIndexes()}
        if rows:
            return sorted(rows)[0]
        return self.table.currentRow()

