    def _add_account(self) -> None:
        dlg, level_edit, account_edit, days_spin, remark_edit = self._build_member_add_account_dialog()
        ok_btn = getattr(dlg, "_member_ok_button", None)

        def _on_ok() -> None:
            level = level_edit.text().strip()
            account = account_edit.text().strip()
            remark = remark_edit.text().strip()
            days = int(days_spin.value())
            if not level or not account:
                QtWidgets.QMessageBox.warning(dlg, "错误", "等级和账号不能为空")
                return
            for r in range(self.table.rowCount()):
                row_level = (self.table.item(r, 0).text() if self.table.item(r, 0) else "").strip()
                acct = (self.table.item(r, 1).text() if self.table.item(r, 1) else "").strip()
                if row_level == level and acct == account:
                    QtWidgets.QMessageBox.warning(dlg, "错误", f"账号【{account}】已存在")
                    return
            expire_date = (datetime.now().date() + timedelta(days=days)).strftime("%Y-%m-%d")
            self._append_row(level, account, expire_date, remark)
            self._update_remainders_only()
            if not self._save_active_data(level, exclude_expired=False):
                self._reload_data()
                QtWidgets.QMessageBox.critical(self, "修改失败", "会员文件提交失败，原文件未改变。")
                return
            self._sort_member_list()
            QtWidgets.QMessageBox.information(self, "添加成功", f"账号【{account}】添加成功，到期日期：{expire_date}")
            dlg.accept()

        if isinstance(ok_btn, QtWidgets.QPushButton):
            ok_btn.clicked.connect(_on_ok)
        _qt_dialog_exec(dlg)

    def _delete_account(self) -> None:
        r = self._get_selected_row()
        if r is None or r < 0:
            QtWidgets.QMessageBox.warning(self, "提示", "请选择要删除的账号")
            return
        level, account, expire_date_str, _display, _remark = self._get_row_values(r)
        status = "已到期" if self._calc_display_remainder(expire_date_str) == "已到期" else "未到期"

        self.is_processing_action = True
        try:
            confirm = QtWidgets.QMessageBox.question(
                self,
                "确认删除",
                f"删除{status}账号【{account}】？\n\n会员等级：{level}\n到期日期：{expire_date_str}",
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
                QtWidgets.QMessageBox.No,
            )
            if confirm != QtWidgets.QMessageBox.Yes:
                return
            self.table.removeRow(r)
            if not self._save_active_data(level, exclude_expired=True):
                self._reload_data()
                QtWidgets.QMessageBox.critical(self, "删除失败", "会员文件提交失败，原文件未改变。")
                return
            self._sort_member_list()
            QtWidgets.QMessageBox.information(self, "删除成功", f"账号【{account}】已删除")
        finally:
            self.is_processing_action = False

    def _modify_expire_date(self) -> None:
        r = self._get_selected_row()
        if r is None or r < 0:
            QtWidgets.QMessageBox.warning(self, "提示", "请选择要修改的账号")
            return
        modify_days = int(self.days_spin.value())
        if modify_days == 0:
            return
        level, account, expire_date_str, _display, _remark = self._get_row_values(r)
        try:
            new_expire = datetime.strptime(expire_date_str, "%Y-%m-%d") + timedelta(days=modify_days)
            new_expire_str = new_expire.strftime("%Y-%m-%d")
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "修改失败", f"错误：{str(e)}")
            return
        preview = (
            "确认修改该会员账号的到期日期吗？\n\n"
            f"账号：{account}\n"
            f"会员等级：{level}\n"
            f"调整天数：{modify_days:+d}\n"
            f"到期日期：{expire_date_str} → {new_expire_str}"
        )
        self.is_processing_action = True
        try:
            confirm = QtWidgets.QMessageBox.question(
                self,
                "修改到期日预检",
                preview,
                QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.Cancel,
                QtWidgets.QMessageBox.Cancel,
            )
            if confirm != QtWidgets.QMessageBox.Yes:
                return
            it = self.table.item(r, 2)
            if it:
                it.setText(new_expire_str)
                it.setToolTip(new_expire_str.strip())
            self._update_remainders_only()
            if not self._save_active_data(level, exclude_expired=False):
                self._reload_data()
                QtWidgets.QMessageBox.critical(self, "添加失败", "会员文件提交失败，原文件未改变。")
                return
            self._sort_member_list()
            QtWidgets.QMessageBox.information(self, "修改成功", f"账号【{account}】新到期日期：{new_expire_str}")
        finally:
            self.is_processing_action = False

    def _toggle_auto_check(self) -> None:
        self.is_running = not self.is_running
        if self.is_running:
            self.auto_btn.setText("关闭检测")
            QtWidgets.QMessageBox.information(
                self,
                "自动检测开启",
                "1. 实时更新剩余时间和到期状态\n2. 到期账号会记录到 到期账号.ini 并更新导出文件",
            )
            self._update_remainder_and_check_expire()
        else:
            self.auto_btn.setText("开启检测")
            QtWidgets.QMessageBox.information(self, "自动检测关闭", "已停止自动刷新")

    def _build_member_text_popup(self, title: str, content: str) -> tuple[QtWidgets.QDialog, QtWidgets.QPlainTextEdit]:
        dlg = QtWidgets.QDialog(self)
        dlg.setObjectName("memberTextPopupDialog")
        dlg.setWindowTitle(str(title or ""))
        dlg.resize(UiMetrics.MEMBER_TEXT_POPUP_DIALOG_W, UiMetrics.MEMBER_TEXT_POPUP_DIALOG_H)
        dlg.setMinimumSize(UiMetrics.MEMBER_TEXT_POPUP_DIALOG_MIN_W, UiMetrics.MEMBER_TEXT_POPUP_DIALOG_MIN_H)
