class _ReloadMenuLeafWorker(QtCore.QObject):
    finished = QtCore.Signal(dict)

    def __init__(self, menu_leaf_text: str, root_dir: str) -> None:
        super().__init__()
        self._menu_leaf_text = str(menu_leaf_text or "").strip()
        self._root_dir = str(root_dir or "").strip()

    @QtCore.Slot()
    def run(self) -> None:
        out = {"ok": False, "msg": "", "menu_leaf_text": self._menu_leaf_text}
        try:
            ok, msg = ToolboxQtWindow._run_engine_reload_menu_leaf(self._menu_leaf_text, self._root_dir)
            out["ok"] = bool(ok)
            out["msg"] = str(msg or "")
        except Exception as e:
            out["ok"] = False
            out["msg"] = str(e)
        self.finished.emit(out)


class _FramelessTitleBar(QtWidgets.QFrame):
    def __init__(self, window: QtWidgets.QMainWindow) -> None:
        super().__init__(window)
        self._window = window
        self._dragging = False
        self._drag_start_pos = QtCore.QPoint(0, 0)
        self._drag_start_top_left = QtCore.QPoint(0, 0)

        self.setObjectName("titleBar")
        self.setFixedHeight(UiMetrics.TITLE_BAR_H)
        self.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)

        lay = QtWidgets.QHBoxLayout(self)
        lay.setContentsMargins(UiMetrics.TITLE_BAR_MARGIN_L, 0, UiMetrics.TITLE_BAR_MARGIN_R, 0)
        lay.setSpacing(UiMetrics.TITLE_BAR_SPACING)

        self._title_icon = QtWidgets.QLabel()
        self._title_icon.setObjectName("titleBarIcon")
        self._title_icon.setFixedSize(UiMetrics.TITLE_BAR_ICON_PX, UiMetrics.TITLE_BAR_ICON_PX)
        self._title_icon.setScaledContents(True)
        lay.addWidget(self._title_icon, 0)

        self._title_label = QtWidgets.QLabel(window.windowTitle() or "")
        self._title_label.setObjectName("titleBarTitle")
        self._title_label.setSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Fixed)
        self._title_label.setAlignment(QtCore.Qt.AlignVCenter | QtCore.Qt.AlignLeft)
        lay.addWidget(self._title_label, 1)

        btn_row = QtWidgets.QHBoxLayout()
        btn_row.setContentsMargins(0, 0, 0, 0)
        btn_row.setSpacing(UiMetrics.TITLE_BAR_BUTTON_SPACING)

        self.min_btn = _make_ui_action_button("-", "icon")
        self.min_btn.setObjectName("titleMinButton")
        self.min_btn.setFocusPolicy(QtCore.Qt.NoFocus)
        self.min_btn.setFixedSize(UiMetrics.TITLE_BAR_BUTTON_W, UiMetrics.TITLE_BAR_BUTTON_H)
        self.min_btn.clicked.connect(self._on_minimize)
        btn_row.addWidget(self.min_btn, 0)

        self.max_btn = _make_ui_action_button("□", "icon")
        self.max_btn.setObjectName("titleMaxButton")
        self.max_btn.setFocusPolicy(QtCore.Qt.NoFocus)
        self.max_btn.setFixedSize(UiMetrics.TITLE_BAR_BUTTON_W, UiMetrics.TITLE_BAR_BUTTON_H)
        self.max_btn.clicked.connect(self._on_toggle_maximize)
        btn_row.addWidget(self.max_btn, 0)

        self.close_btn = _make_ui_action_button("×", "icon")
        self.close_btn.setObjectName("titleCloseButton")
        self.close_btn.setFocusPolicy(QtCore.Qt.NoFocus)
        self.close_btn.setFixedSize(UiMetrics.TITLE_BAR_BUTTON_W, UiMetrics.TITLE_BAR_BUTTON_H)
        self.close_btn.clicked.connect(self._on_close)
        btn_row.addWidget(self.close_btn, 0)

        lay.addLayout(btn_row, 0)

        try:
            ico = window.windowIcon()
            pm = ico.pixmap(UiMetrics.TITLE_BAR_ICON_PX, UiMetrics.TITLE_BAR_ICON_PX) if ico and not ico.isNull() else None
            if pm is not None and not pm.isNull():
                self._title_icon.setPixmap(pm)
        except Exception:
            pass

        self._sync_maximize_button()

    def sync_title(self) -> None:
        try:
            self._title_label.setText(self._window.windowTitle() or "")
        except Exception:
            pass

    def _sync_maximize_button(self) -> None:
        try:
            if self._window.isMaximized():
                self.max_btn.setText("❐")
            else:
                self.max_btn.setText("□")
        except Exception:
            pass

    def _on_minimize(self) -> None:
        try:
            self._window.showMinimized()
        except Exception:
            pass

    def _on_toggle_maximize(self) -> None:
        try:
            if self._window.isMaximized():
                self._window.showNormal()
            else:
                self._window.showMaximized()
        except Exception:
            pass
        self._sync_maximize_button()

    def _on_close(self) -> None:
        try:
            self._window.close()
        except Exception:
            pass

    def mouseDoubleClickEvent(self, event) -> None:
        if event and event.button() == QtCore.Qt.LeftButton:
            self._on_toggle_maximize()
            return
        return super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event) -> None:
        if event and event.button() == QtCore.Qt.LeftButton:
            self._dragging = True
            self._drag_start_pos = event.globalPos()
            try:
                self._drag_start_top_left = self._window.frameGeometry().topLeft()
            except Exception:
                self._drag_start_top_left = self._window.pos()
        return super().mousePressEvent(event)

    def mouseMoveEvent(self, event) -> None:
        if not event:
            return super().mouseMoveEvent(event)
        if self._dragging and (event.buttons() & QtCore.Qt.LeftButton):
            try:
                if self._window.isMaximized():
                    local_x = event.pos().x()
                    ratio = 0.5
                    if self.width() > 0:
                        ratio = max(0.0, min(1.0, local_x / float(self.width())))
                    self._window.showNormal()
                    self._sync_maximize_button()
                    w = max(1, int(self._window.width()))
                    new_x = int(event.globalPos().x() - w * ratio)
                    new_y = int(event.globalPos().y() - int(self.height() / 2))
                    self._window.move(new_x, new_y)
                    self._drag_start_pos = event.globalPos()
                    try:
                        self._drag_start_top_left = self._window.frameGeometry().topLeft()
                    except Exception:
                        self._drag_start_top_left = self._window.pos()
                delta = event.globalPos() - self._drag_start_pos
                self._window.move(self._drag_start_top_left + delta)
            except Exception:
                pass
            return
        return super().mouseMoveEvent(event)

    def mouseReleaseEvent(self, event) -> None:
        if event and event.button() == QtCore.Qt.LeftButton:
            self._dragging = False
        return super().mouseReleaseEvent(event)


class ToolboxQtWindow(QtWidgets.QMainWindow):
    def __init__(self) -> None:
        super().__init__()
        self._ui_invoke = _UiInvokeProxy(self)

        self.setWindowTitle("虾米工具箱")
        ico = _resource_path(os.path.join("resources", "222.ico"))
        if os.path.exists(ico):
            self.setWindowIcon(QtGui.QIcon(ico))
        try:
            if sys.platform == "win32":
                self.setWindowFlags(self.windowFlags() | QtCore.Qt.FramelessWindowHint)
        except Exception:
            pass

        self._tray_icon: QtWidgets.QSystemTrayIcon | None = None
        self._tray_menu: QtWidgets.QMenu | None = None
        self._closing_to_exit = False
        self._app_closing = False

        self._session: dict | None = None
        self._update_mod = _toolbox_update_module()
        self._update_in_progress = False
        self._update_thread: QtCore.QThread | None = None
        self._update_worker: QtCore.QObject | None = None
        self._update_ignore_result = False
        self._update_is_manual = False
        self._update_prompted_latest_versions: set[str] = set()
        self._update_watchdog = QtCore.QTimer(self)
        self._update_watchdog.setSingleShot(True)
        self._update_watchdog.setInterval(15000)
        self._update_watchdog.timeout.connect(self._on_update_check_timeout)
        self._auto_update_timer = QtCore.QTimer(self)
        self._auto_update_timer.setInterval(5 * 60 * 1000)
        self._auto_update_timer.timeout.connect(self._auto_check_update_tick)
        self._heartbeat_timer: QtCore.QTimer | None = None
        self._heartbeat_in_flight = False
        self._heartbeat_interval_ms = 30000
        self._client_config_timer: QtCore.QTimer | None = None
        self._public_client_config_timer: QtCore.QTimer | None = None
        self._client_config_in_flight = False
        self._client_config_last_ts: int | None = None
        self._client_config_refresh_sec = 5
        self._friend_links_sig: tuple[tuple[str, str], ...] | None = None
        self._friend_links_style_sig: tuple[str, str, int, str, int] | None = None
        self._client_config_base = ""
        self._client_config_thread: QtCore.QThread | None = None
        self._client_config_worker: QtCore.QObject | None = None
        self._client_config_finished_slot = None
        self._client_config_thread_cleanup_slot = None
        self._reload_is_manual = False
        self._backend_offline_since_ts: int | None = None
        self._reload_menu_thread: QtCore.QThread | None = None
        self._reload_menu_worker: QtCore.QObject | None = None
        self._reload_menu_in_flight = False
        self._reload_menu_item_buttons: list[QtWidgets.QAbstractButton] = []
        self._reload_menu_defs: list[tuple[str, str]] = []
        self._reload_overflow_defs: list[tuple[str, str]] = []
        self._reload_direct_visible_max = 3
        self._more_reload_menu: QtWidgets.QMenu | None = None
        self._init_ui_scale()

        self._nav_sections = self._build_nav_sections()
        self._items_all = self._flatten_nav_items(self._nav_sections)
        self._items = [dict(it) for it in self._items_all]
        self._current_theme = "Orange"

        self._build_ui()
        self._apply_style()
        self._ensure_tray()
        self._apply_responsive_window_constraints()
        self._apply_startup_geometry()
        try:
            if self._update_mod is None and hasattr(self, "reload_btn") and self.reload_btn:
                self.reload_btn.setVisible(False)
        except Exception:
            pass
        try:
            if self._update_mod is not None:
                self._auto_update_timer.start()
                QtCore.QTimer.singleShot(2500, self._auto_check_update_tick)
        except Exception:
            pass
        app = QtWidgets.QApplication.instance()
        if app:
            app.aboutToQuit.connect(self._on_app_about_to_quit)

