    def _flatten_nav_items(self, sections: list[dict]) -> list[dict]:
        out: list[dict] = []
        for section in sections or []:
            for item in list((section or {}).get("items") or []):
                out.append(dict(item))
        return out

    def _build_ui(self) -> None:
        root = QtWidgets.QWidget()
        self.setCentralWidget(root)
        self._build_toast_overlay(root)

        main_v = QtWidgets.QVBoxLayout(root)
        main_v.setContentsMargins(0, 0, 0, 0)
        main_v.setSpacing(0)

        self.title_bar = None
        if sys.platform == "win32":
            self.title_bar = _FramelessTitleBar(self)
            main_v.addWidget(self.title_bar, 0)

        main_v.addWidget(self._build_main_shell_body(), 1)

        self._init_shared_root_sync()

        self._refill_nav()
        self._select_first_nav_entry()
        self._apply_login_nav_state()
        self._update_session_ui()
        self._apply_heartbeat_state()

    def _build_toast_overlay(self, root: QtWidgets.QWidget) -> None:
        self._toast_frame = QtWidgets.QFrame(root)
        self._toast_frame.setObjectName("toastFrame")
        self._toast_frame.setProperty("toastLevel", "info")
        self._toast_frame.setVisible(False)
        self._toast_frame.setAttribute(QtCore.Qt.WA_TransparentForMouseEvents, True)
        toast_l = QtWidgets.QHBoxLayout(self._toast_frame)
        toast_l.setContentsMargins(
            self._ui_px(UiMetrics.TOAST_PADDING_L),
            self._ui_px(UiMetrics.TOAST_PADDING_T),
            self._ui_px(UiMetrics.TOAST_PADDING_R),
            self._ui_px(UiMetrics.TOAST_PADDING_B),
        )
        toast_l.setSpacing(self._ui_px(UiMetrics.TOAST_SPACING))
        self._toast_label = QtWidgets.QLabel("")
        self._toast_label.setObjectName("toastLabel")
        self._toast_label.setWordWrap(True)
        self._toast_label.setTextInteractionFlags(QtCore.Qt.NoTextInteraction)
        toast_l.addWidget(self._toast_label, 1)
        self._toast_timer = QtCore.QTimer(self)
        self._toast_timer.setSingleShot(True)
        self._toast_timer.timeout.connect(self._hide_toast)

    def _build_main_shell_body(self) -> QtWidgets.QWidget:
        body = QtWidgets.QWidget()
        body.setObjectName("bodyRoot")
        body_grid = QtWidgets.QGridLayout(body)
        body_grid.setContentsMargins(0, 0, 0, 0)
        body_grid.setSpacing(0)

        body_grid.addWidget(self._build_body_row(), 0, 0, 2, 2)
        try:
            size_grip = QtWidgets.QSizeGrip(body)
            size_grip.setObjectName("sizeGrip")
            size_grip.setFixedSize(UiMetrics.SIZE_GRIP_WIDGET_PX, UiMetrics.SIZE_GRIP_WIDGET_PX)
            body_grid.addWidget(size_grip, 1, 1, 1, 1, QtCore.Qt.AlignRight | QtCore.Qt.AlignBottom)
        except Exception:
            pass
        body_grid.setRowStretch(0, 1)
        body_grid.setColumnStretch(0, 1)
        return body

    def _build_body_row(self) -> QtWidgets.QWidget:
        left = self._build_navigation_panel()
