    def _build_friend_links_box(self) -> QtWidgets.QFrame | None:
        active_links = []
        for raw in list(getattr(self, "_friend_links", []) or []):
            title = str((raw or {}).get("title") or "").strip()
            url = str((raw or {}).get("url") or "").strip()
            if not title or not url:
                continue
            active_links.append({"title": title, "url": url})
        if not active_links:
            self._friend_link_labels = []
            return None
        friend_box = QtWidgets.QFrame()
        friend_box.setObjectName("friendLinksBox")
        friend_box.setProperty("sidebarRole", "aux-links")
        friend_l = QtWidgets.QVBoxLayout(friend_box)
        friend_l.setContentsMargins(
            self._ui_px(UiMetrics.SIDEBAR_PANEL_PADDING_PX),
            self._ui_px(UiMetrics.SIDEBAR_PANEL_PADDING_PX),
            self._ui_px(UiMetrics.SIDEBAR_PANEL_PADDING_PX),
            self._ui_px(UiMetrics.SIDEBAR_PANEL_PADDING_PX),
        )
        friend_l.setSpacing(self._ui_px(UiMetrics.FRIEND_LINKS_SPACING))
        friend_header = QtWidgets.QWidget()
        friend_header_l = QtWidgets.QHBoxLayout(friend_header)
        friend_header_l.setContentsMargins(0, 0, 0, 0)
        friend_header_l.setSpacing(self._ui_px(UiMetrics.FRIEND_LINK_GRID_H_SPACING))
        friend_title = QtWidgets.QLabel("常用站点")
        friend_title.setObjectName("friendLinksTitle")
        friend_header_l.addWidget(friend_title, 0)
        friend_header_l.addStretch(1)
        self.friend_links_badge = QtWidgets.QLabel(f"{len(active_links)} 项")
        self.friend_links_badge.setObjectName("friendLinksBadge")
        self.friend_links_badge.setProperty("badgeRole", "muted")
        self.friend_links_badge.setAlignment(QtCore.Qt.AlignCenter)
        self._refresh_dynamic_qss(self.friend_links_badge)
        friend_header_l.addWidget(self.friend_links_badge, 0)
        friend_l.addWidget(friend_header)
        friend_grid = QtWidgets.QGridLayout()
        friend_grid.setContentsMargins(0, 0, 0, 0)
        friend_grid.setHorizontalSpacing(self._ui_px(UiMetrics.FRIEND_LINK_GRID_H_SPACING))
        friend_grid.setVerticalSpacing(self._ui_px(UiMetrics.FRIEND_LINK_GRID_V_SPACING))
        friend_grid.setColumnStretch(0, 1)
        self._friend_link_labels: list[_ClickableLabel] = []
        for i, it in enumerate(active_links):
            title = str(it.get("title") or "").strip()
            url = str(it.get("url") or "").strip()
            lb = _MarqueeClickableLabel(url, title)
            lb.setObjectName("friendLinkItem")
            lb.setProperty("linkState", "active")
            lb.setProperty("visualTone", "auxiliary")
            try:
                lb.set_dynamic_color_enabled(False)
            except Exception:
                pass
            lb.setAlignment(QtCore.Qt.AlignCenter)
            lb.setFixedHeight(max(self._ui_px(UiMetrics.FRIEND_LINK_MIN_H), lb.sizeHint().height() + self._ui_px(UiMetrics.FRIEND_LINK_EXTRA_H)))
            lb.setSizePolicy(QtWidgets.QSizePolicy.Ignored, QtWidgets.QSizePolicy.Fixed)
            try:
                lb.set_force_marquee(True)
            except Exception:
                pass
            lb.clicked.connect(self._on_friend_link_clicked)
            self._friend_link_labels.append(lb)
            friend_grid.addWidget(lb, i, 0)
        friend_l.addLayout(friend_grid)
        return friend_box

