    def _build_reload_actions(self) -> QtWidgets.QWidget:
        actions = QtWidgets.QWidget()
        actions.setObjectName("reloadActions")
        actions.setProperty("reloadActionsRole", "button-strip")
        actions.setAccessibleName("快速重载操作")
        actions.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
        header_bar_l = QtWidgets.QHBoxLayout(actions)
        header_bar_l.setContentsMargins(0, 0, 0, 0)
        header_bar_l.setSpacing(UiMetrics.RELOAD_ACTION_SPACING)
        self._reload_menu_defs = list(self._get_reload_menu_button_defs() or [])
        self._reload_menu_item_buttons = []
        for display_text, menu_leaf in self._reload_menu_defs:
            btn = self._make_action_button(display_text, "toolbar")
            btn.setObjectName("reloadItemButton")
            btn.setProperty("reloadRole", "direct")
            btn.setProperty("reloadActionState", "")
            btn.setCursor(QtCore.Qt.PointingHandCursor)
            btn.setFocusPolicy(QtCore.Qt.NoFocus)
            try:
                btn.setMinimumWidth(
                    max(self._ui_button_min_width("toolbar"), btn.fontMetrics().horizontalAdvance(display_text) + UiMetrics.RELOAD_ACTION_TEXT_EXTRA_W)
                )
            except Exception:
                btn.setMinimumWidth(self._ui_button_min_width("toolbar"))
            btn.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
            btn.setToolTip(f"执行 {display_text} 重载")
            btn.setAccessibleName(f"重载{display_text}")
            btn.clicked.connect(lambda checked=False, p=menu_leaf, b=btn: self._run_reload_menu_leaf_async(p, b))
            header_bar_l.addWidget(btn, 0)
            self._reload_menu_item_buttons.append(btn)

        self.more_reload_btn = self._make_action_button("更多", "toolbar")
        self.more_reload_btn.setObjectName("reloadItemButton")
        self.more_reload_btn.setProperty("reloadRole", "overflow")
        self.more_reload_btn.setProperty("overflowCount", 0)
        self.more_reload_btn.setCursor(QtCore.Qt.PointingHandCursor)
        self.more_reload_btn.setFocusPolicy(QtCore.Qt.NoFocus)
        self.more_reload_btn.setSizePolicy(QtWidgets.QSizePolicy.Fixed, QtWidgets.QSizePolicy.Fixed)
        try:
            self.more_reload_btn.setMinimumWidth(
                max(
                    self._ui_button_min_width("toolbar") + UiMetrics.RELOAD_OVERFLOW_MIN_EXTRA_W,
                    self.more_reload_btn.fontMetrics().horizontalAdvance("更多(99)") + UiMetrics.RELOAD_OVERFLOW_TEXT_EXTRA_W,
                )
            )
        except Exception:
            self.more_reload_btn.setMinimumWidth(self._ui_button_min_width("toolbar"))
        self.more_reload_btn.setToolTip("显示其余重载项目")
        self.more_reload_btn.setAccessibleName("更多重载项目")
        self.more_reload_btn.clicked.connect(self._show_more_reload_menu)
        header_bar_l.addWidget(self.more_reload_btn, 0)
        return actions

