    def resizeEvent(self, event) -> None:
        super().resizeEvent(event)
        try:
            QtCore.QTimer.singleShot(0, self._relayout_reload_buttons)
        except Exception:
            pass
        try:
            self._queue_refresh_ui_scale_for_current_viewport()
        except Exception:
            pass
        try:
            self._position_toast()
        except Exception:
            pass
        try:
            tb = getattr(self, "title_bar", None)
            if tb:
                tb._sync_maximize_button()
        except Exception:
            pass

    def changeEvent(self, event) -> None:
        try:
            if event and event.type() == QtCore.QEvent.WindowStateChange:
                tb = getattr(self, "title_bar", None)
                if tb:
                    tb._sync_maximize_button()
        except Exception:
            pass
        return super().changeEvent(event)

    def _position_toast(self) -> None:
        frame = getattr(self, "_toast_frame", None)
        if not frame or not frame.isVisible():
            return
        w = int(self.centralWidget().width()) if self.centralWidget() else int(self.width())
        max_w = max(
            self._ui_px(UiMetrics.TOAST_MIN_W, minimum=220),
            min(
                self._ui_px(UiMetrics.TOAST_MAX_W, minimum=320),
                w - self._ui_px(UiMetrics.TOAST_MARGIN_X_PX * 2, minimum=16),
            ),
        )
        frame.setMaximumWidth(max_w)
        frame.adjustSize()
        y = self._ui_px(UiMetrics.TOAST_MARGIN_Y_PX, minimum=8)
        try:
            tb = getattr(self, "title_bar", None)
            if tb:
                y += int(tb.height())
        except Exception:
            pass
        frame.move(self._ui_px(UiMetrics.TOAST_MARGIN_X_PX, minimum=8), int(y))
        frame.raise_()

    def _show_toast(self, text: str, level: str = "info", timeout_ms: int = 2200) -> None:
        return

    def _hide_toast(self) -> None:
        frame = getattr(self, "_toast_frame", None)
        if frame:
            frame.setVisible(False)

