            widget.setMinimumWidth(min_w)
            widget.setMaximumWidth(16777215 if max_w is None else max_w)
            if fixed:
                widget.setSizePolicy(QtWidgets.QSizePolicy.Fixed, widget.sizePolicy().verticalPolicy())

