class _XiamiPluginRuntime:
    def __init__(self, embedded_root: Path, xiami_home: Path | None = None) -> None:
        self.embedded_root = Path(embedded_root)
        self.plugin_root = self.embedded_root / "xiami_plugins"
        self.xiami_home = Path(xiami_home) if xiami_home is not None else self.embedded_root / "runtime" / "xiami_v1"
        self.loader = None
        self.kernel_manager = None
        self.event_bus = None
        self.event_gateway = None
        self.event_url = ""
        self.event_ws_url = ""
        self.event_channel_detail = ""
        self.event_restart_required = False
        self.loaded = False
        self.last_error = ""
        self.sent_messages: list[tuple[str, str, str]] = []
        self.received_message_count = 0
        self.received_event_count = 0
        self.login_started_at = 0.0
        self.login_account = ""
        self._reply_recall_timers: dict[str, threading.Timer] = {}
        self._reply_recall_lock = threading.RLock()
        self.kernel_kind = "NapCat"
        self.kernel_executable = ""
        self.kernel_working_dir = ""
        self.kernel_arguments: list[str] = []
        self.onebot_url = "http://127.0.0.1:3000"
        self.access_token = ""
        self.account_status: dict[str, object] = {
            "state": "offline",
            "account": "",
            "nickname": "",
            "detail": "未上线",
        }
        self.group_list: list[dict[str, str]] = []
        self._napcat_protocol_restarted_accounts: set[str] = set()

    def _prepare_imports(self) -> None:
        root = str(self.embedded_root)
        if root not in sys.path:
            sys.path.insert(0, root)
        os.environ["XIAMI_HOME"] = str(self.xiami_home)

    def _cleanup_runtime_path_aliases(self, remove_current_alias: bool = True) -> None:
        """Clear Xiami runtime path aliases without touching unrelated drives."""
        self._prepare_imports()
        try:
            from xiami_core.path_alias import cleanup_legacy_subst_aliases

            cleanup_legacy_subst_aliases()
            if remove_current_alias:
                from xiami_core.path_alias import cleanup_aliases, remove_empty_alias_base_dirs

                cleanup_aliases()
                remove_empty_alias_base_dirs()
        except Exception as exc:
            self.last_error = str(exc)

    def _saved_accounts_path(self) -> Path:
        return self.xiami_home / "saved_accounts.json"

    def _load_saved_account_records(self) -> list[dict[str, object]]:
        path = self._saved_accounts_path()
        if not path.is_file():
            return []
        try:
            raw = json.loads(path.read_text(encoding="utf-8-sig"))
        except Exception:
            return []
        items = raw.get("accounts") if isinstance(raw, dict) else raw
        if not isinstance(items, list):
            return []
        result: list[dict[str, object]] = []
        seen: set[str] = set()
        for item in items:
            if isinstance(item, dict):
                account = str(item.get("account") or item.get("qq") or "").strip()
                nickname = str(item.get("nickname") or "").strip()
                updated_at = float(item.get("updated_at") or 0)
            else:
                account = str(item or "").strip()
                nickname = ""
                updated_at = 0.0
            if not re.fullmatch(r"\d{5,}", account) or account in seen:
                continue
            seen.add(account)
            result.append({"account": account, "nickname": nickname, "updated_at": updated_at})
        return sorted(result, key=lambda row: float(row.get("updated_at") or 0), reverse=True)

    def _save_account_records(self, records: list[dict[str, object]]) -> None:
        path = self._saved_accounts_path()
        payload = {"accounts": records}
        self._prepare_imports()
        from xiami_core.storage.paths import atomic_write_json

        atomic_write_json(path, payload)

    def _remember_saved_account(self, account: str, nickname: str = "") -> None:
        account_id = str(account or "").strip()
        if not re.fullmatch(r"\d{5,}", account_id):
            return
        records = [row for row in self._load_saved_account_records() if str(row.get("account") or "") != account_id]
        records.insert(
            0,
            {
                "account": account_id,
                "nickname": str(nickname or "").strip(),
                "updated_at": time.time(),
            },
        )
        try:
            self._save_account_records(records[:32])
        except Exception as exc:
            self.last_error = str(exc)

    def _forget_saved_account(self, account: str) -> None:
        account_id = str(account or "").strip()
        if not re.fullmatch(r"\d{5,}", account_id):
            return
        records = [row for row in self._load_saved_account_records() if str(row.get("account") or "") != account_id]
        try:
            self._save_account_records(records)
        except Exception as exc:
            self.last_error = str(exc)

    def _clear_account_status_if_matches(self, account: str) -> None:
        account_id = str(account or "").strip()
        current = str(self.account_status.get("account") or "").strip() if isinstance(self.account_status, dict) else ""
        if account_id and current and current != account_id:
            return
        if self.login_account == account_id:
            self._mark_account_offline()
        self.account_status = {
            "state": "offline",
            "account": "",
            "nickname": "",
            "presence": "offline",
            "presence_label": "离线",
            "detail": "账号已删除，等待重新扫码登录",
            "group_count": 0,
            "groups": [],
            "login_started_at": 0,
            "received_count": 0,
            "sent_count": 0,
        }

    def _cleanup_bundled_test_accounts(self) -> None:
        """Remove account configs accidentally bundled during migration builds."""
        napcat_config_dirs = [
            self.xiami_home / "kernels" / "NapCat.Shell.Windows" / "napcat" / "config",
            self.xiami_home / "kernels" / "NapCat.Shell.Windows" / "config",
        ]
        for config_dir in napcat_config_dirs:
            if not config_dir.is_dir():
                continue
            for account_id in XIAMI_BUNDLED_TEST_QQ_IDS:
                for filename in (
                    f"napcat_{account_id}.json",
                    f"napcat_protocol_{account_id}.json",
                    f"onebot11_{account_id}.json",
                ):
                    try:
                        path = config_dir / filename
                        if path.is_file():
                            path.unlink()
                    except Exception as exc:
                        self.last_error = str(exc)

    def load_connection(self) -> tuple[str, str]:
        self._prepare_imports()
        try:
            from xiami_core.storage.config import load_config

            config = load_config().kernel
            kind = str(getattr(config, "kind", "") or self.kernel_kind).strip()
            self.kernel_kind = kind if kind in {"NapCat", "Lagrange"} else "NapCat"
            self.kernel_executable = str(getattr(config, "executable", "") or "")
            self.kernel_working_dir = str(getattr(config, "working_dir", "") or "")
            arguments = getattr(config, "arguments", None) or []
            self.kernel_arguments = [str(item) for item in arguments] if isinstance(arguments, list) else []
            self.onebot_url = str(getattr(config, "http_url", "") or self.onebot_url)
            self.access_token = str(getattr(config, "access_token", "") or "")
        except Exception as exc:
            self.last_error = str(exc)
        return self.onebot_url, self.access_token

    def _normalize_kernel_kind(self, kind: str) -> str:
        value = str(kind or "").strip()
        return value if value in {"NapCat", "Lagrange"} else "NapCat"

    def save_connection(
        self,
        http_url: str,
        access_token: str,
        kernel_kind: str | None = None,
        executable: str | None = None,
        working_dir: str | None = None,
        arguments: list[str] | None = None,
    ) -> None:
        self._prepare_imports()
        next_kernel_kind = self._normalize_kernel_kind(kernel_kind or self.kernel_kind)
        next_executable = self.kernel_executable if executable is None else str(executable or "").strip()
        next_working_dir = self.kernel_working_dir if working_dir is None else str(working_dir or "").strip()
        next_arguments = list(self.kernel_arguments) if arguments is None else [str(item) for item in arguments]
        next_onebot_url = str(http_url or "").strip() or "http://127.0.0.1:3000"
        next_access_token = str(access_token or "").strip()
        try:
            from dataclasses import replace
            from xiami_core.storage.config import load_config, save_config

            old = load_config()
            save_config(
                replace(
                    old,
                    kernel=replace(
                        old.kernel,
                        kind=next_kernel_kind,
                        executable=next_executable,
                        working_dir=next_working_dir,
                        arguments=list(next_arguments),
                        http_url=next_onebot_url,
                        access_token=next_access_token,
                    ),
                )
            )
        except Exception as exc:
            self.last_error = str(exc)
            raise
        self.kernel_kind = next_kernel_kind
        self.kernel_executable = next_executable
        self.kernel_working_dir = next_working_dir
        self.kernel_arguments = next_arguments
        self.onebot_url = next_onebot_url
        self.access_token = next_access_token

    def _kernel_config(self):
        self._prepare_imports()
        from xiami_core.storage.config import KernelConfig

        return KernelConfig(
            kind=self.kernel_kind,
            executable=self.kernel_executable,
            working_dir=self.kernel_working_dir,
            arguments=list(self.kernel_arguments),
            http_url=self.onebot_url,
            access_token=self.access_token,
        )

    def _napcat_shell_root(self) -> Path | None:
        """Locate the NapCat Shell root that can start without QQNT registry lookup."""
        seeds: list[Path] = []
        for raw in (self.kernel_working_dir,):
            text = str(raw or "").strip()
            if text:
                seeds.append(Path(text))
        executable = str(self.kernel_executable or "").strip()
        if executable:
            try:
                path = Path(executable)
                if path.parent != Path("."):
                    seeds.append(path.parent)
            except Exception:
                pass
        seeds.extend(
            [
                self.xiami_home / "kernels" / "NapCat.Shell.Windows",
                self.xiami_home / "kernels" / "NapCat.Shell.Windows" / "napcat",
            ]
        )

        candidates: list[Path] = []
        seen: set[str] = set()
        for seed in seeds:
            for candidate in (seed, seed.parent, seed / ".."):
                try:
                    path = candidate.resolve()
                except Exception:
                    path = candidate
                key = str(path).lower()
                if not key or key in seen:
                    continue
                seen.add(key)
                candidates.append(path)

        for root in candidates:
            if (root / "index.js").is_file() and (root / "napcat" / "napcat.mjs").is_file():
                return root
        return None

    def _napcat_shell_kernel_config(self, arguments: list[str] | None = None):
        shell_root = self._napcat_shell_root()
        if shell_root is None:
            return None
        bat = shell_root / "napcat.bat"
        index_js = shell_root / "index.js"
        node_exe = shell_root / "node.exe"
        if bat.is_file():
            executable = bat
            args = list(arguments or [])
        elif node_exe.is_file() and index_js.is_file():
            executable = node_exe
            args = ["index.js", *list(arguments or [])]
        else:
            return None
        from dataclasses import replace

        return replace(
            self._kernel_config(),
            kind="NapCat",
            executable=str(executable),
            working_dir=str(shell_root),
            arguments=args,
        )

    @staticmethod
    def _prefer_napcat_winboot() -> bool:
        """Use WinBoot on pre-Windows-10 systems where Node Shell is unreliable."""
        if sys.platform != "win32":
            return False
        try:
            version = sys.getwindowsversion()
            return int(version.major) < 10
        except Exception:
            return False

    def _napcat_winboot_kernel_config(self):
        shell_root = self._napcat_shell_root()
        if shell_root is None:
            return None
        launcher = shell_root / "napcat" / "launcher-user.bat"
        if not launcher.is_file():
            return None
        from dataclasses import replace

        return replace(
            self._kernel_config(),
            kind="NapCat",
            executable=str(launcher),
            working_dir=str(launcher.parent),
            arguments=[],
        )

    def _is_napcat_registry_launcher(self, executable: str | None = None) -> bool:
        text = str(executable if executable is not None else self.kernel_executable or "").strip()
        if not text:
            return False
        name = Path(text).name.lower()
        return name in {"launcher-user.bat", "launcher.bat", "launcher-win10-user.bat", "launcher-win10.bat"}

    def _napcat_runtime_dir(self) -> Path | None:
        shell_root = self._napcat_shell_root()
        if shell_root is not None:
            return shell_root
        candidates: list[Path] = []
        if self.kernel_working_dir:
            candidates.append(Path(self.kernel_working_dir))
        if self.kernel_executable:
            candidates.append(Path(self.kernel_executable).parent)
        seen: set[str] = set()
        for base in candidates:
            for candidate in (base, base / "napcat"):
                key = str(candidate).lower()
                if key in seen:
                    continue
                seen.add(key)
                if (candidate / "launcher-user.bat").is_file():
                    return candidate
        return None

    def _napcat_account_ids_from_files(self) -> list[str]:
        napcat_dir = self._napcat_runtime_dir()
        if napcat_dir is None:
            return []
        config_dirs: list[Path] = []
        for candidate in (napcat_dir / "config", napcat_dir / "napcat" / "config"):
            if candidate.is_dir() and candidate not in config_dirs:
                config_dirs.append(candidate)
        found: dict[str, float] = {}
        for config_dir in config_dirs:
            for pattern in ("napcat_*.json", "napcat_protocol_*.json", "onebot11_*.json"):
                for path in config_dir.glob(pattern):
                    stem = path.stem
                    account = ""
                    for prefix in ("napcat_protocol_", "napcat_", "onebot11_"):
                        if stem.startswith(prefix):
                            account = stem[len(prefix) :]
                            break
                    if not re.fullmatch(r"\d{5,}", account):
                        continue
                    try:
                        mtime = path.stat().st_mtime
                    except OSError:
                        mtime = 0.0
                    found[account] = max(float(found.get(account, 0.0)), float(mtime))
        return [account for account, _mtime in sorted(found.items(), key=lambda item: item[1], reverse=True)]

    def known_napcat_accounts(self) -> list[str]:
        # 只返回工具箱在真实登录成功后登记过的账号。
        # 不再从 NapCat 的 napcat_*.json / onebot11_*.json 文件名推断账号，
        # 避免发布包或旧版本残留的测试配置显示到账号管理列表。
        return [str(row.get("account") or "") for row in self._load_saved_account_records()]

    def delete_napcat_account(self, account: str) -> dict[str, object]:
        account_id = str(account or "").strip()
        if not re.fullmatch(r"\d{5,}", account_id):
            return {"ok": False, "message": "请先选择有效 QQ 账号。", "removed": []}
        napcat_dir = self._napcat_runtime_dir()
        if napcat_dir is None:
            self._forget_saved_account(account_id)
            self._clear_account_status_if_matches(account_id)
            return {"ok": True, "message": f"账号 {account_id} 已从工具箱账号列表移除。", "removed": []}

        config_dirs: list[Path] = []
        seen_config_dirs: set[str] = set()
        for candidate in (napcat_dir / "config", napcat_dir / "napcat" / "config"):
            key = str(candidate).lower()
            if key not in seen_config_dirs and candidate.is_dir():
                seen_config_dirs.add(key)
                config_dirs.append(candidate)

        targets: list[Path] = []
        for config_dir in config_dirs:
            for filename in (f"napcat_{account_id}.json", f"napcat_protocol_{account_id}.json", f"onebot11_{account_id}.json"):
                path = config_dir / filename
                if path not in targets:
                    targets.append(path)

        removed: list[str] = []
        errors: list[str] = []
        for path in targets:
            if not path.is_file():
                continue
            try:
                path.unlink()
                removed.append(str(path))
            except OSError as exc:
                errors.append(f"{path.name}: {exc}")

        self._forget_saved_account(account_id)
        self._clear_account_status_if_matches(account_id)
        self._napcat_protocol_restarted_accounts.discard(account_id)
        if errors:
            self.last_error = "；".join(errors)
            return {
                "ok": False,
                "message": f"账号 {account_id} 删除失败：{self.last_error}",
                "removed": removed,
            }
        if not removed:
            return {"ok": True, "message": f"账号 {account_id} 已从工具箱账号列表移除。", "removed": []}
        return {
            "ok": True,
            "message": f"已删除账号 {account_id} 的本机登录配置；再次上线需要重新扫码。",
            "removed": removed,
        }

    def napcat_quick_login_config(self, account: str):
        account_id = str(account or "").strip()
        if not account_id:
            return None
        shell_config = self._napcat_shell_kernel_config(["-q", account_id])
        if shell_config is not None:
            return shell_config
        return None

    def _status_to_dict(self, status) -> dict[str, object]:
        previous = self.account_status if isinstance(self.account_status, dict) else {}
        state = str(getattr(status, "state", "") or "offline")
        account = str(getattr(status, "account", "") or previous.get("account") or "")
        if state == "online":
            self._mark_account_online(account)
        elif state == "offline":
            self._mark_account_offline()
        return {
            "state": state,
            "account": account,
            "nickname": str(previous.get("nickname") or ""),
            "presence": str(previous.get("presence") or "online"),
            "presence_label": str(previous.get("presence_label") or ("在线" if state == "online" else "")),
            "detail": str(getattr(status, "detail", "") or ""),
            "qr_hint": str(getattr(status, "qr_hint", "") or ""),
            "logs": list(getattr(status, "logs", ()) or ()),
            "event_url": self.event_url,
            "event_ws_url": self.event_ws_url,
            "event_restart_required": self.event_restart_required,
            "group_count": len(self.group_list),
            "login_started_at": self.login_started_at,
            "received_count": self.received_message_count,
            "sent_count": len(self.sent_messages),
        }

    def _mark_account_online(self, account: str = "") -> None:
        account_id = str(account or "").strip()
        if self.login_account and account_id and account_id != self.login_account:
            self.received_message_count = 0
            self.received_event_count = 0
            self.sent_messages = []
            self.login_started_at = time.time()
        elif self.login_started_at <= 0:
            self.received_message_count = 0
            self.received_event_count = 0
            self.sent_messages = []
            self.login_started_at = time.time()
        if account_id:
            self.login_account = account_id
            self._remember_saved_account(account_id)

    def _mark_account_offline(self) -> None:
        self.login_started_at = 0.0
        self.login_account = ""
        self.event_restart_required = False

    def login_elapsed_seconds(self) -> int:
        if self.login_started_at <= 0:
            return 0
        return max(0, int(time.time() - self.login_started_at))

    def account_runtime_stats(self) -> dict[str, int]:
        return {
            "groups": len(self.group_list or []),
            "received": int(self.received_message_count or 0),
            "sent": len(self.sent_messages or []),
            "login_seconds": self.login_elapsed_seconds(),
        }

    @staticmethod
    def _first_text(data: object, *keys: str) -> str:
        if not isinstance(data, dict):
            return ""
        for key in keys:
            value = data.get(key)
            if value is None:
                continue
            text = str(value).strip()
            if text:
                return text
        return ""

    @classmethod
    def _account_from_login_data(cls, data: object) -> tuple[str, str]:
        if not isinstance(data, dict):
            return "", ""
        account = cls._first_text(data, "user_id", "uin", "account", "qq")
        nickname = cls._first_text(data, "nickname", "nick", "name")
        for nested_key in ("user", "self", "account_info", "login_info"):
            nested = data.get(nested_key)
            if not isinstance(nested, dict):
                continue
            account = account or cls._first_text(nested, "user_id", "uin", "account", "qq")
            nickname = nickname or cls._first_text(nested, "nickname", "nick", "name")
        return account, nickname

    @classmethod
    def _nickname_from_profile_data(cls, data: object) -> str:
        if not isinstance(data, dict):
            return ""
        return cls._first_text(data, "nickname", "nick", "name", "card", "remark")

    @classmethod
    def _normalize_group_items(cls, data: object) -> list[dict[str, str]]:
        if isinstance(data, dict):
            for key in ("groups", "group_list", "list", "items", "data"):
                value = data.get(key)
                if isinstance(value, (list, tuple)):
                    data = value
                    break
        if not isinstance(data, (list, tuple)):
            return []
        result: list[dict[str, str]] = []
        seen: set[str] = set()
        for item in data:
            if isinstance(item, dict):
                group_id = cls._first_text(item, "group_id", "gid", "id", "uin")
                name = cls._first_text(item, "group_name", "name", "group_remark", "remark", "display_name")
            else:
                group_id = str(item or "").strip()
                name = ""
            if not group_id or group_id in seen:
                continue
            seen.add(group_id)
            result.append({"group_id": group_id, "name": name})
        return sorted(result, key=lambda item: (item.get("name") or item.get("group_id") or "", item.get("group_id") or ""))

    def refresh_group_list(self, client=None) -> list[dict[str, str]]:
        self._prepare_imports()
        try:
            if client is None:
                from xiami_core.onebot.client import OneBotHttpClient

                client = OneBotHttpClient(self.onebot_url, self.access_token, timeout=3.0)
            response = client.get_group_list()
            if response.ok:
                self.group_list = self._normalize_group_items(response.data)
            else:
                self.last_error = response.message or "读取群列表失败"
            return list(self.group_list)
        except Exception as exc:
            self.last_error = str(exc)
            return list(self.group_list)

    def _ensure_event_bus(self):
        self._prepare_imports()
        from xiami_core.events import EventBus

        if self.event_bus is None:
            self.event_bus = EventBus()
            self.event_bus.subscribe_message(self.dispatch_message)
            self.event_bus.subscribe_plugin_event(self.dispatch_event)
        return self.event_bus

    def start_event_gateway(self) -> str:
        self._prepare_imports()
        from xiami_core.onebot.gateway import OneBotEventGateway

        event_bus = self._ensure_event_bus()
        if self.event_gateway is None:
            self.event_gateway = OneBotEventGateway(event_bus)
        self.event_url = self.event_gateway.start()
        self.event_ws_url = str(getattr(self.event_gateway, "ws_url", "") or "")
        return self.event_url

    def ensure_event_channel(self) -> dict[str, object]:
        self._prepare_imports()
        event_url = self.start_event_gateway()
        event_ws_url = self.event_ws_url
        changed = False
        ok = True
        detail = f"事件接收已就绪：{event_url}"
        try:
            from xiami_core.kernels.napcat_config import inspect_napcat_onebot_config
            from xiami_core.kernels.templates import write_kernel_templates

            config = self._kernel_config()
            before_ok = True
            if self.kernel_kind == "NapCat":
                before = inspect_napcat_onebot_config(config, event_url, event_ws_url)
                before_ok = bool(before.ok)
            result = write_kernel_templates(config, event_url, event_ws_url)
            changed = not before_ok
            detail = result.detail
            if self.kernel_kind == "NapCat":
                after = inspect_napcat_onebot_config(config, event_url, event_ws_url)
                ok = bool(after.ok)
        except Exception as exc:
            ok = False
            detail = f"事件接收配置失败：{exc}"
            self.last_error = detail
        self.event_channel_detail = detail
        self.event_restart_required = bool(changed)
        return {"ok": ok, "changed": changed, "event_url": event_url, "event_ws_url": event_ws_url, "detail": detail}

    def stop_event_gateway(self) -> None:
        try:
            if self.event_gateway is not None:
                self.event_gateway.stop()
        finally:
            self.event_gateway = None
            self.event_url = ""
            self.event_ws_url = ""

    def terminate_kernel_processes(self) -> None:
        """Best-effort cleanup for OneBot/NapCat processes started from bundled workdirs."""
        self._prepare_imports()
        try:
            from xiami_core.kernels.process_tree import terminate_processes_for_workdir
        except Exception as exc:
            self.last_error = str(exc)
            return
        candidates: list[Path] = []
        for raw in (self.kernel_working_dir,):
            text = str(raw or "").strip()
            if text:
                candidates.append(Path(text))
        executable = str(self.kernel_executable or "").strip()
        if executable:
            try:
                path = Path(executable)
                if path.parent != Path("."):
                    candidates.append(path.parent)
            except Exception:
                pass
        candidates.extend(
            [
                self.xiami_home / "kernels" / "NapCat.Shell.Windows",
                self.xiami_home / "kernels" / "NapCat.Shell.Windows" / "napcat",
            ]
        )
        seen: set[str] = set()
        errors: list[str] = []
        for candidate in candidates:
            try:
                path = candidate.resolve()
            except Exception:
                path = candidate
            key = str(path).lower()
            if not key or key in seen or not path.exists():
                continue
            seen.add(key)
            try:
                terminate_processes_for_workdir(path)
            except Exception as exc:
                errors.append(f"{path}: {exc}")
        if errors:
            self.last_error = "；".join(errors)

    def receive_diagnostic_text(self) -> str:
        self._prepare_imports()
        event_url = self.event_url or self.start_event_gateway()
        event_ws_url = self.event_ws_url or str(getattr(self.event_gateway, "ws_url", "") or "")
        try:
            from xiami_core.onebot.receive_diagnostic import format_receive_diagnostic, run_receive_diagnostic

            return format_receive_diagnostic(run_receive_diagnostic(event_url=event_url, event_ws_url=event_ws_url))
        except Exception as exc:
            self.last_error = str(exc)
            return f"接收诊断失败：{exc}"

    def recent_event_text(self, limit: int = 12) -> str:
        self._prepare_imports()
        try:
            from xiami_core.onebot.events_tail import read_recent_event_summaries

            return "\n".join(read_recent_event_summaries(limit)) or "暂无事件"
        except Exception as exc:
            self.last_error = str(exc)
            return f"读取最近事件失败：{exc}"

    def real_acceptance_text(self) -> str:
        self._prepare_imports()
        try:
            from xiami_core.real_acceptance_gate import format_real_acceptance_gate, run_real_acceptance_gate

            gate = run_real_acceptance_gate(
                require_online=True,
                require_messages=True,
                require_sends=True,
                require_migration=True,
            )
            return format_real_acceptance_gate(gate)
        except Exception as exc:
            self.last_error = str(exc)
            return f"闭环验收失败：{exc}"

    def _ensure_kernel_manager(self):
        self._prepare_imports()
        from xiami_core.kernels.manager import KernelManager

        if self.kernel_manager is None:
            self.kernel_manager = KernelManager(self._ensure_event_bus())
        return self.kernel_manager

    def dispatch_message(self, event) -> None:
        self.received_message_count += 1
        if self.loader is None or not self.loaded:
            self.load()
        if self.loader is not None:
            self.loader.dispatch_message(event)

    def dispatch_event(self, event) -> None:
        self.received_event_count += 1
        if self.loader is None or not self.loaded:
            self.load()
        if self.loader is not None:
            self.loader.dispatch_event(event)

    def start_kernel_login(
        self,
        http_url: str,
        access_token: str,
        kernel_kind: str,
        executable: str,
        working_dir: str,
        arguments: list[str] | None = None,
        account: str = "",
    ) -> dict[str, object]:
        self._napcat_protocol_restarted_accounts.clear()
        self._cleanup_bundled_test_accounts()
        self._cleanup_runtime_path_aliases(remove_current_alias=False)
        self.save_connection(http_url, access_token, kernel_kind, executable, working_dir, arguments=arguments)
        if (
            self.kernel_kind == "NapCat"
            and self._is_napcat_registry_launcher()
            and not self._prefer_napcat_winboot()
        ):
            shell_config = self._napcat_shell_kernel_config([])
            if shell_config is not None:
                self.save_connection(
                    http_url,
                    access_token,
                    "NapCat",
                    shell_config.executable,
                    shell_config.working_dir,
                    arguments=list(shell_config.arguments or []),
                )
        manager = self._ensure_kernel_manager()
        status = manager.set_kernel(self._kernel_config())
        if str(getattr(status, "state", "") or "") != "error":
            channel = self.ensure_event_channel()
            if channel.get("detail"):
                status_detail = str(getattr(status, "detail", "") or "")
                status = type(status)(
                    state=getattr(status, "state", "starting"),
                    account=getattr(status, "account", ""),
                    detail=f"{status_detail}；{channel.get('detail')}" if status_detail else str(channel.get("detail") or ""),
                    logs=getattr(status, "logs", ()),
                    qr_hint=getattr(status, "qr_hint", ""),
                )
            status = manager.start_login(account)
        self.account_status = self._status_to_dict(status)
        return self.account_status

    def refresh_kernel_status(self) -> dict[str, object]:
        manager = self._ensure_kernel_manager()
        status = manager.status()
        status_dict = self._status_to_dict(status)
        if str(status_dict.get("state") or "") == "online":
            base_logs = status_dict.get("logs", [])
            base_qr_hint = status_dict.get("qr_hint", "")
            status_dict = self.refresh_account_status()
            if base_logs:
                status_dict["logs"] = base_logs
            if base_qr_hint:
                status_dict["qr_hint"] = base_qr_hint
        else:
            repaired = self._maybe_repair_napcat_protocol_after_scan(status_dict)
            if repaired:
                status_dict = repaired
        self.account_status = status_dict
        return self.account_status

    def _maybe_repair_napcat_protocol_after_scan(self, status_dict: dict[str, object]) -> dict[str, object] | None:
        if self.kernel_kind != "NapCat" or self.kernel_manager is None:
            return None
        accounts = self._napcat_account_ids_from_files()
        if not accounts:
            return None
        account = accounts[0]
        if account in self._napcat_protocol_restarted_accounts:
            return None
        try:
            from xiami_core.kernels.napcat_config import inspect_napcat_onebot_config

            channel = self.ensure_event_channel()
            config = self._kernel_config()
            state = inspect_napcat_onebot_config(config, str(channel.get("event_url") or ""), str(channel.get("event_ws_url") or ""))
            if not state.ok:
                detail = f"检测到扫码账号 {account}，但 OneBot 协议配置仍未就绪：{state}"
                repaired = dict(status_dict)
                repaired["state"] = "starting"
                repaired["account"] = account
                repaired["detail"] = detail
                return repaired
            quick_config = self.napcat_quick_login_config(account)
            if quick_config is None:
                return None
            self._napcat_protocol_restarted_accounts.add(account)
            try:
                self.kernel_manager.stop()
                time.sleep(0.8)
            except Exception:
                pass
            status_obj = self.kernel_manager.set_kernel(quick_config)
            if str(getattr(status_obj, "state", "") or "") != "error":
                status_obj = self.kernel_manager.start_login(account)
            repaired = self._status_to_dict(status_obj)
            repaired["state"] = str(repaired.get("state") or "starting")
            repaired["account"] = account
            detail = str(repaired.get("detail") or "")
            repaired["detail"] = (
                f"已检测到扫码账号 {account}，OneBot 配置已写入，正在重启登录服务。"
                + (f" {detail}" if detail else "")
            )
            return repaired
        except Exception as exc:
            self.last_error = str(exc)
            repaired = dict(status_dict)
            repaired["state"] = "starting"
            repaired["account"] = account
            repaired["detail"] = f"检测到扫码账号 {account}，自动配置 OneBot 时失败：{exc}"
            return repaired

    def stop_kernel(self) -> dict[str, object]:
        self._cancel_pending_reply_recalls()
        if self.kernel_manager is None:
            if self.event_gateway is not None:
                self.stop_event_gateway()
            self.group_list = []
            self._mark_account_offline()
            self.account_status = {
                "state": "offline",
                "account": "",
                "nickname": "",
                "presence": "offline",
                "presence_label": "离线",
                "detail": "内核未启动",
            }
            return self.account_status
        kernel = getattr(self.kernel_manager, "kernel", None)
        kernel_config = getattr(kernel, "config", None)
        config_without_workdir = None
        if kernel_config is not None and hasattr(kernel_config, "working_dir"):
            try:
                from dataclasses import replace

                config_without_workdir = replace(kernel_config, working_dir="")
                kernel.config = config_without_workdir
            except Exception:
                config_without_workdir = None
        try:
            status = self.kernel_manager.stop()
        finally:
            if config_without_workdir is not None:
                kernel.config = kernel_config
        self._cleanup_runtime_path_aliases()
        self.loader = None
        self.loaded = False
        self.stop_event_gateway()
        self.group_list = []
        self._mark_account_offline()
        self.account_status = self._status_to_dict(status)
        self.account_status["presence"] = "offline"
        self.account_status["presence_label"] = "离线"
        return self.account_status

    def refresh_account_status(self) -> dict[str, object]:
        self._prepare_imports()
        try:
            from xiami_core.onebot.client import OneBotHttpClient

            client = OneBotHttpClient(self.onebot_url, self.access_token, timeout=2.0)
            login = client.get_login_info()
            service = client.get_status()
            account, nickname = self._account_from_login_data(login.data)
            if account and not nickname:
                profile = client.get_stranger_info(account, no_cache=False)
                if profile.ok:
                    nickname = self._nickname_from_profile_data(profile.data)
            previous = self.account_status if isinstance(self.account_status, dict) else {}
            presence = str(previous.get("presence") or "online")
            presence_label = str(previous.get("presence_label") or "")
            if login.ok:
                detail = f"OneBot 已登录：{account or '-'} {nickname}".strip()
                state = "online"
                if presence == "offline":
                    presence = "online"
                    presence_label = "在线"
                channel = self.ensure_event_channel()
                if not channel.get("ok"):
                    detail = f"{detail}；事件接收未就绪"
                elif channel.get("changed"):
                    detail = f"{detail}；事件接收地址已更新，点击“上线”重启后接收消息"
                groups = self.refresh_group_list(client)
                if account and not nickname:
                    for group in groups[:5]:
                        group_id = str(group.get("group_id") or "").strip()
                        if not group_id:
                            continue
                        member = client.get_group_member_info(group_id, account, no_cache=False)
                        if member.ok:
                            nickname = self._nickname_from_profile_data(member.data)
                            if nickname:
                                detail = f"OneBot 已登录：{account} {nickname}".strip()
                                break
            elif service.ok:
                detail = "OneBot HTTP 可访问，等待账号登录"
                state = "starting"
                self.group_list = []
            else:
                detail = login.message or service.message or "OneBot 不可访问"
                state = "offline"
                self.group_list = []
            if state == "online":
                self._mark_account_online(account)
                self._remember_saved_account(account, nickname)
            else:
                self._mark_account_offline()
            self.account_status = {
                "state": state,
                "account": account,
                "nickname": nickname,
                "presence": presence,
                "presence_label": presence_label or ("在线" if state == "online" else ""),
                "detail": detail,
                "login_ok": bool(login.ok),
                "service_ok": bool(service.ok),
                "group_count": len(self.group_list),
                "groups": list(self.group_list),
                "event_url": self.event_url,
                "event_ws_url": self.event_ws_url,
                "event_restart_required": self.event_restart_required,
                "login_started_at": self.login_started_at,
                "received_count": self.received_message_count,
                "sent_count": len(self.sent_messages),
            }
            return self.account_status
        except Exception as exc:
            self.group_list = []
            self._mark_account_offline()
            self.account_status = {
                "state": "error",
                "account": "",
                "nickname": "",
                "detail": str(exc),
                "login_ok": False,
                "service_ok": False,
            }
            self.last_error = str(exc)
            return self.account_status

    def set_account_presence(self, presence: str) -> dict[str, object]:
        self._prepare_imports()
        presence_key = str(presence or "online").strip().lower()
        status_map = {
            "online": (10, 0, "在线"),
            "qme": (60, 0, "Q我吧"),
            "away": (30, 0, "离开"),
            "busy": (50, 0, "忙碌"),
            "dnd": (70, 0, "勿扰"),
            "invisible": (40, 0, "隐身"),
        }
        status_code, ext_status, label = status_map.get(presence_key, status_map["online"])
        try:
            from xiami_core.onebot.client import OneBotHttpClient

            client = OneBotHttpClient(self.onebot_url, self.access_token, timeout=5.0)
            response = client.call(
                "set_online_status",
                {"status": status_code, "ext_status": ext_status, "battery_status": 0},
            )
            if response.ok:
                self.account_status["presence"] = presence_key
                self.account_status["presence_label"] = label
                data = self.refresh_account_status()
                data["presence"] = presence_key
                data["presence_label"] = label
                self.account_status = data
                return {"ok": True, "message": f"账号状态已设置为：{label}", "data": data}
            message = response.message or "当前 OneBot 内核未接受 set_online_status"
            return {"ok": False, "message": f"账号状态设置失败：{message}", "data": self.account_status}
        except Exception as exc:
            self.last_error = str(exc)
            return {"ok": False, "message": f"账号状态设置失败：{exc}", "data": self.account_status}

    def send_onebot_message(self, target: str, text: str, message_type: str):
        self._prepare_imports()
        from xiami_core.models import SendResult
        from xiami_core.onebot.client import OneBotHttpClient

        client = OneBotHttpClient(self.onebot_url, self.access_token, timeout=5.0)
        if str(message_type or "").lower() == "group":
            response = client.send_group_msg(target, text)
        else:
            response = client.send_private_msg(target, text)
        data = response.data if isinstance(response.data, dict) else {}
        message_id = str(data.get("message_id") or data.get("id") or "")
        result = SendResult(ok=bool(response.ok), detail=response.message or "", message_id=message_id)
        if result.ok:
            self._record_sent_message(target, text, message_type)
            self._schedule_bot_reply_recall_if_needed(target, message_type, message_id)
        return result

    def _record_sent_message(self, target: object, text: object, message_type: object) -> None:
        self.sent_messages.append((str(target or ""), str(text or ""), str(message_type or "")))

    @staticmethod
    def _onebot_response_message_id(response: object) -> str:
        data = getattr(response, "data", None)
        if isinstance(response, dict):
            direct = str(response.get("message_id") or response.get("id") or "").strip()
            if direct:
                return direct
            data = response.get("data", data)
        if isinstance(data, dict):
            return str(data.get("message_id") or data.get("id") or "").strip()
        return ""

    def _bot_reply_recall_policy(self, group_id: object) -> tuple[bool, int]:
        group_key = str(group_id or "").strip()
        if not re.fullmatch(r"\d{5,}", group_key):
            return False, 30
        try:
            loader = self.loader
            context = getattr(loader, "context", None) if loader is not None else None
            if context is None:
                return False, 30
            from xiami_core.plugins.group_settings import GroupSettingService

            service = GroupSettingService(context)
            enabled = service.enabled(group_key, "bot_reply_recall_enabled")
            seconds = service.number(group_key, "bot_reply_recall_seconds")
            return bool(enabled), max(1, min(int(seconds or 30), 24 * 60 * 60))
        except Exception as exc:
            self.last_error = str(exc)
            return False, 30

    def _schedule_bot_reply_recall_if_needed(
        self,
        target: object,
        message_type: object,
        message_id: object,
    ) -> None:
        message_key = str(message_id or "").strip()
        if str(message_type or "").strip().lower() != "group" or not re.fullmatch(r"\d+", message_key):
            return
        enabled, delay_seconds = self._bot_reply_recall_policy(target)
        if not enabled:
            return
        timer_key = uuid.uuid4().hex

        def recall_later() -> None:
            try:
                self._prepare_imports()
                from xiami_core.onebot.client import _number_or_text

                self.call_onebot_action("delete_msg", {"message_id": _number_or_text(message_key)})
            except Exception as exc:
                self.last_error = f"机器人全部回复自动撤回失败：{exc}"
            finally:
                with self._reply_recall_lock:
                    self._reply_recall_timers.pop(timer_key, None)

        timer = threading.Timer(float(delay_seconds), recall_later)
        timer.daemon = True
        with self._reply_recall_lock:
            self._reply_recall_timers[timer_key] = timer
        timer.start()

    def _cancel_pending_reply_recalls(self) -> None:
        with self._reply_recall_lock:
            timers = list(self._reply_recall_timers.values())
            self._reply_recall_timers.clear()
        for timer in timers:
            try:
                timer.cancel()
            except Exception:
                pass

    def _record_onebot_action_send(self, action: str, params: dict[str, object], response: object) -> None:
        if not self._onebot_response_ok(response):
            return
        action_key = str(action or "").strip().lower()
        if action_key not in {"send_private_msg", "send_group_msg", "send_msg", "send_group_forward_msg", "send_private_forward_msg"}:
            return
        if action_key in {"send_group_msg", "send_group_forward_msg"}:
            message_type = "group"
            target = params.get("group_id") or params.get("target") or ""
        elif action_key in {"send_private_msg", "send_private_forward_msg"}:
            message_type = "private"
            target = params.get("user_id") or params.get("target") or ""
        else:
            message_type = str(
                params.get("message_type")
                or params.get("type")
                or ("group" if params.get("group_id") is not None else "")
                or ("private" if params.get("user_id") is not None else "")
                or "private"
            ).lower()
            target = params.get("group_id") if message_type == "group" else params.get("user_id")
            target = target or params.get("target") or ""
        self._record_sent_message(target, params.get("message") or params.get("text") or "", message_type)
        self._schedule_bot_reply_recall_if_needed(target, message_type, self._onebot_response_message_id(response))

    @staticmethod
    def _onebot_response_ok(response: object) -> bool:
        if hasattr(response, "ok"):
            return bool(getattr(response, "ok"))
        if isinstance(response, dict):
            status = str(response.get("status") or "").lower()
            retcode = response.get("retcode")
            return status == "ok" or retcode in {0, "0"}
        return False

    def call_onebot_action(self, action: str, params: dict[str, object]):
        self._prepare_imports()
        from xiami_core.onebot.client import OneBotHttpClient

        action_stats = None
        try:
            if self.kernel_manager is not None:
                action_stats = self.kernel_manager.action_stats()
        except Exception:
            action_stats = None
        client = OneBotHttpClient(self.onebot_url, self.access_token, timeout=5.0, action_stats=action_stats)
        payload = dict(params or {})
        response = client.call(str(action), payload)
        self._record_onebot_action_send(str(action), payload, response)
        return response

    def run_moderation_action(self, action: str, group_id: str = "", user_id: str = "", **kwargs) -> dict[str, object]:
        self._prepare_imports()
        from xiami_core.onebot.client import _number_or_text

        action_key = str(action or "").strip().lower()
        group_key = str(group_id or "").strip()
        user_key = str(user_id or "").strip()
        labels = {
            "ban": "禁言",
            "unban": "解禁",
            "kick": "踢出",
            "whole_ban_on": "开启全员禁言",
            "whole_ban_off": "关闭全员禁言",
            "set_admin": "设置管理员",
            "unset_admin": "取消管理员",
            "set_card": "设置群名片",
            "set_special_title": "设置专属头衔",
            "clear_special_title": "清除专属头衔",
            "set_group_name": "设置群名",
            "set_group_notice": "发送群公告",
            "delete_msg": "撤回消息",
        }
        if action_key != "delete_msg" and not re.fullmatch(r"\d{5,}", group_key):
            return {"ok": False, "message": "请选择或输入有效QQ群号。", "action": action_key}
        if action_key in {"ban", "unban", "kick", "set_admin", "unset_admin", "set_card", "set_special_title", "clear_special_title"} and not re.fullmatch(r"\d{5,}", user_key):
            return {"ok": False, "message": "请输入有效 QQ 号。", "action": action_key}
        try:
            if action_key == "ban":
                duration = max(1, min(int(kwargs.get("duration", 600) or 600), 30 * 24 * 60 * 60))
                response = self.call_onebot_action(
                    "set_group_ban",
                    {"group_id": _number_or_text(group_key), "user_id": _number_or_text(user_key), "duration": duration},
                )
            elif action_key == "unban":
                response = self.call_onebot_action(
                    "set_group_ban",
                    {"group_id": _number_or_text(group_key), "user_id": _number_or_text(user_key), "duration": 0},
                )
            elif action_key == "kick":
                response = self.call_onebot_action(
                    "set_group_kick",
                    {
                        "group_id": _number_or_text(group_key),
                        "user_id": _number_or_text(user_key),
                        "reject_add_request": bool(kwargs.get("reject_add_request", False)),
                    },
                )
            elif action_key == "whole_ban_on":
                response = self.call_onebot_action(
                    "set_group_whole_ban",
                    {"group_id": _number_or_text(group_key), "enable": True},
                )
            elif action_key == "whole_ban_off":
                response = self.call_onebot_action(
                    "set_group_whole_ban",
                    {"group_id": _number_or_text(group_key), "enable": False},
                )
            elif action_key == "set_admin":
                response = self.call_onebot_action(
                    "set_group_admin",
                    {"group_id": _number_or_text(group_key), "user_id": _number_or_text(user_key), "enable": True},
                )
            elif action_key == "unset_admin":
                response = self.call_onebot_action(
                    "set_group_admin",
                    {"group_id": _number_or_text(group_key), "user_id": _number_or_text(user_key), "enable": False},
                )
            elif action_key == "set_card":
                card = str(kwargs.get("card") or "").strip()
                if not card:
                    return {"ok": False, "message": "请输入群名片。", "action": action_key}
                response = self.call_onebot_action(
                    "set_group_card",
                    {"group_id": _number_or_text(group_key), "user_id": _number_or_text(user_key), "card": card},
                )
            elif action_key == "set_special_title":
                special_title = str(kwargs.get("special_title") or "").strip()
                if not special_title:
                    return {"ok": False, "message": "请输入专属头衔。", "action": action_key}
                response = self.call_onebot_action(
                    "set_group_special_title",
                    {
                        "group_id": _number_or_text(group_key),
                        "user_id": _number_or_text(user_key),
                        "special_title": special_title,
                        "duration": -1,
                    },
                )
            elif action_key == "clear_special_title":
                response = self.call_onebot_action(
                    "set_group_special_title",
                    {
                        "group_id": _number_or_text(group_key),
                        "user_id": _number_or_text(user_key),
                        "special_title": "",
                        "duration": -1,
                    },
                )
            elif action_key == "set_group_name":
                group_name = str(kwargs.get("group_name") or "").strip()
                if not group_name:
                    return {"ok": False, "message": "请输入新群名。", "action": action_key}
                response = self.call_onebot_action(
                    "set_group_name",
                    {"group_id": _number_or_text(group_key), "group_name": group_name},
                )
            elif action_key == "set_group_notice":
                content = str(kwargs.get("notice") or "").strip()
                if not content:
                    return {"ok": False, "message": "请输入群公告内容。", "action": action_key}
                response = self.call_onebot_action(
                    "_send_group_notice",
                    {"group_id": _number_or_text(group_key), "content": content, "image": ""},
                )
            elif action_key == "delete_msg":
                message_id = str(kwargs.get("message_id") or "").strip()
                if not re.fullmatch(r"\d+", message_id):
                    return {"ok": False, "message": "请输入有效 message_id。", "action": action_key}
                response = self.call_onebot_action("delete_msg", {"message_id": _number_or_text(message_id)})
            else:
                return {"ok": False, "message": f"未知群管操作：{action}", "action": action_key}
        except Exception as exc:
            self.last_error = str(exc)
            return {"ok": False, "message": f"{labels.get(action_key, '群管操作')}失败：{exc}", "action": action_key}

        ok = self._onebot_response_ok(response)
        response_message = str(getattr(response, "message", "") or "")
        if not response_message and isinstance(response, dict):
            response_message = str(response.get("message") or response.get("wording") or response.get("msg") or "")
        label = labels.get(action_key, "群管操作")
        if ok:
            return {"ok": True, "message": f"{label}已提交。", "action": action_key}
        return {"ok": False, "message": f"{label}失败：{response_message or response}", "action": action_key}

    def load(self) -> list[dict[str, object]]:
        self._prepare_imports()
        self.last_error = ""
        try:
            from xiami_core.models import SendResult
            from xiami_core.plugins.context import PluginContext
            from xiami_core.plugins.kv import PluginKVStore
            from xiami_core.plugins.loader import PluginLoader
            from xiami_core.plugins.state import PluginStateStore

            def send(target, text, message_type):
                try:
                    return self.send_onebot_message(str(target), str(text), str(message_type))
                except Exception as exc:
                    return SendResult(ok=False, detail=f"OneBot 发送失败：{exc}")

            context = PluginContext(
                send_fn=send,
                onebot_call_fn=self.call_onebot_action,
                config={
                    "account": str(self.login_account or self.account_status.get("account") or ""),
                    "qq": str(self.login_account or self.account_status.get("account") or ""),
                    "self_id": str(self.login_account or self.account_status.get("account") or ""),
                },
                data_root=self.xiami_home / "plugin_data",
                state_store=PluginKVStore(self.xiami_home / "plugin_state"),
            )
            state_store = PluginStateStore(self.xiami_home / "logs" / "plugins.json")
            self._apply_internal_plugin_policy(state_store)
            self.loader = PluginLoader(
                self.plugin_root,
                context,
                state_store,
                user_config_root=self.xiami_home / "plugin_configs",
            )
            self.loader.load_all()
            self._apply_unified_permission_policy()
            self.loaded = True
            return self.diagnostics()
        except Exception as exc:
            self.loaded = False
            self.last_error = str(exc)
            self.loader = None
            return []

    def _apply_internal_plugin_policy(self, state_store) -> None:
        try:
            data = state_store.load()
            changed = False
            for plugin_id in XIAMI_INTERNAL_PLUGIN_IDS:
                if data.get(plugin_id, True):
                    data[plugin_id] = False
                    changed = True
            if changed:
                state_store.save(data)
        except Exception as exc:
            self.last_error = str(exc)

    def _apply_unified_permission_policy(self) -> None:
        """工具箱内置页面统一用 permissions 插件维护权限。

        旧插件仍保留 owners/admins 配置兼容独立运行，但嵌入工具箱时不再让每个插件
        自己携带一套管理员名单，避免“插件里还有权限管理”的产品割裂。
        """
        loader = self.loader
        if loader is None:
            return
        for plugin in list(getattr(loader, "plugins", []) or []):
            plugin_id = str(getattr(plugin, "id", "") or "").strip().lower()
            if not plugin_id or plugin_id == "permissions":
                continue
            config = getattr(plugin, "config", None)
            if isinstance(config, dict):
                if "owners" in config:
                    config["owners"] = []
                if "admins" in config:
                    config["admins"] = []
            context = getattr(plugin, "context", None)
            context_config = getattr(context, "config", None)
            if isinstance(context_config, dict):
                if "owners" in context_config:
                    context_config["owners"] = []
                if "admins" in context_config:
                    context_config["admins"] = []

    def diagnostics(self) -> list[dict[str, object]]:
        loader = self.loader
        if loader is None:
            return []
        try:
            return list(loader.diagnostics())
        except Exception as exc:
            self.last_error = str(exc)
            return []

    def set_enabled(self, plugin_id: str, enabled: bool) -> list[dict[str, object]]:
        if self.loader is None:
            self.load()
        if self.loader is not None:
            self.loader.set_enabled(str(plugin_id), bool(enabled))
            self.loader.reload()
            self._apply_unified_permission_policy()
        return self.diagnostics()

    def reload(self) -> list[dict[str, object]]:
        if self.loader is None:
            return self.load()
        try:
            self.loader.reload()
            self._apply_unified_permission_policy()
            self.loaded = True
            self.last_error = ""
        except Exception as exc:
            self.last_error = str(exc)
        return self.diagnostics()

    def _ensure_loader(self):
        if self.loader is None or not self.loaded:
            self.load()
        if self.loader is None:
            raise RuntimeError(self.last_error or "插件尚未加载")
        return self.loader

    def plugin_config_snapshot(self, plugin_id: str) -> dict[str, object]:
        loader = self._ensure_loader()
        return {
            "default": loader.default_config(str(plugin_id)),
            "current": loader.user_config(str(plugin_id)),
            "schema": loader.config_schema(str(plugin_id)),
        }

    def save_plugin_config(self, plugin_id: str, config: dict[str, object]) -> list[dict[str, object]]:
        loader = self._ensure_loader()
        loader.save_user_config(str(plugin_id), dict(config))
        loader.reload()
        self.loaded = True
        return self.diagnostics()

