    def _loaded_plugin(self, plugin_id: str):
        loader = self._ensure_loader()
        wanted = str(plugin_id or "").strip()
        for plugin in loader.plugins:
            if plugin.id == wanted or plugin.path.name == wanted:
                if plugin.context is None:
                    raise RuntimeError(f"插件上下文不可用：{wanted}")
                return plugin
        raise KeyError(f"plugin not loaded: {wanted}")

    @staticmethod
    def _normalize_id_list(values) -> list[str]:
        if isinstance(values, str):
            values = re.findall(r"\d{5,}", values)
        if not isinstance(values, (list, tuple, set)):
            return []
        result: list[str] = []
        for value in values:
            text = str(value or "").strip()
            if text and text not in result:
                result.append(text)
        return sorted(result)

    @classmethod
    def _normalize_group_id_map(cls, value) -> dict[str, list[str]]:
        if not isinstance(value, dict):
            return {}
        result: dict[str, list[str]] = {}
        for group_id, ids in value.items():
            key = str(group_id or "").strip()
            if not key:
                continue
            normalized = cls._normalize_id_list(ids)
            if normalized:
                result[key] = normalized
        return result

    def permissions_snapshot(self) -> dict[str, object]:
        plugin = self._loaded_plugin("permissions")
        from xiami_core.plugins.permissions import PluginPermissionService

        service = PluginPermissionService(plugin.context)
        config_owners = self._normalize_id_list(plugin.context.get_config("owners", []))
        config_admins = self._normalize_id_list(plugin.context.get_config("admins", []))
        state_owners = self._normalize_id_list(plugin.context.get_state("owners", []))
        state_admins = self._normalize_id_list(plugin.context.get_state("global_admins", []))
        group_admins = self._normalize_group_id_map(plugin.context.get_state("group_admins", {}))
        effective_owners = sorted(service.owners())
        effective_admins = sorted(service.global_admins() - service.owners())
        return {
            "config_owners": config_owners,
            "config_admins": config_admins,
            "state_owners": state_owners,
            "state_global_admins": state_admins,
            "owners": effective_owners,
            "global_admins": effective_admins,
            "group_admins": group_admins,
        }

    def save_permissions(self, owners, global_admins, group_admins: dict[str, list[str]]) -> dict[str, object]:
        loader = self._ensure_loader()
        plugin = self._loaded_plugin("permissions")
        owner_ids = self._normalize_id_list(owners)
        admin_ids = [item for item in self._normalize_id_list(global_admins) if item not in set(owner_ids)]
        groups = self._normalize_group_id_map(group_admins)
        config = dict(loader.user_config(plugin.id))
        config["owners"] = owner_ids
        config["admins"] = admin_ids
        loader.save_user_config(plugin.id, config)
        plugin.config.update(config)
        plugin.context.config.update(config)
        plugin.context.set_state("owners", [])
        plugin.context.set_state("global_admins", [])
        plugin.context.set_state("group_admins", groups)
        try:
            from xiami_core.plugins.permissions import sync_permission_config

            sync_permission_config(plugin.context)
        except Exception:
            pass
        return {
            "ok": True,
            "message": f"权限已保存：主人 {len(owner_ids)} 个，全局管理员 {len(admin_ids)} 个，群配置 {len(groups)} 个。",
            "data": self.permissions_snapshot(),
        }

    def bindings_snapshot(self) -> dict[str, object]:
        plugin = self._loaded_plugin("bindings")
        from xiami_core.plugins.bindings import BindingService

        service = BindingService(plugin.context)
        return {
            "binding_root": service.storage_dir(),
            "bindings": service.groups(),
            "group_labels": service.group_labels(),
            "servers": service.server_list(),
            "records": service.records(),
        }

    @staticmethod
    def _binding_scope(group_id: str, server_name: str = "") -> str:
        group = str(group_id or "").strip()
        server = str(server_name or "").strip()
        if group and server:
            return f"{group}{XIAMI_BIND_SCOPE_SEPARATOR}{server}"
        return group

    @staticmethod
    def _binding_scope_parts(scope: str, labels: dict[str, str] | None = None) -> tuple[str, str]:
        text = str(scope or "").strip()
        if XIAMI_BIND_SCOPE_SEPARATOR in text:
            group_id, server_name = text.split(XIAMI_BIND_SCOPE_SEPARATOR, 1)
            return group_id.strip(), server_name.strip()
        label = ""
        if isinstance(labels, dict):
            label = str(labels.get(text, "") or "").strip()
        return text, label

    def set_binding_root(self, directory: str) -> dict[str, object]:
        loader = self._ensure_loader()
        plugin = self._loaded_plugin("bindings")
        from xiami_core.plugins.bindings import BindingService

        service = BindingService(plugin.context)
        result = service.set_storage_dir(str(directory or "").strip())
        if result.ok:
            config = dict(loader.user_config(plugin.id))
            config["binding_root"] = service.storage_dir()
            loader.save_user_config(plugin.id, config)
            plugin.config.update(config)
            plugin.context.config.update(config)
        return {"ok": bool(result.ok), "message": str(result.message), "data": self.bindings_snapshot()}

    def set_binding_entry(self, group_id: str, user_id: str, account: str, group_label: str = "") -> dict[str, object]:
        plugin = self._loaded_plugin("bindings")
        from xiami_core.plugins.bindings import BindingService

        service = BindingService(plugin.context)
        group_key = str(group_id or "").strip()
        if not group_key:
            return {"ok": False, "message": "QQ群号不能为空。", "data": self.bindings_snapshot()}
        server_name = str(group_label or "").strip()
        if not server_name:
            return {"ok": False, "message": "请先输入并创建区服后再绑定。", "data": self.bindings_snapshot()}
        scope_key = self._binding_scope(group_key, server_name)
        result = service.bind(scope_key, str(user_id or "").strip(), str(account or "").strip())
        ok = bool(result.ok)
        message = result.message if result.ok else result.message
        if ok and server_name:
            message = f"{message}（{server_name}）"
        return {"ok": ok, "message": str(message), "data": self.bindings_snapshot()}

    def create_binding_server(self, group_id: str, group_label: str) -> dict[str, object]:
        plugin = self._loaded_plugin("bindings")
        from xiami_core.plugins.bindings import BindingService

        service = BindingService(plugin.context)
        group_key = str(group_id or "").strip()
        server_name = str(group_label or "").strip()
        if not group_key:
            return {"ok": False, "message": "QQ群号不能为空。", "data": self.bindings_snapshot()}
        if not server_name:
            return {"ok": False, "message": "请输入区服名。", "data": self.bindings_snapshot()}
        if not re.fullmatch(r"[\w\u4e00-\u9fff-]{1,32}", server_name):
            return {"ok": False, "message": "区服名只能包含中文、字母、数字、下划线和短横线，长度 1-32。", "data": self.bindings_snapshot()}
        scope_key = self._binding_scope(group_key, server_name)
        result = service.set_group_label(scope_key, server_name)
        message = f"区服已创建：{group_key} / {server_name}" if result.ok else str(result.message)
        return {"ok": bool(result.ok), "message": message, "data": self.bindings_snapshot()}

    def delete_binding_server(self, group_id: str, group_label: str) -> dict[str, object]:
        plugin = self._loaded_plugin("bindings")
        from xiami_core.plugins.bindings import BindingService

        service = BindingService(plugin.context)
        group_key = str(group_id or "").strip()
        server_name = str(group_label or "").strip()
        if not group_key:
            return {"ok": False, "message": "QQ群号不能为空。", "data": self.bindings_snapshot()}
        if not server_name:
            return {"ok": False, "message": "请先选择或输入区服名。", "data": self.bindings_snapshot()}
        scope_key = self._binding_scope(group_key, server_name)
        result = service.delete_group(scope_key, remove_bindings=True)
        message = f"区服已删除：{group_key} / {server_name}" if result.ok else str(result.message)
        if result.ok and "清理绑定" in result.message:
            message = f"{message}，{result.message.split('，', 1)[-1]}"
        return {"ok": bool(result.ok), "message": message, "data": self.bindings_snapshot()}

    def delete_binding_entry(self, group_id: str, user_id: str) -> dict[str, object]:
        plugin = self._loaded_plugin("bindings")
