        from xiami_core.plugins.knowledge import KnowledgeService

        knowledge_plugin = plugin
        service = KnowledgeService(knowledge_plugin.context)
        config = dict(knowledge_plugin.config or {})
        max_files = int(config.get("max_import_files", 100) or 100)
        max_chars = int(config.get("max_chars_per_file", 200000) or 200000)
        result = (
            service.preview_import(str(path_text or ""), max_files=max_files)
            if preview
            else service.import_path(str(path_text or ""), max_files=max_files, max_chars_per_file=max_chars)
        )
        return {"ok": True, "message": result.message, "data": self.knowledge_snapshot()}

