    def cards_snapshot(self, status: str = "all", query: str = "") -> dict[str, object]:
        plugin = self._loaded_plugin("cards")
        from xiami_core.plugins.cards import CardService, normalize_status

        service = CardService(plugin.context)
        status_key = normalize_status(status)
        rows = service.inventory(status_key, str(query or ""), limit=2000)
        counts = service.counts()
        return {
            "cards": rows,
            "total": counts["total"],
            "unused": counts["unused"],
            "used": counts["used"],
            "card_cost": service.card_cost(),
            "filter": status_key,
            "query": str(query or "").strip(),
        }

    def set_card_cost(self, cost: int) -> dict[str, object]:
        value = max(1, int(cost))
        loader = self._ensure_loader()
        config = dict(loader.user_config("cards"))
        config["card_cost"] = value
        loader.save_user_config("cards", config)
        loader.reload()
        self._apply_unified_permission_policy()
        self.loaded = True
        return {
            "ok": True,
            "message": f"已保存卡密兑换积分：{value} 积分 / 张。",
            "data": self.cards_snapshot(),
        }

