    def invites_snapshot(self, group_id: str = "") -> dict[str, object]:
        plugin = self._loaded_plugin("invites")
        from xiami_core.plugins.invites import InviteService

        service = InviteService(plugin.context)
        settings = plugin.context.get_state("settings", {}) if plugin.context else {}
        if not isinstance(settings, dict):
            settings = {}
        records = plugin.context.get_state("invite_records", {}) if plugin.context else {}
        if not isinstance(records, dict):
            records = {}
        ranks = plugin.context.get_state("invite_ranks", {}) if plugin.context else {}
        if not isinstance(ranks, dict):
            ranks = {}

        known_groups: set[str] = set()
        group_names: dict[str, str] = {}

        def add_group(value: object, name: object = "") -> None:
            key = str(value or "").strip()
            if not re.fullmatch(r"\d{5,}", key):
                return
            known_groups.add(key)
            label = str(name or "").strip()
            if label:
                group_names[key] = label

        for item in self.group_list:
            if isinstance(item, dict):
                add_group(item.get("group_id"), item.get("name"))
        for key in settings:
            add_group(key)
        for key in ranks:
            add_group(key)
        for key, item in records.items():
            if isinstance(item, dict):
                add_group(item.get("group_id"))
            else:
                add_group(str(key).split(":", 1)[0])
        add_group(group_id)

        groups = sorted(known_groups, key=lambda value: (group_names.get(value, "") or value, value))
        group_key = str(group_id or "").strip() or (groups[0] if groups else "")
        query = ""
        reward_points = service.reward_points(group_key) if group_key else int(plugin.config.get("invite_reward_points", 1) or 1)
        record_rows = service.records(group_key, query=query) if group_key else []
        return {
            "group_id": group_key,
            "groups": groups,
            "group_items": [{"group_id": key, "name": group_names.get(key, "")} for key in groups],
            "enabled": service.enabled(group_key) if group_key else bool(plugin.config.get("invite_points_enabled", True)),
            "reward_points": reward_points,
            "retention_days": service.retention_days(group_key) if group_key else int(plugin.config.get("invite_retention_days", 0) or 0),
            "ranking": service.ranking(group_key, 100) if group_key else [],
            "records": record_rows,
        }

    def save_invites_settings(
        self,
        group_id: str,
        enabled: bool,
        reward_points: int,
        retention_days: int | None = None,
    ) -> dict[str, object]:
        plugin = self._loaded_plugin("invites")
        from xiami_core.plugins.invites import InviteService

        group_key = str(group_id or "").strip()
        if not group_key:
            return {"ok": False, "message": "QQ群号不能为空。", "data": self.invites_snapshot("")}
        service = InviteService(plugin.context)
        service.set_enabled(group_key, bool(enabled))
        service.set_reward_points(group_key, int(reward_points or 1))
        if retention_days is not None:
            service.set_retention_days(group_key, int(retention_days or 0))
        return {"ok": True, "message": f"邀请积分设置已保存：{group_key}", "data": self.invites_snapshot(group_key)}

    def add_invites_record(self, group_id: str, user_id: str, inviter_id: str, points: int | None = None) -> dict[str, object]:
        plugin = self._loaded_plugin("invites")
        from xiami_core.plugins.invites import InviteService

        group_key = str(group_id or "").strip()
        user_key = str(user_id or "").strip()
        inviter_key = str(inviter_id or "").strip()
        if not group_key:
            return {"ok": False, "message": "QQ群号不能为空。", "data": self.invites_snapshot("")}
        if not re.fullmatch(r"\d{5,}", user_key) or not re.fullmatch(r"\d{5,}", inviter_key):
            return {"ok": False, "message": "请输入有效的入群 QQ 和邀请人 QQ。", "data": self.invites_snapshot(group_key)}
        result = InviteService(plugin.context).add_record(group_key, user_key, inviter_key, points, award_points=True)
        message = f"已补录邀请记录：{user_key} <- {inviter_key}，奖励 {result.points} 积分。" if result.rewarded else "补录失败：记录已存在或邀请人无效。"
        return {"ok": bool(result.rewarded), "message": message, "data": self.invites_snapshot(group_key)}

