    def quiz_snapshot(self, group_id: str = "") -> dict[str, object]:
        plugin = self._loaded_plugin("quiz")
        from xiami_core.plugins.quiz import QuizService

        service = QuizService(plugin.context)
        settings = plugin.context.get_state("settings", {}) if plugin.context else {}
        if not isinstance(settings, dict):
            settings = {}
        bank = plugin.context.get_state("quiz_bank", {}) if plugin.context else {}
        if not isinstance(bank, dict):
            bank = {}
        sessions = plugin.context.get_state("quiz_sessions", {}) if plugin.context else {}
        if not isinstance(sessions, dict):
            sessions = {}

        known_groups: set[str] = set()
        group_names: dict[str, str] = {}

        def add_group(value: object, name: object = "") -> None:
            key = str(value or "").strip()
            if not re.fullmatch(r"\d{5,}", key):
                return
            known_groups.add(key)
            label = str(name or "").strip()
            if label:
                group_names[key] = label

        for item in self.group_list:
            if isinstance(item, dict):
                add_group(item.get("group_id"), item.get("name"))
        for key in settings:
            add_group(key)
        for key in bank:
            add_group(key)
        for key in sessions:
            add_group(key)
        add_group(group_id)

        groups = sorted(known_groups, key=lambda value: (group_names.get(value, "") or value, value))
        group_key = str(group_id or "").strip() or (groups[0] if groups else "")
        questions = [
            {
                "id": item.question_id,
                "enabled": bool(item.enabled),
                "category": item.category,
                "question": item.question,
                "answer": item.answer,
                "note": item.note,
            }
            for item in service.list_questions(group_key)
        ] if group_key else []
        session = sessions.get(group_key, {}) if group_key else {}
        if not isinstance(session, dict):
            session = {}
        return {
            "group_id": group_key,
            "groups": groups,
            "group_items": [{"group_id": key, "name": group_names.get(key, "")} for key in groups],
            "enabled": service.enabled(group_key) if group_key else bool(plugin.config.get("quiz_enabled", True)),
            "reward_points": service.reward_points(group_key) if group_key else int(plugin.config.get("quiz_reward_points", 1) or 1),
            "interval_seconds": service.interval_seconds(group_key) if group_key else int(plugin.config.get("quiz_interval_seconds", 0) or 0),
            "answer_timeout_seconds": service.answer_timeout_seconds(group_key) if group_key else int(plugin.config.get("quiz_answer_timeout_seconds", 0) or 0),
            "questions": questions,
            "session": dict(session),
        }

