    def save_quiz_question(
        self,
        group_id: str,
        question_id: str,
        question: str,
        answer: str,
        category: str = "",
        note: str = "",
        enabled: bool = True,
    ) -> dict[str, object]:
        plugin = self._loaded_plugin("quiz")
