        question_id = str(question_id or "").strip()
        if question_id:
            item = service.update_question(
                group_key,
                question_id,
                str(question or ""),
                str(answer or ""),
                category=str(category or ""),
                note=str(note or ""),
                enabled=bool(enabled),
            )
            if item is None:
                return {"ok": False, "message": f"未找到题目 #{question_id}，或题目/答案为空。", "data": self.quiz_snapshot(group_key)}
            return {"ok": True, "message": f"已保存题目 #{item.question_id}。", "data": self.quiz_snapshot(group_key)}
        item = service.add_question(
            group_key,
            str(question or ""),
            str(answer or ""),
            category=str(category or ""),
            note=str(note or ""),
            enabled=bool(enabled),
        )
        if item is None:
            return {"ok": False, "message": "题目和答案不能为空。", "data": self.quiz_snapshot(group_key)}
        return {"ok": True, "message": f"已添加题目 #{item.question_id}。", "data": self.quiz_snapshot(group_key)}

