    def help_menu_snapshot(self) -> dict[str, object]:
        plugin = self._loaded_plugin("help_menu")
        from xiami_core.plugins.notification_templates import normalize_notice_switches, normalize_notice_templates

        default_menu_lines = list(getattr(plugin.module, "DEFAULT_MENU_LINES", []) or ["菜单", "积分 / 积分排行"])
        default_admin_menu_lines = list(getattr(plugin.module, "DEFAULT_ADMIN_MENU_LINES", []) or ["管理员命令："])
        state_settings = plugin.context.get_state("help_menu_settings", {}) if plugin.context else {}
        if not isinstance(state_settings, dict):
            state_settings = {}

        def lines_from_config(key: str, default: list[str]) -> list[str]:
            value = state_settings.get(key, plugin.context.get_config(key, default))
            if isinstance(value, str):
                rows = value.splitlines()
            elif isinstance(value, (list, tuple)):
                rows = [str(item) for item in value]
            else:
                rows = list(default)
            cleaned = [line.rstrip() for line in rows]
            return cleaned or list(default)

        notice_templates_state = plugin.context.get_state("notice_templates", {}) if plugin.context else {}
        if not isinstance(notice_templates_state, dict) or not notice_templates_state:
            notice_templates_state = plugin.context.get_config("notice_templates", {}) if plugin.context else {}
        notice_switches_state = plugin.context.get_state("notice_switches", {}) if plugin.context else {}
        if not isinstance(notice_switches_state, dict) or not notice_switches_state:
            notice_switches_state = plugin.context.get_config("notice_switches", {}) if plugin.context else {}

        return {
            "menu_lines": lines_from_config("menu_lines", default_menu_lines),
            "admin_menu_lines": lines_from_config("admin_menu_lines", default_admin_menu_lines),
            "default_menu_lines": default_menu_lines,
            "default_admin_menu_lines": default_admin_menu_lines,
            "notice_templates": normalize_notice_templates(notice_templates_state),
            "notice_switches": normalize_notice_switches(notice_switches_state),
            "default_notice_templates": normalize_notice_templates({}),
            "default_notice_switches": normalize_notice_switches({}),
        }

    def save_help_menu_settings(
        self,
        menu_text: str,
        admin_menu_text: str,
        notice_switches: dict[str, bool],
        notice_templates: dict[str, str],
    ) -> dict[str, object]:
        loader = self._ensure_loader()
        plugin = self._loaded_plugin("help_menu")
        from xiami_core.plugins.notification_templates import normalize_notice_switches, normalize_notice_templates

        default_menu_lines = list(getattr(plugin.module, "DEFAULT_MENU_LINES", []) or ["菜单", "积分 / 积分排行"])
        default_admin_menu_lines = list(getattr(plugin.module, "DEFAULT_ADMIN_MENU_LINES", []) or ["管理员命令："])

        def parse_lines(text: str, default: list[str]) -> list[str]:
            rows = [line.rstrip() for line in str(text or "").splitlines()]
            rows = [line for line in rows if line.strip()]
            return rows or list(default)

        config = dict(loader.user_config(plugin.id))
        config["menu_lines"] = parse_lines(menu_text, default_menu_lines)
        config["admin_menu_lines"] = parse_lines(admin_menu_text, default_admin_menu_lines)
        config["notice_switches"] = normalize_notice_switches(notice_switches)
        config["notice_templates"] = normalize_notice_templates(notice_templates)
        loader.save_user_config(plugin.id, config)
        loader.reload()
        self.loaded = True
        return {"ok": True, "message": "菜单帮助设置已保存。", "data": self.help_menu_snapshot()}

    def custom_replies_snapshot(self, group_id: str = "", query: str = "") -> dict[str, object]:
        plugin = self._loaded_plugin("custom_replies")
        from xiami_core.plugins.custom_replies import CustomReplyService
        from xiami_core.plugins.group_settings import GroupSettingService

        raw = plugin.context.get_state("custom_replies", {}) if plugin.context else {}
        replies = raw if isinstance(raw, dict) else {}
        known_groups = {str(key) for key in replies if str(key).strip()}
        group_names: dict[str, str] = {}
        for item in self.group_list:
            if not isinstance(item, dict):
                continue
            known_group_id = str(item.get("group_id") or "").strip()
            if not re.fullmatch(r"\d{5,}", known_group_id):
                continue
            known_groups.add(known_group_id)
            group_name = str(item.get("name") or "").strip()
            if group_name:
                group_names[known_group_id] = group_name
        if str(group_id or "").strip():
            known_groups.add(str(group_id or "").strip())
        group_items = [
            {"group_id": key, "name": group_names.get(key, "")}
            for key in sorted(known_groups, key=lambda value: (group_names.get(value, "") or value, value))
        ]
        groups = [item["group_id"] for item in group_items]
        group_key = str(group_id or "").strip() or (groups[0] if groups else "")
        service = CustomReplyService(plugin.context)
        rows = [
            {"keyword": item.keyword, "response": item.response, "match_type": item.match_type, "enabled": bool(item.enabled)}
            for item in service.list(group_key, query)
        ] if group_key else []
        enabled = GroupSettingService(plugin.context).enabled(group_key, "custom_replies_enabled") if group_key else True
        return {
            "group_id": group_key,
            "groups": groups,
            "group_items": group_items,
            "enabled": bool(enabled),
            "query": str(query or "").strip(),
            "replies": rows,
        }

