        self.account_tab = QtWidgets.QWidget()
        self.plugin_tab = QtWidgets.QWidget()
        self.tabs.addTab(self.account_tab, "账号管理")
        self.tabs.addTab(self.plugin_tab, "插件管理")

        self._build_account_tab()
        self._build_plugin_tab()
        self._apply_qq_visual_contract()
        self.tabs.currentChanged.connect(self._sync_tab_primary_actions)
        self._sync_tab_primary_actions(self.tabs.currentIndex())

        self.status_label = QtWidgets.QLabel()
        self.status_label.setObjectName("xiamiBotStatus")
        root.addWidget(self.status_label)

