    def refresh_all(self) -> None:
        if self._dark_workbench_smoke:
            self.account_online = False
            self.plugin_runtime.account_status = {
                "state": "offline",
                "account": "",
                "nickname": "",
                "presence": "offline",
                "presence_label": "离线",
                "detail": "smoke 默认离线",
            }
        else:
            # 页面初次打开只展示本地账号与插件，不主动探测 OneBot HTTP。
            # 如果此时 NapCat 未启动，主动探测会把 socket timeout 写到账户表，
            # 用户看起来像“进入页面即报错”。真实连接检查只在点击“刷新状态”、
            # “扫码登录”或“上线”后执行。
            self.account_online = False
            self.plugin_runtime.account_status = {
                "state": "offline",
                "account": "",
                "nickname": "",
                "presence": "offline",
                "presence_label": "离线",
                "detail": "未上线",
                "login_ok": False,
                "service_ok": False,
                "group_count": 0,
                "groups": [],
                "login_started_at": 0,
                "received_count": 0,
                "sent_count": 0,
            }
        self._refresh_plugins()
        self._refresh_account_table()
        self._update_qr_preview()
        self._refresh_lock_state()
        if self.account_online:
            if not self._account_stats_timer.isActive():
                self._account_stats_timer.start()
            status_text = f"账号已在线；{self._plugin_stats_summary_text()}。"
            if self.plugin_runtime.event_restart_required:
                status_text += " 事件接收地址已更新，请点击“上线”重启内核后再测试收发。"
            self.status_label.setText(status_text)
        else:
            self.status_label.setText(f"QQ机器人已准备就绪；发现 {len(self.all_plugins or self.plugins)} 个插件。")

    @staticmethod
    def _friendly_onebot_detail(detail: object, *, during_login: bool = False) -> str:
        text = str(detail or "").strip()
        lower = text.lower()
        if "timed out" in lower or "timeout" in lower:
            return "登录服务暂未连接；请点击“上线”复用登录态，或点击“扫码登录”重新登录。" if not during_login else "正在等待登录服务响应，请稍候。"
        if "onebot 不可访问" in text or "onebot 未就绪" in text or "napcat 未运行" in text.lower():
            return "QQ机器人未上线；请点击“上线”或“扫码登录”。" if not during_login else "登录服务启动中，正在等待二维码或账号状态。"
        return text or ("正在等待登录服务响应，请稍候。" if during_login else "QQ机器人未上线；请点击“上线”或“扫码登录”。")

    def _refresh_account_table(self) -> None:
        self._refreshing_account_table = True
        self.account_table.setRowCount(0)
        account_status = self.plugin_runtime.account_status
        account = str(account_status.get("account") or "")
        nickname = str(account_status.get("nickname") or "")
        detail = str(account_status.get("detail") or "")
        state = str(account_status.get("state") or ("online" if self.account_online else "offline"))
        if not self.account_online and state in {"offline", "error"}:
            account = ""
        presence_label = str(account_status.get("presence_label") or "")
        presence_key = str(account_status.get("presence") or "")
        if presence_key and hasattr(self, "account_presence_combo"):
            index = self.account_presence_combo.findData(presence_key)
            if index >= 0:
                self.account_presence_combo.setCurrentIndex(index)
        status = presence_label if self.account_online and presence_label else ("在线" if self.account_online else ("连接中" if state == "starting" else ("异常" if state == "error" else "离线")))
        runtime_stats = self.plugin_runtime.account_runtime_stats()
        group_count = max(int(account_status.get("group_count") or 0), int(runtime_stats.get("groups") or 0))
        known_accounts = [] if self._dark_workbench_smoke else self.plugin_runtime.known_napcat_accounts()
        accounts: list[str] = []
        for value in [account, *known_accounts]:
            value = str(value or "").strip()
            if value and value not in accounts:
                accounts.append(value)
        if accounts and (not self.selected_account or self.selected_account not in accounts):
            self.selected_account = account if account in accounts else accounts[0]
        elif account and not self.selected_account:
            self.selected_account = account
        self._refresh_account_selector(accounts)
        received_count = int(runtime_stats.get("received") or 0)
        sent_count = int(runtime_stats.get("sent") or 0)
        login_seconds = int(runtime_stats.get("login_seconds") or 0)
        if not accounts:
            accounts = [""]
        for index, account_id in enumerate(accounts, start=1):
            row = self.account_table.rowCount()
            self.account_table.insertRow(row)
            is_active = bool(self.account_online and account_id and account_id == account)
            is_selected = bool(account_id and account_id == self.selected_account)
            if is_active:
                row_status = status
                row_nickname = nickname or "-"
                safe_center = "在线"
                token_state = "已连接"
                info = self._account_info_text(group_count, received_count, sent_count, login_seconds, active=True)
                action = "已连接"
            elif account_id:
                row_status = "已保存"
                row_nickname = "-"
                safe_center = "-"
                token_state = "可复用"
                info = self._account_info_text(0, 0, 0, 0, active=False)
                action = "已选择" if is_selected else "可上线"
            else:
                row_status = "离线"
                row_nickname = "-"
                safe_center = "-"
                token_state = "-"
                info = self._account_info_text(0, 0, 0, 0, active=False)
                action = "等待登录"
            values = (
                str(index),
                account_id or "未登录",
                row_nickname,
                row_status,
                safe_center,
                token_state,
                info,
                action,
            )
            for col, value in enumerate(values):
                item = QtWidgets.QTableWidgetItem(str(value))
                item.setData(QtCore.Qt.UserRole, account_id)
                if col in (0, 3, 4, 5, 7):
                    item.setTextAlignment(QtCore.Qt.AlignCenter)
                self.account_table.setItem(row, col, item)
            if is_selected:
                self.account_table.selectRow(row)
        self.account_hint.setText(
            "可管理多个已保存账号；选择账号后点击“上线”复用登录态，同一时间仅运行一个账号。"
        )
        self._set_account_presence_enabled(self.account_online)
        self._refreshing_account_table = False

    @staticmethod
    def _format_login_duration(seconds: int) -> str:
        total = max(0, int(seconds or 0))
        days, remainder = divmod(total, 86400)
        hours, remainder = divmod(remainder, 3600)
        minutes, seconds = divmod(remainder, 60)
        if days:
            return f"{days}天 {hours:02d}:{minutes:02d}:{seconds:02d}"
        return f"{hours:02d}:{minutes:02d}:{seconds:02d}"

    def _account_info_text(self, groups: int, received: int, sent: int, login_seconds: int, active: bool) -> str:
        if active:
            duration = self._format_login_duration(login_seconds)
            return f"登录时长 {duration}；QQ群 {int(groups)} 个；接收 {int(received)} 条；发送 {int(sent)} 条"
        return f"未上线；QQ群 {int(groups)} 个；接收 {int(received)} 条；发送 {int(sent)} 条"

    def _plugin_stats_summary_text(self) -> str:
        account_status = self.plugin_runtime.account_status
        stats = self.plugin_runtime.account_runtime_stats()
        group_count = max(int(account_status.get("group_count") or 0), int(stats.get("groups") or 0))
        duration = self._format_login_duration(int(stats.get("login_seconds") or 0))
        plugin_count = len(self.all_plugins or self.plugins)
        return (
            f"插件 {plugin_count} 个；登录 {duration}；"
            f"QQ群 {group_count} 个；接收 {int(stats.get('received') or 0)} 条；发送 {int(stats.get('sent') or 0)} 条"
        )

    def _update_plugin_stats_summary(self) -> None:
        if not hasattr(self, "plugin_lock_label"):
            return
        if self.account_online:
            self.plugin_lock_label.setText(f"账号已登录；{self._plugin_stats_summary_text()}。")
        else:
            self.plugin_lock_label.setText("请先完成账号扫码登录，登录成功后加载插件。")

    def _refresh_account_runtime_stats(self) -> None:
        if not self.account_online:
            if self._account_stats_timer.isActive():
                self._account_stats_timer.stop()
            return
        account_status = self.plugin_runtime.account_status
        account = str(account_status.get("account") or "")
        if not account or self.account_table.rowCount() <= 0:
            self._refresh_account_table()
            return
        stats = self.plugin_runtime.account_runtime_stats()
        group_count = max(int(account_status.get("group_count") or 0), int(stats.get("groups") or 0))
        info = self._account_info_text(
            group_count,
            int(stats.get("received") or 0),
            int(stats.get("sent") or 0),
            int(stats.get("login_seconds") or 0),
            active=True,
        )
        account_status["login_started_at"] = self.plugin_runtime.login_started_at
        account_status["group_count"] = group_count
        account_status["received_count"] = int(stats.get("received") or 0)
        account_status["sent_count"] = int(stats.get("sent") or 0)
        self._update_plugin_stats_summary()
        for row in range(self.account_table.rowCount()):
            account_item = self.account_table.item(row, 1)
            info_item = self.account_table.item(row, 6)
            if not account_item or not info_item:
                continue
            row_account = str(account_item.data(QtCore.Qt.UserRole) or account_item.text()).strip()
            if row_account == account:
                info_item.setText(info)
                return
        self._refresh_account_table()

    def _refresh_account_selector(self, accounts: list[str]) -> None:
        if not hasattr(self, "account_select_combo"):
            return
        current_text = self.account_select_combo.currentText().strip()
        selected = self.selected_account or current_text
        self.account_select_combo.blockSignals(True)
        try:
            self.account_select_combo.clear()
            for account_id in accounts:
                self.account_select_combo.addItem(account_id, account_id)
            index = self.account_select_combo.findData(selected)
            if index >= 0:
                self.account_select_combo.setCurrentIndex(index)
            elif selected:
                self.account_select_combo.setEditText(selected)
            else:
                self.account_select_combo.setEditText("")
        finally:
            self.account_select_combo.blockSignals(False)

    def _selected_account_from_combo(self) -> str:
        if not hasattr(self, "account_select_combo"):
            return ""
        data = str(self.account_select_combo.currentData() or "").strip()
        text = self.account_select_combo.currentText().strip()
        value = data or text
        match = re.search(r"\d{5,}", value)
        return match.group(0) if match else ""

    def _apply_account_selection_from_combo(self) -> None:
        account = self._selected_account_from_combo()
        if not account:
            self.status_label.setText("请输入或选择有效 QQ 号。")
            return
        self.selected_account = account
        for row in range(self.account_table.rowCount()):
            item = self.account_table.item(row, 1)
            if item and str(item.data(QtCore.Qt.UserRole) or item.text()).strip() == account:
                self.account_table.selectRow(row)
                break
        self.status_label.setText(f"已选择 QQ 账号：{account}，点击“上线”复用该账号登录态。")

    def _apply_account_selection_from_table(self) -> None:
        if self._refreshing_account_table:
            return
        row = self.account_table.currentRow()
        if row < 0:
            return
        item = self.account_table.item(row, 1)
        if not item:
            return
        account = str(item.data(QtCore.Qt.UserRole) or item.text()).strip()
        if not re.fullmatch(r"\d{5,}", account):
            return
        self.selected_account = account
        if hasattr(self, "account_select_combo"):
            index = self.account_select_combo.findData(account)
            if index >= 0:
                self.account_select_combo.setCurrentIndex(index)
            else:
                self.account_select_combo.setEditText(account)
        self.status_label.setText(f"已选择 QQ 账号：{account}，点击“上线”复用该账号登录态。")

    def _refresh_plugins(self) -> None:
        selected_plugin_id = ""
        if hasattr(self, "plugin_table"):
            selected_row = self.plugin_table.currentRow()
            if 0 <= selected_row < len(self.plugins):
                selected_plugin_id = str(self.plugins[selected_row].get("id") or "")
        if self.account_online:
            diagnostics = self.plugin_runtime.load() if not self.plugin_runtime.loaded else self.plugin_runtime.diagnostics()
            self.plugin_diagnostics = diagnostics
            plugins = [self._plugin_from_diagnostic(item) for item in diagnostics]
        else:
            self.plugin_diagnostics = []
            plugins = []
            if self.plugin_root.is_dir():
                for plugin_dir in sorted(self.plugin_root.iterdir(), key=lambda p: p.name.lower()):
                    if plugin_dir.is_dir() and (plugin_dir / "plugin.py").is_file():
                        plugins.append(self._read_plugin_metadata(plugin_dir))
        if self.account_online:
            self._refresh_group_context_options()
        if self.account_online and self.current_group_id:
            try:
                group_snapshot = self.plugin_runtime.group_settings_snapshot(self.current_group_id)
                group_plugins = {
                    str(item.get("id") or ""): bool(item.get("enabled", False))
                    for item in group_snapshot.get("plugins", [])
                    if isinstance(item, dict)
                }
                for plugin in plugins:
                    plugin_id = str(plugin.get("id") or "")
                    global_enabled = bool(plugin.get("enabled", True))
                    group_enabled = bool(group_plugins.get(plugin_id, False))
                    plugin["global_enabled"] = global_enabled
                    plugin["group_enabled"] = group_enabled
                    plugin["group_id"] = self.current_group_id
                    if plugin.get("error"):
                        plugin["status"] = "异常"
                    elif not global_enabled:
                        plugin["status"] = "全局停用"
                    else:
                        plugin["status"] = "本群启用" if group_enabled else "本群停用"
            except Exception as exc:
                self.plugin_runtime.last_error = str(exc)
        plugins = [plugin for plugin in plugins if not self._plugin_hidden_from_ui(plugin.get("id"))]
        self.all_plugins = plugins
        self.plugins = self._filtered_plugins(plugins)
        self._populate_plugin_table()
        if selected_plugin_id:
            self._select_plugin_by_id(selected_plugin_id)
        if self.plugin_table.currentRow() < 0 and self.plugins:
            self.plugin_table.selectRow(0)
        self._update_plugin_filter_summary()
        self._update_plugin_detail()

    def _populate_plugin_table(self) -> None:
        self.plugin_table.setRowCount(0)
        for plugin in self.plugins:
            row = self.plugin_table.rowCount()
            self.plugin_table.insertRow(row)
            values = (
                plugin.get("name", ""),
                plugin.get("version", ""),
                plugin.get("status", "待登录加载"),
                "有配置" if plugin.get("has_config") else "默认",
            )
            for col, value in enumerate(values):
                item = QtWidgets.QTableWidgetItem(str(value))
                if col in (1, 2, 3):
                    item.setTextAlignment(QtCore.Qt.AlignCenter)
                self.plugin_table.setItem(row, col, item)

    def _apply_plugin_filter(self) -> None:
        selected_plugin_id = ""
        row = self.plugin_table.currentRow()
        if 0 <= row < len(self.plugins):
            selected_plugin_id = str(self.plugins[row].get("id") or "")
        self.plugins = self._filtered_plugins(self.all_plugins)
        self._populate_plugin_table()
        if selected_plugin_id:
            self._select_plugin_by_id(selected_plugin_id)
        if self.plugin_table.currentRow() < 0 and self.plugins:
            self.plugin_table.selectRow(0)
        self._update_plugin_filter_summary()
        self._update_plugin_detail()

    def _filtered_plugins(self, plugins: list[dict[str, object]]) -> list[dict[str, object]]:
        query = ""
        if hasattr(self, "plugin_filter_edit"):
            query = self.plugin_filter_edit.text().strip()
        if not query:
            return list(plugins)
        tokens = [
            self._normalize_plugin_search(token)
            for token in re.split(r"\s+", query)
            if self._normalize_plugin_search(token)
        ]
        if not tokens:
            return list(plugins)
        result: list[dict[str, object]] = []
        for plugin in plugins:
            haystack = self._plugin_search_haystack(plugin)
            if all(token in haystack for token in tokens):
                result.append(plugin)
        return result

    def _plugin_search_haystack(self, plugin: dict[str, object]) -> str:
        parts: list[str] = [
            str(plugin.get("id") or ""),
            str(plugin.get("name") or ""),
            str(plugin.get("version") or ""),
            str(plugin.get("status") or ""),
            str(plugin.get("description") or ""),
            str(plugin.get("commands_text") or ""),
            str(plugin.get("migration_status") or ""),
            self._plugin_category(plugin),
        ]
        for key in ("commands_list", "capabilities"):
            value = plugin.get(key)
            if isinstance(value, (list, tuple, set)):
                parts.extend(str(item) for item in value)
        admin_schema = plugin.get("admin_schema")
        if isinstance(admin_schema, list):
            for item in admin_schema:
                if isinstance(item, dict):
                    parts.append(str(item.get("label") or item.get("id") or ""))
        return self._normalize_plugin_search(" ".join(parts))

    @staticmethod
    def _normalize_plugin_search(value: object) -> str:
        return "".join(str(value or "").strip().lower().split())

    def _update_plugin_filter_summary(self) -> None:
        if not hasattr(self, "plugin_filter_count_label"):
            return
        total = len(self.all_plugins)
        shown = len(self.plugins)
        query = self.plugin_filter_edit.text().strip() if hasattr(self, "plugin_filter_edit") else ""
        self.plugin_filter_count_label.setText(f"显示 {shown}/{total}")
        if query:
            self.plugin_filter_count_label.setToolTip(f"当前筛选：{query}")
        else:
            self.plugin_filter_count_label.setToolTip("可按插件名称、ID、命令、说明或状态筛选。")

    @staticmethod
    def _plugin_hidden_from_ui(plugin_id: object) -> bool:
        normalized = str(plugin_id or "").strip().lower()
        return normalized in XIAMI_PLUGIN_UI_HIDDEN_IDS or normalized in XIAMI_PRODUCT_MERGED_PLUGIN_IDS

    @staticmethod
    def _product_plugin_name(plugin_id: str, fallback: str) -> str:
        if str(plugin_id or "").strip().lower() == "ai_reply":
            return "AI 知识问答"
        return fallback

    def _plugin_from_diagnostic(self, item: dict[str, object]) -> dict[str, object]:
        plugin_id = str(item.get("id") or "")
        plugin_dir = self.plugin_root / plugin_id
        meta = self._read_plugin_metadata(plugin_dir) if plugin_id else {}
        enabled = bool(item.get("enabled"))
        error = str(item.get("error") or item.get("last_error") or "")
        commands = item.get("commands")
        if isinstance(commands, list) and commands:
            commands_text = " ".join(str(cmd) for cmd in commands[:6])
            commands_list = [str(cmd) for cmd in commands]
        else:
            commands_text = str(meta.get("commands_text") or "-")
            commands_list = []
        status = "异常" if error else ("启用" if enabled else "停用")
        result = dict(meta)
        result.update(
            {
                "id": plugin_id,
                "name": self._product_plugin_name(plugin_id, str(item.get("name") or meta.get("name") or plugin_id)),
                "status": status,
                "enabled": enabled,
                "error": error,
                "commands_text": commands_text,
                "commands_list": commands_list,
                "message_count": item.get("message_count", 0),
                "message_handled_count": item.get("message_handled_count", 0),
                "message_unhandled_count": item.get("message_unhandled_count", 0),
                "event_count": item.get("event_count", 0),
                "event_handled_count": item.get("event_handled_count", 0),
                "event_unhandled_count": item.get("event_unhandled_count", 0),
                "error_count": item.get("error_count", 0),
                "last_error": item.get("last_error", ""),
                "error_history": item.get("error_history", []),
                "matcher_hit_count": item.get("matcher_hit_count", {}),
                "recent_logs": item.get("recent_logs", []),
                "log_file": item.get("log_file", ""),
                "config_schema": item.get("config_schema", []),
                "admin_schema": item.get("admin_schema", []),
                "admin_state_preview": item.get("admin_state_preview", []),
                "capabilities": item.get("capabilities", []),
                "migration_status": item.get("migration_status", ""),
            }
        )
        return result

    def _read_plugin_metadata(self, plugin_dir: Path) -> dict[str, object]:
        script_path = plugin_dir / "plugin.py"
        config_path = plugin_dir / "plugin_config.json"
        result: dict[str, object] = {
            "id": plugin_dir.name,
            "name": self._product_plugin_name(plugin_dir.name, plugin_dir.name),
            "version": "-",
            "description": "",
            "path": str(plugin_dir),
            "has_config": config_path.is_file(),
            "commands_text": "-",
        }
        try:
            source = script_path.read_text(encoding="utf-8")
        except Exception:
            source = ""
        for key, field in (
            ("PLUGIN_NAME", "name"),
            ("PLUGIN_VERSION", "version"),
            ("PLUGIN_DESCRIPTION", "description"),
        ):
            value = self._read_module_constant(source, key)
            if value:
                result[field] = str(value)
        result["name"] = self._product_plugin_name(plugin_dir.name, str(result["name"]))
        commands = sorted(set(re.findall(r"['\"](/[A-Za-z0-9_\\-]+)", source)))
        if commands:
            result["commands_text"] = " ".join(commands[:6])
        return result

    def _read_module_constant(self, source: str, name: str) -> object:
        if not source:
            return None
        try:
            module = ast.parse(source)
        except SyntaxError:
            return None
        for node in module.body:
            if not isinstance(node, ast.Assign):
                continue
            if not any(isinstance(target, ast.Name) and target.id == name for target in node.targets):
                continue
            try:
                return ast.literal_eval(node.value)
            except Exception:
                return None
        return None

    def _known_group_options(self, selected: str = "") -> list[dict[str, str]]:
        preferred = str(selected or "").strip()
        groups: list[dict[str, str]] = []
        seen_groups: set[str] = set()

        def add_group(group_id: object, name: object = "") -> None:
            value = str(group_id or "").strip()
            if not re.fullmatch(r"\d{5,}", value) or value in seen_groups:
                return
            seen_groups.add(value)
            groups.append({"group_id": value, "name": str(name or "").strip()})

        for item in getattr(self.plugin_runtime, "group_list", []) or []:
            if not isinstance(item, dict):
                continue
            add_group(item.get("group_id"), item.get("name"))

        if preferred and not any(item.get("group_id") == preferred for item in groups):
            add_group(preferred)
        return sorted(groups, key=lambda item: (item.get("name") or item.get("group_id") or "", item.get("group_id") or ""))

    def _refresh_group_context_options(self) -> None:
        if not hasattr(self, "group_context_combo") or self._refreshing_group_context:
            return
        self._refreshing_group_context = True
        try:
            selected = self.current_group_id
            groups = self._known_group_options(selected)

            self.group_context_combo.clear()
            for item in groups:
                group_id = str(item.get("group_id") or "").strip()
                if not group_id:
                    continue
                group_name = str(item.get("name") or "").strip()
                label = f"{group_name} ({group_id})" if group_name and group_name != group_id else group_id
                self.group_context_combo.addItem(label, group_id)
            index = self.group_context_combo.findData(selected)
            if index < 0 and groups:
                self.current_group_id = str(groups[0].get("group_id") or "").strip()
                index = self.group_context_combo.findData(self.current_group_id)
            if index >= 0:
                self.group_context_combo.setCurrentIndex(index)
            elif self.account_online:
                self.current_group_id = ""
                self.group_context_combo.addItem("未读取到QQ群", "")
                self.group_context_combo.setCurrentIndex(0)
        finally:
            self._refreshing_group_context = False

    def _group_context_from_combo(self) -> str:
        data = self.group_context_combo.currentData() if hasattr(self, "group_context_combo") else ""
        text = self.group_context_combo.currentText().strip() if hasattr(self, "group_context_combo") else ""
        if text in {"", "未读取到QQ群", "未选择群"}:
            return ""
        value = str(data or "").strip()
        if value:
            return value
        match = re.search(r"\((\d{5,})\)\s*$", text)
        if match:
            return match.group(1)
        return text

    def _group_id_from_combo(self, combo: QtWidgets.QComboBox) -> str:
        data = combo.currentData()
        text = combo.currentText().strip()
        if text in {"", "未读取到QQ群", "未选择群"}:
            return ""
        value = str(data or "").strip()
        if value:
            return value
        match = re.search(r"\((\d{5,})\)\s*$", text)
        if match:
            return match.group(1)
        return text

    def _populate_known_group_combo(
        self,
        combo: QtWidgets.QComboBox,
        selected: str = "",
        *,
        include_empty: bool = False,
        extra_groups=None,
    ) -> None:
        current = str(selected or self._group_id_from_combo(combo)).strip()
        seen: set[str] = set()

        def add_option(group_id: object, group_name: object = "") -> None:
            value = str(group_id or "").strip()
            if not re.fullmatch(r"\d{5,}", value) or value in seen:
                return
            seen.add(value)
            name = str(group_name or "").strip()
            label = f"{name} ({value})" if name and name != value else value
            combo.addItem(label, value)

        combo.blockSignals(True)
        try:
            combo.clear()
            if include_empty:
                combo.addItem("未选择群", "")
            for item in self._known_group_options(current):
                add_option(item.get("group_id"), item.get("name"))
            for item in extra_groups or []:
                if isinstance(item, dict):
                    add_option(item.get("group_id"), item.get("name"))
                else:
                    add_option(item)
            index = combo.findData(current)
            if index < 0 and current:
                combo.addItem(current, current)
                index = combo.findData(current)
            if index >= 0:
                combo.setCurrentIndex(index)
            elif include_empty and combo.count():
                combo.setCurrentIndex(0)
        finally:
            combo.blockSignals(False)

    def _apply_group_context_from_combo(self) -> None:
        if self._refreshing_group_context:
            return
        group_id = self._group_context_from_combo()
        if not group_id:
            self._refresh_group_context_options()
            self.status_label.setText("未读取到可管理的QQ群；请确认账号已登录且 OneBot 能读取群列表。")
            self._update_group_action_labels()
            return
        if group_id and not re.fullmatch(r"\d{5,}", group_id):
            self.status_label.setText("请输入有效 QQ 群号。")
            return
        if group_id == self.current_group_id:
            self._refresh_group_context_options()
            self._update_group_action_labels()
            return
        self.current_group_id = group_id
        self._refresh_plugins()
        self._refresh_lock_state()
        self.status_label.setText(f"已切换到群 {group_id}；启用/停用和插件设置将按当前群处理。")

    def _update_group_action_labels(self) -> None:
        if not hasattr(self, "enable_plugin_button"):
            return
        self.enable_plugin_button.setText("本群启用")
        self.disable_plugin_button.setText("本群停用")
        self.save_plugin_button.setText("本群设置" if self.current_group_id else "插件设置")

    def _refresh_lock_state(self) -> None:
        plugin_enabled = bool(self.account_online)
        self.tabs.setTabEnabled(1, plugin_enabled)
        self._set_plugin_actions_enabled(plugin_enabled)
        if hasattr(self, "account_permissions_button"):
            self.account_permissions_button.setVisible(plugin_enabled)
            self.account_permissions_button.setEnabled(plugin_enabled)
        if plugin_enabled:
            self._update_plugin_stats_summary()
            group_text = f"当前群 {self.current_group_id}" if self.current_group_id else "未读取到QQ群"
            self.group_context_combo.setToolTip(f"插件管理上下文：{group_text}")
        else:
            self._update_plugin_stats_summary()
        self._update_group_action_labels()

    def _set_plugin_actions_enabled(self, enabled: bool) -> None:
        for button in (
            self.enable_plugin_button,
            self.disable_plugin_button,
            self.save_plugin_button,
        ):
            button.setEnabled(enabled)
        self.group_context_combo.setEnabled(enabled)
        self.apply_group_context_button.setEnabled(enabled)
        if hasattr(self, "plugin_filter_edit"):
            self.plugin_filter_edit.setEnabled(enabled)

    def populate_smoke_logged_in(self) -> None:
        self.account_online = True
        self.plugin_runtime.login_account = ""
        self.plugin_runtime.login_started_at = time.time() - 65
        self.plugin_runtime.received_message_count = 0
        self.plugin_runtime.sent_messages = []
        self.plugin_runtime.account_status = {
            "state": "online",
            "account": "",
            "nickname": "",
            "detail": "在线态",
            "presence": "online",
            "presence_label": "在线",
            "login_ok": True,
            "service_ok": True,
            "group_count": 0,
            "groups": [],
            "login_started_at": self.plugin_runtime.login_started_at,
            "received_count": self.plugin_runtime.received_message_count,
            "sent_count": len(self.plugin_runtime.sent_messages),
        }
        self.plugin_runtime.group_list = []
        self.current_group_id = ""
        self._refresh_plugins()
        self._refresh_account_table()
        self._refresh_lock_state()
        self.tabs.setCurrentIndex(1)
        if self.plugin_table.rowCount() > 0:
            self.plugin_table.selectRow(0)
        self.status_label.setText(f"账号已登录；已加载 {len(self.all_plugins or self.plugins)} 个插件。")

    def apply_smoke_ui_state(self, state: str) -> None:
        """Select a deterministic, isolated presentation state for screenshot probes."""
        value = str(state or "offline").strip().lower().replace("_", "-")
        if value in {"online", "online-account", "plugin-list", "detail", "filter-empty", "settings"}:
            self.populate_smoke_logged_in()
        else:
            self.account_online = False
            self.refresh_all()
            self.tabs.setCurrentIndex(0)
        if value == "offline-advanced":
            self.account_advanced_toggle.setChecked(True)
        elif value in {"online", "plugin-list", "detail", "settings"}:
            self.tabs.setCurrentIndex(1)
            if self.plugin_table.rowCount() > 0:
                self.plugin_table.selectRow(0)
        elif value == "online-account":
            self.tabs.setCurrentIndex(0)
        elif value == "filter-empty":
            self.tabs.setCurrentIndex(1)
            self.plugin_filter_edit.setText("no-such-plugin-token")
        self._sync_tab_primary_actions()
        self._update_plugin_detail()

    def _set_account_presence_enabled(self, enabled: bool) -> None:
        if hasattr(self, "account_presence_combo"):
            self.account_presence_combo.setEnabled(bool(enabled))
        if hasattr(self, "set_presence_button"):
            self.set_presence_button.setEnabled(bool(enabled))

    @staticmethod
    def _binding_scope(group_id: str, server_name: str = "") -> str:
        return _XiamiPluginRuntime._binding_scope(group_id, server_name)

    @staticmethod
    def _binding_scope_parts(scope: str, labels: dict[str, str] | None = None) -> tuple[str, str]:
        return _XiamiPluginRuntime._binding_scope_parts(scope, labels)

    def _open_account_permissions_dialog(self) -> None:
        if not self.account_online:
            self.status_label.setText("请先完成 QQ 登录后再管理权限。")
            return
        current_config: dict[str, object] = {}
        try:
            snapshot = self.plugin_runtime.plugin_config_snapshot("permissions")
            value = snapshot.get("current", {}) if isinstance(snapshot, dict) else {}
            if isinstance(value, dict):
                current_config = dict(value)
        except Exception:
            current_config = {}

        account = str(self.plugin_runtime.account_status.get("account") or self.selected_account or "").strip()
        dialog = QtWidgets.QDialog(self)
        dialog.setWindowTitle("QQ机器人权限管理")
        dialog.resize(920, 640)
        dialog.setObjectName("xiamiBotPermissionsDialog")

        root = QtWidgets.QVBoxLayout(dialog)
        root.setContentsMargins(12, 12, 12, 12)
        root.setSpacing(8)

        title = QtWidgets.QLabel(f"权限管理  /  当前账号 {account or '-'}")
        title.setObjectName("sectionTitle")
        root.addWidget(title)

        tabs = QtWidgets.QTabWidget()
        root.addWidget(tabs, 1)

        status = QtWidgets.QLabel()
        status.setObjectName("xiamiDialogStatus")
        root.addWidget(status)

        hidden_config_editor = QtWidgets.QPlainTextEdit(dialog)
        hidden_config_editor.setVisible(False)

        def refresh_admin_snapshot() -> None:
            return

        self._add_permissions_settings_tab(
            tabs,
            status,
            current_config,
            hidden_config_editor,
            refresh_admin_snapshot,
            self.current_group_id,
        )

        bottom = QtWidgets.QHBoxLayout()
        bottom.addStretch(1)
        close_button = _make_ui_action_button("关闭", "secondary")
        close_button.clicked.connect(dialog.accept)
        bottom.addWidget(close_button)
        root.addLayout(bottom)

        dialog.exec_()
        self._refresh_plugins()
        self._refresh_lock_state()

    def _set_account_presence(self) -> None:
        presence = str(self.account_presence_combo.currentData() or "online")
        if presence == "offline":
            self._logout_account()
            return
        if not self.account_online:
            self.status_label.setText("请先完成 QQ 扫码登录后再设置账号状态。")
            return
        result = self.plugin_runtime.set_account_presence(presence)
        data = result.get("data") if isinstance(result, dict) else {}
        if isinstance(data, dict):
            self._apply_account_status(data)
        else:
            self._refresh_account_table()
        self.status_label.setText(str(result.get("message") if isinstance(result, dict) else "账号状态设置完成。"))

    def _save_onebot_connection(self) -> None:
        url = self.onebot_url_edit.text().strip()
        token = self.onebot_token_edit.text().strip()
        kernel_kind, executable, working_dir = self._current_kernel_fields()
        self.plugin_runtime.save_connection(url, token, kernel_kind, executable, working_dir)
        self.onebot_url = self.plugin_runtime.onebot_url
        self.onebot_token = self.plugin_runtime.access_token
        self.onebot_url_edit.setText(self.onebot_url)
        self.status_label.setText(f"OneBot 连接已保存：{self.onebot_url}")

    def _refresh_onebot_account(self) -> None:
        if self._runtime_task_busy("account_refresh"):
            self.status_label.setText("正在刷新 QQ 登录状态，请稍候。")
            return
        url = self.onebot_url_edit.text().strip()
        token = self.onebot_token_edit.text().strip()
        kernel_kind, executable, working_dir = self._current_kernel_fields()
        self._set_login_actions_enabled(False)
        self.status_label.setText("正在刷新 QQ 登录状态...")
        started = self._start_runtime_task(
            "account_refresh",
            lambda: self._refresh_onebot_account_job(url, token, kernel_kind, executable, working_dir),
            self._on_refresh_onebot_account_finished,
        )
        if not started:
            self._set_login_actions_enabled(True)
            self.status_label.setText("正在刷新 QQ 登录状态，请稍候。")

    def _refresh_onebot_account_job(self, url: str, token: str, kernel_kind: str, executable: str, working_dir: str) -> dict[str, object]:
        self.plugin_runtime.save_connection(url, token, kernel_kind, executable, working_dir, arguments=list(self.kernel_arguments))
        if self.plugin_runtime.kernel_manager is not None:
            status = self.plugin_runtime.refresh_kernel_status()
        else:
            status = self.plugin_runtime.refresh_account_status()
        try:
            status["event_url"] = self.plugin_runtime.start_event_gateway()
        except Exception as exc:
            self.plugin_runtime.last_error = f"事件接收网关启动失败：{exc}"
        return status

    def _on_refresh_onebot_account_finished(self, payload: object) -> None:
        self._set_login_actions_enabled(True)
        if not isinstance(payload, dict) or not payload.get("ok"):
            raw_error = payload.get("error") if isinstance(payload, dict) else ""
            error = str(raw_error or "状态刷新失败")
            self.status_label.setText(f"QQ 登录状态刷新失败：{error}")
            return
        status = payload.get("data")
        if not isinstance(status, dict):
            status = {"state": "starting", "detail": "OneBot 状态已刷新"}
        self._apply_account_status(status)
        state = str(status.get("state") or "")
        if state in {"starting", "waiting_qr"}:
            self._start_login_polling()
        else:
            self._stop_login_polling()
        detail = str(status.get("detail") or "OneBot 状态已刷新")
        self.status_label.setText(self._friendly_onebot_detail(detail, during_login=state in {"starting", "waiting_qr"}))

    def _current_kernel_fields(self) -> tuple[str, str, str]:
        kind = self.kernel_kind_combo.currentText().strip() or "NapCat"
        executable = self.kernel_executable_edit.text().strip()
        working_dir = self.kernel_workdir_edit.text().strip()
        return kind, executable, working_dir

    def _default_kernel_package_dir(self) -> str:
        candidates = [
            self.embedded_root / "downloads",
            self.embedded_root / "runtime" / "xiami_v1" / "kernels",
            Path(r"D:\AI程序编辑\QQ机器人\downloads"),
            Path(r"D:\AI程序编辑\QQ机器人\runtime\xiami_v1\kernels"),
            Path(r"D:\AI程序编辑\QQ机器人\xiami_desktop\kernels"),
            self.embedded_root,
        ]
        for candidate in candidates:
            if candidate.exists():
                return str(candidate)
        return os.getcwd()

    def _kernel_package_extra_roots(self) -> list[Path]:
        roots = [
            Path(r"D:\AI程序编辑\QQ机器人\downloads"),
            Path(r"D:\AI程序编辑\QQ机器人\runtime\xiami_v1\kernels"),
            Path(r"D:\AI程序编辑\QQ机器人\xiami_desktop\kernels"),
        ]
        return [root for root in roots if root.exists()]

    def _apply_kernel_config(self, config, reason: str) -> None:
        kind = str(getattr(config, "kind", "") or "NapCat")
        executable = str(getattr(config, "executable", "") or "")
        working_dir = str(getattr(config, "working_dir", "") or "")
        arguments = getattr(config, "arguments", None) or []
        self.kernel_arguments = [str(item) for item in arguments] if isinstance(arguments, list) else []
        index = self.kernel_kind_combo.findText(kind)
        self.kernel_kind_combo.setCurrentIndex(index if index >= 0 else 0)
        self.kernel_executable_edit.setText(os.path.normpath(executable) if executable else "")
        self.kernel_workdir_edit.setText(os.path.normpath(working_dir) if working_dir else "")
        self.plugin_runtime.save_connection(
            self.onebot_url_edit.text().strip(),
            self.onebot_token_edit.text().strip(),
            kind,
            executable,
            working_dir,
            arguments=list(self.kernel_arguments),
        )
        arg_text = f"；参数 {' '.join(self.kernel_arguments)}" if self.kernel_arguments else ""
        if str(reason or "").startswith("已使用内置"):
            self.status_label.setText(str(reason))
        else:
            self.status_label.setText(f"{reason}：{kind} {executable}{arg_text}")
        self._refresh_kernel_environment_notice()

    def _import_kernel_package(self) -> None:
        path, _ = _qt_get_open_file_name(
            self,
            "导入 QQ/NapCat 环境包",
            self._default_kernel_package_dir(),
            "QQ/NapCat 环境包 (*.zip);;ZIP 压缩包 (*.zip)",
        )
        if not path:
            return
        try:
            self.plugin_runtime._prepare_imports()
            from xiami_core.kernels.packages import import_kernel_package

            config = import_kernel_package(Path(path))
            self._apply_kernel_config(config, "QQ/NapCat 环境已导入并自动匹配")
        except Exception as exc:
            self.status_label.setText(f"QQ/NapCat 环境导入失败：{exc}")

    def _auto_match_installed_kernel_environment(self) -> bool:
        """Reuse an imported runtime without exposing manual kernel configuration."""
        if self._kernel_executable_is_usable(self.kernel_executable, self.kernel_working_dir):
            return True
        try:
            config = self._default_bundled_kernel_config()
        except Exception:
            config = None
        if config is None:
            return False
        self._apply_kernel_config(config, "已自动匹配 QQ/NapCat 环境")
        return True

    def _discover_kernel_package(self) -> None:
        try:
            self.plugin_runtime._prepare_imports()
            from xiami_core.kernels.packages import discover_kernel_packages

            packages = discover_kernel_packages(self._kernel_package_extra_roots())
        except Exception as exc:
            self.status_label.setText(f"发现内核包失败：{exc}")
            return
        if not packages:
            self.status_label.setText("未发现内核包；可点击“导入包”选择 NapCat/Lagrange zip 或启动文件。")
            return
        menu = QtWidgets.QMenu(self)
        for package in packages[:24]:
            text = f"{package.kind} - {package.path.name}"
            action = menu.addAction(text)
            action.setToolTip(str(package.path))
            action.triggered.connect(lambda _checked=False, item=package: self._use_discovered_kernel_package(item))
        if len(packages) > 24:
            more = menu.addAction(f"另有 {len(packages) - 24} 个结果未显示")
            more.setEnabled(False)
        button = self.discover_kernel_button
        menu.exec_(button.mapToGlobal(QtCore.QPoint(0, button.height())))

    def _use_discovered_kernel_package(self, package) -> None:
        try:
            self.plugin_runtime._prepare_imports()
            from xiami_core.kernels.packages import config_from_entry, import_kernel_package
            from xiami_core.storage.paths import KERNEL_HOME

            path = Path(package.path)
            source = Path(str(package.source))
            try:
                in_kernel_home = path.resolve().is_relative_to(KERNEL_HOME.resolve())
            except AttributeError:
                in_kernel_home = str(path.resolve()).lower().startswith(str(KERNEL_HOME.resolve()).lower())
            if path.suffix.lower() == ".zip" or not in_kernel_home or source.resolve() != KERNEL_HOME.resolve():
                import_source = self._discovered_kernel_import_source(path, source)
                config = import_kernel_package(import_source)
                reason = "内核包已导入"
            else:
                config = config_from_entry(str(package.kind), path)
                reason = "已选择运行时内核"
            self._apply_kernel_config(config, reason)
        except Exception as exc:
            self.status_label.setText(f"内核包选择失败：{exc}")

    def _discovered_kernel_import_source(self, path: Path, source: Path) -> Path:
        if path.suffix.lower() == ".zip" or path.parent == source:
            return path
        try:
            relative = path.resolve().relative_to(source.resolve())
        except Exception:
            return path
        parts = relative.parts
        if not parts:
            return path
        if len(parts) > 1 and parts[0].lower() == "imported":
            package_root = source / parts[0] / parts[1]
            return package_root if package_root.exists() else path
        package_root = source / parts[0]
        return package_root if package_root.exists() else path

    def _kernel_executable_is_usable(self, executable: str, working_dir: str = "") -> bool:
        text = str(executable or "").strip()
        if not text:
            return False
        path = Path(text)
        if path.parent != Path("."):
            return path.exists()
        if working_dir:
            local = Path(working_dir) / text
            if local.exists():
                return True
        return shutil.which(text) is not None

    def _has_qq_kernel_environment(self) -> bool:
        executable_edit = getattr(self, "kernel_executable_edit", None)
        workdir_edit = getattr(self, "kernel_workdir_edit", None)
        executable = executable_edit.text().strip() if executable_edit is not None else self.kernel_executable
        working_dir = workdir_edit.text().strip() if workdir_edit is not None else self.kernel_working_dir
        if self._kernel_executable_is_usable(executable, working_dir):
            return True
        candidates = (
            self.runtime_root / "kernels" / "NapCat.Shell.Windows" / "napcat.bat",
            self.runtime_root / "kernels" / "NapCat.Shell.Windows" / "napcat" / "NapCatWinBootMain.exe",
            self.runtime_root / "kernels" / "Lagrange.OneBot" / "Lagrange.OneBot.exe",
            self.runtime_root / "kernels" / "Lagrange.OneBot" / "Lagrange.OneBot.dll",
        )
        return any(path.is_file() for path in candidates)

    def _refresh_kernel_environment_notice(self) -> None:
        notice = getattr(self, "kernel_environment_notice", None)
        if notice is None:
            return
        notice.setVisible(not self._has_qq_kernel_environment())

    def _default_bundled_kernel_config(self):
        self.plugin_runtime._prepare_imports()
        from xiami_core.kernels.packages import config_from_entry

        if self.plugin_runtime._prefer_napcat_winboot():
            winboot_config = self.plugin_runtime._napcat_winboot_kernel_config()
            if winboot_config is not None:
                return winboot_config

        candidates = [
            ("NapCat", self.runtime_root / "kernels" / "NapCat.Shell.Windows" / "napcat.bat"),
            ("NapCat", self.runtime_root / "kernels" / "NapCat.Shell.Windows" / "napcat" / "NapCatWinBootMain.exe"),
            ("Lagrange", self.runtime_root / "kernels" / "Lagrange.OneBot" / "Lagrange.OneBot.exe"),
            ("Lagrange", self.runtime_root / "kernels" / "Lagrange.OneBot" / "Lagrange.OneBot.dll"),
        ]
        for kind, entry in candidates:
            if entry.exists():
                return config_from_entry(kind, entry)
        return None

    def _kernel_package_rank(self, package) -> tuple[int, str]:
        path = Path(package.path)
        name = path.name.lower()
        full = str(path).lower()
        kind = str(package.kind or "").lower()
        if kind == "napcat" and name == "napcat.bat" and "node" in full:
            rank = 0
        elif kind == "napcat" and name == "napcatwinbootmain.exe" and "node" in full:
            rank = 1
        elif kind == "napcat" and name == "napcat.bat" and "onekey" not in full:
            rank = 2
        elif kind == "napcat" and "napcat." in full and ".shell" in full:
            rank = 3
        elif kind == "lagrange":
            rank = 8
        elif kind == "napcat":
            rank = 20
        else:
            rank = 50
        return rank, full

    def _config_from_kernel_package(self, package):
        self.plugin_runtime._prepare_imports()
        from xiami_core.kernels.packages import config_from_entry, import_kernel_package
        from xiami_core.storage.paths import KERNEL_HOME

        path = Path(package.path)
        source = Path(str(package.source))
        try:
            in_kernel_home = path.resolve().is_relative_to(KERNEL_HOME.resolve())
        except AttributeError:
            in_kernel_home = str(path.resolve()).lower().startswith(str(KERNEL_HOME.resolve()).lower())
        if path.suffix.lower() == ".zip" or not in_kernel_home or source.resolve() != KERNEL_HOME.resolve():
            import_source = self._discovered_kernel_import_source(path, source)
            return import_kernel_package(import_source), f"已自动导入真实内核：{import_source}"
        return config_from_entry(str(package.kind), path), f"已自动选择真实内核：{path}"

    def _prepare_real_kernel_for_scan_login(self) -> bool:
        kernel_kind, executable, working_dir = self._current_kernel_fields()
        if (
            kernel_kind == "NapCat"
            and self.plugin_runtime._is_napcat_registry_launcher(executable)
            and not self.plugin_runtime._prefer_napcat_winboot()
        ):
            shell_config = self.plugin_runtime._napcat_shell_kernel_config([])
            if shell_config is not None:
                self._apply_kernel_config(shell_config, "已切换到内置 QQ 登录内核")
                return True
        if self._kernel_executable_is_usable(executable, working_dir):
            self.plugin_runtime.save_connection(
                self.onebot_url_edit.text().strip(),
                self.onebot_token_edit.text().strip(),
                kernel_kind,
                executable,
                working_dir,
                arguments=list(self.kernel_arguments),
            )
            return True
        try:
            default_config = self._default_bundled_kernel_config()
        except Exception:
            default_config = None
        if default_config is not None:
            self._apply_kernel_config(default_config, "已使用内置 QQ 登录内核")
            return True
        try:
            self.plugin_runtime._prepare_imports()
            from xiami_core.kernels.packages import discover_kernel_packages

            packages = discover_kernel_packages(self._kernel_package_extra_roots())
        except Exception as exc:
            self.status_label.setText(f"自动发现真实内核失败：{exc}")
            return False
        if not packages:
            self.status_label.setText("请先点击“导入环境”导入 QQ/NapCat 环境包，再扫码登录。")
            return False
        errors: list[str] = []
        for package in sorted(packages, key=self._kernel_package_rank):
            try:
                config, reason = self._config_from_kernel_package(package)
                self._apply_kernel_config(config, reason)
                return True
            except Exception as exc:
                errors.append(f"{Path(package.path).name}: {exc}")
                continue
        detail = "；".join(errors[:3]) if errors else "没有可用候选"
        self.status_label.setText(f"自动准备真实内核失败：{detail}")
        return False

    def _pick_kernel_executable(self) -> None:
        start = self.kernel_executable_edit.text().strip() or os.getcwd()
        path, _ = _qt_get_open_file_name(
            self,
            "选择 QQ 机器人内核启动程序",
            start,
            "启动程序 (*.exe *.bat *.cmd);;所有文件 (*.*)",
        )
        if not path:
            return
        self.kernel_arguments = []
        self.plugin_runtime.kernel_arguments = []
        self.kernel_executable_edit.setText(os.path.normpath(path))
        if not self.kernel_workdir_edit.text().strip():
            self.kernel_workdir_edit.setText(os.path.dirname(os.path.normpath(path)))

    def _pick_kernel_workdir(self) -> None:
        start = self.kernel_workdir_edit.text().strip() or os.path.dirname(self.kernel_executable_edit.text().strip()) or os.getcwd()
        path = _qt_get_existing_dir(self, "选择机器人内核工作目录", start)
        if path:
            self.kernel_workdir_edit.setText(os.path.normpath(path))

    def _update_qr_preview(self, status: dict[str, object] | None = None) -> None:
        status = status or self.plugin_runtime.account_status
        state = str(status.get("state") or "").strip()
        qr_hint = str(status.get("qr_hint") or "").strip()
        should_show = state in {"starting", "waiting_qr"} or (bool(qr_hint) and state != "online")
        self.qr_panel.setVisible(should_show)
        if not should_show:
            self.qr_image_label.setPixmap(QtGui.QPixmap())
            self.qr_image_label.setText("等待二维码")
            self.qr_title_label.setText("扫码登录")
            self.qr_hint_label.setText("选择账号后点击“扫码登录”或“上线”。")
            return

        if qr_hint and os.path.isfile(qr_hint):
            pixmap = QtGui.QPixmap(qr_hint)
            if not pixmap.isNull():
                self.qr_image_label.setText("")
                self.qr_image_label.setPixmap(
                    pixmap.scaled(
                        self.qr_image_label.size(),
                        QtCore.Qt.KeepAspectRatio,
                        QtCore.Qt.SmoothTransformation,
                    )
                )
                self.qr_title_label.setText("扫码登录二维码")
                self.qr_hint_label.setText("请使用 QQ 扫描二维码；登录成功后插件页会自动解锁。")
                return

        self.qr_image_label.setPixmap(QtGui.QPixmap())
        self.qr_image_label.setText("等待二维码" if not qr_hint else "登录提示")
        self.qr_title_label.setText("扫码登录状态")
        self.qr_hint_label.setText("正在等待内核返回二维码；如长时间无响应，请重新点击扫码登录。")

    def _apply_account_status(self, status: dict[str, object]) -> None:
        self.account_online = str(status.get("state") or "") == "online"
        self._refresh_plugins()
        self._refresh_account_table()
        self._update_qr_preview(status)
        self._refresh_lock_state()
        self._set_account_presence_enabled(self.account_online)
        if self.account_online:
            if not self._account_stats_timer.isActive():
                self._account_stats_timer.start()
        elif self._account_stats_timer.isActive():
            self._account_stats_timer.stop()

    def _start_login_polling(self) -> None:
        self._login_poll_attempts = 0
        if not self._login_poll_timer.isActive():
            self._login_poll_timer.start()
        try:
            QtCore.QTimer.singleShot(250, self._poll_login_status)
        except Exception:
            pass

    def _stop_login_polling(self) -> None:
        if self._login_poll_timer.isActive():
            self._login_poll_timer.stop()

    def _poll_login_status(self) -> None:
        if self._runtime_task_busy("login_status"):
            return
        if self.plugin_runtime.kernel_manager is None and not self._runtime_task_busy("login_start"):
            self._stop_login_polling()
            return
        self._login_poll_attempts += 1
        started = self._start_runtime_task("login_status", self.plugin_runtime.refresh_kernel_status, self._on_poll_login_status_finished)
        if not started:
            return

    def _on_poll_login_status_finished(self, payload: object) -> None:
        if not isinstance(payload, dict) or not payload.get("ok"):
            raw_error = payload.get("error") if isinstance(payload, dict) else ""
            error = str(raw_error or "OneBot 状态刷新失败")
            previous = self.plugin_runtime.account_status if isinstance(self.plugin_runtime.account_status, dict) else {}
            status = dict(previous)
            status["state"] = str(status.get("state") or "starting")
            status["detail"] = f"等待 OneBot 响应：{error}"
        else:
            status = payload.get("data")
        if not isinstance(status, dict):
            status = {"state": "starting", "detail": "正在等待 OneBot 返回登录状态"}
        self._apply_account_status(status)
        state = str(status.get("state") or "")
        detail = str(status.get("detail") or "")
        qr_hint = str(status.get("qr_hint") or "")
        if state == "online":
            self._stop_login_polling()
            self.status_label.setText(f"{detail or '账号已登录'}；插件页已解锁。")
            return
        # NapCat 启动和扫码期间，HTTP 端口会短暂 timeout/不可访问。
        # 不要因为一次 error/offline 就停止轮询，否则用户扫码后界面看起来“无反应”。
        if self._login_poll_attempts >= self._login_poll_max_attempts:
            self._stop_login_polling()
            self.status_label.setText("扫码登录等待超时；可检查内核窗口、OneBot 地址或重新扫码登录。")
            return
        suffix = f"；二维码：{qr_hint}" if qr_hint else ""
        self.status_label.setText(f"{self._friendly_onebot_detail(detail, during_login=True) or '等待扫码登录'}{suffix}")

    def _run_receive_diagnostic(self) -> None:
        self.status_label.setText("诊断输出已从账号页隐藏。")

    def _show_recent_events(self) -> None:
        self.status_label.setText("事件日志已从账号页隐藏。")

    def _run_real_acceptance(self) -> None:
        url = self.onebot_url_edit.text().strip()
        token = self.onebot_token_edit.text().strip()
        kernel_kind, executable, working_dir = self._current_kernel_fields()
        self.plugin_runtime.save_connection(
            url,
            token,
            kernel_kind,
            executable,
            working_dir,
            arguments=list(self.kernel_arguments),
        )
        self.status_label.setText("闭环验收已从账号页隐藏。")

    def _start_scan_login(self) -> None:
        if self._runtime_task_busy("login_start"):
            self.status_label.setText("正在启动 QQ 扫码登录，请稍候。")
            return
        if not self._prepare_real_kernel_for_scan_login():
            return
        url = self.onebot_url_edit.text().strip()
        token = self.onebot_token_edit.text().strip()
        kernel_kind, executable, working_dir = self._current_kernel_fields()
        if not self._kernel_executable_is_usable(executable, working_dir):
            self.status_label.setText("请先选择可用的 NapCat/Lagrange 启动程序，再扫码登录。")
            return
        # 扫码登录始终按“新登录”处理，不携带下拉框里已删除/旧保存账号。
        # 已保存账号复用只走“上线”按钮。
        target_account = ""
        self._stop_login_polling()
        self._set_login_actions_enabled(False)
        self.status_label.setText("正在启动 QQ 登录服务，请稍候；二维码生成后会自动显示。")
        self.qr_panel.setVisible(True)
        self.qr_image_label.setPixmap(QtGui.QPixmap())
        self.qr_image_label.setText("等待二维码")
        self.qr_title_label.setText("扫码登录状态")
        self.qr_hint_label.setText("正在启动登录服务，请稍候。")
        started = self._start_runtime_task(
            "login_start",
            lambda: self.plugin_runtime.start_kernel_login(
                url,
                token,
                kernel_kind,
                executable,
                working_dir,
                arguments=list(self.kernel_arguments),
                account=target_account,
            ),
            self._on_start_scan_login_finished,
        )
        if not started:
            self._set_login_actions_enabled(True)
            self.status_label.setText("扫码登录正在启动中，请勿重复点击。")

    def _on_start_scan_login_finished(self, payload: object) -> None:
        self._set_login_actions_enabled(True)
        if not isinstance(payload, dict) or not payload.get("ok"):
            raw_error = payload.get("error") if isinstance(payload, dict) else ""
            error = str(raw_error or "启动失败")
            status = {"state": "error", "detail": f"扫码登录启动失败：{self._friendly_onebot_detail(error, during_login=True)}"}
            self.plugin_runtime.account_status = status
            self._apply_account_status(status)
            self._stop_login_polling()
            self.status_label.setText(str(status.get("detail") or "扫码登录启动失败。"))
            return
        status = payload.get("data")
        if not isinstance(status, dict):
            status = {"state": "starting", "detail": "内核已启动，正在等待二维码或登录状态"}
        self._apply_account_status(status)
        state = str(status.get("state") or "")
        if state in {"starting", "waiting_qr"}:
            self._start_login_polling()
        elif state == "online":
            self._stop_login_polling()
            self.status_label.setText(str(status.get("detail") or "账号已登录；插件页已解锁。"))
            return
        else:
            self._stop_login_polling()
        detail = self._friendly_onebot_detail(str(status.get("detail") or "内核已启动"), during_login=state in {"starting", "waiting_qr"})
        qr_hint = str(status.get("qr_hint") or "")
        if qr_hint:
            detail = f"{detail}；二维码：{qr_hint}"
        self.status_label.setText(detail)

    def _quick_online_account(self) -> None:
        if self._runtime_task_busy("quick_online"):
            self.status_label.setText("正在尝试复用登录态上线，请稍候。")
            return
        if not self._prepare_real_kernel_for_scan_login():
            return
        url = self.onebot_url_edit.text().strip()
        token = self.onebot_token_edit.text().strip()
        kernel_kind, executable, working_dir = self._current_kernel_fields()
        if not self._kernel_executable_is_usable(executable, working_dir):
            self.status_label.setText("请先选择可用的 NapCat/Lagrange 启动程序，再点击上线。")
            return
        account = self._selected_account_from_combo() or self.selected_account
        if not account:
            account = str(self.plugin_runtime.account_status.get("account") or "").strip()
        if not account:
            known_accounts = self.plugin_runtime.known_napcat_accounts()
            account = known_accounts[0] if known_accounts else ""
        if account:
            self.selected_account = account
        self._stop_login_polling()
        self._set_login_actions_enabled(False)
        self.status_label.setText("正在复用本机 QQ 登录态上线...")
        started = self._start_runtime_task(
            "quick_online",
            lambda: self._quick_online_account_job(url, token, kernel_kind, executable, working_dir, account),
            self._on_quick_online_account_finished,
        )
        if not started:
            self._set_login_actions_enabled(True)
            self.status_label.setText("正在尝试复用登录态上线，请稍候。")

    def _quick_online_account_job(
        self,
        url: str,
        token: str,
        kernel_kind: str,
        executable: str,
        working_dir: str,
        account: str,
    ) -> dict[str, object]:
        self.plugin_runtime.save_connection(
            url,
            token,
            kernel_kind,
            executable,
            working_dir,
            arguments=list(self.kernel_arguments),
        )
        quick_config = self.plugin_runtime.napcat_quick_login_config(account) if kernel_kind == "NapCat" else None
        persist_config = self.plugin_runtime._napcat_shell_kernel_config([]) if kernel_kind == "NapCat" else None
        normal_config = self.plugin_runtime._kernel_config()
        if kernel_kind == "NapCat" and quick_config is None:
            raise RuntimeError("未找到可复用的 QQ 登录账号；请先扫码登录一次。")
        manager = self.plugin_runtime._ensure_kernel_manager()
        launch_config = quick_config or normal_config
        status_obj = manager.set_kernel(launch_config)
        if str(getattr(status_obj, "state", "") or "") != "error":
            self.plugin_runtime.ensure_event_channel()
            status_obj = manager.start_login(account)
        save_config = persist_config or launch_config
        self.plugin_runtime.save_connection(
            url,
            token,
            str(getattr(save_config, "kind", "") or kernel_kind),
            str(getattr(save_config, "executable", "") or executable),
            str(getattr(save_config, "working_dir", "") or working_dir),
            arguments=list(getattr(save_config, "arguments", None) or []),
        )
        status = self.plugin_runtime._status_to_dict(status_obj)
        self.plugin_runtime.account_status = status
        return {"status": status, "account": account}

    def _on_quick_online_account_finished(self, payload: object) -> None:
        self._set_login_actions_enabled(True)
        if not isinstance(payload, dict) or not payload.get("ok"):
            raw_error = payload.get("error") if isinstance(payload, dict) else ""
            error = str(raw_error or "上线失败")
            self.status_label.setText(self._friendly_onebot_detail(error, during_login=True))
            return
        data = payload.get("data")
        status = data.get("status") if isinstance(data, dict) else {}
        account = str(data.get("account") or "") if isinstance(data, dict) else ""
        if not isinstance(status, dict):
            status = {"state": "starting", "detail": "已尝试复用本机登录态上线"}
        self._apply_account_status(status)
        state = str(status.get("state") or "")
        if state in {"online", "starting", "waiting_qr"}:
            self._start_login_polling()
        else:
            self._stop_login_polling()
        detail = self._friendly_onebot_detail(str(status.get("detail") or "已尝试复用本机登录态上线"), during_login=state in {"starting", "waiting_qr"})
        qr_hint = str(status.get("qr_hint") or "")
        if state == "online":
            self.status_label.setText(f"{detail}；已复用账号 {account or '-'} 的本机登录态上线。")
        elif qr_hint:
            self.status_label.setText(f"{detail}；账号 {account or '-'} 的登录态需要重新验证，请扫码：{qr_hint}")
        else:
            account_suffix = f"账号 {account} " if account else ""
            self.status_label.setText(f"{detail}；正在等待 {account_suffix}恢复登录态。")

    def _delete_saved_account(self) -> None:
        account = self._selected_account_from_combo() or self.selected_account
        if not re.fullmatch(r"\d{5,}", str(account or "").strip()):
            self.status_label.setText("请先选择要删除的 QQ 账号。")
            return
        account = str(account).strip()
        active_account = str(self.plugin_runtime.account_status.get("account") or "").strip()
        is_active = bool(self.account_online and active_account == account)
        message = f"确定删除账号 {account} 的本机登录配置吗？\n删除后再次上线需要重新扫码。"
        if is_active:
            message = f"账号 {account} 当前在线，删除前会先退出登录。\n删除后再次上线需要重新扫码。"
        answer = QtWidgets.QMessageBox.question(
            self,
            "删除账号",
            message,
            QtWidgets.QMessageBox.Yes | QtWidgets.QMessageBox.No,
            QtWidgets.QMessageBox.No,
        )
        if answer != QtWidgets.QMessageBox.Yes:
            return
        self._stop_login_polling()
        self.plugin_runtime.stop_kernel()
        self.account_online = False
        result = self.plugin_runtime.delete_napcat_account(account)
        if result.get("ok"):
            remaining = [item for item in self.plugin_runtime.known_napcat_accounts() if item != account]
            self.selected_account = remaining[0] if remaining else ""
            if hasattr(self, "account_select_combo"):
                self.account_select_combo.blockSignals(True)
                try:
                    self.account_select_combo.clear()
                    for account_id in remaining:
                        self.account_select_combo.addItem(account_id, account_id)
                    if remaining:
                        self.account_select_combo.setCurrentIndex(0)
                    else:
                        self.account_select_combo.setEditText("")
                finally:
                    self.account_select_combo.blockSignals(False)
        self._refresh_plugins()
        self._refresh_account_table()
        self._update_qr_preview()
        self._refresh_lock_state()
        self.status_label.setText(str(result.get("message") or "账号删除已处理。"))

    def _logout_account(self) -> None:
        self._stop_login_polling()
        status = self.plugin_runtime.stop_kernel()
        self.account_online = False
        self._refresh_plugins()
        self._refresh_account_table()
        self._update_qr_preview(status)
        self._refresh_lock_state()
        self.status_label.setText(str(status.get("detail") or "已停止内核并退出账号状态；插件页已锁定。"))

    def _update_plugin_detail(self) -> None:
        row = self.plugin_table.currentRow()
        if row < 0 or row >= len(self.plugins):
            self._update_group_action_labels()
            query = self.plugin_filter_edit.text().strip() if hasattr(self, "plugin_filter_edit") else ""
            if query and self.all_plugins:
                self.plugin_detail.setHtml(
                    "<div style='font-size:14px;color:#5D6876;padding:12px;'>"
                    f"没有匹配“{html.escape(query)}”的插件；可按插件名称、ID、命令、说明或状态筛选。"
                    "</div>"
                )
                return
            self.plugin_detail.setHtml(
                "<div style='font-size:14px;color:#5D6876;padding:12px;'>选择插件后查看功能、命令和配置。</div>"
            )
            return
        plugin = self.plugins[row]
        plugin_id = str(plugin.get("id") or "").lower()
        status = str(plugin.get("status") or "待登录加载")
        status_color = "#27845A" if status in {"启用", "本群启用"} else ("#B83A32" if status == "异常" else "#5D6876")
        commands = self._plugin_commands_for_display(plugin, limit=12)
        command_html = "".join(
            f"<div style='border-bottom:1px solid #E6EAEF;padding:5px 2px;margin:0;background:#F7F8FA;'>{html.escape(command)}</div>"
            for command in commands
        ) or "<span style='color:#87919D;'>暂无公开命令</span>"
        description = html.escape(self._plugin_description_for_display(plugin))
        category = html.escape(self._plugin_category(plugin))
        if plugin_id == "ai_reply":
            description = html.escape("整合 AI 问答、本地知识库检索、知识导入和区服资料增强回复。")
        if self.current_group_id:
            group_state = "响应" if bool(plugin.get("group_enabled", False)) else "不响应"
            group_html = (
                f"<tr><td style='color:#5D6876;'>当前群</td>"
                f"<td>{html.escape(self.current_group_id)} · {group_state}</td></tr>"
            )
            action_hint = "当前已选择群；“本群启用 / 本群停用”只控制该群内此插件是否响应消息。"
        else:
            group_html = "<tr><td style='color:#5D6876;'>当前群</td><td>未读取到QQ群</td></tr>"
            action_hint = "未选择群；请先登录并读取QQ群，再按群管理插件响应。"
        if plugin_id == "permissions":
            action_hint = "权限由账号管理页“权限管理”统一维护；双击本行也会打开同一入口。"
            if hasattr(self, "save_plugin_button"):
                self.save_plugin_button.setText("权限管理")
        else:
            self._update_group_action_labels()
        message_count = self._plugin_metric(plugin.get("message_count"))
        message_handled = self._plugin_metric(plugin.get("message_handled_count"))
        message_unhandled = self._plugin_metric(plugin.get("message_unhandled_count"))
        event_count = self._plugin_metric(plugin.get("event_count"))
        event_handled = self._plugin_metric(plugin.get("event_handled_count"))
        event_unhandled = self._plugin_metric(plugin.get("event_unhandled_count"))
        error_count = self._plugin_metric(plugin.get("error_count"))
        error_text = self._plugin_short_text(plugin.get("last_error") or plugin.get("error"), 120)
        error_html = ""
        if error_count or error_text:
            error_html = (
                "<tr><td style='color:#5D6876;'>异常</td>"
                f"<td style='color:#B83A32;'>次数 {error_count}"
                + (f" · {html.escape(error_text)}" if error_text else "")
                + "</td></tr>"
            )
        self.plugin_detail.setHtml(
            "<div style='font-family:Segoe UI,Microsoft YaHei UI;font-size:13px;color:#17202A;padding:12px;'>"
            f"<div style='font-size:18px;font-weight:700;margin-bottom:4px;'>{html.escape(str(plugin.get('name') or ''))}</div>"
            f"<div style='color:#5D6876;margin-bottom:12px;'>{category} · v{html.escape(str(plugin.get('version') or '-'))}</div>"
            f"<div style='line-height:1.6;margin-bottom:14px;'>{description}</div>"
            "<table cellspacing='0' cellpadding='6' style='width:100%;border-collapse:collapse;margin-bottom:14px;'>"
            f"<tr><td style='color:#5D6876;width:72px;'>状态</td><td style='font-weight:600;color:{status_color};'>{html.escape(status)}</td></tr>"
            f"{group_html}"
            f"<tr><td style='color:#5D6876;'>消息</td><td>收到 {message_count} 条；处理 {message_handled}；未匹配 {message_unhandled}</td></tr>"
            f"<tr><td style='color:#5D6876;'>事件</td><td>收到 {event_count} 条；处理 {event_handled}；未匹配 {event_unhandled}</td></tr>"
            f"{error_html}"
            "</table>"
            "<div style='font-weight:700;margin-bottom:8px;'>常用命令</div>"
            f"<div style='margin-bottom:12px;'>{command_html}</div>"
            "<div style='color:#5D6876;line-height:1.6;'>"
            f"{html.escape(action_hint)} 使用“插件设置”管理功能参数。"
            "</div>"
            "</div>"
        )

    @staticmethod
    def _plugin_metric(value: object) -> int:
        try:
            return int(value or 0)
        except (TypeError, ValueError):
            return 0

    @staticmethod
    def _plugin_short_text(value: object, limit: int = 120) -> str:
        text = " ".join(str(value or "").split())
        if len(text) <= limit:
            return text
        return text[: max(0, limit - 1)] + "…"

    def _plugin_category(self, plugin: dict[str, object]) -> str:
        plugin_id = str(plugin.get("id") or "").lower()
        name = str(plugin.get("name") or "")
        if plugin_id == "ai_reply":
            return "AI 与知识库"
        if plugin_id in {"permissions", "member_guard", "moderation", "friend_review", "join_review"}:
            return "风控与审核"
        if plugin_id in {"checkin", "quiz", "invites", "cards"}:
            return "积分与活动"
        if plugin_id in {"ai_reply", "knowledge", "custom_replies", "help_menu"}:
            return "内容与回复"
        if plugin_id in {"onebot_tools"}:
            return "OneBot 工具"
        if plugin_id in {"bindings", "group_settings"}:
            return "运营配置"
        if "echo" in plugin_id or "case" in plugin_id:
            return "测试工具"
        return name or "插件"

    def _plugin_description_for_display(self, plugin: dict[str, object]) -> str:
        text = str(plugin.get("description") or "").strip()
        if not text:
            return "该插件暂无说明。"
        text = re.sub(r"^\s*迁移旧机器人[：:、\s]*", "", text)
        text = text.replace("迁移旧机器人", "").strip()
        return text or "该插件暂无说明。"

    def _plugin_commands_for_display(self, plugin: dict[str, object], limit: int = 12) -> list[str]:
        plugin_id = str(plugin.get("id") or "").lower()
        product_commands = self._product_plugin_commands(plugin_id)
        if product_commands:
            return product_commands[: max(1, int(limit))]
        raw_list = plugin.get("commands_list")
        if isinstance(raw_list, list) and raw_list:
            commands = [self._compact_plugin_command_label(str(item)) for item in raw_list if str(item).strip()]
            if plugin_id == "ai_reply":
                commands.extend(
                    [
                        "知识导入 <文件或目录路径>",
                        "知识搜索 <关键词>",
                        "知识添加 <标题> | <内容>",
                        "知识统计",
                    ]
                )
            return self._dedupe_labels(commands)[: max(1, int(limit))]
        text = str(plugin.get("commands_text") or "").strip()
        if not text or text == "-":
            commands = []
            if plugin_id == "ai_reply":
                commands = ["问 <问题>", "知识导入 <文件或目录路径>", "知识搜索 <关键词>", "知识统计"]
            return commands[: max(1, int(limit))]
        commands = [item.strip() for item in re.split(r"\s+", text) if item.strip()]
        if plugin_id == "ai_reply":
            commands.extend(["知识导入 <文件或目录路径>", "知识搜索 <关键词>", "知识统计"])
        return self._dedupe_labels(commands)[: max(1, int(limit))]

    @staticmethod
    def _product_plugin_commands(plugin_id: str) -> list[str]:
        commands: dict[str, list[str]] = {
            "bindings": [
                "绑定 <区服> <账号>",
                "绑定+<区服>+<账号>",
                "区服列表",
                "绑定记录 [关键词]",
                "导出绑定 [关键词]",
                "导入绑定 <区服|QQ|账号>",
                "删除绑定 <区服> <QQ>",
                "我的绑定",
                "查询绑定",
                "解绑 [区服]",
            ],
            "group_settings": [
                "本群设置",
                "开启/关闭指定功能",
                "设置积分奖励",
            ],
        }
        return list(commands.get(str(plugin_id or "").strip().lower(), []))

    @staticmethod
    def _dedupe_labels(values: list[str]) -> list[str]:
        result: list[str] = []
        for value in values:
            text = str(value or "").strip()
            if text and text not in result:
                result.append(text)
        return result

    def _compact_plugin_command_label(self, value: str) -> str:
        text = str(value or "").strip()
        if text.startswith("正则:") and " - " in text:
            text = text.split(" - ", 1)[1].strip()
        if " - " in text:
            text = text.split(" - ", 1)[0].strip()
        if len(text) > 34:
            text = text[:34] + "..."
        return text

    def _set_selected_plugin_enabled(self, enabled: bool) -> None:
        row = self.plugin_table.currentRow()
        if row < 0 or row >= len(self.plugins):
            self.status_label.setText("请先选择插件。")
            return
        plugin_id = str(self.plugins[row].get("id") or "")
        if not plugin_id:
            self.status_label.setText("无法识别插件 ID。")
            return
        if not self.current_group_id:
            self.status_label.setText("请先选择QQ群；插件启用/停用只按具体群处理。")
            return
        try:
            self.plugin_runtime.save_group_settings(self.current_group_id, {plugin_id: bool(enabled)}, {}, {})
            self._refresh_plugins()
            self._select_plugin_by_id(plugin_id)
            self._refresh_lock_state()
            self.status_label.setText(
                f"群 {self.current_group_id} 已{'启用' if enabled else '停用'}插件响应：{plugin_id}"
            )
        except Exception as exc:
            self.status_label.setText(f"保存本群插件状态失败：{exc}")

    def _reload_plugins(self) -> None:
        if not self.account_online:
            self.status_label.setText("请先完成账号登录后再重载插件。")
            return
        current_id = ""
        row = self.plugin_table.currentRow()
        if 0 <= row < len(self.plugins):
            current_id = str(self.plugins[row].get("id") or "")
        self.plugin_runtime.reload()
        self._refresh_plugins()
        if current_id:
            self._select_plugin_by_id(current_id)
        self._refresh_lock_state()
        self.status_label.setText(f"插件已刷新，共 {len(self.plugins)} 个。")

    def _open_plugin_config_dialog(self) -> None:
        if not self.account_online:
            self.status_label.setText("请先完成账号登录后再管理插件配置。")
            return
        row = self.plugin_table.currentRow()
        if row < 0 or row >= len(self.plugins):
            self.status_label.setText("请先选择插件。")
            return
        plugin = self.plugins[row]
        plugin_id = str(plugin.get("id") or "")
        if not plugin_id:
            self.status_label.setText("无法识别插件 ID。")
            return
        if plugin_id == "permissions":
            self._open_account_permissions_dialog()
            return
        try:
            config_snapshot = self.plugin_runtime.plugin_config_snapshot(plugin_id)
        except Exception as exc:
            self.status_label.setText(f"读取插件配置失败：{exc}")
            return
        admin_error = ""
        try:
            admin_snapshot = self.plugin_runtime.plugin_admin_snapshot(plugin_id, include_values=True)
        except Exception as exc:
            admin_snapshot = {"items": []}
            admin_error = str(exc)

        dialog = QtWidgets.QDialog(self)
        dialog.setWindowTitle(f"插件设置 - {plugin.get('name', plugin_id)}")
        dialog.resize(860, 600)
        if str(plugin_id).lower() == "ai_reply":
            dialog.resize(1080, 720)
        elif str(plugin_id).lower() == "invites":
            dialog.resize(1200, 720)
        dialog.setObjectName("xiamiPluginConfigDialog")

        root = QtWidgets.QVBoxLayout(dialog)
        root.setContentsMargins(12, 12, 12, 12)
        root.setSpacing(8)

        title_text = f"{plugin.get('name', plugin_id)}"
        title = QtWidgets.QLabel(title_text)
        title.setObjectName("sectionTitle")
        root.addWidget(title)

        tabs = QtWidgets.QTabWidget()
        root.addWidget(tabs, 1)

        config_tab = QtWidgets.QWidget()
        config_layout = QtWidgets.QVBoxLayout(config_tab)
        config_layout.setContentsMargins(0, 8, 0, 0)
        config_layout.setSpacing(8)
        schema_table = QtWidgets.QTableWidget(0, 5)
        schema_table.setHorizontalHeaderLabels(("参数", "类型", "必填", "默认", "说明"))
        schema_table.verticalHeader().setVisible(False)
        schema_table.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        schema_table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        schema_header = schema_table.horizontalHeader()
        schema_header.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeToContents)
        schema_header.setSectionResizeMode(1, QtWidgets.QHeaderView.ResizeToContents)
        schema_header.setSectionResizeMode(2, QtWidgets.QHeaderView.ResizeToContents)
        schema_header.setSectionResizeMode(3, QtWidgets.QHeaderView.ResizeToContents)
        schema_header.setSectionResizeMode(4, QtWidgets.QHeaderView.Stretch)
        schema = config_snapshot.get("schema", [])
        if not isinstance(schema, list):
            schema = []
        for item in schema:
            if not isinstance(item, dict):
                continue
            table_row = schema_table.rowCount()
            schema_table.insertRow(table_row)
            default_text = self._format_json_for_editor(item.get("default", ""))
            values = (
                item.get("key", ""),
                item.get("type", ""),
                "是" if item.get("required") else "-",
                default_text.replace("\n", " "),
                item.get("description", ""),
            )
            for col, value in enumerate(values):
                cell = QtWidgets.QTableWidgetItem(str(value))
                if col in (1, 2):
                    cell.setTextAlignment(QtCore.Qt.AlignCenter)
                schema_table.setItem(table_row, col, cell)
        schema_table.setMaximumHeight(170)
        config_layout.addWidget(schema_table)

        current_config = config_snapshot.get("current", {})
        default_config = config_snapshot.get("default", {})
        if not isinstance(current_config, dict):
            current_config = {}
        if not isinstance(default_config, dict):
            default_config = {}

        form_fields: dict[str, tuple[QtWidgets.QWidget, str]] = {}
        form_scroll = QtWidgets.QScrollArea()
        form_scroll.setWidgetResizable(True)
        form_content = QtWidgets.QWidget()
        form_layout = QtWidgets.QFormLayout(form_content)
        form_layout.setContentsMargins(8, 8, 8, 8)
        form_layout.setSpacing(10)
        if schema:
            for item in schema:
                if not isinstance(item, dict):
                    continue
                key = str(item.get("key") or "").strip()
                if not key:
                    continue
                label_text = str(item.get("label") or key)
                value = current_config.get(key, default_config.get(key, item.get("default", "")))
                field_type = str(item.get("type") or "").lower()
                choices = item.get("choices") or []
                if choices:
                    widget = QtWidgets.QComboBox()
                    widget.addItems([str(choice) for choice in choices])
                    current_text = str(value)
                    index = widget.findText(current_text)
                    if index >= 0:
                        widget.setCurrentIndex(index)
                elif field_type in {"bool", "boolean"} or isinstance(value, bool):
                    widget = QtWidgets.QCheckBox("启用")
                    widget.setChecked(bool(value))
                elif field_type in {"int", "integer"} and not isinstance(value, bool):
                    widget = QtWidgets.QSpinBox()
                    widget.setRange(-999999999, 999999999)
                    try:
                        widget.setValue(int(value or 0))
                    except Exception:
                        widget.setValue(0)
                elif field_type in {"float", "number"}:
                    widget = QtWidgets.QDoubleSpinBox()
                    widget.setRange(-999999999.0, 999999999.0)
                    widget.setDecimals(3)
                    try:
                        widget.setValue(float(value or 0))
                    except Exception:
                        widget.setValue(0.0)
                elif field_type in {"list", "array", "dict", "object", "map", "json"} or isinstance(value, (list, dict)):
                    widget = QtWidgets.QPlainTextEdit()
                    widget.setMaximumHeight(90)
                    widget.setPlainText(self._format_json_for_editor(value))
                else:
                    widget = _make_ui_line_edit("normal", "")
                    widget.setText("" if value is None else str(value))
                    if bool(item.get("secret")):
                        widget.setEchoMode(QtWidgets.QLineEdit.Password)
                widget.setObjectName(f"xiamiPluginConfigField_{key}")
                description = str(item.get("description") or "")
                if description:
                    box = QtWidgets.QWidget()
                    box_layout = QtWidgets.QVBoxLayout(box)
                    box_layout.setContentsMargins(0, 0, 0, 0)
                    box_layout.setSpacing(3)
                    box_layout.addWidget(widget)
                    hint = QtWidgets.QLabel(description)
                    hint.setWordWrap(True)
                    hint.setStyleSheet("color:#64748B;")
                    box_layout.addWidget(hint)
                    form_layout.addRow(label_text, box)
                else:
                    form_layout.addRow(label_text, widget)
                form_fields[key] = (widget, field_type)
        else:
            empty_label = QtWidgets.QLabel("该插件没有需要手动配置的基础参数。")
            empty_label.setStyleSheet("color:#64748B;")
            form_layout.addRow(empty_label)
        form_layout.setFieldGrowthPolicy(QtWidgets.QFormLayout.ExpandingFieldsGrow)
        form_scroll.setWidget(form_content)
        tabs.addTab(form_scroll, "基础设置")

        config_editor = QtWidgets.QPlainTextEdit()
        config_editor.setObjectName("xiamiPluginConfigEditor")
        config_editor.setPlainText(self._format_json_for_editor(current_config or default_config))
        config_layout.addWidget(config_editor, 1)
        tabs.addTab(config_tab, "高级 JSON")

        admin_tab = QtWidgets.QWidget()
        admin_layout = QtWidgets.QVBoxLayout(admin_tab)
        admin_layout.setContentsMargins(0, 8, 0, 0)
        admin_layout.setSpacing(8)
        admin_splitter = QtWidgets.QSplitter(QtCore.Qt.Horizontal)
        admin_table = QtWidgets.QTableWidget(0, 5)
        admin_table.setHorizontalHeaderLabels(("项目", "类型", "保存位置", "当前状态", "相关命令"))
        admin_table.verticalHeader().setVisible(False)
        admin_table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        admin_table.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        admin_header = admin_table.horizontalHeader()
        admin_header.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeToContents)
        admin_header.setSectionResizeMode(1, QtWidgets.QHeaderView.ResizeToContents)
        admin_header.setSectionResizeMode(2, QtWidgets.QHeaderView.ResizeToContents)
        admin_header.setSectionResizeMode(3, QtWidgets.QHeaderView.ResizeToContents)
        admin_header.setSectionResizeMode(4, QtWidgets.QHeaderView.Stretch)
        admin_splitter.addWidget(admin_table)

        admin_right = QtWidgets.QWidget()
        admin_right_layout = QtWidgets.QVBoxLayout(admin_right)
        admin_right_layout.setContentsMargins(0, 0, 0, 0)
        admin_right_layout.setSpacing(8)
        admin_value_editor = QtWidgets.QPlainTextEdit()
        admin_value_editor.setObjectName("xiamiPluginAdminValueEditor")
        admin_right_layout.addWidget(admin_value_editor, 1)
        admin_button_bar = QtWidgets.QHBoxLayout()
        apply_admin_button = _make_ui_action_button("保存项目", "primary")
        delete_admin_button = _make_ui_action_button("清空", "danger")
        refresh_admin_button = _make_ui_action_button("刷新", "secondary")
        admin_button_bar.addWidget(apply_admin_button)
        admin_button_bar.addWidget(delete_admin_button)
        admin_button_bar.addWidget(refresh_admin_button)
        admin_button_bar.addStretch(1)
        admin_right_layout.addLayout(admin_button_bar)
        admin_splitter.addWidget(admin_right)
        admin_splitter.setStretchFactor(0, 3)
        admin_splitter.setStretchFactor(1, 2)
        admin_layout.addWidget(admin_splitter, 1)
        tabs.addTab(admin_tab, "业务数据")

        dialog_status = QtWidgets.QLabel(admin_error or "配置和后台项已读取。")
        dialog_status.setWordWrap(True)
        root.addWidget(dialog_status)

        button_bar = QtWidgets.QHBoxLayout()
        save_config_button = _make_ui_action_button("保存配置", "primary")
        close_button = _make_ui_action_button("关闭", "secondary")
        button_bar.addWidget(save_config_button)
        button_bar.addStretch(1)
        button_bar.addWidget(close_button)
        root.addLayout(button_bar)

        admin_state = {"snapshot": admin_snapshot, "items": []}

        def fill_admin_table() -> None:
            raw_items = admin_state["snapshot"].get("items", []) if isinstance(admin_state["snapshot"], dict) else []
            items = [item for item in raw_items if isinstance(item, dict)] if isinstance(raw_items, list) else []
            admin_state["items"] = items
            admin_table.setRowCount(0)
            for item in items:
                table_row = admin_table.rowCount()
                admin_table.insertRow(table_row)
                binding = item.get("state_key") or item.get("config_key") or item.get("runtime_key") or ""
                commands = item.get("commands", [])
                command_text = " ".join(str(command) for command in commands[:4]) if isinstance(commands, list) else ""
                values = (item.get("label", "") or item.get("id", ""), item.get("type", ""), binding, item.get("summary", ""), command_text)
                for col, value in enumerate(values):
                    cell = QtWidgets.QTableWidgetItem(str(value))
                    if col == 2:
                        cell.setTextAlignment(QtCore.Qt.AlignCenter)
                    admin_table.setItem(table_row, col, cell)
            if items:
                admin_table.selectRow(0)
            else:
                admin_value_editor.setPlaceholderText("该插件没有可维护的业务数据。")
                admin_value_editor.clear()
                apply_admin_button.setEnabled(False)
                delete_admin_button.setEnabled(False)

        def selected_admin_item() -> dict[str, object] | None:
            admin_row = admin_table.currentRow()
            items = admin_state.get("items", [])
            if admin_row < 0 or admin_row >= len(items):
                return None
            return items[admin_row]

        def update_admin_editor() -> None:
            item = selected_admin_item()
            if not item:
                admin_value_editor.setPlaceholderText("选择左侧项目后查看或修改。")
                admin_value_editor.clear()
                apply_admin_button.setEnabled(False)
                delete_admin_button.setEnabled(False)
                return
            value = item.get("value", None)
            value_type = str(item.get("value_type") or "")
            if value is None:
                admin_value_editor.clear()
                admin_value_editor.setPlaceholderText("当前未设置。可直接输入文本；列表或对象请使用 JSON。")
            elif value_type in {"dict", "list"} or isinstance(value, (dict, list)):
                admin_value_editor.setPlainText(self._format_json_for_editor(value))
            else:
                admin_value_editor.setPlainText(str(value))
            description = str(item.get("description") or "")
            if description:
                admin_value_editor.setToolTip(description)
            editable = bool(item.get("state_key") or item.get("config_key")) and not item.get("runtime_key")
            apply_admin_button.setEnabled(editable)
            delete_admin_button.setEnabled(editable)

        def refresh_admin_snapshot() -> None:
            try:
                admin_state["snapshot"] = self.plugin_runtime.plugin_admin_snapshot(plugin_id, include_values=True)
                fill_admin_table()
                self._refresh_plugins()
                self._select_plugin_by_id(plugin_id)
                dialog_status.setText("后台项已刷新。")
            except Exception as exc:
                dialog_status.setText(f"刷新后台项失败：{exc}")

        def apply_admin_value() -> None:
            item = selected_admin_item()
            if not item:
                dialog_status.setText("请先选择后台项。")
                return
            item_id = str(item.get("id") or item.get("state_key") or item.get("config_key") or "")
            if not item_id:
                dialog_status.setText("无法识别后台项 ID。")
                return
            try:
                value = self._parse_json_editor_value(admin_value_editor.toPlainText())
                result = self.plugin_runtime.set_plugin_admin_item(plugin_id, item_id, value)
                dialog_status.setText(str(result.get("message") or "后台项已写入。"))
                refresh_admin_snapshot()
            except Exception as exc:
                dialog_status.setText(f"写入后台项失败：{exc}")

        def delete_admin_value() -> None:
            item = selected_admin_item()
            if not item:
                dialog_status.setText("请先选择后台项。")
                return
            item_id = str(item.get("id") or item.get("state_key") or item.get("config_key") or "")
            if not item_id:
                dialog_status.setText("无法识别后台项 ID。")
                return
            try:
                result = self.plugin_runtime.delete_plugin_admin_item(plugin_id, item_id)
                dialog_status.setText(str(result.get("message") or "后台项已删除。"))
                refresh_admin_snapshot()
            except Exception as exc:
                dialog_status.setText(f"删除后台项失败：{exc}")

        def save_config() -> None:
            if tabs.currentWidget() is config_tab:
                raw = config_editor.toPlainText().strip() or "{}"
                try:
                    config = json.loads(raw)
                except json.JSONDecodeError as exc:
                    dialog_status.setText(f"配置 JSON 格式错误：{exc}")
                    return
                if not isinstance(config, dict):
                    dialog_status.setText("插件配置必须是 JSON 对象。")
                    return
            else:
                config = dict(current_config)
                if tabs.currentWidget() is form_scroll:
                    for key, field in form_fields.items():
                        widget, field_type = field
                        try:
                            config[key] = self._read_config_field_value(widget, field_type)
                        except Exception as exc:
                            dialog_status.setText(f"{key} 配置格式错误：{exc}")
                            return
                config_editor.setPlainText(self._format_json_for_editor(config))
            try:
                self.plugin_runtime.save_plugin_config(plugin_id, config)
                current_config.clear()
                current_config.update(config)
                self._refresh_plugins()
                self._select_plugin_by_id(plugin_id)
                refresh_admin_snapshot()
                self._refresh_lock_state()
                self.status_label.setText(f"插件配置已保存：{plugin_id}")
                dialog_status.setText("插件配置已保存并重载。")
            except Exception as exc:
                dialog_status.setText(f"保存插件配置失败：{exc}")

        self._add_plugin_specific_settings_tabs(
            tabs,
            plugin_id,
            dialog_status,
            current_config,
            config_editor,
            refresh_admin_snapshot,
        )
        basic_settings_available = any(
            isinstance(item, dict) and str(item.get("key") or "").strip()
            for item in schema
        )
        show_basic_settings = basic_settings_available and not self._plugin_settings_business_only(plugin_id)
        self._remove_plugin_engineering_tabs(tabs, keep_basic_settings=show_basic_settings)
        if tabs.count() <= 0:
            self.status_label.setText(f"{plugin.get('name', plugin_id)} 暂无需要维护的设置。")
            return

        def update_save_config_button() -> None:
            save_config_button.setVisible(bool(show_basic_settings and tabs.currentWidget() is form_scroll))

        admin_table.itemSelectionChanged.connect(update_admin_editor)
        apply_admin_button.clicked.connect(apply_admin_value)
        delete_admin_button.clicked.connect(delete_admin_value)
        refresh_admin_button.clicked.connect(refresh_admin_snapshot)
        save_config_button.clicked.connect(save_config)
        close_button.clicked.connect(dialog.accept)
        tabs.currentChanged.connect(lambda _index: update_save_config_button())
        update_save_config_button()
        fill_admin_table()
        dialog.exec_()

    def _plugin_settings_business_only(self, plugin_id: str) -> bool:
        # QQ机器人插件设置只保留产品化后台页；不再向用户暴露通用 JSON 或状态表。
        return True

    def _remove_plugin_engineering_tabs(self, tabs: QtWidgets.QTabWidget, keep_basic_settings: bool = False) -> None:
        engineering_titles = {"高级 JSON", "业务数据", "当前群配置", "本群配置", "当前群设置", "当前群设置项"}
        engineering_keywords = ("当前群配置", "本群配置", "当前群设置")
        if not keep_basic_settings:
            engineering_titles.add("基础设置")
            engineering_titles.add("基本设置")
        for index in range(tabs.count() - 1, -1, -1):
            title = tabs.tabText(index).strip()
            normalized = re.sub(r"\s+", "", title)
            if title in engineering_titles or normalized in engineering_titles or any(keyword in title for keyword in engineering_keywords):
                tabs.removeTab(index)
        if tabs.count() > 0:
            tabs.setCurrentIndex(0)

    def _format_json_for_editor(self, value) -> str:
        try:
            return json.dumps(value, ensure_ascii=False, indent=2)
        except TypeError:
            return str(value)

    def _parse_json_editor_value(self, text: str):
        raw = str(text or "").strip()
        if not raw:
            return ""
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            return raw

    def _read_config_field_value(self, widget: QtWidgets.QWidget, field_type: str):
        field_type = str(field_type or "").lower()
        if isinstance(widget, QtWidgets.QCheckBox):
            return bool(widget.isChecked())
        if isinstance(widget, QtWidgets.QSpinBox):
            return int(widget.value())
        if isinstance(widget, QtWidgets.QDoubleSpinBox):
            return float(widget.value())
        if isinstance(widget, QtWidgets.QComboBox):
            return str(widget.currentText())
        if isinstance(widget, QtWidgets.QPlainTextEdit):
            text = widget.toPlainText().strip()
            if field_type in {"list", "array", "dict", "object", "map", "json"}:
                if not text:
                    return [] if field_type in {"list", "array"} else {}
                return json.loads(text)
            return text
        if isinstance(widget, QtWidgets.QLineEdit):
            text = widget.text()
            if field_type in {"int", "integer"}:
                return int(text.strip() or "0")
            if field_type in {"float", "number"}:
                return float(text.strip() or "0")
            return text
        return ""

    @staticmethod
    def _parse_qq_id_text(text: str) -> list[str]:
        ids = re.findall(r"\d{5,}", str(text or ""))
        result: list[str] = []
        for value in ids:
            if value not in result:
                result.append(value)
        return sorted(result)

    @staticmethod
    def _format_qq_id_text(values) -> str:
        if isinstance(values, str):
            values = re.findall(r"\d{5,}", values)
        if not isinstance(values, (list, tuple, set)):
            return ""
        return "\n".join(str(value) for value in values if str(value).strip())

