        retention_spin.setSpecialValueText("不限制留群天数")
        retention_spin.setToolTip("成员在设置天数内退群时，自动从邀请人积分中扣回原奖励；余额允许为负数。")
        load_button = _make_ui_action_button("读取", "secondary")
        save_button = _make_ui_action_button("保存设置", "primary")
