        inviter_edit = _make_ui_line_edit("normal", "邀请人QQ")
        manual_points_spin = QtWidgets.QSpinBox()
        manual_points_spin.setRange(1, 999999)
        manual_points_spin.setValue(1)
        add_record_button = _make_ui_action_button("补录记录", "primary")
        import_record_button = _make_ui_action_button("批量导入", "secondary")
