        edit_row.addWidget(invitee_edit, 1)
        edit_row.addWidget(QtWidgets.QLabel("邀请人QQ"))
        edit_row.addWidget(inviter_edit, 1)
        edit_row.addWidget(QtWidgets.QLabel("奖励积分"))
