        config_layout.addWidget(QtWidgets.QLabel("退群撤回条数"), 2, 2)
        config_layout.addWidget(leave_recall_limit_spin, 2, 3)
        config_layout.addWidget(QtWidgets.QLabel("成员消息缓存条数"), 3, 0)
