        bot_reply_recall_layout.setSpacing(8)
        bot_reply_recall_layout.addWidget(bot_reply_recall_check)
        bot_reply_recall_layout.addWidget(QtWidgets.QLabel("延迟"))
        bot_reply_recall_layout.addWidget(bot_reply_recall_seconds_spin)
        bot_reply_recall_layout.addStretch(1)
        config_layout.addWidget(bot_reply_recall_box, 3, 2, 1, 2)

        recall_type_options = (
            ("image", "图片"),
            ("video", "视频"),
            ("url", "链接"),
            ("json", "JSON"),
            ("xml", "XML"),
            ("card", "卡片"),
            ("redbag", "红包"),
            ("miniapp", "小程序"),
            ("email", "邮箱"),
        )
        recall_type_checks: dict[str, QtWidgets.QCheckBox] = {}
