        list_table.verticalHeader().setVisible(False)
        list_table.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        list_table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        list_header = list_table.horizontalHeader()
        for col in range(3):
            list_header.setSectionResizeMode(col, QtWidgets.QHeaderView.ResizeToContents)
        list_header.setSectionResizeMode(3, QtWidgets.QHeaderView.Stretch)
