        word_table.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
        word_table.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
        word_header = word_table.horizontalHeader()
        word_header.setSectionResizeMode(0, QtWidgets.QHeaderView.ResizeToContents)
