        words_editor = QtWidgets.QPlainTextEdit()
        words_editor.setMaximumHeight(86)
        words_editor.setPlaceholderText("违禁词，支持逗号或换行分隔")
        forms.addWidget(users_editor, 1)
        forms.addWidget(words_editor, 1)
