        remove_member_button = _make_ui_action_button("删除名单", "secondary")
        clear_member_button = _make_ui_action_button("清空名单", "danger")
        add_word_button = _make_ui_action_button("添加违禁词", "primary")
        remove_word_button = _make_ui_action_button("删除违禁词", "secondary")
        clear_word_button = _make_ui_action_button("清空违禁词", "danger")
        refresh_button = _make_ui_action_button("刷新", "secondary")
