    explicit_visual_spawn = bool(getattr(args, "dark_workbench_real_visual_spawn", False))
    explicit_db = bool(getattr(args, "dark_workbench_real_db", False))
    explicit_drop = bool(getattr(args, "dark_workbench_real_drop", False))
    explicit_spawn = bool(getattr(args, "dark_workbench_real_spawn", False))
    explicit_store = bool(getattr(args, "dark_workbench_real_store", False))
    explicit_recycle = bool(getattr(args, "dark_workbench_real_recycle", False))
    explicit_var_query = bool(getattr(args, "dark_workbench_real_var_query", False))
    explicit_encoding = bool(getattr(args, "dark_workbench_real_encoding", False))
    explicit_script = bool(getattr(args, "dark_workbench_real_script", False))
    explicit_item = bool(getattr(args, "dark_workbench_real_item", False))
    explicit_micro = bool(getattr(args, "dark_workbench_real_micro", False))
    explicit_free_micro = bool(getattr(args, "dark_workbench_real_free_micro", False))
    explicit_cdk = bool(getattr(args, "dark_workbench_real_cdk", False))
    explicit_member = bool(getattr(args, "dark_workbench_real_member", False))
    explicit_qq_bot = bool(getattr(args, "dark_workbench_real_qq_bot", False))
    explicit_website = bool(getattr(args, "dark_workbench_real_website", False))
    want_basic = want_core or explicit_basic
    want_search = want_core or explicit_search or explicit_currency
    want_compare = want_core or explicit_compare
    want_currency = want_core or explicit_currency
    want_map = want_core or explicit_map
    want_visual_npc = want_core or explicit_visual_npc
    want_visual_spawn = want_core or explicit_visual_spawn
    want_db = want_core or explicit_db
    want_drop = want_core or explicit_drop
    want_spawn = want_core or explicit_spawn
    want_store = want_core or explicit_store
    want_recycle = want_core or explicit_recycle
    want_var_query = want_core or explicit_var_query
    want_encoding = want_core or explicit_encoding
    want_script = want_core or explicit_script
    want_item = want_core or explicit_item
    want_micro = want_core or explicit_micro
    want_free_micro = want_core or explicit_free_micro
    want_cdk = want_core or explicit_cdk
    want_member = want_core or explicit_member
    want_qq_bot = want_core or explicit_qq_bot
    want_website = want_core or explicit_website
    if not (want_basic or want_search or want_compare or want_currency or want_map or want_visual_npc or want_visual_spawn or want_db or want_drop or want_spawn or want_store or want_recycle or want_var_query or want_encoding or want_script or want_item or want_micro or want_free_micro or want_cdk or want_member or want_qq_bot or want_website):
        return

    context = _DarkWorkbenchPreviewContext()
    context.attach_shell(win)
    context._dark_workbench_smoke = bool(getattr(args, "dark_workbench_smoke", False))
    context.start_global_auto_update_check()
    auth_gate_setter = getattr(win, "set_auth_gate_enabled", None)
    if callable(auth_gate_setter):
        try:
            auth_gate_setter(True, bypass=bool(getattr(args, "dark_workbench_smoke", False)))
        except Exception:
            pass
    version_setter = getattr(win, "set_app_version", None)
    if callable(version_setter):
        try:
            version_setter(_read_legacy_toolbox_version() or str(globals().get("VERSION") or ""))
        except Exception:
            pass
    context.bind_shell_project_root_picker()
    context.bind_shell_account_center()
    context.bind_shell_global_tools()
    context.bind_shell_friend_links()
