def _legacy_ui_snapshot_contract(win) -> dict:
    nav_entries: list[str] = []
    nav_sections: list[str] = []
    try:
        tree = getattr(win, "nav_tree", None)
        if tree is not None:
            for row in range(int(tree.topLevelItemCount())):
                section = tree.topLevelItem(row)
                if section is None:
                    continue
                nav_sections.append(str(section.text(0) or ""))
                for child_row in range(int(section.childCount())):
                    child = section.child(child_row)
                    if child is not None:
                        nav_entries.append(str(child.text(0) or ""))
    except Exception:
        nav_entries = []
        nav_sections = []

    current_nav = ""
    try:
        item = win.nav_tree.currentItem()
        if item is not None:
            current_nav = str(item.text(0) or "")
    except Exception:
        current_nav = ""

    stack_count = 0
    current_page_type = ""
    try:
        stack = getattr(win, "stack", None)
        if stack is not None:
            stack_count = int(stack.count())
            current = stack.currentWidget()
            if current is not None:
                current_page_type = type(current).__name__
    except Exception:
        stack_count = 0
        current_page_type = ""

    return {
        "window_title": str(win.windowTitle() or ""),
        "size": [int(win.width()), int(win.height())],
        "mode": "legacy-ui",
        "nav_sections": nav_sections,
        "nav_entries": nav_entries,
        "nav_entry_count": len(nav_entries),
        "stack_pages": stack_count,
        "current_nav": current_nav,
        "current_page_type": current_page_type,
        "has_login_page": bool(getattr(win, "login_page", None) is not None),
        "has_basic_page": bool(getattr(win, "basic_page", None) is not None),
        "tray_created": bool(getattr(win, "_tray_icon", None) is not None),
    }


